	["%s no se puede invitar desde Alfa: el juego solo lo deja desde su ventana. Ábrela aquí y pega el nombre."] = "Alfa не может пригласить в %s: игра разрешает это только в своём окне. Откройте его здесь и вставьте имя.",
	["%s no se puede tomar"] = "%s: нельзя взять",
	["%s no tiene %s"] = "У %s нет «%s»",
	["%s o %s"] = "%s или %s",
	["%s pide %s: apréndela antes."] = "%s требует %s: сначала изучите.",
	["%s pide grupo"] = "%s: нужна группа",
	["%s pide un grupo de %d"] = "%s нужна группа из %d",
	["%s pidió ayuda aquí"] = "%s просит помощи здесь",
	["%s pidió entrar a tu guarida: lo invitaste a tu grupo. Saldrá solo al llegar."] = "%s попросился в твоё логово: ты пригласил его в группу. Он выйдет сам, когда окажется там.",
	["%s por hora"] = "%s в час",
	["%s prefiere seguir por su cuenta por ahora."] = "%s пока предпочитает идти сам.",
	["%s propone una cita"] = "%s предлагает сбор",
	["%s pudo volver ya"] = "%s мог уже вернуться",
	["%s puede vender lo gris y reparar, igual que Alfa. Si lo tienes encendido allá, los dos lo harían a la vez."] = "%s умеет продавать серые предметы и чинить, как и Alfa. Если там это включено, оба сделают это сразу.",
	["%s quedó completa. Elige qué sigue y la manada va contigo."] = "Готово: %s. Выберите, что дальше, и стая пойдет с вами.",
	["%s quiere ser tu mentor"] = "%s хочет стать твоим наставником",
	["%s resultados"] = "Результатов: %s",
	["%s se borra de todos tus personajes. No se puede deshacer."] = "%s будет удален у всех ваших персонажей. Отменить это нельзя.",
	["%s se compartirá con tu grupo al salir de la instancia."] = "Маркер «%s» будет передан группе после выхода из подземелья.",
	["%s también arregla el buzón: dos «Tomar todo» se estorban."] = "%s тоже улучшает почтовый ящик: две кнопки «Забрать все» мешают друг другу.",
	["%s también cambia tus bolsas y el banco: las dos ventanas se pisan al abrirlas."] = "%s тоже меняет сумки и банк: при открытии окна мешают друг другу.",
	["%s también es una guía: las dos aceptarían y entregarían tus misiones a la vez."] = "%s тоже гид: оба будут одновременно брать и сдавать твои задания.",
	["%s también hace “%s”. ¿Cazan juntos?"] = "%s тоже выполняет «%s». Поохотитесь вместе?",
	["%s también marca tus misiones en el mapa. Conviven bien; si ves marcas dobles, apaga las de uno de los dos."] = "%s тоже отмечает задания на карте. Они уживаются; если видишь двойные метки, выключи одну.",
	["%s también pone precios en el cuadro de los objetos: verías dos."] = "%s тоже показывает цены в подсказках предметов: ты увидишь две.",
	["%s te abre la puerta"] = "%s открывает тебе дверь",
	["%s te abre su guarida"] = "%s открывает для тебя свое логово",
