	["%s te habló de %s, y hay más historia de la que dice la flecha. ¿Te la cuento?"] = "%s рассказывает тебе про %s, и тут больше истории, чем говорит стрелка. Рассказать?",
	["%s tiene hambre. Una buena comida y vuelve a pelear contento."] = "%s голоден. Хорошая еда — и он снова с радостью в бой.",
