	["Avisar en el chat cuando completas una misión"] = "Сообщать в чате о выполнении задания",
	["Avisar los hechizos nuevos para entrenar"] = "Сообщать о новых заклинаниях для изучения",
	["Avisar rangos viejos en tus barras"] = "Сообщать о старых рангах на панелях",
	["Avisar si la barra de una forma está vacía"] = "Предупреждать, если панель облика пуста",
	["Avisar si lo das más barato de"] = "Предупреждать, если дешевле на",
	["Avisar también si le quedan menos de"] = "Предупреждать также, если осталось меньше",
	["Avisarme al descubrir un jefe"] = "Сообщать, когда открываю босса",
	["Avisarme al entrar a una mazmorra"] = "Сообщать при входе в подземелье",
	["Avisarme cuando mi equipo se gaste"] = "Предупреждать, когда экипировка изнашивается",
	["Avisarme cuando mis bolsas se llenen"] = "Предупреждать, когда сумки заполняются",
	["Avisarme cuando se me acabe la comida o el agua"] = "Говорить, когда кончаются еда или вода",
	["Avisarme de mi XP descansada"] = "Сообщать об опыте за отдых",
	["Avisarme del talento que toca"] = "Сообщать, какой талант следующий",
	["Avisarme en la ciudad si tengo habilidades por aprender"] = "Напоминать в городе о навыках к изучению",
	["Avisarme si me falta mi buff fuera de combate"] = "Напоминать вне боя, если нет моего баффа",
	["Aviso"] = "Сигнал",
	["Aviso al poner la flecha"] = "Оповещение при установке стрелки",
	["Aviso con lo que sacas"] = "Сводка улова",
	["Aviso para cortar"] = "Оповещение о прерывании",
	["Aviso urgente, con sonido"] = "Срочное оповещение, со звуком",
	["Avisos"] = "Оповещения",
	["Avisos con sonido"] = "Звуковые оповещения",
	["Avisos de descanso"] = "Напоминания об отдыхе",
	["Avisos de jefes"] = "Предупреждения о боссах",
	["Avisos de jefes como los recomienda Alfa"] = "Предупреждения о боссах в рекомендуемой Alfa настройке",
	["Avisos de jefes del juego"] = "Игровые предупреждения о боссах",
	["Avisos de reacción"] = "Оповещения о реакциях",
	["Avisos y diario"] = "Оповещения и дневник",
	["Avisos, golpe y estadísticas"] = "Оповещения, удар и характеристики",
	["Ay, lobo… van varias caídas seguidas. Respira, repara tu equipo y, si quieres, pide ayuda a la manada."] = "Ох, волк… несколько смертей подряд. Выдохни, почини снаряжение и, если хочешь, попроси стаю о помощи.",
	["Ayuda al subastar"] = "Помощь на аукционе",
	["Ayuda de rotación"] = "Помощник ротации",
	["Ayuda de rotación para las 27 especializaciones y la ventana /alfa paisaje con 68 ajustes gráficos explicados."] = "Помощник ротации для всех 27 специализаций и окно /alfa paisaje с 68 графическими настройками и пояснениями.",
	["Ayudas de combate"] = "Боевые подсказки",
	["Ayudas para tu personaje"] = "Помощь вашему персонажу",
	["Azeroth"] = "Азерот",
	["Azeroth tiene dos continentes en el Clásico: Kalimdor al oeste y los Reinos del Este. En medio está el Gran Mar."] = "В классике у Азерота два континента: Калимдор на западе и Восточные королевства. Между ними — Великое море.",
	["Azshara lleva el nombre de la reina de los elfos que abrió la puerta a la Legión Ardiente. Tras la Gran División se convirtió en la reina de los naga."] = "Азшара названа в честь королевы эльфов, открывшей дверь Пылающему Легиону. После Раскола она стала королевой наг.",
	["Azshara y los Altonato que se hundieron con su palacio no murieron: se transformaron en los naga."] = "Азшара и высокорожденные, утонувшие вместе с ее дворцом, не погибли: они превратились в наг.",
	["Azul"] = "Синий",
	["Azul de medianoche casi negro con detalles en plata de luna. Para cazar de noche."] = "Почти черная полуночная синева с отделкой лунным серебром. Для охоты по ночам.",
	["Aún nada esta semana"] = "На этой неделе пока ничего",
	["Aún nadie responde"] = "Пока никто не ответил",
	["Aún no conozco a ningún lobo conectado que comparta su clase y su nivel. Pídeles que prendan «Compartir mi clase y nivel» en La Jauría."] = "Я пока не знаю ни одного волка в сети, который делится классом и уровнем. Попроси их включить «Делиться классом и уровнем» в La Jauría.",
	["Aún no conozco ese objeto. Pásale el ratón encima y vuelve a intentarlo."] = "Этот предмет еще неизвестен. Наведите на него курсор и попробуйте снова.",
	["Aún no conozco su precio. Al buscarlo o escanear, Alfa lo aprende."] = "Я пока не знаю его цену. Alfa узнает ее, когда ты ищешь предмет или сканируешь.",
	["Aún no dejas notas. También sirve /alfa nota <texto>."] = "Заметок пока нет. Можно и так: /alfa nota <текст>.",
	["Aún no está terminada: te falta %s."] = "Еще не выполнено: осталось %s.",
	["Aún no está terminada: termínala antes de entregarla."] = "Еще не выполнено: выполните его, прежде чем сдавать.",
	["Aún no ganas oro en esta sesión. Alfa cuenta lo que ganas desde que entraste al juego."] = "В этом сеансе золота пока нет. Alfa считает заработанное с момента входа в игру.",
	["Aún no guardas ningún conjunto."] = "Ты еще не сохранил ни одного комплекта.",
	["Aún no hay historias"] = "Историй пока нет",
	["Aún no hay misiones de clase para ti: la próxima abre a nivel %d."] = "Классовых заданий для вас пока нет: следующее откроется на уровне %d.",
	["Aún no hay personajes guardados"] = "Сохраненных персонажей пока нет",
	["Aún no la aprendes"] = "Еще не изучено",
	["Aún no la tomas"] = "Еще не взято",
	["Aún no lo aprendes"] = "Еще не изучено",
	["Aún no los aprendes"] = "Еще не изучены",
	["Aún no picaba"] = "Еще не клевало",
	["Aún no puedes tomar %s"] = "Пока нельзя взять %s",
	["Aún no sé cómo va."] = "Пока нет новостей.",
	["Aún no tienes el nivel"] = "Пока не хватает уровня",
	["Aún no tienes nada abierto. Mira Todas o usa los filtros de arriba para encontrar una guía."] = "Пока ничего не открыто. Загляните во «Все» или используйте фильтры сверху, чтобы найти гайд.",
	["Aún no tienes perfiles"] = "У тебя пока нет профилей",
	["Aún no tienes precios de la subasta: escanéala para saber cuánto vale de verdad."] = "У вас пока нет аукционных цен: просканируйте аукцион, чтобы узнать реальную стоимость.",
	["Aún no tienes precios. Pulsa «Escanear con Alfa»."] = "Цен пока нет. Нажмите «Сканировать с Alfa».",
	["Aún no tienes rutas. Ármalas en la ventana de Alfa: Aventura > Rutas; cada una aparece aquí como guía."] = "Маршрутов пока нет. Составьте их в окне Alfa: «Приключения» > «Маршруты»; каждый появится здесь как гайд.",
	["Aún sin abrir: gana tu primer punto"] = "Еще не открыто: заработайте первое очко",
	["Bahía del Botín es el puerto del cártel Bonvapor, y ahí manda el barón Revilgaz."] = "Пиратская Бухта — порт картеля Хитрой Шестеренки, и правит там барон Ревилгаз.",
	["Bailar"] = "Танец",
	["Baja"] = "Низкое",
	["Baja tu amenaza un rato. Úsalo si los enemigos se te vienen encima."] = "На время снижает твою угрозу. Применяй, если враги идут за тобой.",
	["Baja tu amenaza. Úsalo en grupo para no quitarle el enemigo al tanque."] = "Снижает твою угрозу. Применяй в группе, чтобы не отбирать врага у танка.",
	["Bajar"] = "Вниз",
	["Bajarlas ayuda en tarjetas de video con poca memoria."] = "Понижение помогает видеокартам с малым объемом памяти.",
	["Bajas"] = "Низкие",
	["Bajas la amenaza que generas. Úsalo si el enemigo se te viene encima."] = "Снижает твою угрозу. Применяй, если враг идет за тобой.",
	["Bajo"] = "Низкий",
	["Bajo estas tierras está Uldaman, una ciudad de los titanes. Los enanos de la Liga de Expedicionarios creen que ahí están las pistas de su propio origen."] = "Под этими землями лежит Ульдаман, город титанов. Дворфы из Лиги исследователей верят, что там скрыты подсказки об их собственном происхождении.",
	["Bajos"] = "Низкие",
	["Balanceo al caminar"] = "Покачивание при ходьбе",
	["Balas"] = "Пули",
	["Balas: llevas %d (mejor %d o más)"] = "Пули: у тебя %d (лучше %d или больше)",
	["Ballesta"] = "Арбалет",
	["Banco"] = "Банк",
