	["Barbabronce, Hierro Negro y Martillo Salvaje pelearon la Guerra de los Tres Martillos, que partió a los enanos de Khaz Modan."] = "Бронзобороды, Черное Железо и Громовой Молот сражались в Войне Трех Молотов, которая расколола дворфов Каз Модана.",
	["Barco de %s"] = "Корабль: %s",
