	["Bestias de nivel 30 a 45."] = "Звери 30–45-го уровня.",
	["Bestias de nivel 45 a 60."] = "Звери 45–60-го уровня.",
	["Bestias hasta el nivel 15."] = "Звери до 15-го уровня.",
	["Biblioteca de guías"] = "Библиотека гайдов",
	["Bienvenida"] = "Приветствие",
	["Bienvenida a Alfa"] = "Добро пожаловать в Alfa",
	["Bienvenida a Alfa %s"] = "Добро пожаловать в Alfa %s",
	["Bienvenida a pantalla completa"] = "Приветствие на весь экран",
	["Bienvenido a %s. Mira bien antes de jalar: un grupo de más nos puede tumbar a todos."] = "Добро пожаловать в %s. Смотри внимательно, прежде чем пуллить: одна лишняя группа может положить нас всех.",
	["Bilineal"] = "Билинейная",
	["Blackmoore le enseñó a Thrall a leer y a pelear para usarlo como arma... y eso terminó volviéndose en su contra."] = "Блэкмур учил Тралла читать и сражаться, чтобы сделать из него оружие... и в итоге это обернулось против него самого.",
	["Blanco"] = "Белый",
	["Blizzard no deja que un addon copie tu mapa. Abre su ventana con el botón «Abrir clic para lanzar» o escribe %s en el chat, y arma ahí los mismos clics."] = "Blizzard не позволяет аддону скопировать вашу схему. Откройте окно Blizzard кнопкой «Открыть заклинания по щелчку» или введите %s в чате и настройте там те же щелчки.",
	["Blizzard no deja que un addon copie tu mapa. Se abrió su ventana de clic para lanzar: arma ahí los mismos clics."] = "Blizzard не позволяет аддону скопировать вашу схему. Открылось окно заклинаний по щелчку Blizzard: настройте там те же щелчки.",
	["Blizzard no deja que un addon copie tu mapa. Ábrelo en el menú del juego: Opciones, Clic para lanzar."] = "Blizzard не позволяет аддону скопировать вашу схему. Откройте ее в меню игры: Настройки, Заклинания по щелчку.",
	["Bloqueada"] = "Заблокировано",
	["Bloquear"] = "Блок",
	["Bloquear posición"] = "Закрепить положение",
	["Bloquear su lugar"] = "Закрепить ее место",
	["Bloqueas más y ganas ira al bloquear."] = "Вы чаще блокируете и получаете ярость при блоке.",
	["Bloqueas más y ganas ira."] = "Вы чаще блокируете и получаете ярость.",
	["Bloqueas más, y cada bloqueo te da ira."] = "Вы чаще блокируете, и каждый блок дает ярость.",
	["Bloqueaste, esquivaste o paraste: Revancha es barata y genera mucha amenaza. Necesita actitud defensiva."] = "Вы заблокировали, уклонились или парировали: Реванш дешев и создает много угрозы. Нужна Оборонительная стойка.",
	["Bloqueo"] = "Блок",
	["Bloqueo con escudo: bloqueas los golpes y activa Revancha."] = "Блок щитом: вы блокируете удары, и становится доступен Реванш.",
	["Bolsa"] = "Сумка",
	["Bolsa de almas"] = "Сумка душ",
	["Bolsa de componentes"] = "Сумка для реагентов",
	["Bolsa de componentes: %d de %d libres"] = "Сумка для реагентов: свободно %d из %d",
	["Bolsa de encantamiento"] = "Сумка зачаровывателя",
