	["Bolsa de munición"] = "Подсумок",
	["Bolsas"] = "Сумки",
	["Bolsas casi llenas (%d libres). Vende lo gris y haz lugar para el botín."] = "Сумки почти полны (свободно: %d). Продай серое и освободи место для добычи.",
	["Bolsas de %s"] = "Сумки: %s",
	["Bolsas encuentra tus objetos en ruso y en otros alfabetos aunque escribas con mayúscula."] = "Сумки находят ваши предметы на русском и в других алфавитах, даже если вы пишете с заглавной буквы.",
	["Bolsas especiales: %d de %d libres"] = "Особые сумки: свободно %d из %d",
	["Bolsas llenas"] = "Сумки полны",
	["Bolsas sin errores, conjuntos de equipo, comparar y buscar en todos tus personajes."] = "Сумки без ошибок, комплекты экипировки, сравнение и поиск по всем персонажам.",
	["Bolsas y banco"] = "Сумки и банк",
	["Bolsas: %d de %d libres"] = "Сумки: свободно %d из %d",
	["Bolsas: %d objetos en %d de %d casillas"] = "Сумки: %d предм. в %d из %d ячеек",
	["Bolsas: te queda 1 espacio para el botín"] = "Сумки: осталась 1 ячейка для добычи",
	["Bolsas: te quedan %d espacios para el botín"] = "Сумки: осталось ячеек для добычи: %d",
	["Bolvar Fordragón, hoy regente de Ventormenta, fue paladín de la Mano de Plata."] = "Болвар Фордрагон, ныне регент Штормграда, был паладином ордена Серебряной Длани.",
	["Bonus de tu tipo de arma."] = "Бонус вашего типа оружия.",
	["Bonus según tu tipo de arma (hacha, espada o maza): más crítico o más golpes."] = "Бонус по типу оружия (топор, меч или дробящее): больше критических ударов или больше атак.",
	["Bonus según tu tipo de arma: más golpes y más críticos."] = "Бонус по типу оружия: больше атак и больше критических ударов.",
	["Borde de calidad"] = "Рамка качества",
