	["Borraste esta ruta. Desaparece del menú al recargar la interfaz."] = "Вы удалили этот маршрут. Он исчезнет из меню после перезагрузки интерфейса.",
	["Borraste «%s»"] = "Ты удалил «%s»",
	["Botones con el estilo"] = "Кнопки в стиле",
	["Botones de Alfa en el mapa del juego"] = "Кнопки Alfa на карте игры",
	["Botones de acción, experiencia, menú y bolsas con tu estilo. Nunca se tocan en combate."] = "Кнопки действий, опыт, меню и сумки в вашем стиле. В бою не меняются.",
	["Botones de objetos"] = "Кнопки предметов",
