	["Botón del objeto de misión más claro"] = "Понятнее кнопка предмета для задания",
	["Botón resaltado en tu barra"] = "Подсвеченная кнопка на панели",
	["Botón «Acomodar»"] = "Кнопка «Разобрать»",
	["Botón «Buscar cerca» en el rastreador"] = "Кнопка «Найти рядом» в трекере",
	["Brasa"] = "Уголь",
	["Brillan los objetos que acabas de conseguir, hasta que cierras las bolsas."] = "Только что полученные предметы подсвечиваются, пока вы не закроете сумки.",
	["Brillo"] = "Свечение",
	["Brillo máximo (nits)"] = "Пиковая яркость (нит)",
	["Brillo normal (nits)"] = "Обычная яркость (нит)",
	["Brillo: un borde dorado que late y una insignia «!» (llena si el objeto empieza una misión). Marco fijo: el marco dorado del juego. Nada: sin marca."] = "Свечение: пульсирующая золотая рамка и значок «!» (залит, если предмет начинает задание). Постоянная рамка: золотая рамка игры. Нет: без отметки.",
	["Brujo"] = "Чернокнижник",
	["Bruma"] = "Дымка",
	["Buen lanzamiento"] = "Хороший заброс",
	["Buena caza hoy: %s Descansa, que yo cuido tu lugar."] = "Хорошая охота сегодня: %s Отдохни, а я посторожу твое место.",
	["Buenas noches, lobo. Si te vas a ir pronto, termina en una posada para descansar bien."] = "Добрый вечер, волк. Если скоро уходишь, закончи в таверне, чтобы хорошо отдохнуть.",
	["Buenas tardes. Es buena hora para entregar misiones y ver qué hay de nuevo."] = "Добрый день. Хорошее время сдать задания и посмотреть, что нового.",
	["Buff activo"] = "Бафф активен",
	["Buff fuera de combate"] = "Бафф вне боя",
	["Buffs"] = "Положительные эффекты",
	["Build completo"] = "Билд завершен",
	["Build importado"] = "Импортированный билд",
	["Build importado de una cadena. Alfa lo resuelve en tu árbol y te avisa si algún talento no existe."] = "Билд, импортированный из строки. Alfa сопоставляет его с вашим деревом и предупреждает, если какого-то таланта нет.",
	["Busca %s en: %s."] = "Ищи %s здесь: %s.",
	["Busca addons que chocan con Alfa, partes apagadas y ajustes raros, con el arreglo a un clic. También con /alfa diagnostico."] = "Ищет аддоны, которые конфликтуют с Alfa, выключенные части и странные настройки, с исправлением в один щелчок. Также /alfa diagnostico.",
	["Busca al entrenador de tu clase en la ciudad."] = "Найдите учителя своего класса в городе.",
	["Busca cualquier cosa del juego"] = "Найдите что угодно в игре",
	["Busca cualquier cosa, en español o en inglés…"] = "Ищите что угодно, на испанском или английском…",
	["Busca el arma de dos manos con más daño por segundo: es lo que más sube tu daño."] = "Ищите двуручное оружие с наибольшим уроном в секунду: оно сильнее всего повышает ваш урон.",
	["Busca el arma de dos manos más lenta y fuerte: tus sellos pegan con ella."] = "Ищите самое медленное и сильное двуручное оружие: ваши печати бьют вместе с ним.",
	["Busca la zona de la misión entre las guías de subir de nivel."] = "Найдите зону задания среди гайдов прокачки.",
	["Busca lo mejor que puedes usar"] = "Найти лучшее, что вам доступно",
	["Busca por aquí"] = "Искать поблизости",
	["Busca siempre el arco, arma de fuego o ballesta con más daño por segundo."] = "Всегда ищите лук, огнестрельное оружие или арбалет с наибольшим уроном в секунду.",
	["Busca un escudo con valor de bloqueo alto: sube el daño de Embate con escudo."] = "Ищите щит с высоким показателем блока: он повышает урон Мощного удара щитом.",
	["Busca un objeto en las bolsas, bancos y equipo de todos tus personajes. Los demás, con lo último que guardó Alfa."] = "Найди предмет в сумках, банках и экипировке всех персонажей. Остальные — по последним данным, сохраненным Alfa.",
	["Busca una misión, un PNJ, una zona o una palabra…"] = "Ищите задание, NPC, зону или слово…",
	["Busca una versión nueva de Alfa"] = "Проверить новую версию Alfa",
	["Busca y elige un objeto."] = "Найдите и выберите предмет.",
	["Busca y elige una misión."] = "Найдите и выберите задание.",
	["Buscador"] = "Поиск",
	["Buscando a la manada…"] = "Ищем стаю…",
	["Buscando a un oficial..."] = "Ищем офицера...",
	["Buscando lo mejor para tu nivel…"] = "Ищем лучшее для вашего уровня…",
	["Buscando misiones cerca..."] = "Ищем задания поблизости...",
	["Buscando otras misiones..."] = "Ищем другие задания...",
	["Buscando otro plano"] = "Поиск другого слоя",
	["Buscando su rastro..."] = "Ищем след...",
	["Buscando..."] = "Поиск...",
	["Buscar"] = "Поиск",
	["Buscar ajustes"] = "Поиск настроек",
	["Buscar cerca"] = "Найти рядом",
	["Buscar cerca (vuelo, posada, reparar...)"] = "Найти рядом (полет, таверна, ремонт...)",
	["Buscar cerca no está disponible."] = "«Найти рядом» недоступно.",
	["Buscar cerca y tus planes"] = "«Найти рядом» и ваши планы",
	["Buscar cerca..."] = "Найти рядом...",
	["Buscar cerca:"] = "Найти рядом:",
	["Buscar cerca: vuelo, posada, banco…"] = "Найти рядом: полет, таверна, банк…",
	["Buscar en el diario"] = "Поиск в журнале",
	["Buscar en todos tus personajes"] = "Искать у всех персонажей",
	["Buscar equipo para mi nivel"] = "Найти экипировку для моего уровня",
	["Buscar guías por nombre o zona"] = "Искать гайды по названию или зоне",
	["Buscar otra vez"] = "Искать снова",
	["Buscar por nombre, zona o quién lo mandó"] = "Искать по имени, зоне или отправителю",
	["Buscar un lugar..."] = "Найти место...",
	["Buscar «%s» en la Enciclopedia"] = "Найти «%s» в «Энциклопедии»",
	["Buscar: pasto, niebla, sombras..."] = "Поиск: трава, туман, тени...",
	["Buzones, entrenadores, banco, subasta, reparar..."] = "Почтовые ящики, учителя, банк, аукцион, ремонт...",
	["Buzón"] = "Почтовый ящик",
	["Básico"] = "Базовый",
	["Búscalo en %s."] = "Ищи в: %s.",
	["Búscalo en la Enciclopedia: objetos, PNJ, misiones, zonas y raros, con dónde están y el botón «Guíame»."] = "Ищи в Энциклопедии: предметы, НИП, задания, зоны и редкие, где они и кнопка «Веди меня».",
	["Búscalo por su nombre; se cumple cuando lo tienes en tus bolsas."] = "Найдите его по названию; цель выполнена, когда он у вас в сумках.",
	["CPS"] = "HPS",
	["Cabeza"] = "Голова",
	["Cada 2 niveles"] = "Каждые 2 уровня",
	["Cada Aspecto guía un vuelo de dragones: Alexstrasza el rojo, Ysera el verde, Nozdormu el bronce, Malygos el azul y Neltharion el negro."] = "Каждый Аспект ведет стаю драконов: Алекстраза — красных, Изера — зеленых, Ноздорму — бронзовых, Малигос — синих, Нелтарион — черных.",
	["Cada ajuste que Alfa cambió vuelve al valor que tenía antes. Los filtros no cambian."] = "Каждая настройка, которую изменил Alfa, возвращается к прежнему значению. Фильтры не меняются.",
	["Cada aviso y cada porqué sale con texto hasta %d veces y luego solo queda el ícono."] = "Каждое оповещение и каждая причина показываются с текстом до %d раз, потом остается только значок.",
	["Cada año, el día que empezaron a cazar juntos, Lya lo festeja. Y también el cumpleaños de Alfa."] = "Каждый год в день, когда вы начали охотиться вместе, Лия празднует. И день рождения Alfa тоже.",
	["Cada bloqueo te da ira: nunca te falta."] = "Каждый блок дает ярость: ее всегда хватает.",
	["Cada bolsa en su bloque, con su nombre y su espacio."] = "Каждая сумка — отдельным блоком, с названием и местом.",
	["Cada botón de acción con el borde y el fondo del estilo, el ícono cuadrado y la letra de Alfa en la tecla y la cuenta."] = "Каждая кнопка действия с рамкой и фоном стиля, квадратным значком и шрифтом Alfa на клавише и счетчике.",
	["Cada casilla en su lugar, como en tus bolsas."] = "Каждая ячейка на своем месте, как в ваших сумках.",
	["Cada clase da retos del Legado al llegar a 25, 45 y 60: subir otras clases también le suma a tu cuenta."] = "Каждый класс дает испытания «Наследия» на 25, 45 и 60-м уровнях: прокачка других классов тоже идет в зачет учетной записи.",
	["Cada clic que cura también selecciona a ese compañero, para seguir con otro poder, un buff o quitarle una maldición o un veneno."] = "Каждый лечащий щелчок еще и берет союзника в цель, чтобы продолжить другой способностью, положительным эффектом или снять проклятие или яд.",
	["Cada cofre o tesoro conocido."] = "Каждый известный сундук или сокровище.",
	["Cada crítico hace sangrar."] = "Каждый критический удар вызывает кровотечение.",
	["Cada domingo en Tuercespina: el primero en llevar 40 pescados sabrosos de los bancos especiales gana. También salen peces raros que se cambian por premios."] = "Каждое воскресенье в Тернистой долине: побеждает тот, кто первым принесет 40 пятнистых вкуснорыбок из особых косяков. Ловятся и редкие рыбы, которые меняют на призы.",
	["Cada entrada de mazmorra y banda con su rango de niveles. Clic: su página; Mayús+clic: la flecha te lleva."] = "Каждый вход в подземелье и рейд с диапазоном уровней. Щелчок: его страница; Shift+щелчок: стрелка поведет туда.",
	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "Каждая фраза звучит не больше трех раз. Это вернет их все с самого начала.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "Каждый критический удар оставляет противника истекать кровью: дополнительный урон без усилий.",
	["Cada grupo de la banda en su propia columna (o fila), como en la ventana de banda. Con el orden por grupo."] = "Каждая группа рейда в своем столбце (или строке), как в окне рейда. С сортировкой по группам.",
	["Cada hierba pide más habilidad que la anterior: recoge todo lo que puedas y sube sola. Enciende el rastreo de hierbas."] = "Каждая трава требует больше навыка, чем прошлая: собирай все, что можешь, и навык растет сам. Включи поиск трав.",
	["Cada hierba tiene su lugar: unas junto al agua, otras en las montañas o bajo los árboles."] = "У каждой травы свое место: одни растут у воды, другие в горах или под деревьями.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "Каждое известное место, где появляется редкий противник.",
	["Cada lunes te pongo tres retos chiquitos: misiones, raros y uno sorpresa. Tu avance está en mi página y cada reto cumplido vale una salchicha de premio."] = "Каждый понедельник я даю тебе три маленьких испытания: задания, редкие и одно сюрприз. Прогресс на моей странице, а каждое выполненное стоит сосиски в награду.",
	["Cada lunes, tres retos chiquitos con su salchicha de premio. Tu avance sale arriba, en esta página."] = "Каждый понедельник — три маленьких испытания с сосиской в награду. Прогресс виден вверху этой страницы.",
	["Cada meseta de Cima del Trueno tiene su función: una para los ancianos y los druidas, otra para los espíritus y otra para los cazadores."] = "У каждой месы Громового Утеса свое назначение: одна для старейшин и друидов, другая для духов, третья для охотников.",
	["Cada misión que terminas te hace más fuerte."] = "Каждое выполненное задание делает тебя сильнее.",
	["Cada muelle con cuánto falta para que llegue su barco o zepelín."] = "Каждый причал — сколько осталось до прибытия корабля или дирижабля.",
	["Cada muelle con cuánto falta para que llegue."] = "Каждый причал — сколько осталось до прибытия.",
	["Cada nivel"] = "Каждый уровень",
	["Cada paso de la bienvenida deja bajar hasta el final, sin cerrar y volver a abrir."] = "Каждый шаг приветствия прокручивается до самого конца — не нужно закрывать и открывать заново.",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "Каждый набор заполняет щелчки уже известными вам заклинаниями. Потом можно изменить что угодно на странице «Исцеление».",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "Каждое испытание дает 1 очко. На запуске Forever испытаний: %d, и каждый персонаж может потратить до %d.",
	["Cada semana guardo una copia de tus ajustes y perfiles. En Ajustes > Estilo y sonido, en «Respaldos», vuelves a una con un clic."] = "Каждую неделю я сохраняю копию твоих настроек и профилей. В «Настройки > Стиль и звук», в «Резервные копии», возвращаешься к ней одним щелчком.",
	["Cada versión nueva te recibe con la intro del lobo y sus notas, como estas."] = "Каждая новая версия встречает вас вступлением с волком и своими заметками, вроде этих.",
	["Cada vez que aprendes uno de los principales de tu clase te digo en corto para qué sirve y cuándo usarlo."] = "Каждый раз, когда ты учишь одно из главных заклинаний класса, я коротко рассказываю, для чего оно и когда его применять.",
	["Cada vez que entras al juego, la intro del lobo y la luna te da la bienvenida. Un clic o Esc la saltan."] = "При каждом входе в игру вас встречает заставка с волком и луной. Клик или Esc её пропускают.",
	["Cada vez: %s."] = "Каждый раз: %s.",
	["Cada zona con lobos y cuántos hay en cada guarida. En el mapa del mundo también sale."] = "Каждая зона с волками и сколько их в каждом логове. На карте мира тоже видно.",
	["Cada ícono del mapa con su tamaño exacto en tu pantalla, nítido de orilla a orilla."] = "Каждый значок на карте точного размера на вашем экране, чёткий от края до края.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "Кэрн Кровавое Копыто правит из Громового Утеса, хотя Магата из Зловещего Тотема любит его не так сильно, как делает вид.",
	["Cairne Pezuña de Sangre peleó en el Monte Hyjal junto a Thrall contra la Legión."] = "Кэрн Кровавое Копыто сражался на горе Хиджал бок о бок с Траллом против Легиона.",
	["Caja para escribir con el estilo"] = "Поле ввода в стиле",
	["Calculando"] = "Расчет",
	["Calculando la vuelta más corta…"] = "Рассчитываем самый короткий круг…",
	["Calidad"] = "Качество",
	["Calidad de la niebla"] = "Качество тумана",
	["Calidad de las sombras"] = "Качество теней",
	["Calla las voces de /bailar, /reír, /aplaudir y otros gestos."] = "Заглушает голоса эмоций /танец, /смех, /аплодировать и других.",
	["Calla los ruidos de las mascotas, como el bostezo de los gatos de cazador."] = "Заглушает звуки питомцев, например зевание кошек охотника.",
	["Calma, que la cacería no se va a ningún lado. Come algo, repara y, si es mucho, la manada te echa la mano."] = "Спокойно, охота никуда не денется. Поешь, почини снаряжение, а если тяжело, стая подставит лапу.",
	["Cambia a «Todo» para ver su botín completo."] = "Переключитесь на «Все», чтобы увидеть всю добычу.",
	["Cambia al mapa de Alfa en esta zona: todo el mundo en un solo mapa, con zoom y tus marcadores."] = "Переключает на карту Alfa в этой зоне: весь мир на одной карте, с масштабом и вашими маркерами.",
	["Cambia de plano cuando está lleno, «¿Quién tiene...?» y los festejos de la manada."] = "Смена слоя, когда людно, «У кого есть...?» и праздники стаи.",
	["Cambia el modo limpio del mapa"] = "Переключает чистый режим карты",
	["Cambia lo que quieras: se guarda al momento."] = "Меняйте что угодно: все сохраняется сразу.",
	["Cambiar"] = "Сменить",
	["Cambiar de forma te quita lentitudes y raíces: úsalo para escapar."] = "Смена облика снимает замедления и обездвиживание: используйте ее, чтобы сбежать.",
	["Cambiar de plano"] = "Сменить слой",
	["Cambiar de plano si está lleno"] = "Менять слой, когда людно",
	["Cambiar de plano: te pasa al de un lobo de la manada con su guarida abierta"] = "Сменить слой: переносит в слой волка из стаи с открытым логовом",
	["Cambiar el tamaño"] = "Изменить размер",
	["Cambiar esta meta"] = "Изменить эту цель",
	["Cambiar guía"] = "Сменить гайд",
	["Cambiar la meta"] = "Изменить цель",
	["Cambiar nombre..."] = "Переименовать...",
	["Cambiar o borrar"] = "Изменить или удалить",
	["Cambias de actitud según la pelea sin perder ira."] = "Вы меняете стойку по ходу боя, не теряя ярости.",
	["Cambias de actitud sin perder ira."] = "Вы меняете стойку, не теряя ярости.",
	["Cambias de actitud sin perder ira: puedes pasar a defensiva cuando se complica."] = "Вы меняете стойку, не теряя ярости: можно перейти в оборонительную, когда становится трудно.",
	["Cambias vida por maná. Úsalo y luego recupera tu vida comiendo."] = "Меняет здоровье на ману. Примени, потом поешь, чтобы вернуть здоровье.",
	["Cambiaste %d ajustes aquí. Volver a ponerlos al entrar está apagado (Avanzado)."] = "Вы изменили здесь настроек: %d. Повторное применение при входе выключено (Дополнительно).",
	["Camina"] = "Пешком",
	["Camina por el agua: espérenlo en tierra y atráiganlo con un ataque a distancia."] = "Он ходит по воде: ждите его на суше и выманите атакой издалека.",
	["Caminar"] = "Ходьба",
	["Camino al 60"] = "Путь к 60",
	["Camisa"] = "Рубашка",
	["Campana"] = "Колокольчик",
	["Campo de visión"] = "Поле зрения",
	["Canal oculto: %s (%s, número %s, intentos %d)"] = "Скрытый канал: %s (%s, номер %s, попыток %d)",
	["Cancelar"] = "Отмена",
	["Cantidad: %d"] = "Количество: %d",
	["Capas de Alfa"] = "Слои Alfa",
	["Capas de Alfa: elige qué se ve en el mapa"] = "Слои Alfa: выберите, что видно на карте",
	["Capas del mapa"] = "Слои карты",
	["Capas en la lupa del mapa del juego"] = "Слои в меню лупы на карте игры",
	["Capturas"] = "Улов",
	["Capturas: %d de %d"] = "Улов: %d из %d",
	["Carbón cálido y el naranja de las brasas, como la manada junto al fuego."] = "Теплый уголь и оранжевый отблеск углей, как стая у костра.",
	["Carcaj"] = "Колчан",
	["Carcajs"] = "Колчаны",
	["Cargando los datos…"] = "Загрузка данных…",
	["Cargando tus cartas..."] = "Загружаю твою почту...",
	["Cargando…"] = "Загрузка…",
	["Cargar en actitud defensiva."] = "Рывок в Оборонительной стойке.",
	["Cargar en actitud defensiva: empiezas cada pelea sin cambiar de actitud."] = "Рывок в Оборонительной стойке: вы начинаете каждый бой, не меняя стойку.",
	["Cargar te da más ira al empezar: la pelea arranca a tu favor."] = "Рывок дает больше ярости в начале: бой начинается в вашу пользу.",
