	["Cebos"] = "Приманки",
	["Cecina dura"] = "Жесткое вяленое мясо",
	["Celestes"] = "Небесные",
	["Cenarius, el señor del bosque, es hijo de Malorne, el Ciervo Blanco. Los druidas de la Alianza y de la Horda lo honran por igual."] = "Кенарий, повелитель леса, — сын Малорна, Белого Оленя. Друиды Альянса и Орды почитают его одинаково.",
	["Ceniza"] = "Пепел",
	["Central"] = "Средняя",
	["Centrar en mí"] = "Центрировать на мне",
	["Cerca de Gnomeregan verás gnomos leprosos: los que se quedaron atrás cuando la radiación llenó su ciudad."] = "Возле Гномрегана ты увидишь прокаженных гномов — тех, кто остался, когда радиация заполнила их город.",
	["Cerca de la entrada hay un gong: tocarlo trae oleadas de arañas y luego un jefe."] = "Рядом со входом есть гонг: удар в него вызывает волны пауков, а затем босса.",
	["Cerca de ti"] = "Рядом с вами",
	["Cerca de ti: %s"] = "Рядом с вами: %s",
	["Cerca de ti: %s."] = "Вокруг тебя: %s.",
	["Cerca del suelo, la cámara gira sobre tu personaje en lugar de chocar."] = "У самой земли камера поворачивается вокруг персонажа, а не упирается.",
	["Cerrada"] = "Закрыто",
	["Cerrada: hiciste otra que la excluye"] = "Закрыто: вы выполнили другое, исключающее его",
	["Cerrada: nadie te pide entrar. Ábrela para echarle la mano a la manada."] = "Закрыто: никто не просится. Открой, чтобы помочь стае.",
	["Cerrar"] = "Закрыть",
	["Cerrar el modo al montar"] = "Закрывать режим, когда вы садитесь на транспорт",
	["Cerrar el modo pesca"] = "Закрыть режим рыбалки",
	["Cerrar esta pestaña"] = "Закрыть эту вкладку",
	["Cerrar la ventana"] = "Закрыть окно",
	["Cerrar la ventana de Alfa"] = "Закрыть окно Alfa",
	["Cerrar lo que tu guía salta"] = "Закрывать то, что гайд пропускает",
	["Cerrar mi guarida"] = "Закрыть моё логово",
	["Cerrar mis misiones"] = "Закрыть мои задания",
	["Cerrar mis misiones antes"] = "Сначала закрыть мои задания",
	["Cerrar todas mis misiones"] = "Закрыть все мои задания",
	["Cerraste tu guarida."] = "Ты закрыл своё логово.",
	["Cerrotajo es el primer pueblo orco grande que encuentras en Durotar; desde ahí se cuida el camino entre el Valle de los Retos y Orgrimmar."] = "Колючий Холм — первый большой город орков в Дуротаре; отсюда охраняют дорогу между Долиной Испытаний и Оргриммаром.",
	["Chamán"] = "Шаман",
	["Chatarra"] = "Хлам",
	["Chispas, humo, polvo y efectos de hechizos."] = "Искры, дым, пыль и эффекты заклинаний.",
	["Chocar con el agua"] = "Столкновение с водой",
	["Choque sagrado: daño instantáneo, cada vez que esté listo."] = "Шок небес: мгновенный урон, применяйте при каждой готовности.",
	["Choque: daño instantáneo."] = "Шок: мгновенный урон.",
	["Choques de la cámara"] = "Столкновения камеры",
	["Chuleta de cordero"] = "Баранья отбивная",
	["Ciega a un enemigo un rato. Útil para salir de una pelea mala."] = "Ослепляет врага на время. Полезно, чтобы выйти из неудачного боя.",
	["Cielo y clima"] = "Небо и погода",
	["Cien al cesto"] = "Сотня в корзине",
	["Cierra la ventana de talentos y hechizos del juego y vuelve a aplicar"] = "Закройте окно талантов и заклинаний игры и примените снова",
	["Cierra misiones de %s"] = "Завершите задания: %s",
	["Cierra misiones de esta zona"] = "Заверши задания в этой зоне",
	["Cierra una pestaña para abrir esta guía."] = "Закройте вкладку, чтобы открыть этот гайд.",
	["Cierra una pestaña para abrir otra."] = "Закройте вкладку, чтобы открыть другую.",
	["Cierra una pestaña para abrir tu plan."] = "Закройте вкладку, чтобы открыть план.",
	["Cierra una pestaña para abrir tu ruta."] = "Закройте вкладку, чтобы открыть маршрут.",
	["Cincuenta. Casi en la cima, y yo contigo."] = "Пятьдесят. Почти на вершине, и я с тобой.",
	["Cintura"] = "Пояс",
	["Circuito de %s"] = "Обход: %s",
	["Circuito de la zona"] = "Обход зоны",
	["Citas de la manada"] = "Сборы стаи",
	["Citas de la manada, «¿Quién va?», raros con reloj y notas en tu mapa."] = "Сборы стаи, «Кто идет?», таймеры редких и заметки на твоей карте.",
	["Citas y notas sin compartir tu ubicación, el oro del buzón aparte y Alfa más ligero."] = "Встречи и заметки без показа твоего местоположения, золото из почты отдельно и более лёгкая Alfa.",
	["Ciudad"] = "Город",
	["Ciudad Manitas, dentro de Forjaz, es el barrio de los gnomos: ruido, vapor e inventos por todos lados."] = "Город Механиков в Стальгорне — квартал гномов: шум, пар и изобретения повсюду.",
	["Clase"] = "Класс",
	["Clases (27): llegar a nivel 25, 45 y 60 con cada una de las 9 clases."] = "Классы (27): достичь 25, 45 и 60-го уровня каждым из 9 классов.",
	["Clic derecho (o Mayús+clic): un marcador ahí. Ctrl+clic: la flecha y la ruta te llevan ahí sin guardar nada."] = "Правый щелчок (или Shift+щелчок): маркер там. Ctrl+щелчок: стрелка и маршрут ведут туда, ничего не сохраняя.",
	["Clic derecho en la misión, en tu registro o en el rastreador: «Ver la cadena completa». Te digo cuáles hiciste y el premio del final."] = "Правый щелчок по заданию в журнале или в отслеживании: «Показать всю цепочку». Я скажу, какие ты выполнил, и итоговую награду.",
	["Clic derecho en su retrato o en su nombre del chat y elige «Invitar al clan». A tu hermandad le llega con un clic."] = "Правый клик по портрету или имени в чате и «Пригласить в клан». В гильдию приглашение уходит в один клик.",
	["Clic derecho en un jugador (su retrato, su nombre en el chat o tu grupo) y elige tu hermandad: la invitación le llega sin escribir su nombre. Para una comunidad, Alfa te deja el nombre listo para pegar en la ventana del juego."] = "Щёлкните правой кнопкой по игроку (по портрету, имени в чате или в вашей группе) и выберите гильдию: приглашение придёт без ввода имени. Для сообщества Alfa подготовит имя, чтобы вставить его в окно игры.",
	["Clic derecho en un jugador y «Invitar al clan»: eliges tu hermandad o tu comunidad y la invitación le llega sin escribir su nombre."] = "Правый клик по игроку и «Пригласить в гильдию или сообщество»: выберите гильдию или сообщество, и приглашение придёт без ввода имени.",
	["Clic derecho: dejarla sin acción."] = "Правый щелчок: оставить без действия.",
	["Clic derecho: opciones de esta guía"] = "Правый щелчок: настройки этого гайда",
	["Clic derecho: reiniciar, quitar o llevar a Mis planes."] = "Правый щелчок: начать заново, убрать или отправить в «Мои планы».",
	["Clic en Llévame: la flecha te lleva"] = "Нажмите «Отведи меня»: стрелка поведет вас",
	["Clic en un marcador: su ficha (cambiarlo, compartirlo, borrarlo o seguirlo). Mayús+clic: seguirlo de una vez. Clic derecho en cualquier otro pin: seguirlo o guardarlo como marcador."] = "Щелчок по маркеру: его карточка (изменить, поделиться, удалить или следовать). Shift+щелчок: сразу следовать. Правый щелчок по любой другой метке: следовать или сохранить как маркер.",
	["Clic en una casilla para elegir qué hace sobre el compañero bajo tu ratón; clic derecho la deja sin acción. Los cambios se aplican fuera de combate."] = "Щелкните по ячейке, чтобы выбрать, что она делает с союзником под курсором; правый щелчок оставляет ее без действия. Изменения применяются вне боя.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta."] = "Щелкните по одному: карта Alfa переместится к нему. «Следовать» включает стрелку и маршрут.",
	["Clic en uno: el mapa de Alfa va hasta él. «Seguir» pone la flecha y la ruta; la huella del grupo lo comparte con quien use Alfa."] = "Щелкните по одному: карта Alfa переместится к нему. «Следовать» включает стрелку и маршрут; след лапы делится им с теми, кто пользуется Alfa.",
	["Clic en uno: el mapa va hasta él. Clic derecho en el mapa: uno nuevo."] = "Щелкните по одному: карта переместится к нему. Правый щелчок по карте: новый маркер.",
	["Clic o Esc para saltar"] = "Щелчок или Esc — пропустить",
	["Clic para asignar"] = "Щелкните, чтобы назначить",
	["Clic para comprarla."] = "Щелкните, чтобы купить.",
	["Clic para desplegar."] = "Щелкните, чтобы развернуть.",
	["Clic para detener."] = "Щелчок — остановить.",
	["Clic para elegir"] = "Щелкните, чтобы выбрать",
	["Clic para plegar o desplegar"] = "Щелкните, чтобы свернуть или развернуть",
	["Clic para plegar."] = "Щелкните, чтобы свернуть.",
	["Clic: Guíame"] = "Щелчок: «Веди меня»",
	["Clic: Guíame a conseguirlo."] = "Щелчок: «Веди меня» к получению.",
	["Clic: Guíame a la misión."] = "Щелчок: «Веди меня» к заданию.",
	["Clic: Guíame al banco."] = "Щелчок: «Веди меня» к косяку.",
	["Clic: a la cola de cocina."] = "Щелчок: в очередь готовки.",
	["Clic: abre %s."] = "Щелчок: открыть %s.",
	["Clic: abre La Jauría."] = "Щелчок: открыть La Jauría.",
	["Clic: abre su página con sus misiones, jefes y entrada."] = "Щелчок: открыть его страницу с заданиями, боссами и входом.",
	["Clic: abre tu plan para verlo o cambiarlo."] = "Щелчок: открывает план, чтобы посмотреть или изменить его.",
	["Clic: abrir o cerrar la ventana de Alfa"] = "Щелчок: открыть или закрыть окно Alfa",
	["Clic: abrir su guía de 1 a 300."] = "Щелчок: открыть гид с 1 до 300.",
	["Clic: agregarlo a tu lista de compras."] = "Щелчок: добавить в список покупок.",
	["Clic: el mapa muestra todo el camino, de ti al destino."] = "Щелчок: карта покажет весь путь, от тебя до цели.",
	["Clic: elegir otra guía"] = "Щелчок: выбрать другой гайд",
	["Clic: elegir qué hace."] = "Щелчок: выбрать действие.",
	["Clic: elegir qué hace. Clic derecho: dejarla sin acción."] = "Щелчок: выбрать действие. Правый щелчок: оставить без действия.",
	["Clic: guardar este en el banco."] = "Щелчок: убрать это в банк.",
	["Clic: ir de caza"] = "Щелчок: на охоту",
	["Clic: la flecha te lleva"] = "Щелчок: стрелка поведет вас",
	["Clic: la flecha te lleva al muelle."] = "Щелчок: стрелка поведет к причалу.",
	["Clic: la flecha te lleva al más cercano, por tiempo de camino."] = "Щелчок: стрелка ведет к ближайшему по времени пути.",
	["Clic: la flecha te lleva aquí."] = "Щелчок: стрелка поведет сюда.",
	["Clic: la flecha te lleva."] = "Щелчок: стрелка отведет тебя.",
	["Clic: la flecha te lleva. Clic derecho: ya no mostrarla."] = "Щелчок: стрелка поведет вас. Правый щелчок: больше не показывать.",
	["Clic: la lista de pasos. Rueda: mirar otros pasos sin cambiar nada."] = "Щелчок: список шагов. Колесо: посмотреть другие шаги, ничего не меняя.",
	["Clic: ocultarlo en el modelo."] = "Щелчок: скрыть на модели.",
	["Clic: opciones  ·  Mayús+clic: seguir"] = "Щелчок: настройки  ·  Shift+щелчок: следовать",
	["Clic: ponerlo en tu caña. Clic derecho: usarlo siempre que tu tecla ponga cebo."] = "Щелчок: наложить на удочку. Правый щелчок: использовать всегда, когда клавиша накладывает приманку.",
	["Clic: ponértelo."] = "Щелчок: надеть.",
	["Clic: quitar de la cola."] = "Щелчок: убрать из очереди.",
	["Clic: quitarla de tu lista."] = "Щелчок: убрать из списка.",
	["Clic: resalta lo que lleva."] = "Щелчок: подсветить содержимое.",
	["Clic: seguir con la flecha"] = "Щелчок: следовать по стрелке",
	["Clic: un consejo. Clic derecho: mis opciones."] = "Щелчок: совет. Правый щелчок: мои настройки.",
	["Clic: un consejo. Clic derecho: mis opciones. Arrástrame para moverme."] = "Щелчок: совет. Правый щелчок: мои настройки. Перетащи меня, чтобы передвинуть.",
	["Clic: un consejo. Clic derecho: «¿En qué te ayudo?» y mis opciones."] = "Клик: совет. Правый клик: «Чем помочь?» и мои настройки.",
	["Clic: un consejo. Clic derecho: «¿En qué te ayudo?» y mis opciones. Arrástrame para moverme."] = "Клик: совет. Правый клик: «Чем помочь?» и мои настройки. Перетащи меня, чтобы подвинуть.",
	["Clic: ver su diario en Alfa"] = "Щелчок: открыть его журнал в Alfa",
	["Clic: volver a ponerlo."] = "Щелчок: надеть обратно.",
	["Clima"] = "Погода",
	["Clásico WoW"] = "Классический WoW",
	["Clásico, el arte pintado del juego"] = "Классическая, нарисованная карта игры",
	["Cobra tus %d misiones listas"] = "Сдайте готовые задания: %d",
	["Cobre, estaño, hierro, mitril y torio: así sube un minero, con plata y oro de vez en cuando."] = "Медь, олово, железо, мифрил и торий — так растет шахтер, а иногда попадаются серебро и золото.",
	["Cocina"] = "Кулинария",
	["Cocina %d"] = "Кулинария %d",
	["Cocina %d/%d"] = "Кулинария %d/%d",
	["Cocina 10 lotes desde tu cola de cocina."] = "Приготовьте 10 партий из очереди готовки.",
	["Cocina 100 piezas de pescado."] = "Приготовьте 100 порций рыбы.",
	["Cocina junto al agua"] = "Кухня у воды",
	["Cocina va de la mano con Pesca: tú pescas y tú cocinas."] = "Кулинария идет рука об руку с рыбной ловлей: ты ловишь рыбу, ты же ее и готовишь.",
	["Cocinando %d de %s"] = "Готовится %d: %s",
	["Cocinar el siguiente lote"] = "Приготовить следующую партию",
	["Codorniz asada"] = "Жареный перепел",
	["Cofre"] = "Сундук",
	["Cofres, baúles y almejas que se abren."] = "Сундуки, сундучки и моллюски, которые можно открыть.",
	["Coleccionables"] = "Коллекции",
	["Coleccionista del agua"] = "Собиратель вод",
	["Colmillo"] = "Клык",
	["Color"] = "Цвет",
	["Color de clase"] = "Цвет класса",
	["Colores de clase en los marcos"] = "Цвета классов на рамках",
	["Colores de clase en los marcos, un cuadro de información más útil, el probador mejorado, la siguiente parada en los vuelos y sin voces de error. Cada una se apaga abajo cuando quieras."] = "Цвета классов на рамках, более полезная подсказка, улучшенная примерочная, следующая остановка в полетах и без голосовых ошибок. Каждую можно выключить ниже в любой момент.",
	["Colores para daltonismo"] = "Цвета для дальтоников",
	["Columnas"] = "Столбцы",
	["Comando"] = "Команда",
	["Comandos de Ruta:"] = "Команды «Маршрута»:",
	["Combate"] = "Бой",
	["Combate feral"] = "Сила зверя",
	["Combate feral para subir"] = "Сила зверя для прокачки",
	["Combate para subir"] = "Бой для прокачки",
	["Combustión: tus hechizos de fuego hacen más críticos un rato."] = "Возгорание: ваши заклинания огня какое-то время чаще наносят критический урон.",
	["Combínala con Encantamiento para desencantar lo que coses y no uses."] = "Совмести с наложением чар, чтобы распылять то, что ты шьешь и не носишь.",
	["Combínala con Herboristería: así recoges tú lo que necesitas."] = "Совмести с травничеством: так все нужное ты соберешь своими руками.",
	["Combínala con Minería: casi todo lo que fabricas lleva metal."] = "Совмести с горным делом: почти все, что ты мастеришь, требует металла.",
	["Combínalo con Sastrería: la tela te da objetos verdes para desencantar."] = "Совмести с портняжным делом: ткань дает зеленые предметы для распыления.",
	["Come y bebe entre peleas: recuperas vida y maná mucho más rápido."] = "Ешь и пей между боями: здоровье и мана восстанавливаются намного быстрее.",
	["Comentario"] = "Комментарий",
	["Comentarios de la zona"] = "Комментарии о зоне",
	["Comentarios del momento"] = "Комментарии к моменту",
	["Comerciante"] = "Торговец",
	["Comerciante:"] = "Торговец:",
	["Comerciantes"] = "Торговцы",
	["Comerciantes y viajes"] = "Торговцы и путешествия",
	["Comercio"] = "Торговля",
	["Comercio te dice qué vale más en la subasta que con el comerciante, y cuánto pedir."] = "«Торговля» подскажет, что на аукционе дороже, чем у торговца, и сколько просить.",
	["Comida que da aguante o fuerza extra, y comes mientras descansas."] = "Еда, которая дает дополнительную выносливость или силу; ее едят во время отдыха.",
	["Comida y agua"] = "Еда и вода",
	["Comida y agua para llevar"] = "Сколько еды и воды носить",
	["Comida y bebida"] = "Еда и напитки",
	["Comida, bebida y más"] = "Еда, напитки и прочее",
	["Comida: llevas %d (mejor %d o más). A tu nivel: %s"] = "Еда: у тебя %d (лучше %d или больше). Для твоего уровня: %s",
	["Comisión de la subasta"] = "Комиссия аукциона",
	["Comisión de la subasta estimada: %d%%."] = "Примерная комиссия аукциона: %d%%.",
	["Como el juego"] = "Как в игре",
	["Como espíritu, Lya te dice a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "Когда ты дух, Лия говорит, далеко ли тело, сколько стоит целитель душ на твоем уровне и что лучше. Стрелка отведет тебя.",
	["Como están"] = "Как есть",
	["Como guerrero no te curas solo: Primeros auxilios y algo de comida te salvan entre peleas."] = "Воин не умеет лечить себя: первая помощь и немного еды спасут тебя между боями.",
	["Como juegas, llegas en 1 día."] = "В твоем темпе доберешься за 1 день.",
	["Como juegas, llegas en unos %d días."] = "В твоем темпе доберешься примерно за %d дн.",
	["Comodidades"] = "Удобства",
	["Comparar con lo que llevas"] = "Сравнить с надетым",
	["Comparar equipo con mi build"] = "Сравнивать снаряжение по моему билду",
	["Comparte %s"] = "Поделитесь: %s",
	["Comparte por ti"] = "Делится за вас",
	["Comparte tu ubicación para ver las guaridas de la manada."] = "Поделись своим местоположением, чтобы видеть логова стаи.",
	["Comparte tus talentos"] = "Поделитесь талантами",
	["Compartido por %s"] = "Отправитель: %s",
	["Compartir"] = "Поделиться",
	["Compartir con el grupo"] = "Поделиться с группой",
	["Compartir con la manada"] = "Поделиться со стаей",
	["Compartir esta ruta"] = "Поделиться маршрутом",
	["Compartir mi clase y nivel"] = "Делиться классом и уровнем",
	["Compartir mi semana"] = "Делиться моей неделей",
	["Compartir mis logros"] = "Делиться моими достижениями",
	["Compartir mis spots"] = "Делиться моими местами",
	["Compartir..."] = "Поделиться...",
	["Compartiste %s con tu grupo."] = "Вы поделились «%s» с группой.",
	["Compañeros por columna"] = "Союзников в столбце",
	["Completa"] = "Собрано",
	["Completa el objetivo"] = "Выполните задачу",
	["Completa o entrega las que tienes abiertas"] = "Выполните или сдайте открытые задания",
	["Completar %s"] = "Выполнить: %s",
	["Completarla"] = "Выполнить",
	["Completas"] = "Полные",
	["Completo"] = "Полный",
	["Componentes"] = "Реагенты",
	["Compra lo que tu paso necesita si el comerciante lo vende. Nada de más de 50 de oro."] = "Покупает то, что нужно шагу, если торговец это продает. Ничего дороже 50 золотых.",
	["Compra tu montura con %s"] = "Купите транспорт у: %s",
	["Comprar"] = "Купить",
	["Comprar comida y bebida"] = "Купить еду и напитки",
	["Comprar lo que falta cuesta más de %s (faltan precios)."] = "Купить недостающее стоит больше %s (некоторых цен нет).",
	["Comprar lo que falta cuesta unos %s."] = "Купить недостающее стоит около %s.",
	["Comprar lo que pide tu guía"] = "Покупать то, что просит гайд",
	["Comprar otra casilla del banco"] = "Купить еще одну ячейку банка",
	["Comprar y vender con otros"] = "Покупать и продавать с другими игроками",
	["Compártela y la hacen juntos."] = "Поделись и выполняйте вместе.",
	["Comunidad"] = "Сообщество",
	["Común"] = "Обычный",
	["Con %s salen dos flechas a la vez. Alfa puede usar la de TomTom y esconder la suya."] = "С %s у тебя две стрелки сразу. Alfa может взять стрелку TomTom и спрятать свою.",
	["Con /alfa reportar: yo ya junté los errores que atrapé, con su versión y cuántas veces salieron. Tú solo lo pegas en el Discord."] = "Через /alfa reportar: я уже собрала пойманные ошибки, с версией и тем, сколько раз они появлялись. Тебе остается вставить это в Discord.",
	["Con /alfa, con el lobo del minimapa o dándome clic derecho. Para hablar conmigo de todo esto: /alfa ayuda."] = "Командой /alfa, волком у миникарты или правым кликом по мне. Поговорить со мной обо всём этом: /alfa ayuda.",
	["Con 10 de furia o más lo lanzas."] = "Применяется при 10 ед. ярости и больше.",
	["Con 2 casillas libres o menos, un aviso con lo primero que puedes soltar y un botón para vender o ver tus bolsas."] = "Когда свободных ячеек 2 или меньше — уведомление с первым, с чем можно расстаться, и кнопка, чтобы продать или открыть сумки.",
	["Con 2 o más misiones listas, el rastreador ofrece llevarte a entregarlas por el camino más corto."] = "Если готово 2 задания или больше, список заданий предложит отвести тебя сдать их кратчайшим путем.",
	["Con Cocina puedes encender tu propia fogata en cualquier lado."] = "С кулинарией можно развести свой костер где угодно.",
	["Con Redención reviven tus compañeros caídos: en una mazmorra vale oro."] = "«Искупление» возвращает к жизни павших соратников: в подземелье это на вес золота.",
	["Con aullido"] = "С воем",
	["Con buena reputación, los vendedores de esa facción te hacen descuento."] = "При хорошей репутации торговцы этой фракции дают скидку.",
	["Con calma, nos pasa a todos. Mira qué te pegó y vuelve con todo."] = "Спокойно, такое бывает со всеми. Посмотри, что тебя ударило, и возвращайся в полную силу.",
	["Con dos amigos, trae hasta aquí a alguien de tu grupo."] = "С двумя друзьями призывает к тебе кого-то из группы.",
	["Con dos armas pega más rápido: guarda maná para el final."] = "С двумя оружиями он бьет быстрее: приберегите ману на конец.",
	["Con el correo puedes enviar contra reembolso: mandas el objeto y cobras al entregarlo."] = "По почте можно отправить наложенным платежом: ты посылаешь предмет, а оплату получаешь при его получении.",
	["Con el cuadro oculto en combate, mantén presionado Mayús para verlo."] = "Когда подсказка скрыта в бою, удерживайте Shift, чтобы ее увидеть.",
	["Con el cursor encima no se cierra."] = "Не закрывается, пока на нем курсор.",
	["Con el entrenador más cercano en tu camino."] = "У ближайшего учителя по пути.",
	["Con el mapa de vuelos abierto, marca el destino más cerca de tu paso de ahora."] = "Когда открыта карта полетов, отмечает пункт, ближайший к текущему шагу.",
	["Con el mapa de vuelos abierto, marco con una huella el destino más cerca de tu paso de ahora."] = "Когда открыта карта полетов, я отмечаю отпечатком лапы пункт, ближайший к твоему текущему шагу.",
	["Con el modo pesca abierto y alguna meta, la ventanita de metas se ve sola."] = "Когда режим рыбалки открыт и есть цель, окошко целей появляется само.",
	["Con el modo pesca abierto, esta tecla lo hace todo: equipo, cebo, lanzar y recoger. Al cerrarlo vuelve a ser la de siempre."] = "При открытом режиме рыбалки эта клавиша делает все: снаряжение, приманка, заброс и подсечка. Когда режим закрыт, клавиша снова работает как обычно.",
	["Con el modo pesca abierto, un aviso suave para volver a lanzar."] = "При открытом режиме рыбалки — мягкое напоминание забросить снова.",
	["Con el tiempo, los magos humanos se reunieron en Dalaran, que se volvió la ciudad de la magia de los Reinos del Este."] = "Со временем маги-люди собрались в Даларане, и он стал городом магии Восточных королевств.",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "С интерфейсом геймпада карта игры открывается своей клавишей.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "При интерфейсе для геймпада Alfa оставляет игровые сумки. Окно Alfa все равно можно открыть отсюда.",
	["Con la tecla en Espacio, Mayús+Espacio salta mientras el modo está abierto."] = "Если клавиша — Пробел, Shift+Пробел прыгает, пока режим открыт.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "С сумками Alfa все видно в одном окне: три вида, поиск, панель сумок и что продать, когда они заполнятся.",
	["Con lo que gastaste: %s."] = "С учетом трат: %s.",
	["Con lo que tienes haces %d: +%s en total"] = "Из того, что есть, сделаешь %d: всего +%s",
	["Con mando, se quedan las bolsas del juego"] = "С геймпадом остаются сумки игры",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "С Shift, Ctrl, Alt или без них. Ничего не применяется: здесь видно, что было бы применено к союзнику.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "При малом запасе здоровья он зовет двух помощников: если ему осталось немного, добейте его; если нет, убейте помощников.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "При малом запасе здоровья он превращается в змея и бьет сильнее: приберегите лучшие атаки на этот момент.",
	["Con qué prioridad sugiere Alfa. Automática: la de tus talentos o, mientras subes, la de tu clase."] = "По какому приоритету подсказывает Alfa. Автоматически: по вашим талантам или, пока вы растете, по вашему классу.",
	["Con reputación %s"] = "При репутации «%s»",
	["Con sonido"] = "Со звуком",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Зная ваш билд, Alfa понимает, какие характеристики вам полезны и какое снаряжение искать.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Свободное очко дает 1 ранг таланта «%s»:",
	["Con tu ritual de invocación y la ayuda de dos compañeros, traes a otro miembro del grupo hasta donde estés."] = "Ритуалом призыва с помощью двух соратников ты переносишь к себе другого участника группы.",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "На ваши %d свободных очков будет изучено %d рангов таланта %s:",
	["Con un brillo suave"] = "С мягким свечением",
	["Con un comerciante abierto vende tu chatarra; con un banquero guarda tus materiales."] = "У торговца продает хлам; у банкира складывает материалы.",
	["Con un comerciante o un banquero abierto, «Acomodar» en tus bolsas vende tu chatarra o guarda tus materiales en el banco. Un clic, y otro para detenerlo."] = "Когда открыт торговец или банкир, «Разобрать» в сумках продает хлам или складывает материалы в банк. Один щелчок — и еще один, чтобы остановить.",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "С выбранным противником, до начала боя, полупрозрачно, чтобы не мешать.",
	["Con una tecla escondes lo del juego que no necesitas y quedan Alfa, tu rastreador y Lya. Otra pulsación lo devuelve todo."] = "Одна клавиша прячет лишнее из игры, и остаются Alfa, отслеживание и Лия. Нажми еще раз, чтобы все вернуть.",
	["Con él tu tope sube a %d."] = "С ней предел вырастет до %d.",
	["Concurso"] = "Состязание",
	["Concurso de pesca de Tuercespina"] = "Рыболовная феерия Тернистой долины",
	["Configura tu Alfa"] = "Настройте Alfa",
	["Configuración terminada"] = "Настройка завершена",
	["Configuración y ayuda"] = "Настройка и помощь",
	["Configurar"] = "Настроить",
	["Configurar con el asistente"] = "Настроить с помощником",
	["Confirmado por Blizzard (su noticia del sistema de Legado de WoW Forever): los 65 retos de 1 punto, el tope de 16 por personaje, los tres árboles, los cuatro premios del registro y lo del modo extremo."] = "Подтверждено Blizzard (новость о системе «Наследие» WoW Forever): 65 испытаний по 1 очку, предел 16 на персонажа, три дерева, четыре награды шкалы и правила режима «Хардкор».",
	["Conflagrar: consume tu Inmolar para un golpe fuerte."] = "Поджигание: поглощает ваш Жертвенный огонь ради сильного удара.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Он замораживает тех, кто рядом: если сражаетесь на расстоянии, держитесь подальше.",
	["Congela a un enemigo un rato. Ideal para controlar a uno extra en mazmorras."] = "Замораживает врага на время. Отлично для контроля лишнего врага в подземельях.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Заморозьте монстра Кольцом льда и отойдите, прежде чем продолжать произносить заклинания.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Она обездвиживает и бьет молниями: если сражаетесь на расстоянии, отойдите от группы.",
	["Congela en su lugar a los enemigos cercanos. Aléjate y sigue lanzando."] = "Замораживает врагов рядом на месте. Отойди и продолжай колдовать.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Вы замораживаете и замедляете монстров, чтобы они никогда до вас не добрались: самый безопасный маг для прокачки.",
	["Conjuntos de equipo"] = "Комплекты экипировки",
	["Conjúralas fuera de combate."] = "Сотворяйте их вне боя.",
	["Conocerlo"] = "Показать",
	["Conocido"] = "Знакомство",
	["Conozco la clase y el nivel de %d lobos conectados. Si levantas algo que les sirve, te lo digo."] = "Я знаю класс и уровень волков в сети: %d. Если поднимешь то, что им пригодится, я скажу.",
	["Conseguir %d de %s"] = "Добыть %d × %s",
	["Conseguir %d × %s"] = "Получить %d × %s",
	["Conseguir %s"] = "Добыть: %s",
	["Conseguir un objeto"] = "Получить предмет",
	["Consejo en el cuadro de los objetos"] = "Совет в подсказках предметов",
	["Consejos"] = "Советы",
	["Consejos al entrar a una mazmorra"] = "Советы при входе в подземелье",
	["Consejos de equipo apagados."] = "Советы по экипировке выключены.",
	["Consejos del juego"] = "Игровые советы",
	["Consejos para jugarlo"] = "Советы по игре",
	["Consejos que callaste"] = "Отключенные советы",
	["Consejos vistos"] = "Просмотренные советы",
	["Consejos: muchos"] = "Советы: много",
	["Consejos: pocos"] = "Советы: мало",
	["Consejos: solo importantes"] = "Советы: только важные",
	["Conserva %s: vale más de otra forma."] = "Оставьте %s: это выгоднее использовать иначе.",
	["Considerar desencantar"] = "Учитывать распыление",
	["Consigue %s"] = "Добудьте: %s",
	["Consigue bolsas más grandes en cuanto puedas: más espacio, más botín."] = "Добудь сумки побольше, как только сможешь: больше места — больше добычи.",
	["Consigue una caña de pescar"] = "Раздобудьте удочку",
	["Consumibles"] = "Расходуемые",
	["Contar tu avance en el chat del grupo"] = "Сообщать о прогрессе в чат группы",
	["Contenta"] = "Доволен",
	["Contestar «¿Quién tiene...?»"] = "Отвечать на «У кого есть...?»",
	["Contigo"] = "С вами",
	["Continuar"] = "Продолжить",
	["Continuar mi ruta"] = "Продолжить маршрут",
	["Contra jefes de nivel alto fallas mucho: esto lo arregla."] = "По боссам высокого уровня вы часто промахиваетесь: это исправляет ситуацию.",
	["Contra jefes fallas mucho: esto te ayuda."] = "По боссам вы часто промахиваетесь: это помогает.",
	["Contra lo que llevas:"] = "По сравнению с надетым:",
	["Contra lo que llevas: lo mismo."] = "По сравнению с надетым: то же самое.",
	["Contra no-muertos y demonios: Exorcismo pega muy fuerte."] = "Против нежити и демонов: Экзорцизм бьет очень сильно.",
	["Control de animación"] = "Управление анимацией",
	["Contármela"] = "Расскажи",
	["Contármelo"] = "Расскажи",
	["Convierte a un enemigo en oveja un rato. El mejor control en mazmorras."] = "Превращает врага в овцу на время. Лучший контроль в подземельях.",
	["Coordenadas en el mapa"] = "Координаты на карте",
	["Coordenadas en el minimapa"] = "Координаты на мини-карте",
	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Скопируйте этот текст (Ctrl+C) и передайте стае. Его вставляют в «Импорт».",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Скопируйте строку ниже и передайте ее в чате или Discord: с Alfa ее вставляют в «Импорт» и получают ваш билд.",
	["Copiar"] = "Копировать",
	["Copiar el Discord"] = "Скопировать Discord",
	["Copiar y editar"] = "Копировать и изменить",
	["Coral"] = "Коралловый",
	["Corre hacia el enemigo y lo aturde un momento. Úsala para empezar la pelea, desde lejos."] = "Рывок к врагу с коротким оглушением. Применяй издалека, чтобы начать бой.",
	["Correr"] = "Бег",
	["Corres mucho más rápido un momento. Para huir o para alcanzar a alguien."] = "Ненадолго ты бегаешь намного быстрее. Чтобы сбежать или догнать.",
	["Corres más rápido, pero si te pegan te aturdes. Solo para viajar."] = "Ты бегаешь быстрее, но от ударов теряешь ориентацию. Только для путешествий.",
	["Cortar"] = "Прерывание",
	["Cortar hechizos, amenaza, el tablón de la manada, mentor y dos estilos nuevos."] = "Прерывание заклинаний, угроза, доска стаи, наставник и два новых стиля.",
	["Cortar, amenaza y recargas"] = "Прерывание, угроза и восстановление",
	["Costa Oscura está llena de ruinas élficas, como Ameth'Aran, de una época mucho más antigua."] = "Темные берега полны эльфийских руин, вроде Амет'Арана, из куда более древней эпохи.",
	["Costasur y Molino Tarren están a un paso uno del otro, y la Alianza y la Horda se miran feo desde siempre."] = "Южнобережье и Мельница Таррен в двух шагах друг от друга, и Альянс с Ордой здесь всегда косо смотрят друг на друга.",
	["Costuras, una abominación enorme, ataca Villa Oscura en una de las misiones más famosas del bosque."] = "Шов, огромная поганищь, нападает на Темнолесье в одном из самых известных заданий леса.",
	["Crear %s ≈ %s"] = "Создать %s ≈ %s",
	["Crear ruta"] = "Создать маршрут",
	["Crecen hacia"] = "Направление роста",
	["Criatura peligrosa"] = "Опасное существо",
	["Criaturas de nivel %d a %d"] = "Существа %d–%d уровня",
	["Criaturas raras y tesoros: dónde aparecen y lo que sueltan."] = "Редкие существа и сокровища: где появляются и что роняют.",
	["Cristal"] = "Стекло",
	["Créditos y licencias"] = "Авторы и лицензии",
	["Crítico"] = "Крит",
	["Crítico con hechizos"] = "Крит. эффект заклинаний",
	["Críticos enormes: matas antes de que te curen."] = "Огромные критические удары: вы убиваете раньше, чем противника вылечат.",
	["Críticos más fuertes."] = "Более сильные критические удары.",
	["Críticos un poco más fuertes."] = "Чуть более сильные критические удары.",
	["Ctrl"] = "Ctrl",
	["Cuadro de información"] = "Подсказка",
	["Cualquier criatura de su nivel"] = "Любое существо его уровня",
	["Cualquier habilidad tuya que el juego resalte por un efecto."] = "Любая ваша способность, которую игра подсвечивает из-за эффекта.",
	["Cualquier instructor de pesca te la enseña. Luego compra una caña y unas lombrices: con eso empiezas."] = "Ее обучит любой учитель рыбной ловли. Затем купите удочку и червей — и можно начинать.",
	["Cualquier profesión"] = "Любая профессия",
	["Cualquiera"] = "Любой",
	["Cuando al monstruo le quede poca vida, usa Ejecutar (Alfa te avisa)."] = "Когда у монстра останется мало здоровья, используйте Казнь (Alfa подскажет).",
	["Cuando alguien de tu grupo sube de nivel, Lya aúlla, lo felicita y te deja felicitarlo en el chat con un clic."] = "Когда кто-то из группы получает уровень, Лия воет, поздравляет и даёт поздравить в чате одним кликом.",
	["Cuando aprendas %s, también."] = "Когда изучите %s — тоже.",
	["Cuando aprendas %s, te avisa al momento de usarlas."] = "Когда изучите %s, Alfa подскажет, когда их применять.",
	["Cuando aprendas a cortar, aquí sale tu habilidad y su tecla."] = "Когда выучишь прерывание, здесь появятся способность и ее клавиша.",
	["Cuando aprendas una habilidad para cortar hechizos, te avisa en cuanto tu objetivo empiece a lanzar."] = "Когда выучишь способность, прерывающую заклинания, она предупредит, как только цель начнет произносить.",
	["Cuando aprendes un hechizo importante de tu clase, Lya te dice para qué sirve y cuándo usarlo."] = "Когда ты учишь важное заклинание класса, Лия говорит, для чего оно и когда его применять.",
	["Cuando aprendes un rango nuevo, un aviso ofrece cambiarlo en tus barras."] = "Когда вы изучаете новый ранг, оповещение предложит заменить его на панелях.",
	["Cuando buscas algo en la subasta, Alfa guarda el precio más bajo que ves."] = "Когда вы что-то ищете на аукционе, Alfa запоминает самую низкую увиденную цену.",
	["Cuando caes"] = "Когда ты падаешь",
	["Cuando el Pozo de la Eternidad explotó, el gran continente antiguo se partió en pedazos. A eso le llaman la Gran División."] = "Когда взорвался Источник Вечности, древний великий континент раскололся на части. Это называют Расколом.",
	["Cuando el juego termina de cargar, Alfa revisa lo que elegiste aquí y lo vuelve a poner si algo lo cambió. Si después los cambias en el menú del juego, Alfa se queda con lo nuevo."] = "Когда игра заканчивает загрузку, Alfa проверяет ваш выбор здесь и возвращает его, если что-то его изменило. Если потом вы измените настройки в меню игры, Alfa оставит новые.",
	["Cuando entras a una posada o ciudad, y cuando tu XP descansada se acaba."] = "Когда вы входите в таверну или город и когда заканчивается опыт за отдых.",
	["Cuando hay un festival, vale la pena darse una vuelta: casi siempre trae mascotas, ropa o comida que no salen el resto del año."] = "Когда идет праздник, стоит заглянуть: почти всегда там есть питомцы, одежда или еда, которых нет в остальное время года.",
	["Cuando hay varias para elegir, toma la que más te sirve."] = "Если есть из чего выбрать, берет самое полезное для вас.",
	["Cuando huelo salchichas se me olvida todo. Bueno, menos tú."] = "Когда я чую сосиски, я забываю обо всем. Ну, кроме тебя.",
	["Cuando la Legión volvió en la Tercera Guerra, Malfurion y Tyrande hicieron sonar el Cuerno de Cenarius para despertar a los druidas dormidos."] = "Когда Легион вернулся в Третьей войне, Малфурион и Тиранда протрубили в Рог Кенария, чтобы разбудить спящих друидов.",
	["Cuando la meta de ahora de tu plan es un lugar, la flecha lo toma sin que hagas clic."] = "Когда текущая цель плана — место, стрелка берет его без щелчка.",
	["Cuando le baja la vida aturde a todos y corre a su cofre a cambiar de arma: espérenlo, no lo persigan."] = "Когда его здоровье падает, он оглушает всех и бежит к сундуку сменить оружие: ждите его, не преследуйте.",
	["Cuando levantes algo que le sirve a un lobo conectado, te lo digo aquí. Ellos comparten su clase y nivel en los ajustes."] = "Когда поднимешь то, что пригодится волку в сети, я скажу здесь. Они делятся классом и уровнем в настройках.",
	["Cuando lleves algo, Alfa te dice si conviene venderlo, subastarlo o transformarlo, y cuánto ganas."] = "Когда у вас что-то есть, Alfa подскажет, выгоднее продать это торговцу, выставить на аукцион или переработать, и сколько вы заработаете.",
	["Cuando los orcos se volvieron brujos, dejaron de oír a los elementos. Thrall les devolvió ese camino."] = "Когда орки стали чернокнижниками, они перестали слышать стихии. Тралл вернул им этот путь.",
	["Cuando no sepas algo de Alfa, dame clic derecho y elige «¿En qué te ayudo?»: te explico cada cosa y te llevo a ella. También te cuento historias del lugar donde estás."] = "Если чего-то не знаешь об Alfa, кликни по мне правой кнопкой и выбери «Чем помочь?»: объясню и отведу. А ещё расскажу истории о месте, где ты.",
	["Cuando otro lobo con Alfa comparta su ubicación, aparece aquí y en tu mapa. Para que la manada crezca, invita a tus amigos: que instalen Alfa, acepten compartir y entren al Discord de La Jauría."] = "Когда другой волк с Alfa поделится местоположением, он появится здесь и на вашей карте. Чтобы стая росла, приглашайте друзей: пусть установят Alfa, согласятся делиться и зайдут в Discord La Jauría.",
	["Cuando sales como espíritu te digo a cuánto está tu cuerpo, lo que cuesta el ángel a tu nivel y qué conviene. La flecha te lleva."] = "Когда ты выходишь духом, я говорю, далеко ли твое тело, сколько стоит целитель душ на твоем уровне и что лучше. Стрелка отведет тебя.",
	["Cuando se abre una misión de clase para ti, te ofrece su guía."] = "Когда для вас открывается классовое задание, предлагает его гайд.",
	["Cuando se escapa"] = "Когда рыба срывается",
	["Cuando se llenan"] = "Когда заполняются",
	["Cuando se te acaban te digo qué te conviene a tu nivel y te llevo al vendedor más cercano. El agua solo si usas maná."] = "Когда запасы кончаются, я скажу, что подходит твоему уровню, и отведу к ближайшему торговцу. Вода — только если у тебя мана.",
	["Cuando te llega equipo mejor que lo que llevas puesto, un aviso con un botón para ponértelo (solo con tu clic y fuera de combate)."] = "Когда тебе попадается снаряжение лучше надетого — напоминание с кнопкой, чтобы надеть (только по твоему щелчку и вне боя).",
	["Cuando te quedes sin maná, cambia a forma felina para terminar la pelea."] = "Когда закончится мана, перейдите в облик кошки, чтобы закончить бой.",
	["Cuando tengas las guías de tu facción, aquí sale tu ruta al 60."] = "Когда у тебя будут гиды твоей фракции, здесь появится путь к 60.",
	["Cuando tengas pescado que sepas cocinar, aparece aquí."] = "Когда у вас будет рыба, которую вы умеете готовить, она появится здесь.",
	["Cuando termine el combate."] = "Когда бой закончится.",
	["Cuando tu guía dice «Sube al nivel», el rastreador te dice cuánta experiencia te falta y dónde rinde más: enemigos de tu nivel que también cuentan para tus misiones. «Llévame» y la flecha te lleva."] = "Когда гид говорит «Достичь уровня», отслеживание покажет, сколько нужно опыта и где он выгоднее всего: враги твоего уровня, которые идут и в зачет заданий. «Отведи меня» — и стрелка поведет.",
	["Cuando tu objetivo lance algo que se puede cortar, te avisa con %s y su tecla."] = "Когда цель начнет произносить то, что можно прервать, напомнит про %s и его клавишу.",
	["Cuando tu objetivo lanza algo que se puede cortar: tu habilidad para cortar, su tecla y si está lista."] = "Когда цель произносит то, что можно прервать: твоя способность прерывания, ее клавиша и готова ли она.",
	["Cuando tu objetivo o tu foco empieza a lanzar algo que se puede cortar, Alfa te avisa con tu habilidad para cortar, su tecla y si ya está lista. En mazmorras el juego a veces lo oculta: ahí avisa igual que está lanzando."] = "Когда твоя цель или фокус начинает произносить то, что можно прервать, Alfa предупредит: твоя способность прерывания, ее клавиша и готова ли она. В подземельях игра иногда это скрывает — тогда предупредит просто о произнесении.",
	["Cuando tu paso lo pide y hablas con su posadero. Nunca en otra posada."] = "Когда этого требует шаг и вы говорите с его трактирщиком. Никогда в другой таверне.",
	["Cuando tus bolsas se llenan, Hoy te dice qué puedes vender y cuánto te dan."] = "Когда сумки заполняются, «Сегодня» подскажет, что можно продать и сколько вы получите.",
	["Cuando tú o tu grupo peleen, aquí sale quién hace más daño."] = "Когда вы или ваша группа сражаетесь, здесь видно, кто наносит больше всего урона.",
	["Cuando un elfo de la noche muere, su espíritu toma forma de fuego fatuo y corre más rápido hasta su cuerpo."] = "Когда ночной эльф умирает, его дух принимает облик огонька и быстрее бежит к телу.",
	["Cuando un lobo de la manada encuentra un raro, te aviso en qué guarida está y te dejo pedir entrar con un clic."] = "Когда волк стаи находит редкого, я скажу, в каком он логове, и дам попроситься одним кликом.",
	["Cuando un lobo de tu zona pide ayuda, te avisa dónde está con «¡Voy!»: la flecha te lleva y le dice que vas."] = "Когда волк твоей зоны просит помощи, ты узнаёшь, где он, с кнопкой «Иду!»: стрелка ведёт тебя и сообщает ему, что ты идёшь.",
	["Cuando un lobo encuentra un raro o un tesoro en tu zona, te avisa en qué guarida está. Si es la tuya, «Ir de caza»; si es otra, «Pedir entrar»."] = "Когда волк находит редкого или сокровище в твоей зоне, ты узнаёшь, в каком он логове. Если в твоём — «На охоту»; если в другом — «Попроситься».",
	["Cuando un oficio llega al tope de su rango, Lya te dice que ya puedes aprender el siguiente y dónde está tu instructor."] = "Когда профессия достигает предела своего уровня, Лия говорит, что можно учить следующий, и где твой учитель.",
	["Cuando una pieza baja de este porcentaje."] = "Когда прочность вещи опускается ниже этого процента.",
	["Cuando una zona se llena, el juego la parte en guaridas (capas): el mismo lugar con otra gente, otros raros y otros minerales. Pide entrar a la de alguien de la manada y el juego te pasa al unirte a su grupo."] = "Когда зона заполняется, игра делит её на логова (слои): то же место, но другие люди, другие редкие и другая руда. Попросись в логово кого-то из стаи, и игра перенесёт тебя, когда вступишь в его группу.",
	["Cuando usas una habilidad que tarda 30 segundos o más en volver, Alfa la pone en una barra discreta con lo que le falta. En Combate eliges cuáles no quieres ver."] = "Когда ты используешь способность, которая восстанавливается 30 секунд и дольше, Alfa ставит ее на неприметную полосу с оставшимся временем. В «Бою» ты выбираешь, какие не показывать.",
	["Cuando vas solo por el mundo, así no sale tras cada enemigo."] = "Когда вы путешествуете в одиночку, чтобы сводка не появлялась после каждого врага.",
	["Cuando venzas a tu primer jefe, tu progreso aparecerá aquí."] = "Когда вы победите первого босса, здесь появится ваш прогресс.",
	["Cuando ves a alguien que también usa Alfa (y comparte con la manada), un anuncio corto te lo dice para que lo saludes."] = "Когда ты видишь того, кто тоже пользуется Alfa (и делится со стаей), короткое объявление скажет тебе об этом, чтобы ты мог поздороваться.",
	["Cuando ves caer a un raro, me acuerdo: en su cuadro y en La Jauría te digo hace cuánto lo cazaron y si pudo volver ya (a la media hora, más o menos)."] = "Когда ты видишь, как падает редкий, я запоминаю: в его подсказке и в La Jauría скажу, как давно его убили и мог ли он уже вернуться (примерно через полчаса).",
	["Cuando ya casi se rompe."] = "Когда вещь вот-вот сломается.",
	["Cuando ya entregaste todo o cerraste tu zona, te dice qué sigue (la flecha la pones tú con «Llévame»)."] = "Когда все сдано или зона пройдена, подскажет, что дальше (стрелку ставишь кнопкой «Отведи меня»).",
	["Cuarenta. ¡Hora de correr más rápido!"] = "Сорок. Пора бегать быстрее!",
	["Cuello"] = "Шея",
	["Cuenta:"] = "Учетная запись:",
	["Cuero"] = "Кожа",
	["Cuerpo a cuerpo con tótems y golpes elementales: el chamán que mejor sube."] = "Ближний бой с тотемами и стихийными ударами: шаман, который лучше всех качается.",
	["Cuesta %s."] = "Стоит %s.",
	["Cuestan %s: te alcanza."] = "Стоимость: %s, денег хватает.",
	["Cuestan %s; llevas %s."] = "Стоимость: %s; у вас %s.",
	["Cuida bien a %s, que la manada lo necesita."] = "Береги %s, стае он нужен.",
	["Cuidado al nadar mar adentro: en aguas profundas te cansas y te puedes ahogar."] = "Осторожно в открытом море: на глубине ты устаешь и можешь утонуть.",
	["Cuidado con atraer varios a la vez: Fuego no tiene tanto control."] = "Осторожно, не притягивайте нескольких сразу: у Огня не так много контроля.",
	["Cuidado: aquí los enemigos son nivel %s."] = "Осторожно: здесь враги %s уровня.",
	["Cumpleaños"] = "Дни рождения",
	["Cumpliste todas sus metas."] = "Вы выполнили все его цели.",
	["Cumpliste todas sus metas. Elige otro plan o arma uno nuevo."] = "Вы выполнили все его цели. Выберите другой план или составьте новый.",
	["Cumpliste tu plan en %s."] = "План выполнен за %s.",
	["Cura"] = "Лекарь",
	["Cura a quien tenga el dolor de sombras; la pelea es corta."] = "Лечите того, на ком теневая боль; бой короткий.",
	["Cura a sus ayudantes y a sí misma: interrúmpanla."] = "Она лечит помощников и себя: прерывайте ее.",
	["Cura a todo tu grupo a la vez. Perfecta cuando a todos les pegan."] = "Лечит всю группу сразу. Идеально, когда бьют всех.",
	["Cura a tu grupo con un clic."] = "Лечите группу одним щелчком.",
	["Cura a tu mascota poco a poco. Mantenla viva: ella te cuida."] = "Лечит питомца со временем. Береги его: он бережет тебя.",
	["Cura con un clic y ese compañero queda seleccionado; limpia maldiciones y venenos con otro clic."] = "Лечи одним щелчком, и союзник остается в цели; снимай проклятия и яды другим щелчком.",
	["Cura de golpe y luego un rato más."] = "Лечит сразу и потом еще со временем.",
	["Cura poco a poco. Ideal para alguien que recibe daño sin parar."] = "Лечит со временем. Отлично для того, кто постоянно получает урон.",
	["Cura poco a poco. Ponla en quien recibe daño."] = "Лечит со временем. Наложи на того, кто получает урон.",
	["Curación"] = "Исцеление",
	["Curación con clic"] = "Исцеление по щелчку",
	["Curación: arrastra para mover"] = "Исцеление: перетащите, чтобы передвинуть",
	["Curandero"] = "Лекарь",
	["Curar con un clic"] = "Исцеление одним щелчком",
	["Curar y seleccionar"] = "Лечить и брать в цель",
	["Curas"] = "Ты лечишь",
	["Curas que van llegando"] = "Входящее исцеление",
	["Cursor"] = "Курсор",
	["Cuándo"] = "Когда",
	["Cuándo vuelve sola detrás de tu personaje."] = "Когда она сама возвращается за спину персонажа.",
	["Cuánta lluvia, nieve y polvo se ve cuando hay mal tiempo."] = "Сколько дождя, снега и пыли видно в непогоду.",
	["Cuánta memoria usa cada parte de Alfa ahora, y suelta la que ya no ocupa. También con /alfa rendimiento."] = "Сколько памяти сейчас использует каждая часть Alfa, и освобождает ту, что больше не нужна. Также через /alfa rendimiento.",
	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "Сколько слоев теней рисуется: чем больше слоев, тем дальше видны четкие тени.",
	["Cuántas casillas caben en cada fila."] = "Сколько ячеек помещается в ряд.",
	["Cuántas casillas libres quedan cuando Alfa te avisa."] = "Сколько свободных ячеек должно остаться, чтобы Alfa предупредил.",
	["Cuántas habilidades después"] = "Сколько способностей дальше",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Сколько урона снимает каждый блок; также повышает урон Мощного удара щитом.",
	["Cuánto dura un aviso en pantalla"] = "Сколько оповещение держится на экране",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Сколько осталось до следующей автоатаки каждой рукой. Помогает вставить Мощный удар или Удар героя без потери ударов.",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "Насколько свет ярче, чем на обычном экране. Игра не превысит максимум вашего монитора.",
	["Cuánto oro"] = "Сколько золота",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "Сколько травы, цветов и растений покрывает землю.",
	["Cuánto por debajo de lo que vale tiene que estar tu precio para avisarte."] = "Насколько ниже стоимости должна быть цена, чтобы я предупредила.",
	["Cuánto se ve el fondo de las ventanas de chat; en cero solo queda el borde."] = "Насколько виден фон окон чата; при нуле остается только рамка.",
	["Cuánto te ayuda Alfa"] = "Насколько помогает Alfa",
	["Cuánto te falta para el 60 a tu ritmo, qué guías y mazmorras te tocan y cuánto avanzas cada día."] = "Сколько тебе до 60 в твоем темпе, какие гиды и подземелья твои и насколько ты продвигаешься за день.",
	["Cuántos"] = "Сколько",
	["Cuántos consejos"] = "Сколько советов",
	["Cuántos en el top"] = "Сколько в топе",
	["Cuántos se anuncian"] = "Сколько объявлять",
	["Cuántos tienes, en el cuadro de cada objeto"] = "Сколько у вас есть — в подсказке каждого предмета",
	["Cuántos van en cada columna (o fila) antes de empezar otra. 5 es un grupo por columna."] = "Сколько помещается в столбце (или ряду), прежде чем начнется следующий. 5 — одна группа на столбец.",
	["Cuéntame algo"] = "Расскажи что-нибудь",
	["Cuéntame algo de aquí"] = "Расскажи что-нибудь об этом месте",
	["Cuéntanos qué te parece en La Jauría."] = "Поделитесь впечатлениями в La Jauría.",
	["Cálido"] = "Теплый",
	["Cámara"] = "Камера",
	["Cámbialo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el juego lo lee en combate y fallaría."] = "Измените это в меню игры: Настройки > %s > «%s». Alfa не меняет это за вас: игра читает настройку в бою, и возникла бы ошибка.",
	["Cólera de las bestias: tu mascota pega mucho más un rato."] = "Звериный гнев: ваш питомец какое-то время бьет намного сильнее.",
	["Cómo cambiarlo"] = "Как изменить",
	["Cómo conseguir cualquier objeto, misión o PNJ, y qué guía te lleva ahí."] = "Как получить любой предмет, задание или найти NPC и какой гайд вас туда приведет.",
	["Cómo conseguir cualquier objeto, montura, PNJ, misión o lugar."] = "Как получить или найти любой предмет, транспорт, NPC, задание или место.",
	["Cómo conseguirla"] = "Как получить",
	["Cómo conseguirlo"] = "Как получить",
	["Cómo decide Alfa"] = "Как решает Alfa",
	["Cómo encenderlo"] = "Как включить",
	["Cómo está tu plano: %s."] = "Обстановка в твоем слое: %s.",
	["Cómo hacer oro"] = "Как заработать золото",
	["Cómo juego"] = "Как я играю",
	["Cómo se consigue"] = "Как получить",
	["Cómo se ganan"] = "Как заработать",
	["Cómo se mueve"] = "Как движется",
	["Cómo se usa"] = "Как пользоваться",
	["Cómo se ven las zonas sin descubrir"] = "Как выглядят неоткрытые области",
	["Cómo subir"] = "Как качаться",
	["Cómo subirla"] = "Как развивать",
	["Cómo trabaja tu ruta"] = "Как работает ваш маршрут",
	["Cómo ves Alfa"] = "Как ты видишь Alfa",
	["Cómprala con un vendedor."] = "Купите у торговца.",
	["Cópialo con Ctrl+C y guárdalo, o pásaselo a la manada. Para traerlo de vuelta: «Importar»."] = "Скопируй его с помощью Ctrl+C и сохрани или передай стае. Чтобы вернуть его: «Импорт».",
	["Cópialo con Ctrl+C. Luego abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y pégalo con Ctrl+V."] = "Скопируйте его Ctrl+C. Затем откройте «Гильдия и сообщества», выберите %s, нажмите «Пригласить участника» и вставьте его Ctrl+V.",
	["Cópialos con Ctrl+C y pégalos en tu reporte. «Reportar» ya los lleva."] = "Скопируй их Ctrl+C и вставь в отчет. «Отчет» их уже включает.",
	["DPS"] = "DPS",
	["DPS del arma"] = "DPS оружия",
	["Daga"] = "Кинжал",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Кормите питомца, чтобы он был доволен и бил сильнее.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Покормите его, чтобы он был счастлив: так он бьет сильнее.",
	["Dame clic derecho y elige «¿En qué te ayudo?» cuando quieras. ¡Buena caza, lobo!"] = "Щелкни по мне правой кнопкой и выбери «Чем помочь?», когда захочешь. Хорошей охоты, волк!",
	["Dar a las barras el estilo de Alfa"] = "Оформить панели в стиле Alfa",
	["Dar al chat el estilo de Alfa"] = "Оформить чат в стиле Alfa",
	["Dar al minimapa el estilo de Alfa"] = "Оформить мини-карту в стиле Alfa",
	["Darle una salchicha"] = "Дать ей сосиску",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "Дарнас стоит в ветвях Тельдрассила. Верховная жрица Тиранда Шепот Ветра правит из Храма Луны.",
	["Dath'Remar Caminante del Sol guió a los altos elfos hasta Quel'Thalas. De su linaje viene el príncipe Kael'thas."] = "Дат'Ремар Солнечный Скиталец привел высших эльфов в Кель'Талас. Из его рода происходит принц Кель'тас.",
	["Datos"] = "Данные",
	["Datos curiosos"] = "Интересные факты",
	["Datos curiosos de Lya, escritos por Alfa."] = "Любопытные факты от Lya, написанные Alfa.",
	["Daño"] = "Боец",
	["Daño a distancia"] = "Урон в дальнем бою",
	["Daño a todos los que están cerca de ti. Para cuando te rodean."] = "Ранит всех рядом с тобой. Когда тебя окружили.",
	["Daño arcano al instante y un rato más. Bueno para empezar o mientras corres."] = "Мгновенный урон от тайной магии и еще со временем. Хорошо для начала или на ходу.",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Периодический урон: наложите в начале боя.",
	["Daño de arcos, armas de fuego y ballestas."] = "Урон луков, огнестрельного оружия и арбалетов.",
	["Daño de escarcha que deja lento al enemigo. Perfecto si huye."] = "Урон от магии льда, замедляющий врага. Идеально, если он убегает.",
	["Daño de escarcha que deja lento al enemigo. Tu hechizo para mantenerlo lejos."] = "Урон от магии льда, замедляющий врага. Твое заклинание, чтобы держать его на расстоянии.",
	["Daño de fuego al instante. Úsalo para rematar o mientras te mueves."] = "Мгновенный урон от огня. Применяй для добивания или на ходу.",
	["Daño de fuego con el tiempo."] = "Периодический урон от огня.",
	["Daño de fuego que quema un rato. Bueno para empezar la pelea."] = "Урон от огня, который продолжает жечь. Хорошо, чтобы начать бой.",
	["Daño de sombra durante un buen rato. Ponla al inicio."] = "Урон от темной магии на долгое время. Накладывай первым.",
	["Daño de sombra durante un rato. Ponla al inicio y sigue con otra cosa."] = "Урон от темной магии со временем. Наложи первым и займись другим.",
	["Daño de sombra fuerte. Buen golpe para empezar o para rematar."] = "Сильный урон от темной магии. Хорошо для начала или добивания.",
	["Daño de sombra que hace lento al enemigo. Canalízalo mientras se acerca."] = "Урон от темной магии, замедляющий врага. Поддерживай, пока он идет к тебе.",
	["Daño del arma"] = "Урон оружия",
	["Daño directo de fuego y sombras: matas antes de que el monstruo llegue."] = "Прямой урон огнем и тьмой: вы убиваете раньше, чем монстр до вас доберется.",
	["Daño directo de tus armas y habilidades."] = "Прямой урон вашего оружия и способностей.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Урон в группе из пяти: бить сильно, не отбирая монстров у танка.",
	["Daño extra después de recibir críticos."] = "Дополнительный урон после получения критических ударов.",
	["Daño extra después de recibir un golpe crítico."] = "Дополнительный урон после получения критического удара.",
	["Daño o curas"] = "Урон или лечение",
	["Daño periódico"] = "Периодический урон",
	["Daño por segundo"] = "Урон в секунду",
	["Daño rápido que también interrumpe hechizos. Úsalo con quien lanza magia."] = "Быстрый урон, который еще и прерывает заклинания. Применяй на заклинателей.",
	["Daño sagrado fuerte contra no-muertos y demonios."] = "Сильный урон от светлой магии по нежити и демонам.",
	["Daño sobre tus enemigos"] = "Урон над противниками",
	["De %d a %d"] = "С %d до %d",
	["De %s"] = "От %s",
	["De %s, %s"] = "От %s, %s",
	["De 1 a 300"] = "С 1 до 300",
	["De 1 a 300, dónde pescar cerca de ti, equipo, cebos, misiones y el concurso."] = "С 1 до 300: где рыбачить рядом с вами, снаряжение, приманки, задания и состязание.",
	["De 1 a 300: qué hacer, con qué y dónde aprender"] = "С 1 до 300: что делать, из чего и где учиться",
	["De 15 minutos a 4 horas."] = "От 15 минут до 4 часов.",
	["De Forever"] = "Forever",
	["De La Jauría"] = "Из La Jauría",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono. Lo que el juego hace brillar pasa al frente; las de área salen con varios enemigos peleando. Solo aparecen las que ya aprendiste."] = "Сверху вниз: первая способность, которую игра позволяет использовать, показывается на значке. То, что игра подсвечивает, выходит вперед; способности по области появляются, когда сражаются несколько противников. Показываются только изученные.",
	["De arriba abajo: la primera que el juego te deja usar es la que sale en el ícono; las de área, solo con 3 o más enemigos peleando."] = "Сверху вниз: на значке — первая, которую игра позволяет применить; способности по области — только когда сражаются 3 противника и больше.",
	["De clase"] = "Классовый",
	["De clase: %s"] = "Классовый: %s",
	["De donde estés a cualquier lugar, con vuelos, barcos, zepelines, portales y a pie, y la lista de tramos."] = "Откуда угодно куда угодно: полеты, корабли, дирижабли, порталы и пешком, со списком отрезков.",
	["De este lugar Lya todavía no sabe datos curiosos. Elige una misión de la lista para leer su historia."] = "Об этом месте Lya пока не знает любопытных фактов. Выберите задание в списке, чтобы прочитать его историю.",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "Об этом месте я пока знаю немного. Посмотрим твои истории?",
	["De fábrica el seguimiento muestra solo lo que estás haciendo; encendido, muestra el paso completo con sus notas."] = "По умолчанию трекер показывает только то, что вы делаете; если включить — весь шаг с заметками.",
	["De la base de datos incluida"] = "Из встроенной базы данных",
	["De la otra facción"] = "Другая фракция",
	["De los que se presumen"] = "Есть чем похвастаться",
	["De misión"] = "Для заданий",
	["De nivel %.1f a %.1f, con unos %s de oro. Solo misiones que ya puedes tomar; lo que pide más nivel va después de un paso que lo espera."] = "С уровня %.1f до %.1f, примерно %s золота. Только задания, которые уже можно взять; то, что требует более высокого уровня, идет после шага ожидания.",
	["De noche Durotar refresca y se ven muchas estrellas desde Orgrimmar."] = "Ночью Дуротар остывает, и из Оргриммара видно множество звезд.",
	["De noche Teldrassil se llena de luciérnagas. Los elfos de la noche están en su hora."] = "Ночью Тельдрассил наполняется светлячками. Это час ночных эльфов.",
	["De noche Un'Goro ruge. Los diablosaurios del cráter no duermen nunca."] = "Ночью Ун'Горо ревет. Девилзавры кратера никогда не спят.",
	["De noche Vallefresno brilla con luz de luna. Los furbolg duermen... casi todos."] = "Ночью Ясеневый лес светится под луной. Фурболги спят... почти все.",
	["De noche en Cuna del Invierno la aurora pinta el cielo. Vale la pena verla un ratito."] = "Ночью в Зимних Ключах сияние раскрашивает небо. Стоит немного посмотреть.",
	["De noche en Dun Morogh la nieve cruje bajo las patas. Me encanta ese sonido."] = "Ночью в Дун Мороге снег хрустит под лапами. Обожаю этот звук.",
	["De noche en Elwynn se oyen los lobos del bosque. Tranquilo: son primos lejanos."] = "Ночью в Элвиннском лесу слышно лесных волков. Не бойся: это дальняя родня.",
	["De noche en Los Humedales croan las ranas y los raptores acechan entre los juncos."] = "Ночью в Болотине квакают лягушки, а в камышах прячутся ящеры.",
	["De noche en Mulgore el viento canta entre las mesetas. Los tauren dicen que es la Madre Tierra."] = "Ночью в Мулгоре ветер поет между столовыми горами. Таурены говорят, что это Мать-Земля.",
	["De noche en Tanaris la arena se enfría rápido. Cuidado con los escorpiones."] = "Ночью в Танарисе песок быстро остывает. Осторожно со скорпионами.",
	["De noche en el Bosque del Ocaso los worgen salen a cazar. No te separes de mí."] = "Ночью в Сумеречном лесу на охоту выходят ворги. Держись рядом со мной.",
	["De noche en las Tierras de la Peste los muertos caminan más. Quédate junto a la luz."] = "Ночью в Чумных землях мертвые бродят чаще. Держись поближе к свету.",
	["De noche los Defias se mueven por los Páramos. Mira bien antes de entrar a una granja."] = "Ночью Братство Справедливости бродит по Западному Краю. Осмотрись, прежде чем зайти на ферму.",
	["De todo %s, ¿qué rincón te gusta más?"] = "Какой уголок всего %s тебе нравится больше всего?",
	["De tu gente todavía no sé mucho. ¿Te cuento otra cosa?"] = "О твоем народе я пока знаю немного. Рассказать что-нибудь другое?",
	["De tu nivel al 60, a tu ritmo"] = "От твоего уровня до 60, в твоем темпе",
	["De vez en cuando Lya te pide una. Te las tiene bien contadas."] = "Время от времени Лия просит у тебя одну. Она их все считает.",
	["Debajo del ícono: útil mientras aprendes."] = "Под значком: полезно, пока учитесь.",
	["Dedo"] = "Палец",
	["Defensa"] = "Защита",
	["Deja Alt abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve. La tecla se cambia en Estilo y sonido."] = "Удерживай Alt и наведи курсор на что угодно в Alfa: я скажу, для чего это. Клавиша меняется в «Стиль и звук».",
	["Deja esta tecla abajo y pasa el ratón por cualquier cosa de Alfa: te digo para qué sirve."] = "Удерживай эту клавишу и наведи курсор на что угодно в Alfa: я скажу, для чего это.",
	["Deja que el tanque golpee primero unos segundos antes de usar tus golpes fuertes."] = "Дайте танку несколько секунд побить первым, прежде чем использовать сильные удары.",
	["Deja que la manada te vea en el mapa"] = "Позвольте стае видеть вас на карте",
	["Deja que tu mascota empiece la pelea y dispara cuando el monstruo la esté atacando."] = "Пусть питомец начнет бой, а вы стреляйте, когда монстр атакует его.",
	["Deja solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Оставляет только главное: вас, вашу группу, ваши маркеры и следующий шаг гайда.",
	["Deja una nota en tu mapa donde estás (/alfa nota <texto>)"] = "Оставить заметку на карте там, где ты стоишь (/alfa nota <текст>)",
	["Dejar"] = "Перестать",
	["Dejar de seguir"] = "Перестать следовать",
	["Dejar de seguirlo"] = "Перестать следовать",
	["Dejar el chat"] = "Оставить чат",
	["Dejar el minimapa"] = "Оставить мини-карту",
	["Dejar el plan"] = "Бросить план",
	["Dejar la vuelta"] = "Прервать обход",
	["Dejarlo como recomienda Alfa"] = "Настроить, как советует Alfa",
	["Dejarlo ir"] = "Отпустить",
	["Dejaste la vuelta: la flecha vuelve a tu guía."] = "Обход прерван: стрелка вернулась к руководству.",
	["Dejaste una nota en tu mapa: «%s»."] = "Заметка на карте оставлена: «%s».",
	["Dejé %d cartas que se abren a mano (pago contra entrega o de un MJ)."] = "Писем, которые нужно открыть вручную (наложенный платеж или от ГМ), осталось: %d.",
	["Dejé 1 carta que se abre a mano (pago contra entrega o de un MJ)."] = "Осталось 1 письмо, которое нужно открыть вручную (наложенный платеж или от ГМ).",
	["Del Legado"] = "Из «Наследия»",
	["Del agua"] = "Из воды",
	["Del buzón: %s (no cuenta por hora)"] = "Из почтового ящика: %s (не входит в доход в час)",
	["Del color del estilo"] = "Цвета стиля",
	["Del motor de Alfa: al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Из движка Alfa: при повышении уровня показывает, что изучить и сколько это стоит.",
	["Del motor de Alfa: con el entrenador más cercano en tu camino."] = "Из движка Alfa: с ближайшим учителем на вашем пути.",
	["Del preajuste"] = "Из набора",
	["Demonología"] = "Демонология",
	["Demonología para subir"] = "Демонология для прокачки",
	["Densidad de partículas"] = "Плотность частиц",
	["Dentro"] = "Внутри",
	["Dentro de"] = "Находится в",
	["Dentro de %s (mazmorra)"] = "Внутри: %s (подземелье)",
	["Dentro de la mazmorra"] = "Внутри подземелья",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "В подземельях и городах узлов нет. Выйдите в мир, и маршрут составится в один щелчок.",
	["Dentro de una instancia el juego no deja compartir: sale solo cuando salgas."] = "В подземелье игра не позволяет делиться: маркер отправится сам, когда вы выйдете.",
	["Dentro de una instancia no hay planos."] = "Внутри подземелья слоев нет.",
	["Dentro de una instancia no se puede seguir a nadie."] = "В подземелье нельзя ни за кем следовать.",
	["Dentro de una mazmorra, al apuntar a un jefe sale una tarjeta chica con lo que te toca según tu papel y cómo van tus misiones de ahí. No atrapa clics."] = "В подземелье, если взять босса в цель, появится маленькая карточка: что делать твоей роли и как идут задания там. Она никогда не перехватывает щелчки.",
	["Dentro de una mazmorra, apunta al jefe: arriba te sale una tarjeta con lo que te toca según tu papel y cómo van tus misiones de ahí."] = "В подземелье возьми босса в цель: карточка вверху покажет, что делать твоей роли и как идут твои задания там.",
	["Depositar"] = "Положить",
	["Depositar rápido"] = "Быстро положить",
	["Depósito detenido: guardaste %d."] = "Перенос остановлен: положено %d.",
	["Derecho"] = "Правая",
	["Derrota a %s"] = "Победите: %s",
	["Derrotar al último jefe de todas las mazmorras de un rango de niveles da un punto del Legado por cada rango."] = "Победа над последним боссом всех подземелий одного диапазона уровней дает по очку «Наследия» за каждый диапазон.",
	["Desapareces y vuelves al sigilo, aun en combate. Tu escape de emergencia."] = "Ты исчезаешь обратно в незаметность, даже в бою. Твой запасной выход.",
	["Desarmar más seguido: quitas el arma a los enemigos que pegan fuerte."] = "Обезоруживание чаще: вы отнимаете оружие у противников, которые сильно бьют.",
	["Desbloquear %s"] = "Открыть: %s",
	["Desbloquear posición"] = "Открепить положение",
	["Descansa en una posada o una ciudad para juntar más."] = "Отдыхайте в таверне или городе, чтобы накопить больше.",
	["Descansa hasta que la llames"] = "Отдыхает, пока не позовёшь",
	["Descansando"] = "Отдых",
	["Descansando%s%d%% de un nivel"] = "Отдых%s%d%% уровня",
	["Descansando: %d %%"] = "Отдых: %d %%",
	["Descanso"] = "Отдых",
	["Descanso %d %%"] = "Отдых %d %%",
	["Desconectado"] = "Не в сети",
	["Descontenta"] = "Недоволен",
	["Descubrir aquí te dio %d de experiencia la última vez."] = "В прошлый раз открытие здесь дало тебе %d опыта.",
	["Descubrirlo te da experiencia."] = "Открытие дает опыт.",
	["Descubriste a %s"] = "Открыт босс: %s",
	["Descubriste a %s (%s)."] = "Открыт босс: %s (%s).",
	["Desde Auberdine sale un barco al muelle de Rut'theran, al pie de Teldrassil."] = "Из Аубердина корабль идет к причалу Рут'теран у подножия Тельдрассила.",
	["Desde cero"] = "С нуля",
	["Desde cuántas habilidades"] = "Начиная со скольких навыков",
	["Desde cuántos segundos"] = "От скольких секунд",
	["Desde el nivel 10"] = "С 10-го уровня",
	["Desde el nivel 20"] = "С 20-го уровня",
	["Desde el nivel 20, desuellas bestias de hasta tu habilidad dividida entre 5. Necesitas un cuchillo de desollar."] = "С 20-го уровня ты снимаешь шкуры со зверей до уровня навыка, деленного на 5. Нужен нож для снятия шкур.",
	["Desde el sigilo y por la espalda: lo hace sangrar un buen rato."] = "Из незаметности и со спины: враг долго истекает кровью.",
	["Desde el sigilo y por la espalda: un golpe enorme para empezar."] = "Из незаметности и со спины: огромный первый удар.",
	["Desde el sigilo: aturde al enemigo unos segundos para empezar con ventaja."] = "Из незаметности: оглушает врага на несколько секунд, чтобы ты начал первым.",
	["Desde hoy apunto cada paso grande que demos juntos."] = "С сегодняшнего дня я записываю каждый большой шаг, который мы делаем вместе.",
	["Desde nivel %d"] = "С %d-го уровня",
	["Desde siempre"] = "За все время",
	["Desde tu última visita también hubo cambios en %s: los ves en «Ver todo lo nuevo»."] = "С вашего прошлого визита были изменения и в %s: смотрите их в «Все новое».",
	["Desencanta los objetos verdes y azules que no uses para sacar polvos, esencias y fragmentos."] = "Распыляй ненужные зеленые и синие предметы, чтобы получить пыль, сущности и осколки.",
	["Desencantar ≈ %s"] = "Распылить ≈ %s",
	["Desencantar: ≈ %s por objeto%s. Pide Encantamiento %d."] = "Распыление: ≈ %s за предмет%s. Нужно наложение чар %d.",
	["Deseo de muerte: mucho más daño un rato; úsalo en peleas largas."] = "Жажда смерти: намного больше урона на время; используйте в долгих боях.",
	["Desgarrar hace más daño mientras el monstruo sangra; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона, пока монстр истекает кровью; оно нужно для Глубоких ран.",
	["Desgarrar hace más daño; lo necesitas para Heridas profundas."] = "Кровопускание наносит больше урона; оно нужно для Глубоких ран.",
	["Desgarrar te prepara más Abrumar: más golpes que no se pueden esquivar."] = "Кровопускание чаще открывает Превосходство: больше ударов, от которых нельзя уклониться.",
	["Deshacer"] = "Отменить",
	["Deshacer preajuste"] = "Отменить набор",
	["Desmarca las metas hechas de este personaje (las que ya se cumplen se vuelven a marcar solas)."] = "Снимает отметки с выполненных целей этого персонажа (уже выполненные отметятся снова сами).",
	["Desmarcar"] = "Снять отметку",
	["Desollar es de las formas más fáciles de hacer oro mientras subes de nivel."] = "Снятие шкур — один из самых простых способов зарабатывать золото при прокачке.",
	["Desollar y Peletería van de la mano: tú consigues el cuero y tú lo trabajas."] = "Снятие шкур и кожевничество идут рука об руку: ты добываешь кожу, ты же ее и обрабатываешь.",
	["Despojar más rápido"] = "Быстрый сбор добычи",
	["Después"] = "Позже",
	["Después de"] = "После",
	["Después de cada golpe, regresa a tu lugar rápido."] = "После каждого отбрасывания быстро возвращайтесь на место.",
	["Después de estos siguen %d más."] = "Дальше еще %d.",
	["Después de otra"] = "После другого задания",
	["Después de tu segunda pelea, aquí ves la de antes."] = "После второго боя здесь виден предыдущий.",
	["Después de un crítico atacas más rápido: más golpes, más ira."] = "После критического удара вы атакуете быстрее: больше ударов, больше ярости.",
	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "После него зажигаются жаровни алтаря и приходят волны противников: подготовьтесь заранее.",
	["Después del combate"] = "После боя",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "После первого босса пленник вашей фракции открывает дверь: поговорите с ним.",
	["Después sigue"] = "Дальше",
	["Después: %d %% del nivel %d"] = "После: %d %% уровня %d",
	["Después: nivel %d"] = "После: уровень %d",
	["Destierra a un demonio o elemental un rato. Buen control en mazmorras."] = "Изгоняет демона или элементаля на время. Хороший контроль в подземельях.",
	["Destino"] = "Цель",
	["Destrucción"] = "Разрушение",
	["Destrucción para subir"] = "Разрушение для прокачки",
	["Desuellas lo que matas y lo conviertes en armaduras de cuero para ti; lo que sobra se vende."] = "Вы снимаете шкуры с убитых и делаете из них кожаную броню для себя; остальное продается.",
	["Desuello"] = "Снятие шкур",
	["Desuello es su mejor pareja. Los hilos y la sal los venden los proveedores de peletería."] = "Лучший напарник — снятие шкур. Нитки и соль продают поставщики кожевников.",
	["Desvanecer objetos lejanos"] = "Растворять дальние объекты",
	["Desvías golpes con tu arma."] = "Вы отражаете удары своим оружием.",
	["Detalle al pasar el ratón"] = "Подробности при наведении",
	["Detalle de la guía"] = "Подробности гайда",
	["Detalle de los edificios"] = "Детализация зданий",
	["Detalle de los objetos"] = "Детализация объектов",
	["Detalle del agua"] = "Детализация воды",
	["Detalle del terreno"] = "Детализация рельефа",
	["Detalle fino"] = "Мелкие детали",
	["Detener"] = "Остановить",
	["Detener (%d/%d)"] = "Стоп (%d/%d)",
	["Detrás de «%s» hay más de lo que parece. ¿Te la cuento?"] = "За «%s» скрывается больше, чем кажется. Рассказать?",
	["Devolver"] = "Вернуть",
	["Devolver los avisos a su lugar"] = "Вернуть оповещения на место",
	["Devolverlos todos"] = "Вернуть все",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "Возвращает каждую настройку, которую трогал Alfa, к прежнему значению и перестает их поддерживать.",
	["Devuelve los valores que tenías antes del último preajuste."] = "Возвращает значения, которые были до последнего набора.",
	["Diario"] = "Дневник",
	["Diario de mazmorras"] = "Журнал подземелий",
	["Diario de pesca"] = "Журнал рыбалки",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Рисует полное изображение каждой зоны, обрезанное по ее форме, со встроенными детальными текстурами. Без них карта остается целой, просто переходы между зонами мягче.",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "Рисует маршрут к цели: где идти, лететь или плыть.",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "Пишет в чат, какое задание вы потеряете, и оставляет решение вам.",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "Говорят, Сумеречный лес потемнел из-за близости к Каражану и с тех пор живет в полумраке.",
	["Dicen que en Thelsamar venden morcilla. ¡Es casi una salchicha! Solo digo."] = "Говорят, в Телсамаре продают кровяную колбасу. Это почти сосиска! Я просто так сказала.",
	["Dices cuánto vas a jugar y Alfa arma tu plan: entregar, cerrar misiones, una mazmorra si cabe y lo demás."] = "Скажи, сколько будешь играть, и Alfa составит план: сдача заданий, завершение, подземелье, если влезет, и остальное.",
	["Diestro"] = "Сноровка",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "Десять тысяч лет назад Иллидан создал на вершине Хиджала новый Источник Вечности, и над ним посадили Нордрассил.",
	["Diez niveles juntos. Ya hueles a aventura."] = "Десять уровней вместе. От тебя уже пахнет приключениями.",
	["Dinero de toda la cuenta"] = "Деньги всей учетной записи",
	["Dinero de tus personajes"] = "Деньги ваших персонажей",
	["Disciplina"] = "Послушание",
	["Disciplina para subir"] = "Послушание для прокачки",
	["Dispara desde lejos: alguien debe ir por él."] = "Он стреляет издалека: кто-то должен к нему подойти.",
	["Disparas mucho más rápido un rato. Guárdalo para los jefes."] = "Ты стреляешь намного быстрее на время. Береги для боссов.",
	["Disparo apuntado: tu disparo más fuerte."] = "Прицельный выстрел: ваш самый сильный выстрел.",
	["Disparo arcano: instantáneo, úsalo cuando esté listo."] = "Чародейский выстрел: мгновенный, применяйте, как только готов.",
	["Disponible a nivel %d"] = "Доступно на %d-м уровне",
	["Distancia"] = "Дальний бой",
	["Distancia a la que ciudades, torres y cuevas conservan su detalle."] = "Расстояние, на котором города, башни и пещеры сохраняют детализацию.",
	["Distancia a la que el suelo conserva su forma completa."] = "Расстояние, на котором земля сохраняет полную форму.",
	["Distancia de las placas"] = "Дальность индикаторов здоровья",
	["Distancia de visión"] = "Дальность обзора",
	["Distancia del pasto"] = "Дальность травы",
	["Distancia y velocidad"] = "Расстояние и скорость",
	["Doble clic derecho"] = "Двойной щелчок ПКМ",
	["Doble clic derecho para lanzar"] = "Двойной щелчок ПКМ — забросить",
	["Doble clic mientras pescas vuelve a lanzar"] = "Двойной щелчок во время рыбалки забрасывает снова",
	["Dolanaar es la aldea élfica en el camino a Darnassus; su posada huele a bosque."] = "Доланаар — эльфийская деревня по дороге в Дарнас; в ее таверне пахнет лесом.",
	["Domestica una bestia para que sea tu compañera. Elige una de tu nivel o menos."] = "Приручает зверя в спутники. Выбирай своего уровня или ниже.",
	["Domingo"] = "Воскресенье",
	["Domingo de concurso"] = "Воскресное состязание",
	["Dominio de bestias"] = "Чувство зверя",
	["Dominio de bestias para subir"] = "Чувство зверя для прокачки",
	["Donde antes estaba el Pozo de la Eternidad hoy gira el Maelstrom, un remolino eterno en medio del Gran Mar."] = "Там, где был Источник Вечности, теперь кружит Водоворот — вечная воронка посреди Великого моря.",
	["Donde lo sacas: %s."] = "Где ловится: %s.",
	["Donde más rinde"] = "Где выгоднее всего",
	["Donde más rinde: %s (nivel %d), y cuenta para %s."] = "Выгоднее всего: %s (уровень %d), и это идет в зачет: %s.",
	["Donde puedes seguir en varias zonas, toma la recomendada sin preguntar."] = "Если продолжить можно в нескольких зонах, без вопросов выбирает рекомендуемую.",
	["Dormir"] = "Сон",
	["Dos armas"] = "Два оружия",
	["Dos armas y mucha ira. Furia pega más que Armas cuando tiene buen equipo, y Sed de sangre llega al nivel 40. Necesitas dos armas de una mano desde el nivel 20."] = "Два оружия и много ярости. С хорошей экипировкой Неистовство бьет сильнее, чем Оружие, а Кровожадность приходит на 40 уровне. С 20 уровня вам нужны два одноручных оружия.",
	["Dos clics y Alfa te lleva"] = "Два щелчка, и Alfa отведет вас",
	["Dos manos"] = "Двуручное",
	["Dos monstruos a la vez dejan de ser un problema."] = "Два монстра сразу перестают быть проблемой.",
	["Dos profesiones de recolección: oro constante sin perder tiempo, justo cuando más lo necesitas."] = "Две собирательные профессии: стабильное золото без потери времени, как раз когда оно нужнее всего.",
	["Drek'Thar, el viejo chamán ciego del clan Lobo Gélido, le enseñó a Thrall a hablar con los espíritus. ¡Un sabio de los lobos!"] = "Дрек'Тар, старый слепой шаман клана Северного Волка, научил Тралла говорить с духами. Мудрец среди волков!",
	["Drenar alma al rematar te da uno."] = "«Похищение души» при добивании дает один.",
	["Druida"] = "Друид",
	["Druidas, guerreros y pícaros: si tu barra de forma o de actitud está vacía, Alfa te avisa y la llena con un clic."] = "Друиды, воины и разбойники: если панель облика или стойки пуста, Alfa предупредит вас и заполнит ее одним щелчком.",
	["Duelos"] = "Дуэли",
	["Duerme a un enemigo sin pelear. Perfecto para controlar uno en las mazmorras."] = "Выводит врага из строя без боя. Идеально для контроля в подземельях.",
	["Duerme a un jugador y lanza sombras: interrúmpelo."] = "Он усыпляет игрока и применяет темную магию: прерывайте его.",
	["Duerme a una bestia o a un dragón. Buen control en mazmorras."] = "Усыпляет зверя или дракона. Хороший контроль в подземельях.",
	["Dun Algaz es el túnel enano que une Los Humedales con Loch Modan."] = "Дун Альгаз — дворфийский туннель между Болотиной и Лок Моданом.",
	["Duplicar"] = "Дублировать",
	["Durabilidad"] = "Прочность",
	["Duración"] = "Длительность",
	["Durante la pelea despierta a guardianes de piedra: alguien debe tanquearlos o mátenlos rápido."] = "Во время боя он пробуждает каменных стражей: кто-то должен их танковать, или убейте их быстро.",
	["Durante siglos los druidas durmieron en el Sueño Esmeralda mientras las Centinelas cuidaban el bosque."] = "Веками друиды спали в Изумрудном Сне, пока Часовые охраняли лес.",
	["Durotan y su clan Lobo Gélido se negaron a beber la sangre de Mannoroth. Gul'dan nunca se lo perdonó."] = "Дуротан и его клан Северного Волка отказались пить кровь Маннорота. Гул'дан так этого и не простил.",
	["Durotar lleva el nombre de Durotan, el padre de Thrall y jefe del clan Lobo Gélido. Thrall honró su memoria al nombrar así la tierra de los orcos."] = "Дуротар назван в честь Дуротана, отца Тралла и вождя клана Северного Волка. Тралл почтил его память, дав это имя земле орков.",
	["Dónde"] = "Где",
	["Dónde anda la manada"] = "Где бродит стая",
	["Dónde aprender Pesca y sus rangos. Se llenan al abrir la guía de pesca."] = "Где изучить рыбную ловлю и ее ступени. Заполняется, когда вы открываете гайд по рыбалке.",
	["Dónde empieza el paisaje lejano simplificado."] = "Где начинается упрощенный дальний пейзаж.",
	["Dónde entregar"] = "Где сдавать",
	["Dónde está"] = "Где находится",
	["Dónde está cada uno, lo que vende, lo que suelta y sus misiones."] = "Где находится каждый, что продает, что роняет и его задания.",
	["Dónde está lo que pide cada misión de tu grupo y quién la lleva."] = "Где выполняется каждое задание твоей группы и у кого оно есть.",
	["Dónde mandarlo"] = "Куда отправить",
	["Dónde sale"] = "Где добыть",
	["Dónde se entrega"] = "Где сдавать",
	["Dónde se ven"] = "Где показывать",
	["Editar"] = "Изменить",
	["Edwin VanCleef, el jefe Defias, era maestro cantero. Cuando la nobleza no pagó la reconstrucción de Ventormenta, juró venganza."] = "Эдвин ван Клиф, главарь Братства Справедливости, был мастером-каменщиком. Когда знать не заплатила за восстановление Штормграда, он поклялся отомстить.",
	["Efecto activo"] = "Активный эффект",
	["Efecto del vacío"] = "Эффект Пустоты",
	["Efectos"] = "Эффекты",
	["Efectos de pantalla del juego"] = "Экранные эффекты игры",
	["Ej.: Comprar bolsas de 10 casillas"] = "Напр.: Купить сумки на 10 ячеек",
	["Ejecutar cuesta menos ira: rematas antes."] = "Казнь стоит меньше ярости: вы добиваете раньше.",
	["Ejecutar más barato para rematar jefes."] = "Более дешевая Казнь, чтобы добивать боссов.",
	["El Alba Argenta pelea contra la Plaga sin el fanatismo de los Escarlatas, y recibe por igual a la Alianza y a la Horda."] = "Серебряный Рассвет сражается с Плетью без фанатизма Алого ордена и одинаково принимает Альянс и Орду.",
	["El Bastión Plumaluna, en una isla frente a la costa, es el puesto de las centinelas élficas."] = "Крепость Оперенной Луны на острове у побережья — застава эльфийских часовых.",
	["El Bosque del Ocaso y las Montañas Crestagrana también son tierras del reino, y piden ayuda porque los soldados no alcanzan."] = "Сумеречный лес и Красногорье — тоже земли королевства, и они просят помощи, потому что солдат не хватает.",
	["El Campamento Mojache es el hogar de la Horda en Feralas."] = "Лагерь Мохаче — дом Орды в Фераласе.",
	["El Castillo de Colmillo Oscuro fue de Arugal, un mago de Dalaran que convocó a los worgen para pelear contra la Plaga y terminó perdiendo la razón."] = "Крепость Темного Клыка принадлежала Аругалу, магу из Даларана, который призвал воргенов против Плети и в итоге лишился рассудка.",
	["El Claro de la Luna es un santuario de druidas; ahí se reúne el Círculo Cenarion."] = "Лунная поляна — святилище друидов; здесь собирается Круг Кенария.",
	["El Codex no sabe de dónde sale; si ya la tienes, la ves en tu diario de monturas."] = "Codex не знает, откуда он берется; если он у вас уже есть, он виден в журнале транспорта.",
	["El Cruce es un puesto de la Horda justo en medio de Los Baldíos, donde se juntan los caminos principales. De ahí su nombre."] = "Перекресток — застава Орды прямо посреди Степей, где сходятся главные дороги. Отсюда и название.",
	["El Culto de los Malditos lo fundó Kel'Thuzad: les prometía a los campesinos de Lordaeron una vida eterna y más justa."] = "Культ Проклятых основал Кел'Тузад: он обещал крестьянам Лордерона вечную и более справедливую жизнь.",
	["El Discord de La Jauría"] = "Discord La Jauría",
	["El Festival de Invierno me pone de buenas. Busca al Abuelo Invierno: siempre trae algo para ti."] = "Зимний Покров поднимает мне настроение. Найди Дедушку Зиму: у него всегда есть что-то для тебя.",
	["El Fuerte Cenarion es la base del Círculo Cenarion en Silithus, frente a los qiraji."] = "Крепость Кенария — база Круга Кенария в Силитусе, напротив киражей.",
	["El Gran Manitas Gelbin Mekkatorque es el líder de los gnomos."] = "Главный механик Гельбин Меккаторк — лидер гномов.",
	["El Guardián Remulos, hijo de Cenarius, cuida el Claro de la Luna desde su santuario."] = "Хранитель Ремул, сын Кенария, оберегает Лунную поляну из своего святилища.",
	["El Horado Rajacieno y la Zahúrda Rajacieno son guaridas de los jabaespines, entre Los Baldíos y Las Mil Agujas."] = "Лабиринты Иглошкурых и Курганы Иглошкурых — логова свинобразов между Степями и Тысячей Игл.",
	["El Legado se abre con tu primer punto (casi siempre, al llegar a nivel 25), con la tecla Y o con su botón del menú."] = "«Наследие» открывается с первым очком (почти всегда на 25-м уровне), клавишей Y или кнопкой в меню.",
	["El Loto negro crece solo en zonas de nivel muy alto, y es tan raro que vale una fortuna."] = "Черный лотос растет только в зонах очень высокого уровня и так редок, что стоит целое состояние.",
	["El Loto negro es rarísimo: crece en Cuna del Invierno, las Estepas Ardientes, las Tierras de la Peste del Este y Silithus."] = "Черный лотос — большая редкость: он растет в Зимних Ключах, Пылающих степях, Восточных Чумных землях и Силитусе.",
	["El Martillo Crepuscular tiene campamentos en Silithus, donde intenta invocar a los señores elementales."] = "У Сумеречного Молота есть лагеря в Силитусе, где они пытаются призвать повелителей стихий.",
	["El Núcleo de Magma, en el fondo de la Montaña Roca Negra, es el hogar de Ragnaros, el Señor del Fuego."] = "Огненные Недра в глубине Черной горы — дом Рагнароса, Повелителя Огня.",
	["El Paso de la Muerte no tiene ni un pueblo: solo ogros, bestias y la sombra de Karazhan."] = "На Перевале Мертвого Ветра нет ни одного поселения: только огры, звери и тень Каражана.",
	["El Paso de la Muerte une el Bosque del Ocaso con el Pantano de las Penas."] = "Перевал Мертвого Ветра соединяет Сумеречный лес с Болотом Печали.",
	["El Portal Oscuro está apagado en el Clásico. En Burning Crusade vuelve a abrirse rumbo a Terrallende."] = "В классике Темный портал не действует. В Burning Crusade он снова откроется — в Запределье.",
	["El Portal Oscuro lo abrieron Medivh y Gul'dan juntos, cada uno desde su lado."] = "Темный портал открыли Медив и Гул'дан вместе, каждый со своей стороны.",
	["El Puente Thandol, al norte, une Khaz Modan con Arathi; los Hierro Negro lo dejaron medio destruido."] = "Мост Тандола на севере соединяет Каз Модан с Нагорьем Арати; дворфы Черного Железа оставили его полуразрушенным.",
	["El Puerto de Menethil lleva el apellido de la familia real de Lordaeron. De ahí salen barcos a Theramore y a Auberdine."] = "Гавань Менетилов носит имя королевской семьи Лордерона. Отсюда корабли идут в Терамор и Аубердин.",
	["El Puesto Hachazo es el campamento de la Horda que tala Vallefresno."] = "Застава Расщепленного Дерева — лагерь Орды, который вырубает Ясеневый лес.",
	["El Refugio Roca del Sol es el hogar de los tauren en estas montañas."] = "Приют Солнечного Камня — дом тауренов в этих горах.",
	["El Refugio de la Zaga es el campamento de la Alianza en Arathi, entre ruinas, trols y ogros."] = "Опорный пункт — лагерь Альянса в Нагорье Арати, среди руин, троллей и огров.",
	["El Refugio del Mariscal es el único campamento del cráter, y lo comparten todos."] = "Убежище Маршалла — единственный лагерь в кратере, и он общий для всех.",
	["El SI:7 de Ventormenta y Ravenholdt son nombres que todo pícaro conoce."] = "ШРУ:7 из Штормграда и Черный Ворон — имена, которые знает каждый разбойник.",
	["El Sepulcro es el puesto de los Renegados en el bosque; desde ahí vigilan a los worgen y a los magos de Dalaran."] = "Гробница — застава Отрекшихся в лесу; отсюда они следят за воргенами и магами Даларана.",
	["El Sindicato, los nobles caídos de Alterac, también asalta caminos y granjas por estas tierras."] = "Синдикат, павшая знать Альтерака, тоже грабит дороги и фермы в этих краях.",
	["El Sueño Esmeralda se está volviendo pesadilla: algo corrompe a los dragones verdes que lo cuidan."] = "Изумрудный Сон превращается в кошмар: что-то оскверняет охраняющих его зеленых драконов.",
	["El Tranvía Subterráneo une Forjaz con Ventormenta por debajo de la tierra. Lo construyeron los gnomos."] = "Подземный поезд соединяет Стальгорн и Штормград под землей. Его построили гномы.",
	["El Trono Helado es la armadura de hielo donde quedó atrapado Ner'zhul, en lo alto de la Corona de Hielo."] = "Ледяной Трон — ледяная броня, в которой заточен Нер'зул, на вершине Ледяной Короны.",
	["El Valle Calcinado, al sur de la sierra, quedó quemado y lleno de elementales de fuego."] = "Обугленная долина к югу от гор выжжена и полна огненных элементалей.",
	["El Vigía de Morgan es el puesto de la Alianza en las estepas, desde donde vigilan la Montaña Roca Negra."] = "Застава Моргана — аванпост Альянса в степях, откуда следят за Черной горой.",
	["El aguante es tu mejor amigo: más vida para más Transfusión de vida."] = "Выносливость — ваш лучший друг: больше здоровья для большего числа Жизнеотводов.",
	["El alfa de La Jauría anda cerca"] = "Альфа La Jauría где-то рядом",
	["El almirante Daelin Valiente, padre de Jaina, cayó en Theramore tras atacar a la Horda. Su hija eligió la paz."] = "Адмирал Делин Праудмур, отец Джайны, погиб у Терамора, напав на Орду. Его дочь выбрала мир.",
	["El archidruida Fandral Corzocelada enseña en el Enclave Cenarion de Darnassus."] = "Верховный друид Фэндрал Олений Шлем учит в Анклаве Кенария в Дарнасе.",
	["El archidruida Fandral Corzocelada plantó Teldrassil con la esperanza de recuperar la inmortalidad que los elfos perdieron en el Monte Hyjal."] = "Верховный друид Фэндрал Олений Шлем посадил Тельдрассил в надежде вернуть бессмертие, которое эльфы потеряли у горы Хиджал.",
	["El archidruida Hamuul Tótem de Runa enseña a los druidas tauren, y fue de los primeros tauren aceptados en el Círculo Cenarion."] = "Верховный друид Хамуул Рунический Тотем учит друидов-тауренов; он был одним из первых тауренов, принятых в Круг Кенария.",
	["El arma principal debe ser la más lenta y fuerte; la secundaria, la más rápida."] = "Оружие в правой руке должно быть самым медленным и сильным, а в левой — самым быстрым.",
	["El aro y la cabecera del minimapa con tu estilo."] = "Кольцо и заголовок мини-карты в вашем стиле.",
	["El banco está lleno: compra otra casilla o pon una bolsa más grande en el banco."] = "Банк заполнен: купите еще ячейку или положите в банк сумку побольше.",
	["El barco a %s ya viene"] = "Корабль до %s уже идёт",
	["El barco goblin une Bahía del Botín con Trinquete, y lo pueden usar los dos bandos."] = "Гоблинский корабль соединяет Пиратскую Бухту с Кабестаном, и им могут пользоваться обе фракции.",
	["El barón Osahendido manda en Stratholme como caballero de la muerte de la Plaga."] = "Барон Ривендер правит Стратхольмом как рыцарь смерти Плети.",
	["El blanco de la interfaz y del cielo de día."] = "Белый цвет интерфейса и дневного неба.",
	["El bonus de tu arma al máximo."] = "Бонус вашего оружия на максимуме.",
	["El borde del minimapa, redondo o cuadrado («Minimapa cuadrado», arriba), y la barra con la zona y la hora toman el estilo que elijas, como la ventana del mapa. Al apagarlo vuelve el de siempre."] = "Рамка мини-карты, круглая или квадратная («Квадратная мини-карта» выше), и панель с зоной и временем принимают выбранный стиль, как окно карты. Если выключить — вернется обычная.",
	["El borde toma el color del perjuicio (magia, maldición, enfermedad o veneno) cuando tú lo puedes quitar."] = "Рамка окрашивается в цвет отрицательного эффекта (магия, проклятие, болезнь или яд), если вы можете его снять.",
	["El botón «Escanear con Alfa» bajo la ventana de la subasta."] = "Кнопка «Сканировать с Alfa» под окном аукциона.",
	["El brillo más alto que da tu monitor; viene en su caja o su ficha."] = "Максимальная яркость вашего монитора; она указана на коробке или в характеристиках.",
	["El brillo suave de luces y cielo en toda la pantalla."] = "Мягкое свечение огней и неба по всему экрану.",
	["El brujo Zalazane les robó las Islas del Eco a los Lanza Negra con su vudú."] = "Колдун Залазан своим вуду отнял Острова Эха у племени Черного Копья.",
	["El buscador"] = "Поиск",
	["El buscador de Ajustes ya encuentra todo: también Pesca, Comercio, Ruta, Bolsas, Combate, Curación, Lya y Estilo y sonido."] = "Поиск по настройкам теперь находит всё: и Рыбалку, и Торговлю, и Маршрут, Сумки, Бой, Лечение, Лию, Стиль и звук.",
	["El buscador del motor está apagado (Ajustes > Descubrir): enciéndelo para que Alfa arme guías."] = "«Поиск» движка выключен (Настройки > Открытия): включите его, чтобы Alfa составлял гайды.",
	["El buscador no está disponible."] = "Поиск недоступен.",
	["El buzón"] = "Почтовый ящик",
	["El calendario de la manada"] = "Календарь стаи",
	["El camino a Entrañas pasa por las ruinas de la Ciudad Capital de Lordaeron, donde Arthas mató a su padre."] = "Путь в Подгород лежит через руины столицы Лордерона, где Артас убил своего отца.",
	["El camino a la meta en el mapa del mundo y el minimapa: una línea o puntos donde caminas, líneas donde vuelas, navegas o montas, y los tramos que siguen más tenues."] = "Путь к цели на карте мира и мини-карте: линия или точки — где идти пешком, линии — где лететь, плыть или ехать; последующие участки бледнее.",
	["El camino en el mapa y el minimapa"] = "Путь на карте и мини-карте",
	["El camino hasta el destino dibujado en el mapa."] = "Путь до цели, нарисованный на карте.",
	["El camino más sencillo para subir: un arma grande, golpes que hacen sangrar y Golpe mortal al nivel 40. Aguantas bien y matas rápido."] = "Самый простой путь прокачки: большое оружие, удары с кровотечением и Смертельный удар на 40 уровне. Вы хорошо держитесь и быстро убиваете.",
	["El camino que baja de la sierra hacia Los Baldíos está lleno de arañas. ¡Brrr!"] = "Дорога с гор в Степи кишит пауками. Бррр!",
	["El chat"] = "Чат",
	["El chat usa la letra de Alfa (la de Ajustes > Apariencia). El tamaño se sigue cambiando en el menú de la pestaña."] = "Чат использует шрифт Alfa (из Настройки > Внешний вид). Размер по-прежнему меняется в меню вкладки.",
	["El clan"] = "Клан",
	["El clan Lobo Gélido monta lobos de verdad. Por eso es mi clan favorito, no lo voy a negar."] = "Клан Северного Волка ездит на настоящих волках. Поэтому это мой любимый клан, не стану скрывать.",
	["El clan Lobo Gélido vive exiliado en el valle de Alterac. Thrall, hijo de su antiguo jefe, los encontró ahí después de escapar de Durnholde."] = "Клан Северного Волка живет в изгнании в Альтеракской долине. Тралл, сын их бывшего вождя, нашел их там после побега из Дарнхольда.",
	["El clic derecho solo sigue alejando el mapa del juego, como siempre."] = "Обычный правый щелчок, как всегда, отдаляет карту игры.",
	["El clic izquierdo solo selecciona"] = "Левый щелчок только выбирает цель",
	["El clásico para pelear contra jugadores: Golpe mortal corta las curas del rival, Seccionar mejorado lo deja quieto y Cargar mejorado te da ira para empezar."] = "Классика для боя с игроками: Смертельный удар режет исцеление противника, Улучшенное подрезание сухожилий не дает ему двигаться, а Улучшенный рывок дает ярость для начала.",
	["El color de mi clase"] = "Цвет моего класса",
	["El comerciante no lo compra"] = "Торговец это не покупает",
	["El contenido va en una columna centrada y se acomoda solo si cambias la resolución o la escala."] = "Содержимое идет по центру одной колонкой и само подстраивается, если вы меняете разрешение или масштаб.",
	["El corcho quedó lejos · relanza con %s"] = "Поплавок упал далеко · перезабросьте: %s",
	["El corcho quedó lejos · vuelve a lanzar"] = "Поплавок упал далеко · забросьте снова",
	["El cuadro del jugador al pasar el ratón. En combate no sale, para no estorbar."] = "Подсказка игрока при наведении. В бою не показывается, чтобы не мешать.",
	["El cártel Bonvapor controla Bahía del Botín, Trinquete, Gadgetzan y Vista Eterna. Por eso esos puertos reciben a todos."] = "Картель Хитрой Шестеренки заправляет Пиратской Бухтой, Кабестаном, Прибамбасском и Круговзором. Поэтому эти порты принимают всех.",
	["El daño por segundo de tu arma a distancia."] = "Урон в секунду вашего оружия дальнего боя.",
	["El daño por segundo del arma: para el guerrero, lo que más cuenta al subir."] = "Урон оружия в секунду: для воина это важнее всего при прокачке.",
	["El daño se lo come tu maná en vez de tu vida."] = "Урон принимает твоя мана вместо здоровья.",
	["El de tu juego"] = "Как в игре",
	["El demosaurio es el gran depredador del cráter: si oyes pasos que retumban, escóndete."] = "Дьявозавр — главный хищник кратера: если слышишь грохочущие шаги, прячься.",
	["El destino de la flecha y sus zonas en el minimapa."] = "Цель стрелки и ее области на мини-карте.",
	["El destino de la flecha, su camino y las otras metas del paso, en el mapa."] = "Цель стрелки, путь к ней и другие цели шага на карте.",
	["El diario de mazmorras del motor está apagado (Ajustes > Descubrir > Mazmorras)."] = "Журнал подземелий движка выключен (Настройки > Открытия > Подземелья).",
	["El diario de mazmorras está apagado"] = "Журнал подземелий выключен",
	["El diario está apagado. Préndelo abajo, en «Lo que Lya nota»."] = "Дневник выключен. Включи его ниже, в «Что замечает Лия».",
	["El dragón azul Azuregos ronda Azshara, cuidando la magia antigua que quedó en sus ruinas."] = "Синий дракон Азурегос бродит по Азшаре, охраняя древнюю магию, оставшуюся в ее руинах.",
	["El druida hace de todo: puedes tanquear, curar o pegar según lo que pida el grupo."] = "Друид умеет все: можно танковать, лечить или наносить урон — смотря что нужно группе.",
	["El emperador Dagran Thaurissan gobierna la Ciudad de Hierro Negro, en las Profundidades de Roca Negra."] = "Император Дагран Тауриссан правит городом Черного Железа в Глубинах Черной горы.",
	["El enemigo esquivó: Abrumar no se puede esquivar y pega fuerte."] = "Противник уклонился: от Превосходства нельзя уклониться, и оно бьет сильно.",
	["El enemigo esquivó: este golpe cuerpo a cuerpo está listo."] = "Противник уклонился: этот удар ближнего боя готов.",
	["El enemigo esquivó: este golpe está listo."] = "Противник уклонился: этот удар готов.",
	["El enemigo está encima: golpéalo cuerpo a cuerpo."] = "Противник вплотную: бейте его в ближнем бою.",
	["El enemigo está lanzando un hechizo: Choque de tierra lo corta."] = "Противник читает заклинание: Земной шок прервет его.",
	["El enemigo está lanzando un hechizo: aturdirlo lo corta."] = "Противник читает заклинание: оглушение прервет его.",
	["El enemigo está lanzando un hechizo: córtalo con tu escudo."] = "Противник читает заклинание: прервите его щитом.",
	["El enemigo está lanzando un hechizo: córtalo."] = "Противник читает заклинание: прервите его.",
	["El enemigo está lanzando un hechizo: el golpe lo corta."] = "Противник читает заклинание: удар прервет его.",
	["El enemigo está por caer: drénale el alma y gana un fragmento."] = "Противник вот-вот падет: похитьте его душу и получите осколок.",
	["El enemigo pega menos. Útil cuando te pega a ti o a tu demonio."] = "Враг бьет слабее. Полезно, когда он бьет тебя или твоего демона.",
	["El enlace del Discord ya está elegido: cópialo con Ctrl+C y pégalo en tu navegador."] = "Ссылка на Discord выделена: скопируйте её Ctrl+C и вставьте в браузер.",
	["El entrenador de oficio más cercano"] = "Ближайший учитель профессии",
	["El espíritu te devuelve maná rápido: descansas muy poco."] = "Дух быстро восполняет ману: вы почти не отдыхаете.",
	["El estilo del mapa (terreno como el minimapa, o el arte clásico) y las opciones de Mundo."] = "Стиль карты (рельеф как на мини-карте или классический рисунок) и настройки мира.",
	["El estilo que elegiste también puede vestir el chat, el minimapa, las barras de abajo y el mapa. Se apaga cuando quieras y todo vuelve a como estaba."] = "Выбранный стиль может оформить и чат, мини-карту, нижние панели и карту. Его можно выключить в любой момент — и все вернется как было.",
	["El final"] = "Концовка",
	["El final de cada misión"] = "Концовка каждого задания",
	["El final de la cadena no da objetos."] = "Конец цепочки не дает предметов.",
	["El final lo verás al entregarla."] = "Концовку вы увидите, когда сдадите задание.",
	["El fondo se ve deformado a través del agua."] = "Дно сквозь воду выглядит искаженным.",
	["El fuego pega a todos los de cerca: mantén la vida alta de quienes pelean cuerpo a cuerpo."] = "Огонь бьет всех рядом: держите высоким здоровье бойцов ближнего боя.",
	["El fundente débil lo venden los proveedores de comercio. Minería te da las piedras y las barras."] = "Слабый флюс продают поставщики ремесленников. Горное дело дает камни и слитки.",
	["El general Drakkisath guarda la entrada a la Guarida Alanegra, en lo alto de la Cumbre de Roca Negra."] = "Генерал Драккисат охраняет вход в Логово Крыла Тьмы на вершине пика Черной горы.",
	["El globo de Lya en una sola línea, con sus botones. Pasa el ratón encima para leerlo completo."] = "Облачко Лии в одну строку, с ее кнопками. Наведи мышь, чтобы прочитать полностью.",
	["El gran cruzado de la Cruzada Escarlata, Saidan Dathrohan, es en realidad el demonio Balnazzar. Lo encuentras en Stratholme."] = "Великий воитель Алого ордена Сайдан Датрохан на самом деле демон Бальназзар. Он ждет тебя в Стратхольме.",
	["El guerrero que más daño hace en mazmorras. Con un tanque delante, tus dos armas no paran, y Ejecutar mejorado remata a los jefes."] = "Воин с самым большим уроном в подземельях. С танком впереди ваши два оружия не останавливаются, а Улучшенная казнь добивает боссов.",
	["El hacha de Grom Grito Infernal tiene nombre propio, y dicen que aúlla cuando corta el aire. ¡Aullar es cosa seria!"] = "У топора Грома Адского Крика есть собственное имя, и говорят, он воет, рассекая воздух. Вой — дело серьезное!",
	["El hierro negro solo se funde en la Forja Negra de las Profundidades de Roca Negra."] = "Черное железо плавят только в Черной Кузне в Глубинах Черной горы.",
	["El hijo de Cairne, Baine, cuida el poblado Pezuña de Sangre en Mulgore."] = "Сын Кэрна, Бейн, оберегает деревню Кровавого Копыта в Мулгоре.",
	["El idioma, el estilo, lo que Alfa hace sola por ti y La Jauría, con «Cambiar» en cada cosa. También con /alfa bienvenida."] = "Язык, стиль, что Alfa делает за вас и La Jauría — с кнопкой «Сменить» у каждого пункта. Также командой /alfa bienvenida.",
	["El izquierdo selecciona y el derecho abre el menú."] = "Левая выбирает цель, правая открывает меню.",
	["El izquierdo selecciona y el derecho abre el menú. Tus buffs para otros se suman aquí al aprenderlos."] = "Левая выбирает цель, правая открывает меню. Ваши баффы для других появятся здесь, когда вы их изучите.",
	["El izquierdo selecciona y el derecho abre el menú. Tú eliges el resto."] = "Левая выбирает цель, правая открывает меню. Остальное выбираете вы.",
	["El izquierdo selecciona y el derecho abre el menú: lo básico, porque tu clase no lanza hechizos sobre sus compañeros."] = "Левая выбирает цель, правая открывает меню: только основное, ведь ваш класс не применяет заклинания к союзникам.",
	["El juego elige entre estas según la situación; el ícono te muestra cuál conviene ahora."] = "Игра выбирает между ними по ситуации; значок показывает, какую лучше применить сейчас.",
	["El juego la hizo brillar: es buen momento para usarla."] = "Игра подсветила ее: самое время применить.",
	["El juego manda la imagen en HDR."] = "Игра выводит изображение в HDR.",
	["El juego no aceptó el lote."] = "Игра не приняла партию.",
	["El juego no aceptó esa tecla."] = "Игра не приняла эту клавишу.",
	["El juego no aceptó la prueba."] = "Игра не приняла проверку.",
	["El juego no da tu posición aquí (en una instancia, por ejemplo)."] = "Игра не сообщает здесь ваше положение (например, в подземелье).",
	["El juego no deja cambiar talentos ahora mismo"] = "Игра сейчас не позволяет менять таланты",
	["El juego no deja cocinar desde aquí."] = "Игра не позволяет готовить отсюда.",
	["El juego no deja enviar mensajes en este momento (un encuentro o una partida). Tu rastro vuelve a salir solo cuando termine."] = "Сейчас игра не позволяет отправлять сообщения (бой с боссом или матч). Ваш след снова начнет передаваться сам, когда все закончится.",
	["El juego no deja que las cuentas de prueba envíen mensajes de addon ni usen canales propios. Tu grupo sí se ve."] = "Игра не позволяет пробным учетным записям отправлять сообщения аддонов и пользоваться своими каналами. Ваша группа все равно видна.",
	["El juego no dejó cambiar las demás."] = "Игра не позволила изменить остальные.",
	["El juego no dejó compartir el marcador ahora. Prueba en un momento."] = "Сейчас игра не позволила поделиться маркером. Попробуйте чуть позже.",
	["El juego no dejó comprar ese rango."] = "Игра не позволила изучить этот ранг.",
	["El juego no dejó entrar al canal oculto de Alfa y, sin hermandad, no hay otro camino para compartir. Alfa lo vuelve a intentar sola en unos minutos. Tu grupo sí se ve."] = "Игра не пустила в скрытый канал Alfa, а без гильдии другого способа делиться нет. Alfa сам попробует снова через несколько минут. Ваша группа все равно видна.",
	["El juego no dice si la tienes"] = "Игра не сообщает, есть ли он у вас",
	["El juego no dio tus puntos todavía: se ven desde que ganas el primero."] = "Игра еще не выдала ваши очки: они видны с момента, как вы заработаете первое.",
	["El juego no la ofrece ahora mismo."] = "Сейчас игра ее не предлагает.",
	["El juego no lo dice ahora."] = "Игра сейчас этого не сообщает.",
	["El juego no permite usar el medidor ahora."] = "Сейчас игра не позволяет использовать измеритель.",
	["El juego no trae la ayuda de Blizzard, así que Alfa sugiere con su prioridad para %s, leyendo solo tu personaje: tu recurso, tus efectos y lo que el juego te deja usar. Con 3 o más enemigos cambia a las de área. Tú decides qué presionar."] = "В игре нет помощника Blizzard, поэтому Alfa подсказывает по своему приоритету (%s), читая только вашего персонажа: ресурс, эффекты и то, что игра позволяет применить. При 3 противниках и больше переключается на способности по области. Что нажимать, решаете вы.",
	["El juego oculta los números exactos mientras peleas: la barra y la cifra se ven, el detalle al salir de combate."] = "Во время боя игра скрывает точные числа: полоса и цифра видны, подробности — после выхода из боя.",
	["El juego rechazó confirmar los cambios. Se deshicieron para que tu árbol quede como estaba."] = "Игра отказалась подтвердить изменения. Они отменены, и ваше дерево осталось как было.",
	["El juego solo deja cambiarla fuera de combate."] = "Игра позволяет изменить это только вне боя.",
	["El juego te pasó a la %s. Otra gente, otros raros, otros minerales."] = "Игра перенесла тебя в: %s. Другие люди, другие редкие, другая руда.",
	["El juego todavía no carga tu árbol"] = "Игра еще не загрузила ваше дерево",
	["El juego todavía no carga tu árbol."] = "Игра еще не загрузила ваше дерево.",
	["El juego todavía no cargó tus talentos. Espera unos segundos o abre la ventana de talentos (tecla N) una vez."] = "Игра еще не загрузила ваши таланты. Подождите несколько секунд или откройте окно талантов (клавиша N) один раз.",
	["El juego todavía no dio la lista de retos: ábrelo con la tecla Y."] = "Игра еще не выдала список испытаний: откройте его клавишей Y.",
	["El juego todavía no la abre: se abre con tu primer punto del Legado (casi siempre, al llegar a nivel 25)."] = "Игра его пока не открывает: оно откроется с вашим первым очком «Наследия» (почти всегда на 25-м уровне).",
	["El juego todavía no tiene los datos de algunos objetos. En un momento aparecen."] = "У игры пока нет данных о некоторых предметах. Они появятся через мгновение.",
	["El juego todavía oculta los números o los nombres (pasa en combate y dentro de mazmorras). Inténtalo al salir."] = "Игра все еще скрывает числа или имена (так бывает в бою и в подземельях). Попробуйте после выхода.",
	["El lago Lordamere separa el Bosque de Argénteos de las Laderas de Trabalomas y de las Montañas de Alterac."] = "Озеро Лордамир отделяет Серебряный бор от Предгорий Хилсбрада и Альтеракских гор.",
	["El lago de Loch Modan existe gracias a una enorme presa enana. Si se rompiera, el agua arrasaría las tierras de abajo."] = "Озеро Лок Модана существует благодаря огромной дворфийской плотине. Если она прорвется, вода смоет земли внизу.",
	["El lago del Claro de la Luna se llama Elune'ara, en honor a la diosa de la luna."] = "Озеро на Лунной поляне называется Элуна'ара — в честь богини луны.",
	["El lago helado de Kel'Theril guarda ruinas de los Altonato."] = "Замерзшее озеро Кел'Терил хранит руины высокорожденных.",
	["El lobo de la intro aúlla de pie sobre la peña, con un aullido largo que otro lobo contesta; y al entrar, Lya llega corriendo a decirte que te extrañó."] = "Волк в заставке воет стоя на скале — долгий вой, на который отвечает другой волк; а когда ты входишь в игру, Lya прибегает и говорит, что скучала по тебе.",
	["El lobo te recibe al entrar"] = "Волк встречает вас при входе",
	["El lobo te recibe cada vez que entras al juego, redibujado: cabeza, orejas y hocico de lobo de verdad."] = "Волк встречает вас при каждом входе в игру — перерисованный: голова, уши и морда настоящего волка.",
	["El maestro de vuelo, la posada, reparar, el banco y más, con la flecha."] = "Распорядитель полетов, таверна, ремонт, банк и другое — со стрелкой.",
	["El maestro de vuelo, la posada, reparar, el banco y más: el más cercano, con la flecha y la ruta."] = "Распорядитель полетов, таверна, ремонт, банк и другое: ближайший, со стрелкой и маршрутом.",
	["El maestro de vuelo, la posada, reparar, el banco... el más cercano (/alfa cerca ayuda)."] = "Распорядитель полетов, таверна, ремонт, банк... ближайший (/alfa cerca ayuda).",
	["El mago Rhonin y el dragón Korialstrasz ayudaron a liberar a Alexstrasza en Grim Batol, y ahí quedó destruida el Alma de Demonio."] = "Маг Ронин и дракон Кориалстраз помогли освободить Алекстразу в Грим Батоле, и там же была уничтожена Душа Демона.",
	["El mago que más daño hace: hechizos de fuego y críticos que queman."] = "Маг с самым большим уроном: огненные заклинания и обжигающие критические удары.",
	["El mapa a tu gusto"] = "Карта на ваш вкус",
	["El mapa abre sin errores con M y se arrastra suave, aunque empieces encima de un ícono."] = "Карта открывается по M без ошибок и плавно перетаскивается, даже если начать над значком.",
	["El mapa de Alfa"] = "Карта Alfa",
	["El mapa de Alfa muestra el terreno real, con puntos de vuelo, mazmorras, barcos, zepelines y portales."] = "Карта Alfa показывает настоящий рельеф с точками полетов, подземельями, кораблями, дирижаблями и порталами.",
	["El mapa de Alfa, el del juego y el minimapa. Si algo te estorba, apágalo aquí; los otros módulos de Alfa agregan sus capas a esta misma lista."] = "Карта Alfa, карта игры и мини-карта. Если что-то мешает, выключите здесь; другие модули Alfa добавляют свои слои в этот же список.",
	["El mapa del mundo entero con zoom, tus marcadores y un solo control para todo lo que se pinta."] = "Карта всего мира с масштабом, вашими маркерами и одним переключателем для всего, что на ней рисуется.",
	["El mapa no se abre en combate."] = "Карта не открывается в бою.",
	["El mapa se ve más limpio: sin líneas finas entre sus pedazos ni halos oscuros en las orillas de las zonas."] = "Карта стала чище: никаких тонких линий между её частями и тёмных ореолов по краям зон.",
	["El mar paga"] = "Море платит",
	["El marco de las barras de experiencia y reputación; el relleno conserva sus colores."] = "Рамка полос опыта и репутации; заполнение сохраняет свои цвета.",
	["El marco del menú del juego y de las bolsas, abajo a la derecha."] = "Рамка меню игры и сумок, внизу справа.",
	["El marco del tanque late en rojo cuando le queda menos del 40 % de vida."] = "Рамка танка мигает красным, когда у него меньше 40 % здоровья.",
	["El mariscal Dughan cuida Villadorada y siempre anda buscando quien le eche la mano con los problemas de Elwynn."] = "Маршал Дуган охраняет Златоземье и всегда ищет, кто поможет с бедами Элвиннского леса.",
	["El medallón bajo cada marca del mapa y del minimapa: el de Alfa o solo el símbolo, sin medallón."] = "Медальон под каждой меткой на карте и мини-карте: от Alfa или только символ, без медальона.",
	["El medidor de daño aguanta en combate y la ayuda de rotación ya no te pide interrumpir lo que no se puede."] = "Измеритель урона держится в бою, а помощник ротации больше не просит прерывать то, что прервать нельзя.",
	["El medidor del juego no tiene números de esta pelea."] = "У измерителя игры нет цифр по этому бою.",
	["El medidor no está disponible"] = "Измеритель недоступен",
	["El mejor que tengas"] = "Лучшая, что есть",
	["El mekigeniero Termochufe, el traidor de Gnomeregan, sigue escondido dentro de la ciudad: es su último jefe."] = "Анжинер Термоштепсель, предатель Гномрегана, все еще прячется в городе: он его последний босс.",
	["El mentor está apagado (Ajustes de La Jauría)."] = "Наставник выключен (настройки La Jauría).",
	["El menú de la lupa del mapa del juego tiene también todas las capas de Alfa."] = "В меню лупы на карте игры тоже есть все слои Alfa.",
	["El menú y las bolsas del juego"] = "Меню и сумки игры",
	["El mineral se funde en barras en cualquier forja."] = "Руду переплавляют в слитки в любой кузне.",
	["El minimapa"] = "Мини-карта",
	["El minimapa de Recolección descansa cuando no tiene nada que mostrar."] = "Мини-карта Сбора отдыхает, когда ей нечего показать.",
	["El minimapa pasa de redondo a cuadrado, con un borde fino. No se recomienda junto con girar el minimapa."] = "Мини-карта становится не круглой, а квадратной, с тонкой рамкой. Не рекомендуется вместе с вращением мини-карты.",
	["El mismo arreglo llegó a los asistentes de Ruta y de Curación."] = "То же исправление пришло в помощники «Маршрута» и «Исцеления».",
	["El mitril abunda en las Tierras Inhóspitas, las Tierras del Interior y Tanaris."] = "Мифрила много в Бесплодных землях, Внутренних землях и Танарисе.",
	["El modelo no lleva nada aquí."] = "На модели здесь ничего нет.",
	["El modo pesca se abre al salir de combate."] = "Режим рыбалки откроется после выхода из боя.",
	["El modo prueba se usa fuera de combate."] = "Тестовый режим работает вне боя.",
	["El motor no aceptó la guía."] = "Движок не принял гайд.",
	["El motor no puede armar guías ahora."] = "Движок сейчас не может составлять гайды.",
	["El mundo entero en un mapa"] = "Весь мир на одной карте",
	["El mundo pierde el color mientras eres espíritu."] = "Мир теряет цвет, пока вы в виде духа.",
	["El más bajo que viste, %s."] = "Самая низкая, что ты видел: %s.",
	["El más cercano cuando le toque, por tiempo de camino."] = "Ближайший, когда до него дойдет очередь, по времени пути.",
	["El más cercano, por tiempo de camino"] = "Ближайший по времени пути",
	["El más cercano: %s"] = "Ближайший: %s",
	["El más reciente"] = "Последняя",
	["El módulo Curación no está cargado."] = "Модуль «Исцеление» не загружен.",
	["El nombre de cada zona sobre el mapa de Alfa."] = "Название каждой зоны на карте Alfa.",
	["El número abajo a la izquierda de cada pieza de equipo."] = "Число в левом нижнем углу каждой вещи экипировки.",
	["El número es el orden en que se toma. Pasa el ratón por un talento para ver qué hace."] = "Число — порядок, в котором берется талант. Наведите курсор на талант, чтобы узнать, что он дает.",
	["El número que cuenta hacia atrás. Apagado, solo la barra."] = "Обратный отсчет цифрами. Выключено: только полоса.",
	["El objeto"] = "Предмет",
	["El objeto que usa el paso actual, o el objeto de misión que junta, brilla en tus bolsas. Un objeto que necesita un paso más adelante lleva un candado, para que no lo vendas."] = "Предмет, который использует текущий шаг, или собираемый предмет задания светится в сумках. Предмет, нужный на одном из следующих шагов, получает замок, чтобы вы его не продали.",
	["El orden importa más que los números: busca piezas con las primeras de la lista."] = "Порядок важнее чисел: ищите вещи с первыми характеристиками из списка.",
	["El paisaje lejano deja de perderse en la niebla espesa."] = "Дальний пейзаж больше не теряется в густом тумане.",
	["El paisaje lejano deja de perderse en la niebla espesa. A veces se nota dónde termina lo que está cargado."] = "Дальний пейзаж больше не теряется в густом тумане. Иногда видно, где кончается загруженная область.",
	["El paquete de datos de Alfa (Alfa_Codex) está desactivado: actívalo en la lista de addons y recarga."] = "Пакет данных Alfa (Alfa_Codex) отключен: включите его в списке модификаций и перезагрузите интерфейс.",
	["El paso de ahora de tu guía te lleva a entrenar."] = "Текущий шаг гайда ведет вас к учителю.",
	["El pequeño rey Anduin Wrynn lleva su nombre en honor a Anduin Lothar, el héroe que salvó a su pueblo."] = "Юного короля Андуина Ринна назвали в честь Андуина Лотара, героя, спасшего его народ.",
	["El primer clic abre la Cocina del juego; el siguiente cocina el lote. Tienes que estar junto a un fuego."] = "Первый щелчок открывает окно «Кулинария» в игре, следующий готовит партию. Нужно стоять у огня.",
	["El primer jefe de guerra de la Horda fue Mano Negra. Su hijo Rend Mano Negra hoy sirve a Nefarian en la Cumbre de Roca Negra."] = "Первым вождем Орды был Чернорук. Его сын Ренд Чернорук теперь служит Нефариану на пике Черной горы.",
	["El primer punto del Legado suele llegar al nivel 25, y con él se abre el Legado."] = "Первое очко «Наследия» обычно приходит на 25-м уровне, и с ним открывается «Наследие».",
	["El próximo: %s"] = "Следующая: %s",
	["El pícaro más fácil para subir: pega de frente, esquiva mucho y aguanta mejor que los demás."] = "Самый простой разбойник для прокачки: бьет в лоб, часто уклоняется и держится лучше остальных.",
	["El rango Experto viene en un libro de Deneb Walker (Tierras Altas de Arathi) o de Balai Lok'Wein (Marjal Revolcafango); el Artesano, con la misión «Triaje» en Theramore o en Sentencia."] = "Ступень «Умелец» — в книге у Денеба Ходока (Нагорье Арати) или Балаи Лок'Вейна (Пылевые топи); «Искусник» — за задание «Сортировка раненых» в Тераморе или Молоте.",
	["El rango Experto viene en un libro que vende el pescador de Bahía del Botín, en Tuercespina."] = "Ступень «Умелец» — в книге, которую продает рыбак в Пиратской Бухте, в Тернистой долине.",
	["El rango Experto viene en un libro que venden los proveedores de cocina; el Artesano, con una misión de Dirge Quikcleave en Gadgetzan."] = "Ступень «Умелец» — в книге у продавцов кулинарных товаров; «Искусник» — за задание Дирджа Быстроруба в Прибамбасске.",
	["El rango de niveles de cada zona, con color según tu nivel."] = "Диапазон уровней каждой зоны, с цветом по вашему уровню.",
	["El rastreador te avisa si tu plan se quedó sin paso y lo rearma con un clic."] = "Трекер сообщит, если в плане не осталось шагов, и соберёт его заново одним щелчком.",
	["El rastreador te dice el siguiente paso y la flecha te lleva."] = "Трекер подсказывает следующий шаг, а стрелка ведет вас.",
	["El recorrido por Alfa"] = "Знакомство с Alfa",
	["El registro de daño del juego está apagado"] = "Учет урона в игре выключен",
	["El registro de daño del juego está apagado: enciéndelo para ver el top de tu grupo."] = "Учет урона в игре выключен: включите его, чтобы видеть топ группы.",
	["El registro del Legado"] = "Шкала наград «Наследия»",
	["El reino humano de Alterac traicionó a la Alianza en la Segunda Guerra: su rey, Aiden Perenolde, se alió con la Horda. Por eso el reino desapareció."] = "Человеческое королевство Альтерак предало Альянс во Второй войне: его король Эйден Перенольд перешел на сторону Орды. Поэтому королевство и исчезло.",
	["El reino limita los mensajes de addon salientes: %s"] = "Игровой мир ограничивает исходящие сообщения аддонов: %s",
	["El reloj de Alfa mueve %d tareas. La que más tarda: %s (%.1f ms en %d veces)."] = "Часы Alfa ведут задач: %d. Самая медленная: %s (%.1f мс за %d запусков).",
	["El resumen se ve al salir de combate."] = "Итог появится после выхода из боя.",
	["El rey Llane Wrynn murió en la Primera Guerra a manos de Garona, la espía de la Horda."] = "Король Ллейн Ринн погиб в Первой войне от руки Гароны, шпионки Орды.",
	["El rey Magni Barbabronce gobierna Forjaz; sus hermanos son Muradin y Brann, el explorador."] = "Король Магни Бронзобород правит Стальгорном; его братья — Мурадин и исследователь Бранн.",
	["El rey Thoradin unió a las tribus humanas en Arathor, y los altos elfos les enseñaron magia para vencer juntos a los trols Amani."] = "Король Торадин объединил людские племена в Араторе, а высшие эльфы научили их магии, чтобы вместе победить троллей Амани.",
	["El rey Varian Wrynn es hijo de Llane, el rey que murió en la Primera Guerra."] = "Король Вариан Ринн — сын Ллейна, короля, погибшего в Первой войне.",
	["El rey Varian desapareció camino a una reunión de paz. Mientras tanto reina su hijo Anduin, todavía niño, con el alto señor Bolvar Fordragón como regente."] = "Король Вариан пропал по дороге на мирные переговоры. Пока правит его юный сын Андуин, а регентом при нем — верховный лорд Болвар Фордрагон.",
	["El saludo de la manada"] = "Приветствие стаи",
	["El sanador de los chamanes: curas en cadena y tótems que ayudan a todo el grupo."] = "Лекарь среди шаманов: цепное исцеление и тотемы, помогающие всей группе.",
	["El sanador de los druidas: curas a cualquier grupo y sobrevives bien, aunque en solitario matas lento."] = "Лекарь среди друидов: вы лечите любую группу и хорошо выживаете, хотя в одиночку убиваете медленно.",
	["El sanador de los paladines: curas fuertes y mucha armadura, ideal para grupos."] = "Лекарь среди паладинов: сильное исцеление и много брони, идеально для групп.",
	["El sanador puro: curas grandes y curas para todo el grupo."] = "Чистый лекарь: мощное исцеление и исцеление всей группы.",
	["El servicio"] = "Услуга",
	["El sistema de equipo de Alfa no está disponible."] = "Система экипировки Alfa недоступна.",
	["El sol aquí no perdona: las Tierras Inhóspitas son tierra de coyotes, buitres y basiliscos."] = "Солнце здесь беспощадно: Бесплодные земли — край койотов, стервятников и василисков.",
	["El sol de Durotar quema la tierra roja. Por algo los orcos son tan duros."] = "Солнце Дуротара обжигает красную землю. Неудивительно, что орки такие крепкие.",
	["El suelo y los muros se ven nítidos aunque estén lejos o de lado."] = "Земля и стены остаются четкими, даже вдали или под углом.",
	["El tablón de la manada"] = "Доска стаи",
	["El tablón está apagado (Ajustes de La Jauría)."] = "Доска выключена (настройки La Jauría).",
	["El talento que toca"] = "Следующий талант",
	["El tanque clásico: bloqueas mucho, generas amenaza con Revancha y Embate con escudo, y tienes Último recurso para cuando todo sale mal."] = "Классический танк: вы часто блокируете, создаете угрозу Реваншем и Мощным ударом щитом, а на случай, если все пошло не так, есть «Ни шагу назад».",
	["El tanque más difícil de matar: todos los talentos de defensa, Muro de escudo mejorado y Último recurso pronto. Perfecto para empezar a tanquear."] = "Самый живучий танк: все таланты защиты, Улучшенная глухая оборона и раннее «Ни шагу назад». Идеально, чтобы начать танковать.",
	["El terreno real en el mapa"] = "Настоящий рельеф на карте",
	["El texto es demasiado largo."] = "Текст слишком длинный.",
	["El texto llegó cortado o cambiado: cópialo otra vez."] = "Текст пришел обрезанным или измененным: скопируйте его снова.",
	["El tipo de nodos que une la ruta."] = "Тип узлов, которые соединяет маршрут.",
	["El tono de los fondos: Grafito es el de Alfa, Noche el más oscuro y Pizarra un gris neutro."] = "Тон фона: «Графит» — фирменный тон Alfa, «Ночь» — самый темный, «Сланец» — нейтральный серый.",
	["El top de DPS de tu grupo o banda en una ventana pequeña, con la pelea actual y la anterior."] = "Топ DPS группы или рейда в маленьком окне — текущий и предыдущий бой.",
	["El torio abunda en el Cráter de Un'Goro y en Cuna del Invierno."] = "Тория много в кратере Ун'Горо и в Зимних Ключах.",
	["El tranvía a %s ya viene"] = "Поезд до %s уже идёт",
	["El velo de pantalla de algunas zonas y hechizos de las sombras."] = "Пелена на экране в некоторых зонах и от заклинаний тьмы.",
	["El vendedor más cercano"] = "Ближайший торговец",
	["El verdadero nombre de Thrall es Go'el, el que le dieron sus padres."] = "Настоящее имя Тралла — Го'эл, его дали ему родители.",
	["El viejo ermitaño Abercrombie parece amable... hasta que descubres a quién intenta revivir."] = "Старый отшельник Аберкромби кажется добрым... пока не узнаешь, кого он пытается оживить.",
	["El zepelín a %s ya viene"] = "Дирижабль до %s уже идёт",
	["El «?» de cada página"] = "«?» на каждой странице",
	["El «zug zug» de los peones quiere decir algo así como «de acuerdo». ¡Zug zug, jefe!"] = "«Зуг-зуг» у батраков значит что-то вроде «ладно». Зуг-зуг, вождь!",
	["El ángel te revive ya y a tu nivel no quedas débil, pero tu equipo pierde %d %% de durabilidad."] = "Целитель душ вернет тебя сейчас, и на твоем уровне ты не ослабнешь, но снаряжение потеряет %d %% прочности.",
	["El ángel te revive ya, pero tu equipo pierde %d %% de durabilidad y quedas débil %s."] = "Целитель душ вернет тебя сейчас, но снаряжение потеряет %d %% прочности, а ты будешь ослаблен на %s.",
	["El árbol de ruta de Alfa, misiones que se liberan y un catálogo de objetos."] = "Дерево маршрутов Alfa, задания по мере открытия и каталог предметов.",
	["El ícono grande es lo que conviene presionar ahora y los pequeños, lo que sigue. Si late, el juego activó esa habilidad; el barrido oscuro es su recarga. Tú decides: Alfa nunca aprieta nada."] = "Большой значок — то, что лучше нажать сейчас, маленькие — что дальше. Если он пульсирует, игра подсветила эту способность; темное затемнение — ее восстановление. Решаете вы: Alfa никогда ничего не нажимает.",
	["El último punto: paras un poco más."] = "Последнее очко: вы парируете чуть чаще.",
	["Elegida por ti en los ajustes."] = "Выбрано вами в настройках.",
	["Elegida por tus talentos."] = "Выбрано по вашим талантам.",
	["Elegido"] = "Выбрано",
	["Elegido por ti"] = "Выбрано вами",
	["Elegir"] = "Выбрать",
	["Elegir capas"] = "Выбрать слои",
	["Elegir la siguiente guía"] = "Выбрать следующий гайд",
	["Elegir lo que pide tu paso"] = "Выбирать то, что просит шаг",
	["Elegir mi camino"] = "Выбрать мой путь",
	["Elegir mi primera guía"] = "Выбрать первый гайд",
	["Elegir mi tecla"] = "Выбрать клавишу",
	["Elegir otra guía"] = "Выбрать другой гайд",
	["Elegir para copiar"] = "Выделить для копирования",
	["Elegir qué sigue"] = "Выбрать, что дальше",
	["Elegir todo"] = "Выделить все",
	["Elegir una guía"] = "Выбрать гайд",
	["Elegir una guía por ti"] = "Выбирать гайд за вас",
	["Elegiste: %s"] = "Выбрано: %s",
	["Elemental"] = "Стихии",
	["Elemental para subir"] = "Стихии для прокачки",
	["Elfos de la noche"] = "Ночные эльфы",
	["Elige a dónde ir: Alfa arma el camino con vuelos, barcos, zepelines, portales y a pie."] = "Выбери, куда идти: Alfa проложит путь с полетами, кораблями, дирижаблями, порталами и пешком.",
	["Elige abajo qué cocinar y cuánto: la cola espera tu clic para cada lote."] = "Выберите ниже, что и сколько готовить: очередь ждет вашего щелчка для каждой партии.",
	["Elige algo de la lista"] = "Выберите что-нибудь из списка",
	["Elige el objeto"] = "Выберите предмет",
	["Elige el objeto en la Enciclopedia."] = "Выберите предмет в «Энциклопедии».",
	["Elige la opción que nombra tu guía, o abre la tienda o el entrenamiento que necesitas."] = "Выбирает вариант, который называет гайд, или открывает нужный магазин или обучение.",
	["Elige para qué, escribe qué buscas y pulsa «Publicar»: lo ven los lobos de tu hermandad con Alfa. Se quita solo en una hora."] = "Выбери цель, напиши, что ищешь, и нажми «Опубликовать»: увидят волки твоей гильдии с Alfa. Само исчезнет через час.",
	["Elige qué guardar: lo que ya tienes en el banco, los materiales, una categoría o todo lo que no sea equipo. Se mueve de una vez, fuera de combate."] = "Выберите, что положить: то, что уже есть в банке, материалы, категорию или все, кроме снаряжения. Переносится за один раз, вне боя.",
	["Elige qué quieres hacer y Alfa te lleva paso a paso."] = "Выберите, чем хотите заняться, и Alfa проведет вас шаг за шагом.",
	["Elige qué se ve en el mapa: guía, misiones, raros, viajes, zonas y lo que agregan otros módulos."] = "Выберите, что видно на карте: гайд, задания, редкие, путешествия, зоны и то, что добавляют другие модули.",
	["Elige sola la única opción de los PNJ sin misiones."] = "Сам выбирает единственный вариант у NPC без заданий.",
	["Elige solo misiones que ya puedes tomar."] = "Выбирает только задания, которые уже можно взять.",
	["Elige tu camino. Si no sabes, empieza por subir de nivel: Alfa te dice qué conviene."] = "Выберите путь. Если не знаете, начните с прокачки: Alfa подскажет, что выгодно.",
	["Elige tu estilo"] = "Выберите стиль",
	["Elige tu tecla para pescar"] = "Выберите клавишу для рыбалки",
	["Elige tus clics"] = "Выберите щелчки",
	["Elige tus clics, acomoda tus marcos y pruébalos. Te toma un minuto."] = "Выберите щелчки, расставьте рамки и проверьте их. Это займет минуту.",
	["Elige tus extras"] = "Выбери дополнения",
	["Elige tus minutos con la barra de abajo."] = "Выбери минуты ползунком ниже.",
	["Elige tú la zona."] = "Зону выбираете вы.",
	["Elige un camino: Alfa arma tu plan y te guía paso a paso."] = "Выберите путь: Alfa составит план и проведет вас шаг за шагом.",
	["Elige un día y una hora que aún no pasen (hasta una semana)."] = "Выбери день и время, которые еще не прошли (до недели вперед).",
	["Elige un marcador."] = "Выберите маркер.",
	["Elige un servicio."] = "Выберите услугу.",
	["Elige una captura"] = "Выберите улов",
	["Elige una guía para empezar"] = "Выберите гайд, чтобы начать",
	["Elige una mazmorra."] = "Выберите подземелье.",
	["Elige una misión"] = "Выберите задание",
	["Elige una profesión"] = "Выберите профессию",
	["Elige una profesión."] = "Выберите профессию.",
	["Elige una receta o un oficio y Alfa te dice qué materiales te faltan y de dónde sale cada uno. También desde la Enciclopedia."] = "Выбери рецепт или профессию, и Alfa скажет, каких материалов не хватает и откуда каждый берется. Также из «Энциклопедии».",
	["Elige una y listo: Alfa ajusta tus misiones, tu guía, los comerciantes y los viajes. Mantén presionado Mayús en el juego para decidir tú en el momento."] = "Выбери одно, и готово: Alfa настроит задания, гайд, торговцев и поездки. Удерживай Shift в игре, чтобы решать самому.",
	["Elige uno y lo ves al instante en esta ventana y en todas las de Alfa, también la flecha."] = "Выберите один и сразу увидите его в этом окне и во всех окнах Alfa, включая стрелку.",
	["Eliges una"] = "Выберите одно",
	["Ella duerme a todo el grupo y luego resucita a Mograine: es normal, no se asusten."] = "Она усыпляет всю группу, а затем воскрешает Могрейна: это нормально, не паникуйте.",
	["Elune, la diosa de la luna, es la fe de los elfos de la noche. Sus sacerdotisas son las Hermanas de Elune, y Tyrande es su suma sacerdotisa."] = "Элуна, богиня луны, — вера ночных эльфов. Ее жрицы — Сестры Элуны, а Тиранда — их верховная жрица.",
	["Elwynn de día es pura paz: el río, los campos y el olor a pan de Villadorada."] = "Элвиннский лес днем — сама безмятежность: река, поля и запах хлеба из Златоземья.",
	["Embate con escudo: mucho daño y amenaza."] = "Мощный удар щитом: много урона и угрозы.",
	["Embate deja de reiniciar tu ataque: un golpe extra entre golpe y golpe."] = "Мощный удар больше не сбрасывает вашу атаку: дополнительный удар между ударами.",
	["Embate sin perder tu ataque automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin perder tu ataque."] = "Мощный удар без потери атаки.",
	["Embate sin perder tu golpe automático."] = "Мощный удар без потери автоатаки.",
	["Embate sin reiniciar tu ataque: un golpe extra."] = "Мощный удар без сброса атаки: дополнительный удар.",
	["Embate: un golpe fuerte entre golpe y golpe."] = "Мощный удар: сильный удар между автоатаками.",
	["Empezamos a escribir (nivel %d)"] = "Мы начали писать (уровень %d)",
	["Empezar"] = "Начать",
	["Empezar de cero"] = "Начать заново",
	["Empezar de nuevo"] = "Начать заново",
	["Empezar otra"] = "Начать другой",
	["Empezar otra sesión"] = "Начать другой сеанс",
	["Empezó %s"] = "Начало: %s",
	["Empezó %s."] = "Начало: %s.",
	["Empieza al usar este objeto"] = "Начинается при использовании этого предмета",
	["Empieza aquí"] = "Начните здесь",
	["Empieza con %s, que se consigue en la mazmorra."] = "Начинается с предмета %s, который добывается в подземелье.",
	["Empieza con %s, que suelta %s."] = "Начинается с предмета %s — его роняет %s.",
	["Empieza con tu hechizo más lento desde lejos y termina con los instantáneos."] = "Начинайте издалека с самого медленного заклинания и заканчивайте мгновенными.",
	["Empieza de cero, por ejemplo después de mandar tu reporte."] = "Начать с чистого листа, например после отправки отчета.",
	["Empieza dentro"] = "Начинается внутри",
	["Empieza una misión"] = "Начинает задание",
	["Empiezas a juntar XP descansada"] = "Начинает копиться бонус отдыха",
	["Empiezas: nivel %d"] = "Начало: уровень %d",
	["En %s"] = "В: %s",
	["En 9 idiomas"] = "На 9 языках",
	["En Ajustes > Estilo y sonido prende «Letra más grande» y, si confundes el rojo con el verde, «Colores para daltonismo»."] = "В Настройки > Стиль и звук включи «Крупный текст», а если путаешь красный с зеленым — «Цвета для дальтоников».",
	["En Bolsas, «Buscar en todos tus personajes» revisa bolsas, bancos y equipo de todos, con filtros de tipo, calidad y personaje."] = "В «Сумках» кнопка «Искать у всех персонажей» проверяет сумки, банки и экипировку всех, с фильтрами по типу, качеству и персонажу.",
	["En Bolsas, «Qué guardar» te dice lo que sirve más en el banco: materiales de las recetas de tus otros personajes, lo que piden sus misiones y equipo que tu clase no usa. Con un banquero, «Al banco» y listo."] = "В «Сумках» раздел «Что убрать в банк» подскажет, что полезнее хранить в банке: материалы для рецептов других твоих персонажей, то, что просят их задания, и снаряжение, которое твой класс не носит. У банкира — «В банк», и готово.",
	["En Burning Crusade, Karazhan abre sus puertas como banda."] = "В Burning Crusade Каражан откроет двери как рейд.",
	["En Burning Crusade, el Vuelo Bronce pide ayuda en las Cavernas del Tiempo contra dragones que quieren cambiar la historia."] = "В Burning Crusade бронзовые драконы просят помощи в Пещерах Времени против драконов, которые хотят изменить историю.",
	["En Burning Crusade, las Cavernas del Tiempo te regresan a estas laderas para ver la huida de Thrall de Durnholde."] = "В Burning Crusade Пещеры Времени вернут тебя на эти склоны, чтобы увидеть побег Тралла из Дарнхольда.",
	["En Caer Darrow, junto al lago, todavía rondan los fantasmas de sus antiguos vecinos."] = "В Каэр Дарроу у озера до сих пор бродят призраки бывших жителей.",
	["En Ciudad Manitas, dentro de Forjaz, viven los gnomos que escaparon de Gnomeregan."] = "В Городе Механиков в Стальгорне живут гномы, сбежавшие из Гномрегана.",
	["En Combate tienes el medidor de daño del grupo y la ayuda de rotación para tu clase."] = "В «Бою» есть измеритель урона группы и помощь с ротацией для твоего класса.",
	["En Comercio ves precios de la subasta y qué te conviene vender. Yo vendo lo gris por ti con el comerciante."] = "В «Торговле» цены аукциона и что выгодно продать. Серое я продаю за тебя у торговца.",
	["En Comercio, en «Oficios», cada uno tiene su guía de 1 a 300: qué hacer en cada tramo, lo que te falta y dónde aprender el siguiente rango."] = "В «Торговле», в «Профессиях», у каждой есть гид с 1 до 300: что делать на каждом отрезке, чего не хватает и где учить следующую ступень.",
	["En Comercio, en «Tu lista de compras», agrega una receta o un oficio: te digo cuánto tienes, cuánto te falta y de dónde sale. Se va llenando sola mientras juntas."] = "В «Торговле», в «Твоем списке покупок», добавь рецепт или профессию: я скажу, сколько у тебя есть, сколько не хватает и откуда это берется. Список заполняется сам, пока ты собираешь.",
	["En Comercio, «Tus recetas que dejan ganancia» te dice cuánto deja cada receta con los precios de tu reino, y primero las que ya puedes hacer con lo que llevas."] = "В «Торговле» раздел «Твои выгодные рецепты» показывает, сколько приносит каждый рецепт по ценам твоего игрового мира, и сначала те, что ты уже можешь сделать.",
	["En Costa Oscura la Liga de Expedicionarios desentierra fósiles gigantes."] = "На Темных берегах Лига исследователей раскапывает гигантские окаменелости.",
	["En Costa Oscura viven lechúcicos, criaturas mitad búho y mitad oso que veneran la luna."] = "На Темных берегах живут лунные совухи — наполовину совы, наполовину медведи, почитающие луну.",
	["En Cuna del Invierno la nieve no se acaba. Los osos y los yetis andan de buen humor."] = "В Зимних Ключах снег никогда не кончается. Медведи и йети в хорошем настроении.",
	["En Curación, «Curar y seleccionar» viene prendido: cada clic que cura en tus marcos también deja a ese compañero como tu objetivo, para seguir con un buff o quitarle una maldición. En «Tus clics» eliges qué hace cada clic."] = "В «Исцелении» «Лечить и брать в цель» включено: каждый лечащий щелчок по рамкам делает союзника твоей целью, чтобы продолжить положительным эффектом или снять проклятие. В «Ваши щелчки» ты выбираешь, что делает каждый щелчок.",
	["En Desolace está el cementerio de los kodos, donde los viejos kodos van a morir."] = "В Пустошах есть Кладбище кодо, куда старые кодо уходят умирать.",
	["En Dun Morogh la nieve brilla con el sol. Abrígate, que aquí hasta los osos tienen frío."] = "В Дун Мороге снег искрится на солнце. Укутайся: здесь мерзнут даже медведи.",
	["En Durotar ya te topas con el Filo Ardiente, un culto de brujos orcos que sigue adorando a los demonios."] = "Уже в Дуротаре ты встречаешь Пылающий Клинок — культ орков-чернокнижников, которые все еще поклоняются демонам.",
	["En Elwynn, una señora vende gatitos de compañía. ¡Yo me llevo bien con los gatos... casi siempre!"] = "В Элвиннском лесу одна дама продает котят-питомцев. Я с кошками лажу... почти всегда!",
	["En Entrañas venden cucarachas de mascota. Cada quien sus gustos."] = "В Подгороде продают тараканов-питомцев. На вкус и цвет...",
	["En Feralas está uno de los grandes árboles por los que los dragones verdes entran al Sueño Esmeralda."] = "В Фераласе растет одно из великих деревьев, через которые зеленые драконы входят в Изумрудный Сон.",
	["En Forever, Onyxia, la Cumbre Hyjal y Barrow Deeps dan retos del Legado al vencerlas."] = "В Forever Ониксия, Вершина Хиджала и Barrow Deeps дают испытания «Наследия» за победу.",
	["En Forever, el banco vende casillas de bolsa una tras otra: más espacio para tus tesoros."] = "В Forever банк продает ячейки для сумок одну за другой: больше места для твоих сокровищ.",
	["En Forever, los rangos de honor y la reputación de los campos de batalla también dan retos del Legado."] = "В Forever звания чести и репутация полей боя тоже дают испытания «Наследия».",
	["En Forever, los retos del Legado dan puntos a toda tu cuenta, y cada personaje los gasta en sus árboles. Ábrelo con la tecla Y."] = "В Forever испытания «Наследия» дают очки всей учетной записи, а каждый персонаж тратит их в своих деревьях. Открой клавишей Y.",
	["En Forjaz, la sala de la Liga de Expedicionarios tiene un museo con fósiles enormes. Brann Barbabronce es su explorador más famoso."] = "В Стальгорне в зале Лиги исследователей есть музей с огромными окаменелостями. Бранн Бронзобород — ее самый знаменитый исследователь.",
	["En Gadgetzan, el cocinero Dirge enseña una de las mejores recetas del Clásico, con carne de quimerok."] = "В Прибамбасске повар Дирдж учит одному из лучших рецептов классики — из мяса химерока.",
	["En Hoy, en «¿Cuánto tiempo tienes?», elige 30 minutos, 1 hora, 2 o los que quieras. Armo tu plan con tu ritmo y, con «Empezar», la flecha te lleva paso por paso."] = "В «Сегодня», в «Сколько у тебя времени?», выбери 30 минут, 1 час, 2 или сколько хочешь. Я составлю план в твоем темпе, а с «Начать» стрелка поведет тебя шаг за шагом.",
	["En Jaedenar se esconde el Consejo de la Sombra, brujos que sirven a la Legión Ardiente."] = "В Джеденаре скрывается Совет Теней — чернокнижники, служащие Пылающему Легиону.",
	["En Jardín Noble se esconden huevos de colores por los pueblos iniciales; dentro hay dulces y a veces ropa de primavera."] = "В Сад чудес в стартовых городках прячут разноцветные яйца; внутри сладости, а иногда весенняя одежда.",
	["En Kharanos, la posada y la destilería Cebatruenos son la parada obligada para calentarse... por dentro y por fuera."] = "В Караносе таверна и пивоварня Громоваров — обязательная остановка, чтобы согреться... и снаружи, и изнутри.",
	["En La Jauría > Guaridas te digo en cuál estás y en cuáles anda la manada. Con «Pedir entrar» te pasas a la de un lobo con la puerta abierta."] = "В La Jauría > Логова скажу, в каком ты и где стая. Кнопкой «Попроситься» перейдёшь к волку с открытой дверью.",
	["En La Jauría > Guaridas toca «Llamar a la manada» (o escribe /alfa manada llamar): los lobos de tu zona reciben tu lugar y te aviso quién viene."] = "В La Jauría > Логова нажми «Позвать стаю» (или /alfa manada llamar): волки твоей зоны получат твоё место, а я скажу, кто идёт.",
	["En La Jauría está «El tablón de la manada»: pon qué buscas y a tu hermandad le llega. Se quita solo en una hora."] = "В La Jauría есть «Доска стаи»: напиши, что ищешь, и гильдия это получит. Само исчезнет через час.",
	["En La Jauría está «La semana de la manada»: misiones, raros, mazmorras y niveles de los lobos que la comparten. Nadie compite: todo suma."] = "В La Jauría есть «Неделя стаи»: задания, редкие, подземелья и уровни волков, которые ею делятся. Никто не соревнуется: все складывается.",
	["En La Jauría ves a tu grupo y a los lobos que se dejan ver en el mapa. Puedes seguirlos con la flecha o invitarlos."] = "В La Jauría видно твою группу и волков, которые показываются на карте. Можно идти за ними по стрелке или пригласить.",
	["En La Jauría ves cómo va. Si se atora, te aviso."] = "В La Jauría видно, как у него дела. Если застрянет, я скажу.",
	["En La Jauría, en «Citas de la manada», escribe qué, elige día y hora y pulsa «Proponer». A tu hermandad le llega con «Voy» y yo te recuerdo 15 minutos antes."] = "В La Jauría, в «Сборах стаи», напиши что, выбери день и время и нажми «Предложить». Твоя гильдия получит это с кнопкой «Иду», а я напомню за 15 минут.",
	["En La Jauría, en «¿Quién tiene...?», escribe el objeto y pulsa «Buscar». Te contestan los lobos de tu hermandad que lo permiten, con «Susurrar» para pedírselo."] = "В La Jauría, в «У кого есть...?», введи предмет и нажми «Искать». Ответят волки твоей гильдии, которые это разрешили, с кнопкой «Шепнуть», чтобы попросить.",
	["En La Jauría, «El calendario de la manada» acomoda las citas de los próximos siete días."] = "В La Jauría «Календарь стаи» раскладывает сборы на ближайшие семь дней.",
	["En La Jauría, «Las guaridas de la manada» dice cuántos lobos hay en cada guarida de cada zona. En el mapa también sale."] = "В La Jauría «Логова стаи» показывает, сколько волков в каждом логове каждой зоны. На карте тоже видно.",
	["En Los Baldíos el sol pega duro. Las cebras corren por todos lados y yo quiero perseguirlas."] = "В Степях солнце печет вовсю. Повсюду бегают зебры, и мне хочется за ними погнаться.",
	["En Los Humedales siempre está húmedo. Mis patas terminan llenas de lodo."] = "В Болотине всегда сыро. Лапы у меня потом все в грязи.",
	["En Mazmorras ves cuáles van con tu nivel, sus jefes, su botín, sus misiones y cómo llegar a la entrada."] = "В «Подземельях» видно, какие по твоему уровню, их боссы, добыча, задания и путь ко входу.",
	["En Molino Ámbar se refugian magos de Dalaran, y no les gustan nada las visitas de los Renegados."] = "В Янтарной мельнице укрываются маги Даларана, и визиты Отрекшихся им совсем не по душе.",
	["En Mundo pones tus marcadores, los compartes con tu grupo y la flecha te lleva a ellos."] = "В «Мире» ставишь метки, делишься ими с группой, и стрелка ведёт к ним.",
	["En Naxxramas, el gran Alexandros Mograine reaparece como uno de los Cuatro Jinetes de la Plaga. Qué triste destino para un héroe."] = "В Наксрамасе великий Александрос Могрейн возвращается одним из Четырех всадников Плети. Какая грустная судьба для героя.",
	["En Nethergarde, unos magos de sangre te cambian partes de las bestias de aquí por elixires que te potencian un buen rato."] = "В Крепости Стражей Пустоты маги крови меняют части местных зверей на эликсиры, которые надолго усиливают тебя.",
	["En Orgrimmar, el Valle de la Sabiduría guarda la fortaleza de Thrall, y el Valle del Honor reúne a guerreros y cazadores."] = "В Оргриммаре в Аллее Мудрости стоит крепость Тралла, а в Аллее Чести собираются воины и охотники.",
	["En Paisaje y gráficos hay un paisaje más bonito con un clic, y cada ajuste gráfico explicado."] = "В «Пейзаже и графике» красивый пейзаж в один клик и объяснение каждой настройки.",
	["En Pesca tienes una sola tecla para equiparte, lanzar y recoger, un diario de lo que sacas y una guía de 1 a 300."] = "В «Рыбалке» одна клавиша, чтобы экипироваться, забросить и вытащить, журнал улова и гайд с 1 до 300.",
	["En Pico Nidal manda el thane Falstad Martillo Salvaje, señor de los jinetes de grifo."] = "В Заоблачном пике правит тан Фалстад Громовой Молот, повелитель всадников на грифонах.",
	["En Pico Nidal viven los enanos Martillo Salvaje, famosos por volar sobre grifos."] = "В Заоблачном пике живут дворфы Громового Молота, знаменитые полетами на грифонах.",
	["En Recolección eliges qué buscar y te marco en el mapa los puntos de tus profesiones, con los que ya encontraste."] = "В «Сборе» выбираешь, что искать, а я отмечаю на карте точки твоих профессий и найденные тобой.",
	["En Ruta eliges a dónde ir y yo te armo el camino. La flecha te lleva paso a paso y el rastrador te dice qué toca."] = "В «Маршруте» выбираешь, куда идти, а я строю путь. Стрелка ведёт шаг за шагом, а трекер подсказывает, что дальше.",
	["En Seradane hay uno de los grandes árboles que llevan al Sueño Esmeralda, y los dragones verdes lo custodian."] = "В Серадане растет одно из великих деревьев, ведущих в Изумрудный Сон, и его стерегут зеленые драконы.",
	["En Talentos te digo qué punto poner y por qué, según tu clase y cómo juegas."] = "В «Талантах» скажу, какое очко вложить и почему, под твой класс и стиль игры.",
	["En Tanaris el sol del desierto no perdona. Gadgetzan es el único lugar con sombra."] = "В Танарисе солнце пустыни беспощадно. Тень есть только в Прибамбасске.",
	["En Tanaris están las Cavernas del Tiempo, donde el Vuelo Bronce de Nozdormu vigila la historia."] = "В Танарисе находятся Пещеры Времени, где бронзовые драконы Ноздорму охраняют историю.",
	["En Tirisfal casi nunca sale el sol. A los Renegados ni les importa."] = "В Тирисфале солнце почти не выходит. Отрекшимся все равно.",
	["En Tirisfal está la entrada al Monasterio Escarlata, uno de los lugares más visitados por los aventureros de nivel medio."] = "В Тирисфальских лесах вход в Монастырь Алого ордена — одно из самых посещаемых мест у искателей приключений среднего уровня.",
	["En Tuercespina hace un calor de lobo. Toma agua y cuidado con los tigres entre la hierba."] = "В Тернистой долине жарко, как в волчьей шкуре. Пей воду и следи за тиграми в траве.",
	["En Uldaman están los Discos de Norgannon, registros de los titanes que cuentan cómo crearon a los terráneos, los antepasados de piedra de los enanos."] = "В Ульдамане хранятся Диски Норганнона — записи титанов о том, как они создали земельников, каменных предков дворфов.",
	["En Vallefresno, Grom Grito Infernal mató al semidiós Cenarius cuando la Horda empezó a talar el bosque."] = "В Ясеневом лесу Гром Адский Крик убил полубога Кенария, когда Орда начала вырубать лес.",
	["En Vallefresno, Grom volvió a beber sangre demoníaca; Thrall lo rescató y Grom pudo redimirse antes de morir."] = "В Ясеневом лесу Гром снова выпил кровь демона; Тралл спас его, и Гром смог искупить вину перед смертью.",
	["En Ventormenta hay un barrio de enanos, uno de magos y un parque donde se reúnen los elfos de la noche."] = "В Штормграде есть квартал дворфов, квартал магов и парк, где собираются ночные эльфы.",
	["En Warcraft III, si le das muchos clics a una unidad empieza a decir cosas chistosas. Yo, en cambio, te doy consejos."] = "В Warcraft III, если много раз щелкнуть по юниту, он начинает говорить смешные вещи. А я вместо этого даю советы.",
	["En arco"] = "Дугой",
	["En bancos de peces de: %s."] = "В косяках рыбы: %s.",
	["En banda, un grupo por columna"] = "В рейде — группа на столбец",
	["En camino"] = "В пути",
	["En cero los números suben derechos; más alto, salen disparados hacia los lados."] = "При нуле числа поднимаются прямо; чем выше, тем сильнее разлетаются в стороны.",
	["En combate"] = "В бою",
	["En combate el juego oculta los números exactos: las barras y las cifras se ven igual, el detalle y el anuncio, al salir."] = "В бою игра скрывает точные числа: полосы и цифры все равно видны, а подробности и объявление — после выхода из боя.",
	["En combate el mapa del juego no se abre desde Alfa: usa el de Alfa."] = "В бою карта игры не открывается из Alfa: используйте карту Alfa.",
	["En combate no aparece el cuadro de los personajes y criaturas del mundo (el de los marcos sí)."] = "В бою не показывается подсказка персонажей и существ в мире (подсказка рамок — показывается).",
	["En combate no hay prueba: sal de la pelea y vuelve a este paso."] = "В бою проверка недоступна: выйдите из боя и вернитесь к этому шагу.",
	["En combate no puedo buscar: inténtalo al terminar la pelea."] = "В бою я не могу искать: попробуйте после боя.",
	["En combate no se puede cambiar el equipo: te lo pongo al terminar."] = "В бою нельзя менять снаряжение: надену, когда бой закончится.",
	["En combate no se puede cambiar el equipo: te pongo «%s» al terminar."] = "В бою экипировку менять нельзя: я надену «%s», когда бой закончится.",
	["En combate no se puede: espera a terminar."] = "В бою нельзя: дождитесь конца боя.",
	["En combate · la pesca espera"] = "В бою · рыбалка подождет",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard y las %d que siguen. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard, и %d следующих. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate, el ícono muestra la habilidad que sugiere la ayuda de Blizzard. Tú decides qué presionar: Alfa nunca aprieta nada por ti."] = "В бою значок показывает способность, которую предлагает помощник Blizzard. Что нажимать, решаете вы: Alfa никогда ничего не нажимает за вас.",
	["En combate: espera a terminar"] = "В бою: дождитесь окончания",
	["En curso"] = "В процессе",
	["En el Casco Antiguo está el SI:7, los espías y pícaros al servicio del reino."] = "В Старом городе находится ШРУ:7 — шпионы и разбойники на службе королевства.",
	["En el Clásico mandan Thrall en Orgrimmar, Cairne en Cima del Trueno, Sylvanas en Entrañas y Vol'jin con los Lanza Negra."] = "В классике Тралл правит в Оргриммаре, Кэрн — в Громовом Утесе, Сильвана — в Подгороде, а Вол'джин ведет племя Черного Копья.",
	["En el Clásico nadie sabe dónde anda Alamuerte; los que dan la cara son sus hijos, Onyxia y Nefarian."] = "В классике никто не знает, где Смертокрыл; показываются только его дети — Ониксия и Нефариан.",
	["En el Clásico necesitas flechas o balas: lleva siempre de más en tu carcaj o tu bolsa de munición."] = "В классике нужны стрелы или пули: всегда носи запас в колчане или подсумке.",
	["En el Clásico necesitas un cuchillo de desollar en tus bolsas."] = "В классике нужен нож для снятия шкур в сумках.",
	["En el Clásico solo puedes tener dos profesiones principales, pero Cocina, Pesca y Primeros auxilios se aprenden aparte."] = "В классике можно иметь только две основные профессии, но кулинария, рыбная ловля и первая помощь изучаются отдельно.",
	["En el Clásico, Costasur contra Molino Tarren era la pelea entre bandos más famosa del mundo."] = "В классике Южнобережье против Мельницы Таррен было самым знаменитым противостоянием фракций в мире.",
	["En el Clásico, a nivel 20 aprendes a teletransportarte a las capitales, y a 40 a abrir portales para los demás."] = "В классике на 20-м уровне ты учишься телепортироваться в столицы, а на 40-м — открывать порталы для других.",
	["En el Clásico, a nivel 20 haces la misión de los venenos; después los mejoras con tu entrenador."] = "В классике на 20-м уровне ты выполняешь задание на яды, а потом улучшаешь их у учителя.",
	["En el Clásico, a nivel 40 haces la misión de tu caballo de guerra, y a 60 la cadena épica del destrero."] = "В классике на 40-м уровне ты выполняешь задание на боевого коня, а на 60-м — эпическую цепочку на скакуна.",
	["En el Clásico, a nivel 40 recibes un corcel vil, y a 60 una cadena épica en La Masacre te da uno aún más temible."] = "В классике на 40-м уровне ты получаешь коня Скверны, а на 60-м эпическая цепочка в Забытом городе дает еще более грозного.",
	["En el Clásico, abrir las puertas de Ahn'Qiraj pidió un esfuerzo de guerra de todo el servidor: montañas de materiales y una cadena larguísima."] = "В классике открытие ворот Ан'Киража потребовало военных усилий всего сервера: горы материалов и очень длинная цепочка заданий.",
	["En el Clásico, algunos peces solo pican de noche o de día."] = "В классике некоторые рыбы клюют только ночью или только днем.",
	["En el Clásico, cada raza de sacerdote tiene un hechizo propio. Pregúntale a tu entrenador cuál te toca."] = "В классике у жрецов каждой расы есть свое заклинание. Спроси у учителя, какое твое.",
	["En el Clásico, después de vendarte queda un rato en que no puedes usar otra venda."] = "В классике после перевязки какое-то время нельзя использовать другой бинт.",
	["En el Clásico, el Cetro de las Arenas Movedizas abrió las puertas de Ahn'Qiraj tras una larguísima cadena de misiones."] = "В классике Скипетр Зыбучих Песков открыл ворота Ан'Киража после очень длинной цепочки заданий.",
	["En el Clásico, el arco épico de los cazadores sale de una cadena contra demonios que empieza en el Claro de la Luna."] = "В классике эпический лук охотников дает цепочка против демонов, которая начинается на Лунной поляне.",
	["En el Clásico, el chat de Los Baldíos era famoso por sus pláticas eternas... y por preguntar dónde estaba la esposa de Mankrik."] = "В классике чат Степей славился бесконечными разговорами... и вопросами, где жена Манкрика.",
	["En el Clásico, el nivel máximo es 60 y llegar lleva su tiempo. Por eso cada nivel se festeja."] = "В классике максимальный уровень — 60, и путь к нему долгий. Поэтому каждый уровень стоит отпраздновать.",
	["En el Clásico, el rango de honor 14 es Gran Mariscal para la Alianza y Gran Señor de la Guerra para la Horda."] = "В классике 14-е звание чести — Великий маршал у Альянса и Верховный военачальник у Орды.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala en Mulgore, cerca del poblado Pezuña de Sangre."] = "В классике Ярмарка Новолуния иногда приезжает в Мулгор, к деревне Кровавого Копыта.",
	["En el Clásico, la Feria de la Luna Negra a veces se instala junto a Villadorada."] = "В классике Ярмарка Новолуния иногда приезжает к Златоземью.",
	["En el Clásico, la Horda la forman orcos, trols Lanza Negra, tauren y Renegados; la Alianza, humanos, enanos, gnomos y elfos de la noche."] = "В классике Орду составляют орки, тролли Черного Копья, таурены и Отрекшиеся; Альянс — люди, дворфы, гномы и ночные эльфы.",
	["En el Clásico, la Plaga invadió el mundo con necrópolis flotantes antes de que se abriera Naxxramas."] = "В классике Плеть вторглась в мир на летающих некрополях еще до открытия Наксрамаса.",
	["En el Clásico, la actitud defensiva se gana con una misión al nivel 10, y la rabiosa con otra al nivel 30."] = "В классике Оборонительную стойку дает задание на 10-м уровне, а Стойку берсерка — другое, на 30-м.",
	["En el Clásico, la casa de subastas de Forjaz es la más movida de toda la Alianza."] = "В классике аукцион Стальгорна — самый оживленный во всем Альянсе.",
	["En el Clásico, la forma de oso se gana con una misión a nivel 10 y la acuática con otra a nivel 16; luego vienen la felina y la de viaje."] = "В классике облик медведя дает задание на 10-м уровне, а водный облик — другое, на 16-м; потом идут облик кошки и походный облик.",
	["En el Clásico, la montura de nivel 40 es mucho más rápida que correr, y la épica de nivel 60 todavía más."] = "В классике транспорт 40-го уровня намного быстрее бега, а эпический на 60-м — еще быстрее.",
	["En el Clásico, la tela se puede donar en tu capital a cambio de reputación."] = "В классике ткань можно сдавать в своей столице в обмен на репутацию.",
	["En el Clásico, las bandas grandes son de 40 jugadores, y Zul'Gurub y las Ruinas de Ahn'Qiraj, de 20."] = "В классике большие рейды рассчитаны на 40 игроков, а Зул'Гуруб и Руины Ан'Киража — на 20.",
	["En el Clásico, los Renegados se quitan el miedo, el encanto y el sueño con su voluntad."] = "В классике Отрекшиеся силой воли стряхивают страх, очарование и сон.",
	["En el Clásico, los domingos por la tarde Bahía del Botín organizaba un concurso de pesca: ganaba quien entregara primero cuarenta peces de una especie especial."] = "В классике по воскресеньям после обеда Пиратская Бухта устраивала рыболовное состязание: побеждал тот, кто первым сдаст сорок рыб особого вида.",
	["En el Clásico, los enanos pueden buscar tesoros con un rastreo propio. ¡Ideal para encontrar cofres!"] = "В классике дворфы умеют искать сокровища особым поиском. Идеально для сундуков!",
	["En el Clásico, los enanos se convierten en piedra para quitarse venenos y sangrados, y son buenos con las armas de fuego."] = "В классике дворфы обращаются в камень, чтобы избавиться от ядов и кровотечений, и хорошо обращаются с огнестрельным оружием.",
	["En el Clásico, los gnomos pueden ser guerreros, pícaros, magos o brujos."] = "В классике гномы могут быть воинами, разбойниками, магами или чернокнижниками.",
	["En el Clásico, los gnomos son más listos que el resto, tienen talento para la ingeniería y se zafan de lo que los inmoviliza."] = "В классике гномы умнее остальных, у них талант к инженерному делу, и они выскальзывают из всего, что их обездвиживает.",
	["En el Clásico, los humanos ganan reputación más rápido gracias a su diplomacia, y tienen buen ojo para ver a los sigilosos."] = "В классике люди быстрее набирают репутацию благодаря дипломатии и хорошо замечают незаметных.",
	["En el Clásico, los maestros de armas de las capitales te enseñan a usar armas nuevas."] = "В классике мастера оружия в столицах учат пользоваться новым оружием.",
	["En el Clásico, los orcos resisten mejor los aturdimientos y sus mascotas pegan más fuerte."] = "В классике орки лучше сопротивляются оглушению, а их питомцы бьют сильнее.",
	["En el Clásico, los tauren tienen más vida, un pisotón que aturde a los enemigos cercanos y mano verde con las hierbas."] = "В классике у тауренов больше здоровья, есть топот, оглушающий ближайших противников, и легкая рука с травами.",
	["En el Clásico, los trols se regeneran rápido, entran en frenesí, pegan más fuerte a las bestias y son buenos con arcos y armas arrojadizas."] = "В классике тролли быстро восстанавливаются, впадают в берсерк, сильнее бьют зверей и хорошо обращаются с луками и метательным оружием.",
	["En el Clásico, muchas comidas te dejan bien alimentado y te suben estadísticas un buen rato."] = "В классике многие блюда дают сытость и надолго повышают характеристики.",
	["En el Clásico, para pasar de 225 hay una misión de triaje en Theramore o en Sentencia."] = "В классике, чтобы пройти дальше 225, есть задание по сортировке раненых в Тераморе или в Молоте.",
	["En el Clásico, quienes terminaron la cadena del cetro y tocaron el gong de Ahn'Qiraj ganaron un título y una montura únicos."] = "В классике те, кто прошел цепочку скипетра и ударил в гонг Ан'Киража, получили уникальное звание и транспорт.",
	["En el Clásico, solo elfos de la noche y tauren pueden ser druidas."] = "В классике друидами могут быть только ночные эльфы и таурены.",
	["En el Clásico, solo humanos y enanos pueden ser paladines."] = "В классике паладинами могут быть только люди и дворфы.",
	["En el Clásico, solo orcos, trols y tauren pueden ser chamanes."] = "В классике шаманами могут быть только орки, тролли и таурены.",
	["En el Clásico, tu Reencarnación te revive a ti mismo, pero necesita un ankh en tus bolsas."] = "В классике «Перерождение» позволяет тебе воскреснуть самостоятельно, но нужен анкх в сумках.",
	["En el Enclave Cenarion los druidas enseñan a los suyos el camino de la naturaleza."] = "В Анклаве Кенария друиды учат своих пути природы.",
	["En el Festival Lunar, la gente viene al Claro de la Luna a honrar a sus ancestros."] = "Во время Лунного фестиваля люди приходят на Лунную поляну почтить предков.",
	["En el Festival Lunar, un emisario en las capitales te puede llevar al Claro de la Luna para celebrar con los druidas."] = "Во время Лунного фестиваля посланник в столицах может перенести тебя на Лунную поляну, чтобы праздновать с друидами.",
	["En el Festival de Fuego del Solsticio de Verano hay hogueras en muchos pueblos: honrar las de tu bando da premios, y apagar las del otro también."] = "Во время Огненного солнцеворота во многих городках горят костры: почтить костры своей фракции — награда, потушить чужие — тоже.",
	["En el Festival de Invierno venden bolas de nieve. ¡Lánzaselas a tus amigos, que yo las atrapo!"] = "На Зимний Покров продают снежки. Кидай их в друзей, а я буду ловить!",
	["En el Festival de Invierno, el Gran Padre Invierno reparte regalos en Forjaz y Orgrimmar, y bajo el árbol aparecen paquetes el día 25."] = "На Зимний Покров Дедушка Зима раздает подарки в Стальгорне и Оргриммаре, а 25-го под елкой появляются свертки.",
	["En el Festival de la Cosecha, la Horda honra a Grom Grito Infernal y la Alianza a Uther, en sus monumentos."] = "На Праздник урожая Орда чтит Грома Адского Крика, а Альянс — Утера, у их памятников.",
	["En el Núcleo de Magma se desuellan perros del núcleo para un cuero muy especial."] = "В Огненных Недрах с гончих Недр снимают совершенно особую кожу.",
	["En el Santuario Esmeralda, los druidas intentan sanar el bosque enfermo."] = "В Изумрудном святилище друиды пытаются исцелить больной лес.",
	["En el Solsticio cada pueblo prende su hoguera. Me encanta el olor a leña... y a salchicha asada."] = "В Огненный солнцеворот каждый город зажигает свой костер. Обожаю запах дров... и жареной сосиски.",
	["En el Valle de Alterac pelean la Guardia Pico Tormenta de los enanos y el clan Lobo Gélido. Yo ya sé a quién le voy."] = "В Альтеракской долине сражаются Стража Грозовой Вершины дворфов и клан Северного Волка. Я уже знаю, за кого болею.",
	["En el Valle de la Fuerza están el banco y la casa de subastas: el corazón del comercio de la Horda."] = "В Аллее Силы банк и аукцион — сердце торговли Орды.",
	["En el camino"] = "По пути",
	["En el centro de aquel Kalimdor estaba el Pozo de la Eternidad, un lago de pura magia. Unos trols que vivían a su orilla cambiaron con los siglos y se volvieron los elfos de la noche."] = "В центре того Калимдора лежал Источник Вечности, озеро чистой магии. Тролли, жившие на его берегах, за века изменились и стали ночными эльфами.",
	["En el centro de la garganta hay un enorme pozo de lava, la Caldera, donde trabajan esclavos de los Hierro Negro."] = "В центре ущелья огромная лавовая яма — Котел, где трудятся рабы Черного Железа.",
	["En el centro del cráter humea un volcán donde viven elementales de fuego."] = "В центре кратера дымится вулкан, где живут огненные элементали.",
	["En el chat"] = "В чате",
	["En el corazón del Templo de la Luna hay un pozo lunar, donde las sacerdotisas rezan a Elune."] = "В сердце Храма Луны есть лунный колодец, у которого жрицы молятся Элуне.",
	["En el cráter, un tal Linken perdió la memoria y busca su espada y su escudo: un guiño a cierto héroe de orejas puntiagudas."] = "В кратере некий Линкен потерял память и ищет свои меч и щит — отсылка к одному остроухому герою.",
	["En el cuadro de cada pieza de equipo: lo que ganas y lo que pierdes contra lo que llevas puesto, con números."] = "В подсказке каждого предмета экипировки: что ты получишь и потеряешь по сравнению с надетым, в цифрах.",
	["En el este de las Tierras Inhóspitas viven dragones negros y sus siervos. Pasa lejitos si no llevas compañía."] = "На востоке Бесплодных земель живут черные драконы и их слуги. Обходи стороной, если идешь без компании.",
	["En el este del lago viven ogros que les hacen la vida difícil a los enanos de Thelsamar."] = "На востоке озера живут огры, которые портят жизнь дворфам Телсамара.",
	["En el gran salar del este, goblins y gnomos organizan carreras; la rivalidad es feroz."] = "На большой соляной равнине на востоке гоблины и гномы устраивают гонки; соперничество там жестокое.",
	["En el juego"] = "В игре",
	["En el lago de Villa del Lago hay múrlocs, ¡como en casi todo lago de Azeroth!"] = "В озере Приозерья есть мурлоки — как почти в каждом озере Азерота!",
	["En el mapa"] = "На карте",
	["En el mapa de Alfa, clic: seguirla con la flecha o guardarla como marcador."] = "На карте Alfa щелчок: следовать по стрелке или сохранить как маркер.",
	["En el mapa de Alfa, la capa «Peligros» marca los élites y los raros de tu zona que te pueden ganar: en rojo los que te pasan por mucho. Se arma al abrir el mapa."] = "На карте Alfa слой «Опасности» отмечает элитных и редких в твоей зоне, которые могут тебя победить: красным — те, что сильно выше тебя. Собирается при открытии карты.",
	["En el mapa de Alfa, la capa «Por descubrir» marca los rincones de tu zona que no has pisado, y «Vuelos que te faltan» los maestros de vuelo que aún no conoces. Clic en un vuelo y la flecha te lleva."] = "На карте Alfa слой «Не открыто» отмечает уголки зоны, где ты еще не был, а «Недостающие точки полета» — распорядителей полетов, которых ты еще не знаешь. Щелкни по точке полета, и стрелка отведет тебя.",
	["En el mapa del mundo"] = "На карте мира",
	["En el mapa del mundo, cada zona con lobos dice cuántos hay en cada guarida."] = "На карте мира каждая зона с волками показывает, сколько их в каждом логове.",
	["En el marco del objetivo"] = "На рамке цели",
	["En el menú de una misión: toda su cadena, lo que ya hiciste y el premio del final."] = "В меню задания: вся его цепочка, что ты уже сделал, и итоговая награда.",
	["En el minimapa"] = "На мини-карте",
	["En el muelle: sale en %s hacia %s"] = "У причала: отходит через %s в %s",
	["En el mundo"] = "В мире",
	["En el nivel 10 domas tu bestia."] = "На 10-м уровне вы приручите зверя.",
	["En el nivel 20 aprendes venenos."] = "Яды изучаются на 20-м уровне.",
	["En el norte de estas tierras, la Cruzada Escarlata domina un pueblo amurallado y lo defiende con fanatismo."] = "На севере этих земель Алый орден занимает обнесенный стеной город и фанатично его защищает.",
	["En el oeste de Las Mil Agujas anidan dracoleones salvajes."] = "На западе Тысячи Игл гнездятся дикие виверны.",
	["En el pueblo de los druidas del Claro de la Luna conviven Alianza y Horda: el Círculo Cenarion recibe a todos."] = "В деревне друидов на Лунной поляне Альянс и Орда живут бок о бок: Круг Кенария принимает всех.",
	["En el sur de Desolace, demonios y sátiros se reúnen en un aquelarre."] = "На юге Пустошей демоны и сатиры собираются на шабаш.",
	["En el sur de Tanaris hay colmenas de silítidos, primos de los de Silithus."] = "На юге Танариса есть ульи силитидов — родичей тех, что в Силитусе.",
	["En el sureste, la Mano de Tyr es la ciudad más fuerte que le queda a la Cruzada Escarlata."] = "На юго-востоке Длань Тира — самый сильный город, оставшийся у Алого ордена.",
	["En espera"] = "Ожидание",
	["En esta página, cuánto llevas descubierto de cada zona de tu continente y lo que te falta."] = "На этой странице — сколько ты открыл в каждой зоне своего континента и что осталось.",
	["En esta página, lo que te sirve más en el banco o con otro personaje: materiales de sus recetas, lo que piden sus misiones y equipo que tu clase no usa."] = "На этой странице — что полезнее хранить в банке или у другого персонажа: материалы для их рецептов, то, что просят их задания, и снаряжение, которое твой класс не носит.",
	["En esta página, un buscador por las bolsas, bancos y equipo de todos tus personajes, con filtros de tipo, calidad y personaje."] = "На этой странице — поиск по сумкам, банкам и экипировке всех персонажей, с фильтрами по типу, качеству и персонажу.",
	["En esta zona"] = "В этой зоне",
	["En estas laderas está Durnholde, donde Aedelas Blackmoore crió a Thrall como gladiador."] = "На этих склонах стоит Дарнхольд, где Эделас Блэкмур растил Тралла гладиатором.",
	["En estas tierras cayó Anduin Lothar, el León de Azeroth, durante la Segunda Guerra."] = "На этих землях во Второй войне пал Андуин Лотар, Лев Азерота.",
	["En estas tierras estuvo Strom, la capital de Arathor, el primer gran reino humano."] = "На этих землях стоял Стром, столица Аратора, первого великого королевства людей.",
	["En este pantano se hundió el Templo de Atal'Hakkar: los dragones verdes lo hundieron para frenar a los sacerdotes de Hakkar."] = "В этом болоте затонул Храм Атал'Хаккара: зеленые драконы погрузили его, чтобы остановить жрецов Хаккара.",
	["En estos días las calles se llenan de calabazas y velas. A mí me dan un poquito de miedo."] = "В эти дни улицы полны тыкв и свечей. Мне чуть-чуть страшно.",
	["En forma de felino te vuelves sigiloso. Acércate sin que te vean."] = "В облике кошки ты крадешься. Подбирайся незамеченным.",
	["En forma de felino y por la espalda: mucho daño."] = "В облике кошки и со спины: много урона.",
	["En forma de felino, un arañazo que hace sangrar."] = "В облике кошки — царапина, от которой враг истекает кровью.",
	["En forma de oso, golpea a varios enemigos cerca."] = "В облике медведя бьет нескольких врагов рядом.",
	["En grifo, la línea de tu vuelo en el mapa: por dónde vas, dónde aterrizas y el tiempo que falta."] = "На грифоне — линия твоего полёта на карте: где ты сейчас, где приземлишься и сколько осталось лететь.",
	["En grupo"] = "В группе",
	["En grupo casi siempre hay varios enemigos: pegas a dos a la vez."] = "В группе почти всегда несколько противников: вы бьете двоих сразу.",
	["En grupo o con tu mascota: tu amenaza sobre tu objetivo. Te avisa antes de quitárselo al tanque, o si eres tanque, antes de perderlo."] = "В группе или с питомцем: твоя угроза по цели. Предупредит, прежде чем ты сорвешь врага с танка, или, если ты танк, прежде чем потеряешь его.",
	["En grupo o en una instancia."] = "В группе или в подземелье.",
	["En grupo y aguantando: Furia justa te da más amenaza."] = "В группе и в роли танка: Праведное неистовство дает больше угрозы.",
	["En grupo, Alfa muestra una barra pequeña con tu amenaza sobre tu objetivo. Se pone amarilla antes de que se lo quites al tanque y roja si ya te ataca a ti. Si eres tanque, te avisa cuando están por quitártelo."] = "В группе Alfa показывает маленькую полосу твоей угрозы по цели. Она желтеет, пока ты не сорвал врага с танка, и краснеет, если он уже атакует тебя. Если ты танк, она предупредит, когда врага вот-вот сорвут.",
	["En grupo, al seleccionar un raro sin marca, Alfa te ofrece ponerle la calavera con un clic: todo tu grupo la ve. En banda, si eres líder o ayudante."] = "В группе, когда ты выбираешь редкого без метки, Alfa предлагает одним щелчком поставить на него череп: его увидит вся группа. В рейде — если ты лидер или помощник.",
	["En grupo, cura al tanque antes que a nadie."] = "В группе лечите танка раньше всех.",
	["En grupo, cura al tanque primero y no saques monstruos tú."] = "В группе лечите танка в первую очередь и сами не притягивайте монстров.",
	["En grupo, cura antes de que la vida baje mucho: es más barato."] = "В группе лечите, пока здоровье не упало сильно: так дешевле.",
	["En grupo, deja tus tótems de maná y de curas cerca del grupo."] = "В группе ставьте тотемы маны и исцеления рядом с группой.",
	["En grupo, dónde está lo que pide cada misión y quién la lleva."] = "В группе: где выполняется каждое задание и у кого оно есть.",
	["En grupo, si alguien no tiene una misión que tú llevas, el rastreador te lo dice con «Compartir». Un clic y se la ofreces."] = "В группе, если у кого-то нет твоего задания, отслеживание скажет об этом кнопкой «Поделиться». Один щелчок — и ты его предложишь.",
	["En grupo, si alguien no tiene una misión tuya, un botón para compartírsela."] = "В группе, если у кого-то нет одного из твоих заданий, кнопка, чтобы поделиться.",
	["En la %s"] = "В: %s",
	["En la Arena Gurubashi aparece de vez en cuando un cofre que todos se pelean. ¡Sálvese quien pueda!"] = "На Арене Гурубаши время от времени появляется сундук, за который дерутся все. Спасайся, кто может!",
	["En la Enciclopedia"] = "В «Энциклопедии»",
	["En la Feria canjeas vales por premios; los vales se ganan entregando cosas que hiciste con tu profesión o que juntaste cazando."] = "На Ярмарке ты меняешь купоны на призы; купоны дают за вещи, сделанные твоей профессией или добытые на охоте.",
	["En la Feria de la Luna Negra, la adivina Sayge te hace unas preguntas y te da una fortuna que sube tus estadísticas un buen rato."] = "На Ярмарке Новолуния гадалка Сейдж задает пару вопросов и дает предсказание, которое надолго повышает характеристики.",
	["En la Fortaleza de Grommash, Thrall recibe a quien venga; muy cerca está Eitrigg, el viejo orco amigo de Tirion."] = "В Крепости Громмаш Тралл принимает всех; рядом стоит Эйтригг, старый орк, друг Тириона.",
	["En la Guerra de las Arenas Movedizas, el archidruida Fandral perdió a su hijo Valstann a manos de los qiraji."] = "В Войне Зыбучих Песков верховный друид Фэндрал потерял сына Валстанна в бою с киражами.",
	["En la Segunda Guerra, la Horda sumó a los trols Amani, a los ogros y a dragones rojos esclavizados."] = "Во Второй войне к Орде присоединились тролли Амани, огры и порабощенные красные драконы.",
	["En la Semana de los Niños, los huérfanos de Ventormenta y Orgrimmar te piden que los lleves de paseo; al final te dan una mascota."] = "На Детской неделе сироты Штормграда и Оргриммара просят сводить их на прогулку; в конце они дарят питомца.",
	["En la Tercera Guerra, orcos, humanos y elfos se unieron aquí contra Archimonde, y Nordrassil sacrificó su energía para destruirlo."] = "В Третьей войне орки, люди и эльфы объединились здесь против Архимонда, и Нордрассил пожертвовал своей силой, чтобы уничтожить его.",
	["En la Terraza de los Artesanos de Darnassus están los maestros de profesiones."] = "На Террасе Ремесленников в Дарнасе находятся учителя профессий.",
	["En la Vega se encuentran páginas sueltas de un libro de Nesingwary; junta un capítulo completo y llévaselo."] = "В Тернистой долине попадаются разрозненные страницы книги Несингвари; собери целую главу и отнеси ему.",
	["En la batalla de Hyjal, Malfurion hizo sonar el Cuerno de Cenarius y miles de fuegos fatuos rodearon a Archimonde hasta destruirlo."] = "В битве при Хиджале Малфурион протрубил в Рог Кенария, и тысячи огоньков окружили Архимонда, пока не уничтожили его.",
	["En la casa de subastas, mira los precios unos días antes de vender: cambian según la hora y quién esté jugando."] = "На аукционе понаблюдай за ценами несколько дней перед продажей: они меняются в зависимости от времени и того, кто играет.",
	["En la cima del Monte Hyjal crece Nordrassil, el Árbol del Mundo, que los dragones bendijeron."] = "На вершине горы Хиджал растет Нордрассил, Древо Мира, благословленное драконами.",
	["En la costa de Durotar, soldados de Kul Tiras ocupan el Fuerte Tiragarde: una espina clavada en la tierra de la Horda."] = "На побережье Дуротара солдаты Кул-Тираса занимают Крепость Тирагарда — заноза в земле Орды.",
	["En la costa de Tanaris se esconden piratas de los Mares del Sur."] = "На побережье Танариса прячутся пираты Южных морей.",
	["En la costa del pantano hay naga, y no reciben bien a los curiosos."] = "На побережье болота есть наги, и любопытных они не жалуют.",
	["En la costa este vive una tribu trol amiga de la Horda, enemiga de los trols de Jintha'Alor."] = "На восточном побережье живет племя троллей, дружное с Ордой и враждебное троллям Джинта'Алора.",
	["En la costa oeste de Vallefresno, las Cavernas de Brazanegra fueron un templo de Elune; hoy están hundidas y llenas de naga."] = "На западном побережье Ясеневого леса Непроглядная Пучина когда-то была храмом Элуны; теперь она затоплена и полна наг.",
	["En la costa se ven ruinas de antiguos palacios élficos, medio hundidos en el mar."] = "На побережье видны руины древних эльфийских дворцов, наполовину ушедших в море.",
	["En la cueva del barco hay muchos piratas: no bajen todos de golpe al muelle."] = "В пещере с кораблем много пиратов: не спрыгивайте на причал все сразу.",
	["En la excavación de Ironband, los troggs salieron de la tierra y se quedaron con todo."] = "На раскопках Айронбенда трогги вылезли из-под земли и захватили все.",
	["En la ficha de cada mazmorra está el botín de cada jefe y lo que mejora tu equipo."] = "На карточке каждого подземелья добыча каждого босса и то, что улучшит снаряжение.",
	["En la granja de los Saldean, la vieja yegua Blanchy necesita avena. Es de las misiones más tiernitas de los Páramos."] = "На ферме Салдинов старой кобыле Бланш нужен овес. Одно из самых трогательных заданий Западного Края.",
	["En la guarida de Onyxia, a los lados hay nidos con huevos: si alguien los pisa salen dragoncitos... muchísimos."] = "В логове Ониксии по бокам гнезда с яйцами: если на них наступить, вылупятся дракончики... очень много.",
	["En la pelea, el juego te avisa"] = "В бою игра вас предупредит",
	["En la sala de la Liga de Expedicionarios de Forjaz hay biblioteca, mapas y un museo con fósiles gigantes."] = "В зале Лиги исследователей в Стальгорне есть библиотека, карты и музей с гигантскими окаменелостями.",
	["En la segunda parte mátenla a ella primero: cura mucho."] = "Во второй части убейте ее первой: она много лечит.",
	["En la subasta cuenta el precio más bajo que vio, menos la comisión (%d%%, estimada). Al desencantar usa tablas del juego clásico, también estimadas."] = "Для аукциона берется самая низкая увиденная цена минус комиссия (%d%%, примерно). Для распыления используются таблицы классической игры, тоже примерные.",
	["En la subasta, unos %s."] = "На аукционе — около %s.",
	["En la ventana y aquí. Si no estás entre ellos, tu fila sale al final."] = "В окне и здесь. Если вас среди них нет, ваша строка будет в конце.",
	["En las Cuevas de los Lamentos, el druida Naralex soñó con devolverle el verdor a Los Baldíos, y su sueño se volvió pesadilla."] = "В Пещерах Стенаний друид Наралекс мечтал вернуть Степям зелень, но его сон обернулся кошмаром.",
	["En las Guerras Trol, los altos elfos enseñaron magia a cien humanos para vencer juntos a los Amani. Fueron los primeros magos de la humanidad."] = "В Тролльих войнах высшие эльфы научили магии сотню людей, чтобы вместе победить Амани. Это были первые маги человечества.",
	["En las Mazmorras de Ventormenta los presos se amotinaron, y la guardia pide ayuda para calmar el desastre."] = "В Тюрьме Штормграда заключенные подняли бунт, и стража просит помочь навести порядок.",
	["En las Pozas de la Visión, bajo una de las mesetas, entrenan los magos y sacerdotes Renegados."] = "В Прудах Видений под одной из мес обучаются маги и жрецы Отрекшихся.",
	["En las cuevas de Cuna del Invierno viven yetis peludos y gruñones."] = "В пещерах Зимних Ключей живут косматые и ворчливые йети.",
	["En las cuevas de Feralas viven yetis, y los ogros Gordunni tienen sus campamentos en el norte."] = "В пещерах Фераласа живут йети, а у огров Гордунни лагеря на севере.",
	["En las cuevas nevadas de Dun Morogh viven trols de las nieves que no quieren a los enanos ni tantito."] = "В снежных пещерах Дун Морога живут снежные тролли, которые дворфов на дух не переносят.",
	["En las dos armas"] = "На обоих оружиях",
	["En las granjas del oeste hay calderos de la Plaga que siguen esparciendo la peste; la Alianza manda aventureros a destruirlos."] = "На западных фермах котлы Плети продолжают распространять чуму; Альянс посылает искателей приключений их уничтожить.",
	["En las ruinas de la ciudad de Alterac hoy mandan los ogros y el Sindicato, la banda de nobles caídos del viejo reino."] = "В руинах города Альтерак теперь хозяйничают огры и Синдикат — банда павшей знати старого королевства.",
	["En lo alto de la sierra hay un pico sagrado para los druidas elfos, donde anidan aves enormes."] = "Высоко в горах есть пик, священный для эльфийских друидов, где гнездятся огромные птицы.",
	["En lo más alto de la Montaña Roca Negra manda Nefarian, hijo de Alamuerte."] = "На самой вершине Черной горы правит Нефариан, сын Смертокрыла.",
	["En los Páramos de Poniente el viento mueve los molinos. Ojo con los Defias en las granjas."] = "В Западном Крае ветер крутит мельницы. Осторожно с Братством Справедливости на фермах.",
	["En los mapas"] = "На картах",
	["En lugar de las del juego"] = "Вместо сумок игры",
	["En marcha"] = "В процессе",
	["En marcha hacia %s"] = "В пути: %s",
	["En mazmorra"] = "В подземелье",
	["En mazmorras y bandas"] = "В подземельях и рейдах",
	["En mazmorras y en combate Lya se hace chiquita, se calla y no estorba tus clics. Al terminar vuelve."] = "В подземельях и в бою Лия становится маленькой, молчит и не мешает щелчкам. Потом возвращается.",
	["En memoria"] = "В память",
	["En memoria de una gran perrita"] = "В память об одной замечательной собачке",
	["En mi zona"] = "В моей зоне",
	["En movimiento"] = "В движении",
	["En orco, «Lok'tar ogar» quiere decir «victoria o muerte»."] = "По-орочьи «Lok'tar ogar» значит «победа или смерть».",
	["En otra zona: %s"] = "В другой зоне: %s",
	["En pantalla"] = "На экране",
	["En pausa"] = "На паузе",
	["En pausa dentro de la instancia"] = "Пауза внутри подземелья",
	["En pausa por ahora"] = "Пока на паузе",
	["En pausa: hay otro addon de pesca activo"] = "Пауза: включен другой аддон рыбалки",
	["En plena Segunda Guerra, Gul'dan abandonó a la Horda para buscar la Tumba de Sargeras. Ahí lo despedazaron los demonios que encontró."] = "В разгар Второй войны Гул'дан бросил Орду, чтобы найти Гробницу Саргераса. Там его разорвали найденные им демоны.",
	["En posadas y ciudades acumulas XP descansada: ganas el doble de XP por enemigo hasta gastarla. Si cierras sesión aquí, también se acumula."] = "В тавернах и городах накапливается опыт за отдых: за каждого противника вы получаете вдвое больше опыта, пока он не закончится. Если выйти из игры здесь, он тоже накапливается.",
	["En posadas y ciudades juntas XP descansada: ganas el doble por enemigo hasta gastarla."] = "В тавернах и городах копится опыт за отдых: вдвое больше опыта за противника, пока он не кончится.",
	["En qué orden aparecen."] = "В каком порядке они появляются.",
	["En qué se gastan"] = "На что тратятся",
	["En silencio"] = "Без звука",
	["En solitario es lento: usa la varita para rematar."] = "В одиночку медленно: добивайте жезлом.",
	["En solitario, deja curas que duran en el tiempo y pelea con Cólera."] = "В одиночку накладывайте периодическое исцеление и сражайтесь Гневом.",
	["En solitario, pelea con choques y cúrate entre monstruos."] = "В одиночку сражайтесь шоками и лечитесь между монстрами.",
	["En su ficha toca «Agregar a mi ruta»."] = "На его странице нажмите «Добавить в мой маршрут».",
	["En sus inicios, una batalla del Valle de Alterac podía durar horas... ¡y hasta días!"] = "В первые дни битва в Альтеракской долине могла длиться часами... и даже днями!",
	["En todo Alfa"] = "Во всем Alfa",
	["En total, %d cosas por unos %s."] = "Всего вещей: %d, примерно на %s.",
	["En total: %s"] = "Всего: %s",
	["En tu arma"] = "На оружии",
	["En tu marco"] = "На вашей рамке",
	["En tu plan"] = "В вашем плане",
	["En tu registro"] = "В журнале заданий",
	["En tus bolsas"] = "В сумках",
	["En tus bolsas, el botín, el chat o cualquier enlace: Alt+clic abre la guía para conseguirlo o, si no hay, su ficha en la enciclopedia."] = "В сумках, добыче, чате или по любой ссылке: Alt+щелчок открывает гайд, как это получить, а если гайда нет — страницу в энциклопедии.",
	["En tus bolsas: con un comerciante vende tu chatarra; con un banquero guarda tus materiales. Con tu clic."] = "В сумках: у торговца продает хлам, у банкира складывает материалы. По твоему щелчку.",
	["En tus bolsas: úsala para aprenderla"] = "В сумках: используйте, чтобы изучить",
	["En tus recetas que dejan ganancia, primero las que ya puedes hacer con lo que llevas, y cuánto ganarías haciéndolas todas."] = "В выгодных рецептах сначала те, что ты уже можешь сделать из того, что при тебе, и сколько заработаешь, сделав все.",
	["En un aviso"] = "Оповещением",
	["En un aviso y en el chat"] = "Оповещением и в чате",
	["En un cañón de Vallefresno, Grom mató al señor demonio Mannoroth y liberó a los orcos de su sangre maldita."] = "В каньоне Ясеневого леса Гром убил повелителя демонов Маннорота и освободил орков от его проклятой крови.",
	["En un paso de «Sube al nivel», cuánta experiencia te falta y dónde rinde más: enemigos de tu nivel que cuentan para tus misiones."] = "На шаге «Достичь уровня»: сколько нужно опыта и где он выгоднее всего — враги твоего уровня, которые идут в зачет заданий.",
	["En un valle de Frondavil cayeron infernales del cielo, y todavía se ven sus cráteres."] = "В одну из долин Оскверненного леса с неба падали инферналы, и их кратеры видны до сих пор.",
	["En un vuelo con escalas, una línea bajo el temporizador dice dónde es la siguiente parada y cuánto falta para llegar. Necesita el temporizador de vuelo encendido."] = "В полете с пересадками строка под таймером показывает, где следующая остановка и сколько до нее лететь. Нужен включенный таймер полета.",
	["En una aldea del sur del bosque, los vecinos parecen normales de día... y de noche se convierten en worgen."] = "В деревне на юге леса жители днем кажутся обычными... а ночью превращаются в воргенов.",
	["En una de las mesetas, los tauren honran a los espíritus de sus ancestros."] = "На одной из мес таурены чтят духов своих предков.",
	["En una instancia: la flecha vuelve al salir"] = "В подземелье: стрелка вернется после выхода",
	["En una isla de Azshara vive el duque Hydraxis, señor del agua; su gente te ayuda a apagar las runas del Núcleo de Magma."] = "На острове у Азшары живет герцог Гидраксис, повелитель воды; его народ помогает потушить руны Огненных Недр.",
	["En una mazmorra no hay guaridas."] = "В подземельях логов нет.",
	["En una pestaña nueva"] = "В новой вкладке",
	["En unos segundos aparece tu build."] = "Через несколько секунд появится ваш билд.",
	["En uso"] = "Используется",
	["En uso, a tu gusto"] = "Используется, на ваш вкус",
	["En vivo"] = "Вживую",
	["En vivo si estás con un banquero; si no, la última foto."] = "Вживую, если вы у банкира; иначе — последний снимок.",
	["En vuelo a %s"] = "Полёт в %s",
	["En vuelo: la flecha sigue al bajar"] = "В полете: стрелка продолжит после приземления",
	["En vuelo: la flecha sigue al bajar."] = "В полете: стрелка продолжит после посадки.",
	["Enanos"] = "Дворфы",
	["Encanta tu arma antes de pelear."] = "Зачаруйте оружие перед боем.",
	["Encanta tu arma para pegar más fuerte. Renuévalo cuando se acabe."] = "Зачаровывает оружие, чтобы бить сильнее. Обновляй, когда закончится.",
	["Encantada"] = "Зачаровано",
	["Encantamiento"] = "Наложение чар",
	["Encantamientos con Polvo de almas y Esencia astral."] = "Чары с пылью души и астральной эссенцией.",
	["Encantamientos con Polvo de ilusión y Esencia eterna."] = "Чары с пылью иллюзий и эссенцией вечности.",
	["Encantamientos con Polvo de sueño y Esencia abisal."] = "Чары с пылью снов и эссенцией пустоты.",
	["Encantamientos con Polvo de visión y Esencia mística."] = "Чары с пылью видений и мистической эссенцией.",
	["Encantamientos de brazales y capas con Polvo extraño y Esencia mágica mayor."] = "Чары для наручей и плаща со странной пылью и великой магической эссенцией.",
	["Encantamientos menores de brazales y pecheras con Polvo extraño."] = "Простые чары для наручей и нагрудника со странной пылью.",
	["Encantar a otros es un servicio: anúnciate en el chat de comercio de la ciudad."] = "Наложение чар для других — это услуга: предлагай ее в торговом чате города.",
	["Encender el registro"] = "Включить учет",
	["Encender la pesca"] = "Включить рыбалку",
	["Encender las recomendadas"] = "Включить рекомендуемые",
	["Encender una fogata"] = "Развести костер",
	["Encenderla"] = "Включить",
	["Encenderlos"] = "Включить их",
	["Encendida: entra al plan aunque el filtro la deje fuera. Apagada: queda fuera."] = "Вкл.: попадает в план, даже если фильтр ее исключает. Выкл.: остается вне плана.",
	["Encendido"] = "Включено",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Включено: двойной щелчок во время рыбалки забрасывает снова, а с Shift, Ctrl или Alt — вытаскивает. Выключено: наоборот.",
	["Enciclopedia"] = "Энциклопедия",
	["Enciende las comodidades recomendadas"] = "Включите рекомендуемые удобства",
	["Enciende los cambios de abajo en el cuadro que sale al pasar el ratón por un personaje o criatura."] = "Включает изменения ниже в подсказке, которая появляется при наведении курсора на персонажа или существо.",
	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Включает изменения ниже в примерочной (Ctrl + щелчок по предмету).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Включает изменения ниже; каждое можно выключить отдельно. Некоторые аддоны подстраивают свои кнопки под квадрат после /reload.",
	["Enciende primero la guía en el minimapa."] = "Сначала включите гайд на мини-карте.",
	["Enciende primero los servicios."] = "Сначала включите услуги.",
	["Enciéndela para ver en combate qué habilidad conviene ahora y cuáles siguen, en un ícono pequeño que puedes mover."] = "Включите, чтобы в бою видеть, какую способность лучше применить сейчас и какие дальше, на маленьком подвижном значке.",
	["Enciéndelo en el menú del juego: Opciones > %s > «%s». Alfa no lo cambia por ti: el medidor del juego lo lee en combate y fallaría."] = "Включите это в меню игры: Настройки > %s > «%s». Alfa не меняет это за вас: игровой измеритель читает настройку в бою, и возникла бы ошибка.",
	["Enciéndelos abajo, en Marcos, para ver a tu grupo con su vida y curar con un clic."] = "Включите их ниже, в разделе «Рамки», чтобы видеть здоровье группы и лечить одним щелчком.",
	["Enciéndelos en la página Curación."] = "Включите их на странице «Исцеление».",
	["Enciéndelos para ver a tu grupo con su vida y curar con un clic."] = "Включите их, чтобы видеть здоровье группы и лечить одним щелчком.",
	["Encontré %d cosas que revisar."] = "Нашла, что проверить: %d.",
	["Encontré 1 cosa que revisar."] = "Нашла 1 вещь, которую стоит проверить.",
	["Encuentra %d raro"] = "Найди редких: %d",
	["Encuentra %d raros"] = "Найди редких: %d",
	["Enemigo raro"] = "Редкий противник",
	["Enemigos menores"] = "Слабые противники",
	["Enfermedad"] = "Болезнь",
	["Enfoque interno: tu siguiente hechizo es gratis y más crítico."] = "Внутреннее сосредоточение: следующее заклинание бесплатно и чаще критическое.",
	["Enraíza al monstruo y aléjate antes de lanzar tus hechizos largos."] = "Обездвижьте монстра корнями и отойдите, прежде чем произносить долгие заклинания.",
	["Entendido"] = "Понятно",
	["Entereza"] = "Стойкость",
	["Entorno"] = "Окружение",
	["Entra a %d mazmorra"] = "Зайди в подземелья: %d",
	["Entra a %d mazmorras"] = "Зайди в подземелья: %d",
	["Entra al juego con él una vez."] = "Зайдите в игру этим персонажем один раз.",
	["Entra con el registro limpio: entrega lo que ya tienes."] = "Входите с чистым журналом: сдайте то, что уже есть.",
	["Entra en el plan que termina y entrega tus misiones por el camino más corto, con lo que pide antes."] = "Попадает в план, который выполняет и сдает ваши задания кратчайшим путем, вместе с тем, что для него нужно заранее.",
	["Entrada"] = "Вход",
	["Entrada enemiga"] = "Вход на вражеской территории",
	["Entradas de mazmorras"] = "Входы в подземелья",
	["Entradas en el minimapa"] = "Входы на мини-карте",
	["Entradas y salidas"] = "Входы и выходы",
	["Entramos a %s. Antes de cada pelea, espera a que quien cura tenga maná."] = "Мы в %s. Перед каждым боем жди, пока у лекаря будет мана.",
	["Entramos juntos a lo oscuro. Yo te cuido la espalda."] = "Мы вместе вошли во тьму. Я прикрываю тебе спину.",
	["Entraron %s, con lo que piden antes de entregarlas."] = "Добавлены %s — вместе с тем, что нужно до их сдачи.",
	["Entraste a %s"] = "Вы вошли: %s",
	["Entraste a %s."] = "Вы вошли: %s.",
	["Entrañas son las criptas y catacumbas bajo la antigua capital de Lordaeron."] = "Подгород — это склепы и катакомбы под древней столицей Лордерона.",
	["Entrañas tiene barrios para magos, pícaros, guerreros y boticarios, y en el anillo central están el banco y la casa de subastas."] = "В Подгороде есть кварталы магов, разбойников, воинов и аптекарей, а в центральном кольце — банк и аукцион.",
	["Entre Entrañas y Grom'gol también hay zepelín: así bajas al sur sin cruzar todo el continente."] = "Между Подгородом и Гром'голом тоже летает дирижабль: так можно попасть на юг, не пересекая весь континент.",
	["Entre los druidas están los de la Garra, que se vuelven osos, y los del Espolón, que toman forma de cuervo."] = "Среди друидов есть друиды Когтя, которые становятся медведями, и друиды Пера, принимающие облик ворона.",
	["Entrega %d de %d: %s."] = "Сдача %d из %d: %s.",
	["Entrega %d misiones"] = "Сдай заданий: %d",
	["Entrega %d misión"] = "Сдай заданий: %d",
	["Entrega 1 de %d: %s."] = "Сдача 1 из %d: %s.",
	["Entrega lo que terminaste"] = "Сдай выполненное",
	["Entrega tus %d misiones listas"] = "Сдайте готовые задания: %d",
	["Entrega tus misiones listas"] = "Сдай выполненные задания",
	["Entregada"] = "Сдано",
	["Entregar"] = "Сдать",
	["Entregar %s"] = "Сдать: %s",
	["Entregar las completadas"] = "Сдавать выполненные задания",
	["Entregar las misiones de tu guía"] = "Сдавать задания гайда",
	["Entregar mis misiones"] = "Сдать мои задания",
	["Entregar misiones"] = "Сдать задания",
	["Entregar solas las misiones de la guía"] = "Сдавать задания гайда автоматически",
	["Entregar todas"] = "Сдать все",
	["Entregarla"] = "Сдать",
	["Entregarlas ahora"] = "Сдать сейчас",
	["Entregaste %d misiones."] = "Сдано заданий: %d.",
	["Entregaste 1 misión."] = "Ты сдал 1 задание.",
	["Entregaste todo en %d parada."] = "Все сдано, остановок: %d.",
	["Entregaste todo en %d paradas."] = "Все сдано, остановок: %d.",
	["Entrenador"] = "Учитель",
	["Entrenador al día"] = "У учителя все изучено",
	["Entrenador de %s"] = "Учитель: %s",
	["Entrenador de tu clase"] = "Учитель вашего класса",
	["Entrenador: %s, en %s."] = "Учитель: %s (%s).",
	["Entrenador: %s."] = "Учитель: %s.",
	["Entrenadores de profesión"] = "Учителя профессий",
	["Entrenar"] = "Обучиться",
	["Entrenar la rápida"] = "Изучить быструю езду",
	["Entrégala a %s."] = "Сдайте: %s.",
	["Entró %s, con lo que pide antes de entregarla."] = "Добавлено %s — вместе с тем, что нужно до его сдачи.",
	["Envenena al enemigo un rato. Ponla al inicio de cada pelea."] = "Отравляет врага на время. Накладывай в начале каждого боя.",
	["Envenena y lanza rayos: quita el veneno si puedes."] = "Он отравляет и бьет молниями: снимайте яд, если можете.",
	["Equilibrada"] = "Сбалансированный",
	["Equilibrado"] = "Сбалансированно",
	["Equilibrado: se ve bien y corre bien en casi cualquier equipo."] = "Сбалансированный: хорошо выглядит и хорошо идет почти на любом ПК.",
	["Equilibrio"] = "Баланс",
	["Equilibrio para subir"] = "Баланс для прокачки",
	["Equipa tu caña de pescar"] = "Возьмите удочку в руки",
	["Equipo"] = "Экипировка",
	["Equipo %d %%"] = "Снаряжение %d %%",
	["Equipo a punto de romperse."] = "Экипировка вот-вот сломается.",
	["Equipo de pesca"] = "Рыболовное снаряжение",
	["Equipo reparado, comida, espacio y lo de tu clase: a cazar con la manada."] = "Снаряжение починено, еда, комната и реагенты класса: вперед на охоту со стаей.",
	["Equipo y banco"] = "Снаряжение и банк",
	["Equipo y cebos"] = "Снаряжение и приманки",
	["Equipo y estadísticas"] = "Снаряжение и характеристики",
	["Equipo, bolsas, comida y lo de tu clase"] = "Снаряжение, сумки, еда и реагенты класса",
	["Equipo, consumibles, misiones, materiales... con encabezados que se pliegan."] = "Снаряжение, расходуемые предметы, задания, материалы... под сворачиваемыми заголовками.",
	["Equitación"] = "Верховая езда",
	["Equitación de aprendiz (nivel 40)"] = "Верховая езда: ученик (40-й уровень)",
	["Equitación de oficial (la rápida, nivel 60)"] = "Верховая езда: подмастерье (быстрая, 60-й уровень)",
	["Eranikus, el consorte de Ysera, quedó atrapado en la pesadilla; su sombra ronda el Templo de Atal'Hakkar."] = "Эраникус, супруг Изеры, оказался в ловушке кошмара; его тень бродит по Храму Атал'Хаккара.",
	["Eres de la manada"] = "Вы в стае",
	["Eres nivel %d"] = "У вас %d-й уровень",
	["Eres nivel %d y se recomienda el %d: desde ahí cuenta así."] = "Ваш уровень — %d, рекомендуется %d: начиная с него, считается так.",
	["Eres nivel %d."] = "У вас %d-й уровень.",
	["Error"] = "Ошибка",
	["Errores atrapados"] = "Пойманные ошибки",
	["Errores de Alfa"] = "Ошибки Alfa",
	["Errores de Lua de Alfa en esta sesión:"] = "Ошибки Lua в Alfa за этот сеанс:",
	["Errores de Lua de Alfa en esta sesión: ninguno"] = "Ошибки Lua в Alfa за этот сеанс: нет",
	["Es corta y está dentro de Ventormenta. Los presos están en celdas a los lados: avancen despacio."] = "Короткое подземелье внутри Штормграда. Заключенные сидят в камерах по бокам: продвигайтесь медленно.",
	["Es de la otra facción"] = "Это задание другой фракции",
	["Es de una misión."] = "Это предмет для задания.",
	["Es el jefe que pide una misión de la Alianza: revisa tus misiones antes de entrar."] = "Этот босс нужен для задания Альянса: проверьте свои задания перед входом.",
	["Es el primer jefe y es sencillo. Al morir, el prisionero de tu facción abre la puerta del patio."] = "Это первый босс, и он простой. После его смерти пленник вашей фракции открывает дверь во двор.",
	["Es el primer reto: con él se abre el Legado."] = "Это первое испытание: с него открывается «Наследие».",
	["Es el punto %d de %d de tu build."] = "Это очко %d из %d вашего билда.",
	["Es el que toca ahora."] = "Его нужно взять сейчас.",
	["Es el último del Cementerio. Lanza llamas a su alrededor: si peleas de lejos, quédate lejos."] = "Последний босс Кладбища. Он выпускает пламя вокруг себя: если сражаетесь на расстоянии, держитесь подальше.",
	["Es el único lobo a la vista."] = "Это единственный волк в поле зрения.",
	["Es grande y es fácil perderse: sigan a una sola persona y no corran solos."] = "Подземелье большое, в нем легко заблудиться: следуйте за одним человеком и не убегайте поодиночке.",
	["Es la máquina de Sneed: rómpela y él saldrá a pelear."] = "Это машина Снида: сломайте ее, и он выйдет сражаться.",
	["Es la primera mazmorra de la Horda: corta y buena para aprender a jugar en grupo."] = "Это первое подземелье Орды: короткое и хорошее для обучения игре в группе.",
	["Es la primera mazmorra grande de la Alianza: avancen despacio y tiren un grupo a la vez."] = "Это первое большое подземелье Альянса: продвигайтесь медленно и выманивайте по одной группе.",
	["Es la que más vale al venderla."] = "Она дороже всех при продаже.",
	["Es larga y tiene dos entradas. Muchos enemigos son de piedra y pegan fuerte."] = "Длинное подземелье с двумя входами. Многие противники каменные и бьют сильно.",
	["Es larga y tiene muchos robots: algunos ponen bombas o hacen sonar alarmas que traen más enemigos."] = "Длинное подземелье с множеством роботов: некоторые ставят бомбы или включают тревогу, которая зовет еще противников.",
	["Es lento: si peleas de lejos, atácalo mientras se acerca."] = "Он медленный: если сражаетесь на расстоянии, атакуйте его, пока он приближается.",
	["Es muy veloz: frénalo si tu clase puede."] = "Он очень быстрый: замедлите его, если ваш класс это умеет.",
	["Es opcional. Si dices que sí, los lobos de La Jauría que usan Alfa ven a tu personaje en el mapa de WoW, como ves a tu grupo, y pueden llegar a donde estás con la flecha; y tú a ellos. Alfa solo comparte dónde anda tu personaje dentro del juego: la zona, el punto en el mapa, su nivel y su clase. Nada de tu ubicación real, tu computadora ni tu cuenta."] = "Это необязательно. Если вы согласитесь, волки La Jauría, которые пользуются Alfa, будут видеть вашего персонажа на карте WoW, как вы видите свою группу, и смогут добраться до вас по стрелке, а вы — до них. Alfa передает только то, где ваш персонаж находится в игре: зону, точку на карте, его уровень и класс. Никогда — ваше реальное местоположение, компьютер или учетную запись.",
	["Es opcional: tu personaje aparece en el mapa de WoW de los lobos de La Jauría que usan Alfa, y ellos en el tuyo, para encontrarse y llegar con la flecha. Solo se comparte dónde anda tu personaje dentro del juego (zona, punto en el mapa, nivel y clase), nunca tu ubicación real ni nada de tu computadora, y nunca dentro de mazmorras. Va por un canal oculto que no sale en el chat, aunque alguien que entre a él con otro addon podría verlo. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "Это по желанию: ваш персонаж появляется на карте WoW у волков La Jauría, которые пользуются Alfa, а они — на вашей, чтобы находить друг друга и добираться по стрелке. Передаётся только то, где ваш персонаж находится в игре (зона, точка на карте, уровень и класс), никогда не ваше реальное местоположение и ничего с вашего компьютера, и никогда в подземельях. Это идёт через скрытый канал, который не показывается в чате, хотя тот, кто войдёт в него с другим аддоном, может это увидеть. Вашу группу видно всегда. Изменить можно в любой момент в La Jauría.",
	["Es para niveles %s y vas en el %d: te faltan %d niveles."] = "Для уровней %s, а у вас %d: осталось %d ур.",
	["Es para otra raza."] = "Для другой расы.",
	["Es raro del Cementerio y no siempre aparece."] = "Редкий босс Кладбища, появляется не всегда.",
	["Es raro del Cementerio y no siempre aparece. Envenena: quita el veneno."] = "Редкий босс Кладбища, появляется не всегда. Отравляет: снимайте яд.",
	["Es raro del Cementerio y no siempre aparece. Puede silenciar a quien lanza hechizos."] = "Редкий босс Кладбища, появляется не всегда. Может накладывать немоту на заклинателей.",
	["Es raro y aparece pocas veces. Usa fuego a su alrededor."] = "Редкий, появляется нечасто. Использует огонь вокруг себя.",
	["Es raro y está en una cueva escondida. Es un murciélago que pega rápido."] = "Редкий, находится в скрытой пещере. Это летучая мышь, которая быстро бьет.",
	["Es raro y no siempre aparece. Pega muy fuerte para su nivel: tírenlo con cuidado."] = "Редкий, появляется не всегда. Бьет очень сильно для своего уровня: выманивайте его осторожно.",
	["Es raro y no siempre está. Golpea fuerte a todos los que tiene enfrente."] = "Редкий, бывает не всегда. Сильно бьет всех перед собой.",
	["Es raro. Pone un tótem de tierra: rómpelo."] = "Редкий. Ставит тотем земли: разбейте его.",
	["Es raro: no siempre está. Duerme a los jugadores y explota con magia a su alrededor."] = "Редкий: бывает не всегда. Усыпляет игроков и взрывается магией вокруг себя.",
	["Es sencillo: buen momento para beber agua antes del último jefe."] = "Простой босс: хороший момент попить воды перед последним боссом.",
	["Es un brujo que lanza hechizos: interrúmpelo si tu clase puede (Patada, Golpe de escudo, Choque de tierra...)."] = "Это заклинатель: прерывайте его, если ваш класс это умеет (Пинок, Удар щитом, Земной шок...).",
	["Es un chamán con tótems: rompan los tótems, son fáciles de matar."] = "Это шаман с тотемами: разбейте тотемы, их легко уничтожить.",
	["Es un enano con escudo: aguanta mucho pero no tiene trucos."] = "Это дворф со щитом: очень живучий, но без хитростей.",
	["Es un enemigo fuerte de la mina: trátenlo como un jefe pequeño."] = "Сильный противник в шахте: относитесь к нему как к маленькому боссу.",
	["Es un grupo: cada uno suelta su propio botín."] = "Это группа: каждый роняет свою добычу.",
	["Es un paladín: se cura con luz sagrada. Interrumpe su curación."] = "Это паладин: лечит себя Светом небес. Прерывайте его лечение.",
	["Es un sátiro rápido que envenena: si tu clase quita venenos, úsalo."] = "Это быстрый сатир, который отравляет: если ваш класс снимает яды, используйте это.",
	["Es un trogg que lanza rayos: interrúmpelo."] = "Это трогг, который бьет молниями: прерывайте его.",
	["Es una mejora para ti"] = "Это улучшение для вас",
	["Es una mejora para ti."] = "Это улучшение для тебя.",
	["Es una montura de tu clase: pregunta a tu instructor de clase cuándo y cómo se consigue."] = "Это классовый транспорт: спросите у учителя своего класса, когда и как его получить.",
	["Es una tortuga gigante con mucha armadura: pega lento pero duro."] = "Это гигантская черепаха с толстой броней: бьет медленно, но сильно.",
	["Es una tortuga muy dura, pero solo golpea: no tiene trucos."] = "Очень крепкая черепаха, но она только бьет: без хитростей.",
	["Es viejo: escanea para tenerlo al día."] = "Данные устарели: просканируй, чтобы обновить.",
	["Esa cadena no trae ninguna estadística que Alfa puntúe."] = "В этой строке нет характеристик, которые оценивает Alfa.",
	["Esa fila todavía no se abre: faltan puntos en esa rama."] = "Этот ряд еще не открыт: в этой ветке не хватает очков.",
	["Esa tecla ya tiene dueño"] = "Эта клавиша уже занята",
	["Esa ya me la diste, ¡gracias! Guárdame la siguiente."] = "Эту ты мне уже давал, спасибо! Прибереги следующую.",
	["Esbirros enemigos"] = "Прислужники противников",
	["Escala de estadísticas"] = "Шкала характеристик",
	["Escalas:"] = "Остановки:",
	["Escaneando..."] = "Сканирование...",
	["Escanear ahora"] = "Сканировать сейчас",
	["Escanear con Alfa"] = "Сканировать с Alfa",
	["Escaneo completo: %s objetos con precio (%s subastas)."] = "Полное сканирование: предметов с ценой — %s (лотов: %s).",
	["Escarcha"] = "Лед",
	["Escarcha en cono frente a ti que hace lentos a los enemigos."] = "Конус льда перед тобой, замедляющий врагов.",
	["Escarcha para subir"] = "Лед для прокачки",
	["Esconde las placas y los nombres de los PNJ mientras pescas (los enemigos hostiles conservan su nombre), para ver y tocar mejor el corcho."] = "Скрывает индикаторы и имена NPC во время рыбалки (враждебные противники сохраняют имена), чтобы поплавок было лучше видно и легче было по нему щелкнуть.",
	["Esconde lo que pide más habilidad de la que tienes. Sin esto se ve gris y tenue."] = "Скрывает то, что требует навыка выше вашего. Без этой настройки оно показано серым и бледным.",
	["Escribe %s o haz clic en el lobo del minimapa para abrirla. Empieza en Hoy, con lo que toca a tu clase; %s muestra u oculta la ventana de guía."] = "Введите %s или щелкните по волку на мини-карте, чтобы открыть его. Оно открывается на вкладке «Сегодня» с тем, что нужно вашему классу; %s показывает или скрывает окно гайда.",
	["Escribe %s y cuéntanos en el Discord de La Jauría."] = "Введите %s и расскажите нам в Discord La Jauría.",
	["Escribe /alfa diagnostico: reviso si otro addon choca con Alfa, si falta una parte o si un ajuste quedó raro, y te doy el arreglo a un clic."] = "Введи /alfa diagnostico: я проверю, не конфликтует ли другой аддон с Alfa, не пропала ли часть и нет ли странной настройки, и предложу исправление в один щелчок.",
	["Escribe /alfa teclas: ahí están todas, y con un clic pulsas la que quieras."] = "Набери /alfa teclas: там все клавиши, и одним щелчком ты назначишь любую.",
	["Escribe al menos 3 letras del objeto."] = "Введи хотя бы 3 буквы предмета.",
	["Escribe al menos dos letras."] = "Введите хотя бы две буквы.",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. Un clic en la marca y la flecha te lleva."] = "Напиши что-нибудь и нажми «Заметка тут»: она останется на карте там, где ты стоишь. Щелчок по метке — и стрелка поведет тебя.",
	["Escribe algo y pulsa «Nota aquí»: queda en tu mapa donde estás parado. «Spot aquí» marca un buen lugar para farmear, en dorado. Un clic en la marca y la flecha te lleva."] = "Напиши что-нибудь и нажми «Заметка тут»: она останется на карте там, где ты стоишь. «Место тут» золотом отмечает хорошее место для фарма. Щелкни по метке, и стрелка поведет.",
	["Escribe arriba el nombre de una mazmorra para buscarla."] = "Введите название подземелья сверху, чтобы найти его.",
	["Escribe cuánto oro (1 o más)."] = "Введите, сколько золота (1 или больше).",
	["Escribe el número que quieras y presiona Enter."] = "Введите нужное число и нажмите Enter.",
	["Escribe el top %d en el chat de tu grupo o banda."] = "Пишет топ-%d в чат группы или рейда.",
	["Escribe en el chat del grupo cuando terminas un objetivo de una misión compartida. Viene apagado para no llenar el chat de nadie."] = "Пишет в чат группы, когда вы выполняете цель общего задания. По умолчанию выключено, чтобы ни у кого не засорять чат.",
	["Escribe lo que buscas: un ajuste, o algo del juego, y te lo busco en la Enciclopedia."] = "Напиши, что ищешь: настройку или что-то из игры, и я поищу это в Энциклопедии.",
	["Escribe qué buscas: «Minas de la Muerte, falta sanador»."] = "Напиши, что ищешь: «Мертвые копи, нужен лекарь».",
	["Escribe qué dice la nota: /alfa nota Aquí sale el mineral"] = "Напиши текст заметки: /alfa nota Здесь есть руда",
	["Escribe qué se farmea ahí: /alfa spot Lobos para pieles"] = "Напиши, что там фармят: /alfa spot Волки ради шкур",
	["Escribe qué van a hacer (una mazmorra, una misión, lo que sea)."] = "Напиши, что будете делать (подземелье, задание, что угодно).",
	["Escribe tu nota."] = "Напишите заметку.",
	["Escribe un nivel (2 o más)."] = "Введите уровень (2 или больше).",
	["Escribe un nombre corto para reconocerla."] = "Введите короткое название, чтобы его узнавать.",
	["Escribe un objeto y pulsa «Buscar»: te contestan los lobos de tu hermandad que lo permiten."] = "Введи предмет и нажми «Искать»: ответят волки твоей гильдии, которые это разрешили.",
	["Escribir a %s"] = "Написать: %s",
	["Escuchar"] = "Слушать",
	["Escuchar el aullido"] = "Послушать вой",
	["Escudo"] = "Щит",
	["Escudo de relámpagos"] = "Щит молний",
	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Щит и защита: вы держите всех монстров, чтобы группа не страдала.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Щит и Свет: очень крепкий танк, который сам восполняет свою ману.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Щиты и упреждающее исцеление: вы долго держитесь и поддерживаете группу.",
	["Ese build es para otra clase."] = "Этот билд для другого класса.",
	["Ese día ni la manada te alcanzaba."] = "В тот день за тобой не угналась даже стая.",
	["Ese respaldo ya no está."] = "Этой копии больше нет.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Для этого таланта сначала нужен другой талант целиком (стрелка в дереве).",
	["Ese texto es demasiado largo para un build."] = "Этот текст слишком длинный для билда.",
	["Ese texto es demasiado largo para una cadena de escala."] = "Этот текст слишком длинный для строки шкалы.",
	["Ese texto no es un perfil de Alfa. Copia el que da «Exportar» completo."] = "Этот текст — не профиль Alfa. Скопируй целиком текст, который дает «Экспорт».",
	["Ese texto no es una ruta de Alfa."] = "Этот текст не является маршрутом Alfa.",
	["Esmeralda"] = "Изумрудный",
	["Eso no es una cadena de build de Alfa. Empieza con ALFA1;"] = "Это не строка билда Alfa. Она начинается с ALFA1;",
	["Eso no es una cadena de escala de estadísticas. Empieza con ( Pawn: v1: \"Nombre\": ..."] = "Это не строка шкалы характеристик. Она начинается с ( Pawn: v1: \"Название\": ...",
	["Eso se puede al salir de combate."] = "Это можно сделать после выхода из боя.",
	["Espacio"] = "Пробел",
	["Espacio libre"] = "Свободное место",
	["Espacio y dinero"] = "Место и деньги",
	["Espacios libres para el botín"] = "Свободные ячейки для добычи",
	["Espada de dos manos"] = "Двуручный меч",
	["Espada de una mano"] = "Одноручный меч",
	["Espalda"] = "Спина",
	["Español, inglés y siete idiomas más, en toda la interfaz."] = "Испанский, английский и еще семь языков во всем интерфейсе.",
	["Espera %s"] = "Подождите %s",
	["Espera a que el tanque tenga al enemigo bien agarrado antes de pegar fuerte."] = "Подождите, пока танк надежно удержит противника, прежде чем бить сильно.",
	["Espera a que termine el combate."] = "Ждем окончания боя.",
	["Espera a salir de combate para probarla."] = "Дождитесь выхода из боя, чтобы проверить.",
	["Espera a salir de combate."] = "Дождитесь выхода из боя.",
	["Espera a terminar de entrar al juego."] = "Дождитесь окончания входа в игру.",
	["Espera de unos %d min; va a %s"] = "Ждать около %d мин; идет в %s",
	["Espera unos segundos antes de buscar otra vez."] = "Подожди несколько секунд, прежде чем искать снова.",
	["Espera unos segundos antes de volver a poner tu anuncio."] = "Подожди несколько секунд, прежде чем снова размещать объявление.",
	["Espera · nivel %d"] = "Ждет · уровень %d",
	["Esperando"] = "Ожидание",
	["Esperando su respuesta"] = "Ждем ответа",
	["Espíritu"] = "Дух",
	["Esquiva"] = "Уклонение",
	["Esquivar"] = "Уклонение",
	["Esquivas casi todo unos segundos. Tu salvavidas cuando te pegan muchos."] = "Несколько секунд ты уклоняешься почти от всего. Спасение, когда бьют многие.",
	["Esquivas más cuerpo a cuerpo. Úsalo si el enemigo te alcanza."] = "Ты чаще уклоняешься в ближнем бою. Применяй, если враг до тебя добрался.",
	["Esta clase no tiene pesos de estadísticas en Alfa."] = "У этого класса нет весов характеристик в Alfa.",
	["Esta clase no tiene pesos de estadísticas."] = "У этого класса нет весов характеристик.",
	["Esta es Hoy"] = "Это «Сегодня»",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "Это объяснение больше не появится. Снова включить их можно в разделе «Бой».",
	["Esta guía no tiene un paso para ti ahora"] = "В этом руководстве сейчас нет шага для вас",
	["Esta guía no tiene un paso para ti ahora: puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "В этом гайде сейчас нет шага для тебя: возможно, ты пропустил остальное или ещё не время. Выбери другой гайд или вернись к этому позже.",
	["Esta misión va sola: no pide otra ni abre otra."] = "Это задание само по себе: не требует другого и не открывает другое.",
	["Esta semana llevas %s"] = "За эту неделю у тебя: %s",
	["Esta semana todavía no cazamos nada. ¿Salimos?"] = "На этой неделе мы ещё не охотились. Идём?",
	["Esta semana, entre %d lobos: %s"] = "На этой неделе, среди волков (%d): %s",
	["Esta sesión"] = "Этот сеанс",
	["Esta sesión, por recurso"] = "Этот сеанс, по ресурсам",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "Этот сеанс: улов %d за %d забросов. За все время: %d.",
	["Esta sesión: %s"] = "Этот сеанс: %s",
	["Esta sesión: +%s"] = "Этот сеанс: +%s",
	["Esta sesión: +%s · %s por hora"] = "Этот сеанс: +%s · %s в час",
	["Esta subasta no permite el escaneo completo."] = "Этот аукцион не позволяет полное сканирование.",
	["Esta va de %s y %s… ¿Te la cuento?"] = "Эта история про %s и %s… Рассказать?",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "Эта история про %s и про волков… она мне близка. Рассказать?",
	["Esta vez conviene el ángel."] = "На этот раз целитель душ — лучший выбор.",
	["Esta zona"] = "Эта зона",
	["Esta zona huele a aventura. ¿Tú qué hueles?"] = "Эта зона пахнет приключениями. А ты что чуешь?",
	["Establos"] = "Смотритель стойл",
	["Estadísticas"] = "Характеристики",
	["Estadísticas [pesca]"] = "Статистика",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "Это оповещение больше не будет показывать текст — только значок. Снова включить их можно в разделе «Бой».",
	["Este banco no vende más espacio."] = "Этот банк больше не продает место.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Этот билд бьет очень сильно, но держится недолго: хорошо выбирайте момент для атаки.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Этот щелчок ничего не делает. Назначьте ему действие в «Ваша мышь» на странице «Исцеление».",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "Этот клиент не загружает фрагменты мини-карты: показывается нарисованная карта.",
	["Este cliente no da el arte del mapa"] = "Этот клиент не дает изображения карты",
	["Este cliente no deja compartir"] = "Этот клиент не позволяет делиться",
	["Este cliente no deja compartir marcadores."] = "Этот клиент не позволяет делиться маркерами.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Этот клиент не может сам скопировать вашу схему: открылось окно заклинаний по щелчку Blizzard, чтобы вы настроили ее там.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "В этом клиенте нет некоторых из этих настроек (%d): они не показываются.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "В этом клиенте нет заклинаний по щелчку Blizzard. Ваши щелчки работают на рамках Alfa.",
	["Este paso"] = "Этот шаг",
	["Este paso es para cerrar tus misiones de %s. Cuando estés allá, «Llévame» te lleva a cada una."] = "Этот шаг нужен, чтобы завершить ваши задания (%s). Когда будете там, «Отведи меня» проведет к каждому.",
	["Este paso no tiene punto en el mapa."] = "У этого шага нет точки на карте.",
	["Este paso une el Bosque del Ocaso con el Pantano de las Penas, y casi todos lo cruzan sin detenerse."] = "Этот перевал соединяет Сумеречный лес с Болотом Печали, и почти все проходят его без остановки.",
	["Este talento no está en tu build."] = "Этого таланта нет в вашем билде.",
	["Este tramo quedó vacío."] = "Этот этап оказался пустым.",
	["Estilo"] = "Стиль",
	["Estilo de las barras"] = "Стиль панелей",
	["Estilo del chat"] = "Стиль чата",
	["Estilo del mapa"] = "Стиль карты",
	["Estilo del minimapa"] = "Стиль мини-карты",
	["Estilo y sonido"] = "Стиль и звук",
	["Esto está lleno de cazadores"] = "Здесь полно охотников",
	["Esto huele a historia grande. Pon atención."] = "Пахнет большой историей. Будь внимателен.",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Это нельзя изменить в бою. Попробуйте после окончания схватки.",
	["Esto no se puede vincular."] = "Это нельзя вставить ссылкой.",
	["Esto te sirve más en el banco o con otro de tus personajes (mándaselo por correo). Con un banquero, se guarda con un clic."] = "Это полезнее в банке или у другого твоего персонажа (отправь почтой). У банкира кладется одним щелчком.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Эти фильтры рисует Alfa, а не игра: они под всем интерфейсом (никогда его не закрывают) и видны даже со скрытым интерфейсом (Alt+Z) — для ваших скриншотов.",
	["Está en combate. Prueba en un momento."] = "Сейчас в бою. Попробуй чуть позже.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Находится на Кладбище. Накладывает теневую боль, которая наносит урон со временем.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Он в воде, у водопада: выманите его на сушу перед боем.",
	["Está en la %s, otro plano de tu zona."] = "Они в %s, другом слое твоей зоны.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Находится в Оружейной. Когда он кричит, то вращается с топором и бьет всех рядом: отойдите.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Находится в Библиотеке и приходит со своими псами: убейте их первыми или используйте атаки по области.",
	["Está en tu lista de compras."] = "Это в твоем списке покупок.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Спрятан в Соборе. Накладывает проклятия и лечит себя: прерывайте его.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "Здесь полно свинобразов и их колючих туннелей: выманивайте понемногу.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Его окружают гоблины-рабочие: сначала выманите этих гоблинов, по одному.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Его окружают мурлоки: выманите его приятелей раньше него.",
	["Están apagadas en tu lista de addons: %s. Sin ellas faltan páginas de Alfa."] = "Они выключены в списке аддонов: %s. Без них в Alfa не хватает страниц.",
	["Están encendidas pero el juego no las cargó: %s. Recarga; si siguen así, reinstala Alfa completo."] = "Они включены, но игра их не загрузила: %s. Перезагрузи; если так и останется, переустанови весь Alfa.",
	["Están por quitártelo"] = "Его вот-вот сорвут",
	["Estás aquí"] = "Вы здесь",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Вы у банкира: из его окна можно положить что угодно одним щелчком.",
	["Estás con un banquero: «Al banco» los deposita con un clic, o toca uno para guardar solo ese."] = "Ты у банкира: «В банк» кладет их одним щелчком, или нажми на один, чтобы убрать только его.",
	["Estás dentro"] = "Вы внутри",
	["Estás descansando"] = "Вы отдыхаете",
	["Estás en %s. %s Abajo tienes lo que más me preguntan de aquí."] = "Ты в: %s. %s Ниже — что меня здесь спрашивают чаще всего.",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Вы в бою. Таланты меняются только вне боя: закончите бой и попробуйте снова.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Вы в бою: ищите экипировку после окончания боя.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Вы в бою: изменения применятся после выхода из боя.",
	["Estás en combate: lo que cambies se aplica en cuanto termine."] = "Вы в бою: изменения применятся, как только он закончится.",
	["Estás en combate: se aplica en cuanto termine."] = "Вы в бою: применится, как только он закончится.",
	["Estás en combate: tus cambios se aplican en cuanto termine."] = "Вы в бою: ваши изменения применятся, как только он закончится.",
	["Estás en grupo y otro aguanta al enemigo: apuñálalo por la espalda."] = "Вы в группе, и противника держит другой: бейте его Ударом в спину.",
	["Estás en grupo y otro aguanta al enemigo: trízalo por la espalda."] = "Вы в группе, и противника держит другой: Полосните его со спины.",
	["Estás en la %s"] = "Ты в: %s",
	["Estás en la %s. Cómo está: %s."] = "Ты в %s. Обстановка: %s.",
	["Estás en la ciudad y hay habilidades por entrenar (%d). ¡Aprovecha!"] = "Ты в городе, и есть способности для изучения (%d). Не упусти!",
	["Estás en sigilo: Premeditación te da puntos de combo."] = "Вы в незаметности: Умысел дает очки серии.",
	["Estás en sigilo: abre con Emboscada por la espalda."] = "Вы в незаметности: начните с Внезапного удара со спины.",
	["Estás en sigilo: aturde al enemigo al abrir."] = "Вы в незаметности: оглушите противника в начале боя.",
	["Estás en una instancia: la flecha vuelve al salir."] = "Вы в подземелье: стрелка вернется, когда вы выйдете.",
	["Evento"] = "Событие",
	["Evita golpes críticos y aplastantes: lo más importante para un tanque."] = "Защищает от критических и сокрушительных ударов: самое важное для танка.",
	["Evitar misiones de grupo"] = "Избегать групповых заданий",
	["Experiencia"] = "Опыт",
