	["Faltan los datos del mundo de Alfa (la carpeta Alfa_Codex): instala todas las carpetas de Alfa."] = "Нет данных о мире Alfa (папка Alfa_Codex): установите все папки Alfa.",
	["Faltan precios"] = "Нет цен",
