	["Flechas: llevas %d (mejor %d o más)"] = "Стрелы: у тебя %d (лучше %d или больше)",
	["Flor de paz y Hojaplata son las primeras hierbas; las encuentras en las zonas de inicio."] = "Мироцвет и Сребролист — первые травы; они растут в стартовых зонах.",
	["Fogata"] = "Костер",
	["Fondo, pestañas y caja de escribir con tu estilo."] = "Фон, вкладки и поле ввода в вашем стиле.",
	["Fondos transparentes para ver el mundo detrás y el color de acento que elijas."] = "Прозрачный фон, сквозь который виден мир, и выбранный вами акцентный цвет.",
	["Forjaz está tallada dentro de la montaña: los enanos Barbabronce la construyeron alrededor de la Gran Forja."] = "Стальгорн высечен внутри горы: дворфы Бронзобороды построили его вокруг Великой Кузни.",
	["Forma"] = "Облик",
	["Forma felina para matar rápido y forma de oso para las peleas difíciles; casi nunca necesitas beber."] = "Облик кошки, чтобы быстро убивать, и облик медведя для трудных боев; пить почти никогда не нужно.",
	["Forma normal"] = "Обычный облик",
	["Foto: %s"] = "Снимок: %s",
	["Fragmento de alma"] = "Осколок души",
	["Fragmentos de alma"] = "Осколки души",
	["Frases dichas"] = "Сказанные фразы",
	["Frena a los que huyen y te deja escapar de una mala pelea."] = "Замедляет убегающих и позволяет вам выйти из неудачного боя.",
	["Frena a los que huyen y te salva de malas peleas."] = "Замедляет убегающих и спасает вас от неудачных боев.",
	["Frena a todos los rivales cercanos."] = "Замедляет всех противников рядом.",
	["Frondavil era parte del bosque de Vallefresno hasta que los demonios y sus sátiros lo corrompieron."] = "Оскверненный лес был частью Ясеневого леса, пока демоны и их сатиры не осквернили его.",
	["Frío"] = "Холодный",
	["Fuego"] = "Огонь",
	["Fuego en un área. Bueno contra grupos que no se mueven."] = "Огонь по области. Хорошо против групп, которые стоят на месте.",
	["Fuego en un área. Para grupos de enemigos."] = "Огонь по области. Для групп врагов.",
	["Fuego estelar: tu hechizo más fuerte."] = "Звездный огонь: ваше самое сильное заклинание.",
	["Fuego feérico: el enemigo recibe más daño."] = "Волшебный огонь: противник получает больше урона.",
	["Fuego interno"] = "Внутренний огонь",
	["Fuego para subir"] = "Огонь для прокачки",
	["Fuego rápido: disparas mucho más rápido un rato."] = "Быстрая стрельба: какое-то время вы стреляете намного быстрее.",
	["Fuego sagrado: abre la pelea con mucho daño."] = "Священный огонь: начните бой с большим уроном.",
	["Fuentes: Blizzard (news.blizzard.com), warcraft.wiki.gg (Legacy System), Icy Veins y Method. Lo que ves arriba con tus números sale del juego."] = "Источники: Blizzard (news.blizzard.com), warcraft.wiki.gg (Legacy System), Icy Veins и Method. То, что вы видите выше с вашими числами, берется из игры.",
	["Fuera de Cerrar mis misiones"] = "Убрано из «Закрыть мои задания»",
	["Fuera de combate es el mejor momento"] = "Вне боя — лучшее время",
	["Fuera de combate, tamaño, tecla, nombre, explicaciones, barrido y de dónde sale la sugerencia."] = "Вне боя, размер, клавиша, название, пояснения, затемнение и откуда берется подсказка.",
	["Fuera de combate; necesita las placas de enemigos encendidas."] = "Вне боя; нужны включенные индикаторы здоровья противников.",
	["Fuera de este plan: %s (%s)."] = "Вне этого плана: %s (%s).",
	["Fuera del plan"] = "Вне плана",
	["Fuerza"] = "Сила",
	["Fuerza del HDR"] = "Сила HDR",
	["Fuerza del tinte"] = "Сила оттенка",
	["Funciona también fuera del modo pesca. Está en el menú de atajos del juego, en Alfa."] = "Работает и вне режима рыбалки. Находится в меню назначения клавиш игры, в разделе Alfa.",
	["Funde lo que sacas en una forja: también sube Minería. Necesitas un pico de minero y encender el rastreo de minerales."] = "Переплавляй добытое в горне: это поднимает и горное дело. Нужна шахтерская кирка и включенный поиск минералов.",
	["Furia"] = "Неистовство",
	["Furia con dos armas"] = "Неистовство с двумя оружиями",
	["Furia con todo el daño posible: más precisión, Ejecutar mejorado y críticos enormes. Muy rápido matando, pero frágil."] = "Неистовство со всем возможным уроном: больше меткости, Улучшенная казнь и огромные критические удары. Убивает очень быстро, но хрупкое.",
	["Furia contra jugadores"] = "Неистовство для PvP",
	["Furia desatada"] = "Неистовство без оглядки",
	["Furia para grupo"] = "Неистовство для группы",
	["Furia para pelear contra jugadores: muchísimo daño, Ira rabiosa mejorada contra el miedo e Interceptar más seguido para no soltar al rival."] = "Неистовство для боя с игроками: очень много урона, Улучшенная ярость берсерка против страха и более частый Перехват, чтобы не отпускать противника.",
	["Furia sangrienta te da más ira para empezar peleas difíciles."] = "Кровавая ярость дает больше ярости, чтобы начинать трудные бои.",
	["Fíjate en lo que brilla en el suelo: ahí suele estar."] = "Смотри, что блестит на земле: обычно это оно.",
	["Gadgetzan es la ciudad goblin del desierto: ahí todo se compra y todo se vende, hasta el agua."] = "Прибамбасск — гоблинский город в пустыне: там все покупается и продается, даже вода.",
	["Gadgetzan tiene una de las casas de subastas neutrales, donde comercian Alianza y Horda."] = "В Прибамбасске один из нейтральных аукционов, где торгуют Альянс и Орда.",
	["Gana un poco de XP y Alfa calcula cuánto te falta."] = "Наберите немного опыта, и Alfa посчитает, сколько осталось.",
	["Gana un poco de XP y Alfa lo calcula"] = "Получите немного опыта, и Alfa посчитает",
	["Ganado"] = "Получено",
