	["Mascota"] = "Спутник",
	["Mascotas"] = "Питомцы",
	["Mascotas enemigas"] = "Питомцы противников",
	["Materiales"] = "Хозяйственные товары",
	["Mayús"] = "Shift",
	["Mayús + clic: ponerlo en el chat"] = "Shift + щелчок: вставить в чат",
	["Mayús+Espacio sigue saltando"] = "Shift+Пробел по-прежнему прыгает",
	["Maza de dos manos"] = "Двуручное дробящее оружие",
	["Maza de una mano"] = "Одноручное дробящее оружие",
	["Mazmorra"] = "Подземелье",
	["Mazmorra a la vista. Pelea al objetivo que marque tu grupo y todo sale mejor."] = "Подземелье впереди. Бей цель, которую отметит твоя группа, и все пойдет лучше.",
	["Mazmorra: %s"] = "Подземелье: %s",
	["Mazmorras"] = "Подземелья",
	["Mazmorras (3): derrotar al último jefe de todas las mazmorras de nivel 15-25, 26-45 y 46-60 (un punto por grupo)."] = "Подземелья (3): победить последнего босса всех подземелий 15–25, 26–45 и 46–60-го уровней (одно очко за группу).",
	["Mazmorras claras"] = "Понятные подземелья",
	["Mazmorras en el camino"] = "Подземелья по пути",
	["Mazmorras hechas"] = "Пройденные подземелья",
	["Mazmorras y bandas"] = "Подземелья и рейды",
	["Mazmorras: los avisos de jefes que tu juego sí trae ya no salen apagados."] = "Подземелья: предупреждения о боссах, которые есть в вашей игре, больше не отображаются выключенными.",
	["Mazthoril es la guarida de los dragones azules, siempre atentos a quién usa la magia."] = "Мазторил — логово синих драконов, которые всегда следят, кто пользуется магией.",
	["Mañana"] = "Завтра",
	["Me cuesta leer Alfa, ¿qué hago?"] = "Мне трудно читать Alfa, что делать?",
	["Me encanta cazar contigo. ¡Vamos por la siguiente!"] = "Обожаю охотиться с тобой. Вперед, за следующим!",
	["Me gusta cuidarte la espalda. Para eso estoy."] = "Мне нравится прикрывать тебе спину. Для этого я и здесь.",
	["Me gusta este paso tranquilo. Así se disfruta el camino."] = "Мне нравится этот спокойный темп. Так и надо наслаждаться дорогой.",
	["Me gusta ir contigo. Se nota que sabes lo que haces."] = "Мне нравится путешествовать с тобой. Видно, что ты знаешь, что делаешь.",
	["Me morí, ¿corro por mi cuerpo o voy con el ángel?"] = "Я погиб: бежать к телу или идти к целителю душ?",
	["Me quedo aquí sentadita contigo. Tres caídas no te hacen menos lobo. ¿Reparamos y pedimos ayuda?"] = "Я посижу тут с тобой. Три смерти не делают тебя меньше волком. Починимся и попросим помощи?",
	["Me salté la historia de una misión"] = "Я пропустил историю задания",
	["Media"] = "Среднее",
	["Medianos y graves"] = "Средние и серьезные",
	["Medias"] = "Средние",
	["Medidor de daño"] = "Измеритель урона",
	["Medio"] = "Средний",
	["Medivh era hijo de Aegwynn, la Guardiana anterior. Ella escondió en él el poder del Guardián sin saber que Sargeras también se escondía ahí."] = "Медив был сыном Эгвин, прежней Хранительницы. Она спрятала в нем силу Хранителя, не зная, что там же прячется и Саргерас.",
	["Medivh era hijo de Aegwynn, la Guardiana, y de Nielas Aran, un mago de la corte de Ventormenta."] = "Медив был сыном Эгвин, Хранительницы, и Ниеласа Арана, придворного мага Штормграда.",
	["Medivh murió a manos de Khadgar y Lothar, pero años después regresó como el misterioso profeta que llevó a Thrall a Kalimdor."] = "Медив погиб от рук Кадгара и Лотара, но годы спустя вернулся загадочным пророком, который привел Тралла в Калимдор.",
	["Medivh, poseído por Sargeras, abrió el camino para que la Horda llegara a Azeroth."] = "Медив, одержимый Саргерасом, открыл Орде путь в Азерот.",
	["Mejor %s"] = "Лучше %s",
	["Mejor a nivel %d · niveles %d a %d"] = "Лучше всего на %d ур. · уровни %d–%d",
	["Mejor con la manada: llámala y cacen juntos."] = "Лучше со стаей: позови их и охотьтесь вместе.",
	["Mejor no ir sin compañía: puede salir caro."] = "Лучше не идти одному: это может дорого обойтись.",
	["Mejor:"] = "Лучше:",
	["Mejora"] = "Совершенствование",
