	["Modo historia"] = "Режим истории",
	["Modo historia: %d jefes por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "Режим истории: боссов еще не открыто: %d. Победите каждого, чтобы увидеть имя и добычу (можно выключить в «Настройках»).",
	["Modo historia: 1 jefe por descubrir. Vence a cada uno para ver su nombre y su botín (puedes apagarlo en Ajustes)."] = "Режим истории: 1 босс еще не открыт. Победите каждого, чтобы увидеть имя и добычу (можно выключить в «Настройках»).",
	["Modo limpio"] = "Чистый режим",
	["Modo limpio apagado: tus capas volvieron como estaban."] = "Чистый режим выключен: ваши слои вернулись как были.",
	["Modo limpio encendido: solo tú, tu grupo, tus marcadores y la guía."] = "Чистый режим включен: только вы, ваша группа, ваши маркеры и гайд.",
	["Modo limpio: solo tú, tu grupo, tus marcadores y la guía"] = "Чистый режим: только вы, ваша группа, ваши маркеры и гайд",
	["Modo pesca abierto"] = "Режим рыбалки открыт",
