	["Monturas"] = "Транспорт",
	["Monturas y mascotas"] = "Транспорт и питомцы",
	["Mostrar Alfa"] = "Показать Alfa",
	["Mostrar a Lya"] = "Показать Lya",
	["Mostrar a quién apunta"] = "Показывать цель существа",
	["Mostrar el llavero"] = "Показывать связку ключей",
	["Mostrar el rango de tu hermandad"] = "Показывать звание в гильдии",
	["Mostrar en el mapa"] = "Показывать на карте",
	["Mostrar la ayuda de rotación"] = "Показывать помощника ротации",
	["Mostrar la barra en el modo pesca"] = "Показывать полосу в режиме рыбалки",
	["Mostrar la flecha"] = "Показать стрелку",
	["Mostrar la siguiente parada"] = "Показывать следующую остановку",
	["Mostrar la tecla"] = "Показывать клавишу",
	["Mostrar la ventana de guía"] = "Показать окно гайда",
	["Mostrar la ventana del medidor"] = "Показывать окно измерителя",
	["Mostrar menos en el seguimiento"] = "Показывать меньше в трекере",
	["Mostrar mi guía"] = "Показать мой гайд",
	["Mostrar más en el seguimiento"] = "Показывать больше в трекере",
	["Mostrar u ocultar la ventana de guía"] = "Показать или скрыть окно гайда",
	["Mostrarlo con Mayús"] = "Показывать с Shift",
	["Mover el ícono"] = "Передвинуть значок",
	["Mover marcos"] = "Передвинуть рамки",
	["Moviendo"] = "Перемещение",
	["Mucho daño con tu arma a distancia: disparos fuertes antes de que el monstruo llegue."] = "Много урона оружием дальнего боя: сильные выстрелы, пока монстр не добрался до вас.",
	["Mucho daño de sombra que va creciendo. Una maldición por enemigo."] = "Много урона от темной магии, который нарастает. Одно проклятие на врага.",
	["Mucho maná y hechizos arcanos potentes: el mago que menos descansa."] = "Много маны и мощные заклинания тайной магии: маг, которому меньше всех нужно отдыхать.",
	["Mucho tiempo sin verte, %s. Repasa tus misiones antes de salir."] = "Давно не виделись, %s. Просмотри задания перед выходом.",
	["Muchos"] = "Много",
	["Muchos enemigos duermen a un jugador: no es grave, el sueño se quita solo."] = "Многие противники усыпляют игрока: ничего страшного, сон проходит сам.",
	["Muchos: consejos del momento y de vez en cuando uno de Alfa. Pocos: menos seguido. Solo importantes: al morir, al subir de nivel y en tus logros."] = "Много: советы по ситуации и иногда совет об Alfa. Мало: реже. Только важные: при смерти, новом уровне и ваших достижениях.",
	["Muchísima amenaza en un golpe."] = "Очень много угрозы за один удар.",
	["Muelle de %s"] = "Причал: %s",
	["Muelles y torres de zepelín, con a dónde van."] = "Причалы и башни дирижаблей, с пунктами назначения.",
	["Muertes"] = "Смерти",
	["Muerto"] = "Мертв",
	["Muestra la ventana de guía y la flecha, y cierra esta ventana para que las veas."] = "Показывает окно гайда и стрелку и закрывает это окно, чтобы вы их видели.",
	["Muestra la vida en número, debajo del nombre."] = "Показывает здоровье числом под именем.",
	["Muestra lo que aún no exploras, con un tono más frío para distinguirlo."] = "Показывает неисследованное в более холодном оттенке, чтобы его можно было отличить.",
	["Muestra un aviso de ejemplo para que veas dónde sale."] = "Показывает пример оповещения, чтобы вы увидели, где оно появляется.",
	["Muestra un ícono encima del corcho: así sabes que tu tecla lo va a recoger."] = "Показывает значок над поплавком: так вы знаете, что ваша клавиша его вытащит.",
	["Mueve lo de Alfa con el ratón"] = "Двигай элементы Alfa мышью",
	["Mueve tus marcos"] = "Передвиньте рамки",
	["Mulgore de día: pasto hasta donde alcanza la vista y kodos pastando. Qué paz."] = "Мулгор днем: трава до горизонта и пасущиеся кодо. Такая тишь.",
	["Mundo"] = "Мир",
	["Munición"] = "Боеприпасы",
	["Muradin Barbabronce acompañó a Arthas a Rasganorte. Cuando Arthas tomó la espada, un trozo de hielo golpeó a Muradin y lo dieron por muerto."] = "Мурадин Бронзобород отправился с Артасом в Нордскол. Когда Артас взял меч, глыба льда ударила Мурадина, и его сочли погибшим.",
	["Muradin Barbabronce le enseñó a Arthas a pelear cuando el príncipe era joven."] = "Мурадин Бронзобород учил Артаса сражаться, когда принц был юн.",
	["Muro de escudo dura más."] = "Глухая оборона длится дольше.",
	["Muro de escudo dura más: te salva en los jefes."] = "Глухая оборона длится дольше: спасает в боях с боссами.",
	["Muy grande"] = "Очень крупный",
	["Muy peligroso para tu nivel: mejor con grupo o rodéalo."] = "Очень опасно для твоего уровня: лучше с группой или обойди.",
	["Muy pronto"] = "Скоро",
	["Muéstrala u ocúltala. También con su tecla o con /alfa guia."] = "Показать или скрыть его. Также своей клавишей или командой /alfa guia.",
	["Muévete a las zonas de nivel 10 a 20. Las lombrices ayudan a que no se escapen. Pide el rango Experto desde 125."] = "Переходите в зоны 10–20-го уровня. Черви помогают, чтобы рыба не срывалась. Ступень «Умелец» — с 125.",
	["Muñecas"] = "Запястья",
	["Márcala cuando la hagas"] = "Отметьте, когда сделаете",
	["Márcalo con la calavera y todo tu grupo lo verá."] = "Отметь его черепом, и вся группа его увидит.",
	["Más"] = "Еще",
	["Más Abrumar gracias a Desgarrar."] = "Больше Превосходства благодаря Кровопусканию.",
	["Más Golpes heroicos: más daño por pelea."] = "Больше Ударов героя: больше урона за бой.",
	["Más adelante"] = "Позже",
	["Más adelante eliges entre ingeniería gnómica y goblin: los inventos gnómicos fallan a veces de forma muy graciosa, y los goblin explotan más."] = "Позже ты выбираешь гномскую или гоблинскую инженерию: гномские устройства иногда ломаются очень смешно, а гоблинские чаще взрываются.",
	["Más adelante eliges especialidad: de escamas de dragón, elemental o tribal."] = "Позже ты выбираешь специализацию: кожевничество чешуи драконов, стихий или традиций племен.",
	["Más adelante eliges especialidad: forjador de armaduras o armero, y los armeros, entre espadas, mazas y hachas."] = "Позже ты выбираешь специализацию: бронник или оружейник, а оружейники — мечи, молоты или топоры.",
	["Más adelante: %s."] = "Позже: %s.",
	["Más aguante para ti y tus amigos. Dásela a todo el grupo antes de empezar."] = "Больше выносливости тебе и друзьям. Дай ее всей группе перед началом.",
	["Más aguante y seguridad. Matas un poco más lento, pero casi no mueres."] = "Больше выносливости и безопасности. Вы убиваете чуть медленнее, но почти не умираете.",
	["Más alto, atraviesa objetos más grandes antes de acercarse."] = "Чем выше, тем более крупные объекты камера проходит насквозь, прежде чем приблизиться.",
	["Más alto, los objetos lejanos tardan más en desaparecer."] = "Чем выше, тем дольше дальние объекты не исчезают.",
	["Más alto, más nítido. Demasiado puede marcar bordes y brillos."] = "Чем выше, тем четче. Слишком много — и края с бликами станут резкими.",
	["Más alto, ves más a los lados."] = "Чем выше, тем больше видно по сторонам.",
	["Más amenaza."] = "Больше угрозы.",
	["Más amenaza: los monstruos se quedan contigo."] = "Больше угрозы: монстры остаются на вас.",
	["Más armadura para ti y tu grupo cercano. Una buena aura para empezar."] = "Больше брони тебе и группе рядом. Хорошая аура для начала.",
	["Más armadura y más poder. Mantenlo siempre puesto."] = "Больше брони и силы. Держи постоянно.",
	["Más armadura y regeneras vida. Mantenla siempre puesta."] = "Больше брони и восстановления здоровья. Держи постоянно.",
	["Más armadura, atributos y resistencias. Dásela a todo el grupo."] = "Больше брони, характеристик и сопротивлений. Дай всей группе.",
	["Más baja, la niebla se ve más ligera y cuesta menos."] = "Чем ниже, тем легче туман и тем меньше нагрузка.",
	["Más bajo, se siguen viendo objetos pequeños a lo lejos."] = "Чем ниже, тем дольше видны мелкие объекты вдали.",
	["Más cerca de tu paso"] = "Ближе всего к твоему шагу",
	["Más consejos"] = "Больше советов",
	["Más crítico en Abrumar, ideal contra pícaros que esquivan."] = "Больше шанса критического удара для Превосходства, идеально против уклоняющихся разбойников.",
	["Más crítico."] = "Больше критических ударов.",
	["Más daño con dos manos."] = "Больше урона двуручным оружием.",
	["Más daño con el tiempo."] = "Больше периодического урона.",
	["Más daño con escudo."] = "Больше урона со щитом.",
	["Más daño con escudo: lo que hace que Protección suba bien."] = "Больше урона со щитом: благодаря этому Защита хорошо качается.",
	["Más daño con tu arma de dos manos, que es la que usas."] = "Больше урона вашим двуручным оружием, которым вы и пользуетесь.",
	["Más daño con tu arma de dos manos."] = "Больше урона вашим двуручным оружием.",
	["Más daño de sangrado; abre Heridas profundas."] = "Больше урона от кровотечения; открывает Глубокие раны.",
	["Más daño mientras llevas escudo."] = "Больше урона, пока у вас щит.",
	["Más daño y más riesgo. Matas rápido, pero un error se paga caro."] = "Больше урона и больше риска. Вы быстро убиваете, но за ошибку придется дорого заплатить.",
	["Más de 40 arreglos: combate y curación en mazmorras, el buzón cuenta bien tu dinero y la placa de llegada se va sola."] = "Больше 40 исправлений: бой и лечение в подземельях, почта правильно считает твои деньги, а табличка прибытия исчезает сама.",
	["Más de mi gente"] = "Еще о моем народе",
	["Más defensa desde el principio."] = "Больше защиты с самого начала.",
	["Más defensa: te golpean y te hacen crítico menos seguido."] = "Больше защиты: по вам реже попадают и реже наносят критические удары.",
	["Más defensa: te hacen menos críticos."] = "Больше защиты: по вам реже проходят критические удары.",
	["Más detalle al acercar el mapa"] = "Больше деталей при приближении карты",
	["Más distancia, sombras finas y agua con reflejos."] = "Больше дальность, тонкие тени и вода с отражениями.",
	["Más en Calidad de vida"] = "Еще в разделе «Удобство»",
	["Más espacio en el banco"] = "Больше места в банке",
	["Más firme y en tu idioma"] = "Надёжнее и на вашем языке",
	["Más fuerza para ti y tu grupo cercano."] = "Больше силы тебе и группе рядом.",
	["Más golpe crítico para todo lo que haces."] = "Больше шанса критического удара для всего, что вы делаете.",
	["Más golpe crítico, que también te da más ira."] = "Больше шанса критического удара, что дает и больше ярости.",
	["Más golpe crítico."] = "Больше шанса критического удара.",
	["Más golpes bloqueados con el escudo, y cada bloqueo te da ira."] = "Больше ударов блокируется щитом, и каждый блок дает ярость.",
	["Más golpes críticos, pero recibes más daño. La postura para hacer daño."] = "Больше критических ударов, но ты получаешь больше урона. Стойка для нанесения урона.",
	["Más guías"] = "Еще гайды",
	["Más intelecto para ti y tus amigos. Dáselo al grupo antes de empezar."] = "Больше интеллекта тебе и друзьям. Дай группе перед началом.",
	["Más ira al cargar."] = "Больше ярости от Рывка.",
	["Más ira al cargar: tu primer golpe llega antes."] = "Больше ярости от Рывка: первый удар приходит раньше.",
	["Más ira al empezar la pelea."] = "Больше ярости в начале боя.",
	["Más ira al empezar."] = "Больше ярости в начале.",
	["Más ira por cada golpe, sobre todo con armas rápidas."] = "Больше ярости за каждый удар, особенно с быстрым оружием.",
	["Más ira por cada golpe: más Golpe heroico y Golpe mortal."] = "Больше ярости за каждый удар: больше Ударов героя и Смертельных ударов.",
	["Más ira por golpe."] = "Больше ярости за удар.",
	["Más ira por golpe: más habilidades seguidas."] = "Больше ярости за удар: больше способностей подряд.",
	["Más lugares"] = "Другие места",
	["Más maná con el tiempo. Ideal para quien cura y para ti."] = "Больше маны со временем. Отлично для лекарей и для тебя.",
	["Más maná y algo de crítico con hechizos."] = "Больше маны и немного шанса критического эффекта заклинаний.",
	["Más opciones"] = "Другие настройки",
	["Más opciones de Mundo"] = "Другие настройки мира",
	["Más opciones de apariencia"] = "Больше настроек внешнего вида",
	["Más opciones del ícono"] = "Другие настройки значка",
	["Más para tu personaje"] = "Еще для вашего персонажа",
	["Más pasto"] = "Больше травы",
	["Más pasto, más horizonte, niebla ligera y rayos de sol, sin pedirle de más a tu PC. Se deshace en Mundo > Paisaje y gráficos (o /alfa paisaje)."] = "Больше травы, дальше горизонт, легкий туман и солнечные лучи — без лишней нагрузки на ПК. Отменить можно в Мир > Пейзаж и графика (или /alfa paisaje).",
	["Más pasto, más horizonte, niebla ligera y rayos de sol. Bonito sin pedir de más."] = "Больше травы, дальше горизонт, легкий туман и солнечные лучи. Красиво без лишней нагрузки.",
	["Más poder de ataque a distancia. El aspecto para pelear."] = "Больше силы атаки дальнего боя. Дух для боя.",
	["Más poder de ataque para tu grupo."] = "Больше силы атаки для вашей группы.",
	["Más poder de ataque por varios minutos. Dásela a los que pelean cuerpo a cuerpo."] = "Больше силы атаки на несколько минут. Дай друзьям ближнего боя.",
	["Más sangrado; abre Heridas profundas."] = "Больше кровотечения; открывает Глубокие раны.",
	["Más velocidad de ataque: mantenlo puesto."] = "Выше скорость атаки: поддерживайте эффект.",
	["Más vida: aguantas más golpes antes de tener que comer o descansar."] = "Больше здоровья: вы выдерживаете больше ударов, прежде чем придется есть или отдыхать.",
	["Mínimas"] = "Минимальные",
	["Mínimo"] = "Минимум",
	["Módulos activados"] = "Модули включены",
	["Músculos"] = "Мускулы",
	["Música mientras pescas"] = "Музыка во время рыбалки",
	["Nada"] = "Нет",
	["Nada coincide"] = "Ничего не найдено",
	["Nada con ese nombre"] = "Ничего с таким названием",
	["Nada con ese nombre."] = "Ничего с таким названием.",
	["Nada de esto le sirve a tu clase"] = "Ничего из этого не подходит вашему классу",
	["Nada en este grupo"] = "В этой группе ничего нет",
	["Nada nuevo"] = "Ничего нового",
	["Nada nuevo por aprender"] = "Нечего изучать",
	["Nada nuevo por aprender."] = "Нечего изучать.",
	["Nada por aquí"] = "Здесь ничего нет",
	["Nada por regalar por ahora."] = "Пока нечего дарить.",
	["Nada que acomodar aquí: abre un comerciante para vender tu chatarra o habla con un banquero para guardar tus materiales."] = "Здесь нечего разбирать: открой торговца, чтобы продать хлам, или поговори с банкиром, чтобы сложить материалы.",
	["Nada que aplicar"] = "Нечего применять",
	["Nada que entregar todavía"] = "Пока нечего сдавать",
	["Nada que recoger"] = "Нечего брать",
	["Nada que reparar"] = "Нечего чинить",
	["Nada que soltar"] = "Не от чего отказаться",
	["Nada que vender por ahora: lo que llevas sirve o vale más guardado."] = "Пока нечего продать: то, что у вас есть, полезно или выгоднее хранить.",
	["Nada: todo esto lo haces tú."] = "Ничего: все это вы делаете сами.",
	["Nadie a la vista tiene ubicación ahora: en una instancia o desconectados. Cuando vuelvan al mundo, aparecen aquí y en tu mapa."] = "Сейчас ни у кого в поле зрения нет местоположения: они в подземелье или не в сети. Когда вернутся в мир, появятся здесь и на карте.",
	["Nadie abrió la puerta"] = "Никто не открыл",
	["Nadie busca grupo ahora. ¡Pon tu anuncio!"] = "Сейчас никто не ищет группу. Размести свое объявление!",
	["Nadie de la manada a la vista"] = "Никого из стаи в поле зрения",
	["Nadie de la manada anda en otra guarida de esta zona ahora."] = "Сейчас никого из стаи нет в другом логове этой зоны.",
	["Nadie de la manada anda en otro plano"] = "Никого из стаи нет в другом слое",
	["Nadie de la manada dijo tener «%s» (todavía)."] = "Никто в стае (пока) не сказал, что у него есть «%s».",
	["Nadie de la manada respondió desde otro plano. Prueba en un rato o pídelo en el Discord de La Jauría."] = "Никто из стаи в другом слое не ответил. Попробуй позже или спроси в Discord La Jauría.",
	["Nadie para adoptar por ahora: los lobos salen aquí cuando la manada los ve."] = "Пока некого опекать: волки появляются здесь, когда их видит стая.",
	["Nadie respondió desde la %s. Prueba en un rato o pídelo en el Discord de La Jauría."] = "Никто не ответил из: %s. Попробуй позже или спроси в Discord La Jauría.",
	["Nadie tiene esa guarida abierta ahora."] = "Сейчас ни у кого это логово не открыто.",
	["Naranja"] = "Оранжевый",
	["Nat Pagle, el pescador legendario, vive en una isla del Marjal Revolcafango."] = "Нат Пэгл, легендарный рыбак, живет на острове в Пылевых топях.",
	["Nat Pagle, el pescador más famoso, vive en una isla del marjal; sus misiones son para pescadores pacientes."] = "Нат Пэгл, самый известный рыбак, живет на острове в топях; его задания — для терпеливых рыболовов.",
	["Nat Pagle, en el Marjal Revolcafango, te pide cuatro peces raros: con su misión aprendes el rango Artesano."] = "Нат Пэгл в Пылевых топях просит четыре редкие рыбы: его задание обучает ступени «Искусник».",
	["Naxxramas, la necrópolis de Kel'Thuzad, flota sobre estas tierras como una sombra."] = "Наксрамас, некрополь Кел'Тузада, парит над этими землями, словно тень.",
	["Necesita la base de misiones (página Misiones)."] = "Нужна база заданий (страница «Задания»).",
	["Necesita las rutas a pie de Alfa (Alfa_Nav), que se cargan solas con «Seguir caminos reales» encendido."] = "Нужны пешие маршруты Alfa (Alfa_Nav), которые загружаются сами при включенном «Идти по реальным дорогам».",
	["Necesita un monitor HDR"] = "Нужен монитор с HDR",
	["Necesitas %s"] = "Нужно: %s",
	["Necesitas %s con %s"] = "Нужно: %s с %s",
	["Necesitas %s para esta cadena: apréndela con un instructor."] = "Для этой цепочки нужно %s: изучите у учителя.",
	["Necesitas %s para juntarlo: apréndela con un instructor de profesiones."] = "Чтобы это собирать, нужна профессия %s: изучите ее у учителя профессии.",
	["Necesitas al menos 2 misiones listas para entregar."] = "Нужно хотя бы 2 готовых задания, чтобы сдать.",
	["Necesitas una hermandad: el tablón es de los lobos de la tuya."] = "Нужна гильдия: доска — для волков твоей гильдии.",
	["Necesitas una hermandad: «¿Quién tiene...?» pregunta a los lobos de la tuya."] = "Нужна гильдия: «У кого есть...?» спрашивает волков твоей гильдии.",
	["Neltharion, el Guardián de la Tierra, escuchó los susurros de los dioses antiguos y se convirtió en Alamuerte."] = "Нелтарион, Хранитель Земли, прислушался к шепоту Древних богов и стал Смертокрылом.",
	["Ner'zhul abrió varios portales en Draenor y la magia desgarró el planeta. Lo que quedó flota en la nada y se llama Terrallende."] = "Нер'зул открыл на Дреноре несколько порталов, и магия разорвала планету. То, что осталось, парит в пустоте и зовется Запредельем.",
	["Nethergarde es un bastión de magos de la Alianza que vigila el Portal Oscuro, por si algo vuelve a cruzar."] = "Крепость Стражей Пустоты — оплот магов Альянса, следящих за Темным порталом на случай, если через него снова что-то пройдет.",
	["Ni uno se escapa"] = "Ни одна не уйдет",
	["Niebla"] = "Туман",
	["Niebla en interiores"] = "Туман в помещениях",
	["Niebla volumétrica"] = "Объемный туман",
	["Nieve"] = "Снег",
	["Ninguna de tus recetas deja ganancia con los precios que tienes."] = "При текущих ценах ни один ваш рецепт не приносит прибыли.",
	["Ninguna guía cumple estos filtros. Quita alguno para ver más."] = "Нет гайдов под эти фильтры. Уберите какой-нибудь, чтобы увидеть больше.",
	["Ninguna receta deja ganancia"] = "Ни один рецепт не приносит прибыли",
	["Ninguno"] = "Нет",
	["Ninguno coincide"] = "Совпадений нет",
	["Ninguno conocido para tu facción"] = "Для вашей фракции ничего не известно",
	["Ninguno de tus personajes lleva algo así."] = "Ни у одного твоего персонажа нет ничего такого.",
	["Ninguno por ahora"] = "Пока нет",
	["Ninguno puesto"] = "Не поставлены",
	["Ninguno: todo en orden."] = "Нет: все хорошо.",
	["Ningún lobo de tu zona tiene su guarida abierta en otro plano. ¿Le pregunto a la manada si alguien te abre la suya?"] = "Ни у одного волка в твоей зоне нет открытого логова в другом слое. Спросить стаю, не откроет ли кто-нибудь свое?",
	["Ningún lobo dice su guarida ahora."] = "Сейчас ни один волк не сообщает свое логово.",
	["Ningún oficial respondió ahora. %s"] = "Сейчас ни один офицер не ответил. %s",
	["Ningún raro cazado en las últimas horas."] = "За последние часы редких не убивали.",
	["Nitidez"] = "Резкость",
	["Niv. %d"] = "Ур. %d",
	["Nivel"] = "Уровень",
	["Nivel %d"] = "Уровень %d",
	["Nivel %d: %d hechizos nuevos para aprender"] = "Уровень %d: новых заклинаний для изучения: %d",
	["Nivel %d: %s"] = "Уровень %d: %s",
	["Nivel %d: un hechizo nuevo para aprender"] = "Уровень %d: новое заклинание для изучения",
	["Nivel %d–%d"] = "Уровень %d–%d",
	["Nivel %s"] = "Уровень %s",
	["Nivel %s de %d"] = "Уровень %s из %d",
	["Nivel 40, el oro, tu entrenador de equitación y aprender a montar."] = "40-й уровень, золото, учитель верховой езды и обучение езде.",
	["Nivel de objeto"] = "Уровень предмета",
	["Nivel de objeto %d"] = "Уровень предмета %d",
	["Nivel máximo"] = "Максимальный уровень",
	["Niveles"] = "Уровни",
	["Niveles %d a %d: %s"] = "Уровни %d–%d: %s",
	["Niveles %d–%d"] = "Уровни %d–%d",
	["Niveles %s"] = "Уровни %s",
	["Niveles %s, en %s."] = "Уровни %s, %s.",
	["Niveles arriba del tuyo"] = "Уровней выше вашего",
	["Niveles de zona"] = "Уровни зон",
	["Niveles, misiones, raros, mazmorras y servicios de cada zona."] = "Уровни, задания, редкие, подземелья и услуги каждой зоны.",
	["No"] = "Нет",
	["No [apagado]"] = "Выкл.",
	["No armé el circuito"] = "Обход не получился",
	["No armé el plan"] = "Я не составил план",
	["No armé la guía"] = "Я не составил гайд",
	["No armé tu ruta"] = "Я не составил ваш маршрут",
	["No busca apagar tu cerebro ni jugar por ti: busca que entiendas y disfrutes un juego de hace años, a tu ritmo."] = "Он не пытается отключить вам голову или играть за вас: он помогает понять игру многолетней давности и наслаждаться ею в своем темпе.",
	["No cambiar: %s"] = "Не менять: %s",
	["No conozco ese lugar. Prueba: vuelo, posada, reparar, banco, buzón, subasta, entrenador, oficio, vendedor, comida, componentes o establo."] = "Я не знаю такого места. Попробуйте: vuelo, posada, reparar, banco, buzón, subasta, entrenador, oficio, vendedor, comida, componentes или establo (полет, таверна, ремонт, банк, почта, аукцион, учитель, профессия, торговец, еда, реагенты, стойла).",
	["No conozco ese preajuste."] = "Я не знаю такого набора.",
	["No conozco la entrada de esta mazmorra"] = "Я не знаю, где вход в это подземелье",
	["No conozco la profesión «%s»."] = "Я не знаю профессию «%s».",
	["No conozco ningún lugar de «%s» para tu facción."] = "Я не знаю ни одного места «%s» для вашей фракции.",
	["No cupieron %d: el banco está lleno. Compra otra casilla o pon una bolsa más grande."] = "Не поместилось: %d. Банк заполнен. Купите еще ячейку или положите сумку побольше.",
	["No disponible"] = "Недоступно",
	["No disponible: %s"] = "Недоступно: %s",
	["No encontramos a \"%s\" en tu grupo ni entre quienes comparten su ubicación."] = "Не удалось найти «%s» ни в вашей группе, ни среди тех, кто делится местоположением.",
	["No encontramos nada"] = "Ничего не найдено",
	["No encontré cómo llegar a esa misión."] = "Не нашел, как добраться до этого задания.",
	["No encontré ese lugar"] = "Не нашла такое место",
	["No encontré habilidades de %s que ya sepas. Arrástralas desde tu libro de hechizos con la forma puesta."] = "Известных вам способностей для «%s» не найдено. Перетащите их из книги заклинаний, находясь в этом облике.",
	["No encontré misiones de clase para ti ahora."] = "Сейчас классовых заданий для вас не найдено.",
	["No encontré una mazmorra llamada «%s»."] = "Подземелье «%s» не найдено.",
	["No entregué %s: pide materiales de oficio. Entrégala tú si quieres."] = "Не сдано: %s — требует материалы для профессий. Сдайте сами, если хотите.",
	["No entregué %s: pide oro o monedas. Entrégala tú si quieres."] = "Не сдано: %s — требует золото или валюту. Сдайте сами, если хотите.",
	["No es para ti"] = "Не для вас",
	["No es para tu clase"] = "Не для вашего класса",
	["No es para tu raza"] = "Не для вашей расы",
	["No está al salir Forever. Cuando llegue, lo que ganes ahí cuenta en los otros modos, pero no al revés, y los retos de JcJ no se pueden hacer ahí."] = "На запуске Forever его нет. Когда появится, заработанное там будет засчитываться в других режимах, но не наоборот, а испытания PvP там выполнить нельзя.",
	["No está en tu árbol"] = "Нет в вашем дереве",
	["No están en tu árbol y se saltan: %s."] = "Нет в вашем дереве, пропущены: %s.",
	["No estás siguiendo a nadie."] = "Вы ни за кем не следуете.",
	["No gastes todo en equipo: aprender a montar a nivel 40 es la mejor inversión del camino."] = "Не трать все на экипировку: научиться верховой езде на 40-м уровне — лучшее вложение в пути.",
	["No había explicaciones calladas: ya salen todas."] = "Скрытых пояснений не было: показываются все.",
	["No había nada que tomar."] = "Забирать было нечего.",
	["No hay bancos de peces conocidos en esta zona: aquí se pesca en aguas abiertas."] = "В этой зоне нет известных косяков рыбы: здесь ловят в открытой воде.",
	["No hay citas por ahora. ¡Propón la primera!"] = "Сборов пока нет. Предложи первый!",
	["No hay guías así"] = "Таких гайдов нет",
	["No hay misiones para ti cerca de aquí. Prueba en el pueblo más cercano o sigue tu ruta."] = "Рядом нет заданий для вас. Попробуйте ближайшее поселение или идите по маршруту.",
	["No hay misiones para ti en esta zona."] = "В этой зоне для тебя нет заданий.",
	["No hay misiones que convenga dejar"] = "Нет заданий, от которых стоит отказаться",
	["No hay misiones que puedas tomar ahora: te llevo a la entrada."] = "Сейчас нет заданий, которые можно взять: веду ко входу.",
	["No hay nada que comprar: o ya tienes todo lo del plan hasta tu nivel, o no tienes puntos libres."] = "Изучать нечего: либо у вас уже есть все из плана до вашего уровня, либо нет свободных очков.",
	["No hay nodos conocidos en esta zona."] = "В этой зоне нет известных узлов.",
	["No hay prisa: el camino también se disfruta."] = "Спешить некуда: дорогой тоже стоит наслаждаться.",
	["No hay un build exacto para %s y %s: este es el que más se parece."] = "Точного билда для «%s» и «%s» нет: этот ближе всего.",
	["No hay un camino que Alfa pueda guiar para esto."] = "Для этого нет пути, по которому Alfa может провести.",
	["No ignores los objetos verdes: si no te sirven, desencántalos o súbelos a la subasta."] = "Не пренебрегай зелеными предметами: если они тебе не нужны, распыли их или выставь на аукцион.",
	["No la agregué"] = "Я его не добавил",
	["No la usas"] = "Не используются",
	["No llevas chatarra para vender."] = "У вас нет хлама на продажу.",
	["No llevas juguetes ni consumibles de pesca. Lo que tenga que ver con pescar aparece aquí solo."] = "У вас нет рыболовных игрушек и расходников. Все, что связано с рыбалкой, появится здесь само.",
	["No llevas nada de pesca. Compra una caña con un vendedor de suministros de pesca: la guía te dice dónde."] = "У вас нет ничего для рыбалки. Купите удочку у торговца рыболовными принадлежностями: гайд подскажет где.",
	["No llevas nada para depositar con esa opción."] = "При этом варианте класть нечего.",
	["No llevas nada puesto que guardar."] = "На тебе нет ничего, что можно сохранить.",
	["No llevas nada que convenga vender: guarda algo en el banco."] = "Нечего выгодно продать: положите что-нибудь в банк.",
	["No llevas nada que depositar"] = "Нечего положить",
	["No llevas vendas"] = "У тебя нет бинтов",
	["No lo puedes usar todavía"] = "Пока нельзя использовать",
	["No mostrar"] = "Не показывать",
	["No muestra los ataques que todavía tardan mucho: la barra queda más limpia."] = "Не показывает атаки, до которых еще долго: шкала становится чище.",
	["No muestra los ataques que ya deberían haber llegado y esperan su momento."] = "Не показывает атаки, которые уже должны были начаться и ждут своего момента.",
	["No pegaste nada."] = "Вы ничего не вставили.",
	["No pude armar esa guía"] = "Не удалось составить этот гайд",
	["No pude armar la ruta"] = "Не удалось составить маршрут",
	["No pude buscar ahora: inténtalo al salir de combate."] = "Сейчас не удалось выполнить поиск: попробуйте после боя.",
	["No pude cargar los datos del mundo de Alfa (%s)."] = "Не удалось загрузить данные о мире Alfa (%s).",
	["No pude guardar esa meta: revisa lo que escribiste."] = "Не удалось сохранить цель: проверьте, что вы ввели.",
	["No pude leer dónde estás."] = "Не удалось определить, где вы.",
	["No pude leer los datos del mundo de Alfa: vuelve a instalar Alfa."] = "Не удалось прочитать данные о мире Alfa: переустановите Alfa.",
	["No pude poner la flecha ahí."] = "Не удалось направить туда стрелку.",
	["No pude poner la flecha ahí. Inténtalo otra vez en un momento."] = "Не удалось направить туда стрелку. Попробуйте еще раз через минуту.",
	["No pude preparar la ruta"] = "Не удалось подготовить маршрут",
	["No pudimos unirnos al canal de la manada"] = "Не удалось подключиться к каналу стаи",
	["No pueden: %s"] = "Не могут: %s",
	["No puedo"] = "Не могу",
	["No quedan puntos libres."] = "Свободных очков не осталось.",
	["No resaltarlo"] = "Не подсвечивать",
	["No sabemos dónde está %s. Solo se puede seguir a tu grupo y a quien comparte su ubicación con Alfa."] = "Неизвестно, где находится %s. Следовать можно только за своей группой и за теми, кто делится местоположением через Alfa.",
	["No se aplicaron los talentos"] = "Таланты не применены",
	["No se conoce de dónde sale."] = "Источник неизвестен.",
	["No se conoce ningún Alfa más reciente. La app de CurseForge o la página de versiones lo dicen con seguridad."] = "Более новая версия Alfa неизвестна. Точно скажут приложение CurseForge или страница релизов.",
	["No se conoce su botín"] = "Добыча неизвестна",
	["No se encontró el chat."] = "Чат не найден.",
	["No se encontró la carpeta Alfa_Codex. Reinstala Alfa completo."] = "Папка Alfa_Codex не найдена. Переустановите Alfa полностью.",
	["No se encontró nada mejor cerca de tu nivel. Vuelve a buscar al subir unos niveles."] = "Ничего лучше рядом с вашим уровнем не найдено. Поищите снова через несколько уровней.",
	["No se pudieron leer los datos del juego."] = "Не удалось прочитать данные игры.",
	["No se pudo"] = "Не удалось",
	["No se pudo abrir el Codex de Alfa (la base de objetos). Revisa que el addon Alfa Codex esté activado."] = "Не удалось открыть Codex Alfa (базу предметов). Проверьте, что аддон Alfa Codex включен.",
	["No se pudo armar la guía (%s)."] = "Не удалось составить гайд (%s).",
	["No se pudo armar la guía."] = "Не удалось составить гайд.",
	["No se pudo buscar el lugar más cercano."] = "Не удалось найти ближайшее место.",
	["No se pudo comprar: %s"] = "Не удалось изучить: %s",
	["No se pudo enviar la invitación a %s. Prueba desde la ventana de Hermandad y comunidades."] = "Не удалось отправить приглашение игроку %s. Попробуйте через окно «Гильдия и сообщества».",
	["No se pudo importar"] = "Не удалось импортировать",
	["No se pudo leer el escaneo. Intenta de nuevo más tarde."] = "Не удалось прочитать сканирование. Попробуйте позже.",
	["No se pudo marcar: falta el motor de Alfa."] = "Не удалось отметить: нет движка Alfa.",
	["No se pudo mostrar el banco del juego para comprar la casilla."] = "Не удалось показать банк игры для покупки ячейки.",
	["No se pudo probar ahora"] = "Сейчас проверить не удалось",
	["No se pudo restaurar"] = "Не удалось восстановить",
	["No se puede dibujar el mapa continuo. El mapa del juego sigue funcionando con todas las capas de Alfa."] = "Не удается нарисовать сплошную карту. Карта игры по-прежнему работает со всеми слоями Alfa.",
	["No se puede en combate."] = "Нельзя в бою.",
	["No se puede ordenar en combate."] = "В бою сортировать нельзя.",
	["No se puede vender."] = "Нельзя продать.",
	["No se pueden cambiar bolsas en combate."] = "В бою нельзя менять сумки.",
	["No se sabe en qué lugar está."] = "Местоположение неизвестно.",
	["No se ve en pantalla. Tráela de vuelta cuando quieras (también con /alfa lya)."] = "Ее не видно на экране. Верните ее когда угодно (также командой /alfa lya).",
	["No siempre aparece en la mina: si lo ves, es un jefe más con buen botín."] = "В шахте появляется не всегда: если увидите его, это дополнительный босс с хорошей добычей.",
	["No siempre aparece. Pone un dolor de sombras: cura a quien lo tenga."] = "Появляется не всегда. Накладывает теневую боль: лечите того, на ком она.",
	["No sigues ninguna guía"] = "Вы не следуете никакому гайду",
	["No son para ti"] = "Не для вас",
	["No sé de dónde sale este objeto."] = "Не знаю, откуда берется этот предмет.",
	["No sé de eso todavía. Prueba con otra palabra, o pregúntale a la manada en el Discord."] = "Об этом я пока не знаю. Попробуй другое слово или спроси стаю в Discord.",
	["No sé dónde se entrega"] = "Неизвестно, где сдать",
	["No sé dónde se entrega %s: la saqué de la ruta."] = "Неизвестно, где сдавать %s: задание убрано из маршрута.",
	["No sé dónde se entrega %s: la saqué del plan."] = "Не знаю, где сдается %s: убрал из плана.",
	["No sé dónde se junta este material."] = "Неизвестно, где собирать этот материал.",
	["No sé dónde se junta: búscalo en la Enciclopedia para ver de dónde sale."] = "Не знаю, где это собирают: найдите в «Энциклопедии», откуда оно берется.",
	["No sé en qué zona estás."] = "Не удалось определить вашу зону.",
	["No sé qué misión es."] = "Не знаю, что это за задание.",
	["No sé si alguien en Azeroth cocina salchichas como las de casa... pero si encuentras una receta, ¡me avisas!"] = "Не знаю, готовит ли кто-нибудь в Азероте сосиски как дома... но если найдешь рецепт — скажи мне!",
	["No sé si se puede tomar"] = "Неизвестно, можно ли взять",
	["No te alcanza"] = "Не хватает денег",
	["No tienes cartas."] = "Писем нет.",
	["No tienes cebos. Los venden los vendedores de suministros de pesca; la guía dice cuáles sirven a tu habilidad."] = "У вас нет приманок. Их продают торговцы рыболовными принадлежностями; гайд подскажет, какие подходят вашему навыку.",
	["No tienes demonio: el abisario aguanta los golpes por ti."] = "У вас нет демона: Демон Бездны принимает удары на себя.",
	["No tienes demonio: invoca uno antes de pelear."] = "У вас нет демона: призовите его перед боем.",
	["No tienes demonio: invócalo al instante, aun peleando."] = "У вас нет демона: призовите его мгновенно, даже в бою.",
	["No tienes marcadores en el mapa de Alfa. Pon uno en el mapa y vuelve aquí."] = "На карте Alfa нет ваших маркеров. Поставьте маркер на карте и вернитесь сюда.",
	["No tienes mascota: llámala."] = "У вас нет питомца: призовите его.",
	["No tienes mascota: si murió, revívela."] = "У вас нет питомца: если он погиб, воскресите его.",
	["No tienes misiones para este plan con ese filtro."] = "С этим фильтром у вас нет заданий для этого плана.",
	["No tienes puntos libres. El siguiente talento del plan (%s) te toca en el nivel %d."] = "Свободных очков нет. Следующий талант плана (%s) — на %d-м уровне.",
	["No tienes un conjunto llamado «%s»."] = "У тебя нет комплекта «%s».",
