	["Notas del lobo"] = "Заметки волка",
	["Novedades de Alfa %s"] = "Что нового в Alfa %s",
	["Nozdormu, el Atemporal, cuida el curso del tiempo. Dicen que conoce el día de su propia muerte, y aun así sigue con su deber."] = "Ноздорму Вневременный оберегает ход времени. Говорят, он знает день своей смерти — и все равно исполняет долг.",
	["Nuestra manada en Discord: ayuda, avisos y reportes. Haz clic en el enlace y cópialo con Ctrl+C."] = "Наша стая в Discord: помощь, новости и сообщения об ошибках. Щелкните по ссылке и скопируйте ее с помощью Ctrl+C.",
	["Nueva ruta vacía"] = "Новый пустой маршрут",
