	["Nuevo: las guaridas. Alfa te dice en qué capa de la zona estás y en cuáles anda la manada; con «Pedir entrar» te pasas a la de un lobo con la puerta abierta."] = "Новое: логова. Alfa говорит, в каком слое зоны ты и где стая; кнопкой «Попроситься» переходишь к волку с открытой дверью.",
