	["Ojo por aquí: %s tiene sus sorpresas."] = "Осторожнее здесь: у %s свои сюрпризы.",
	["Ojo: %s es de élite"] = "Внимание: %s — элитное",
	["Ojo: puedes quitar %s, pero ningún clic lo hace. Elígelo en Tus clics."] = "Внимание: ты можешь снять %s, но ни один щелчок этого не делает. Выбери его в «Ваши щелчки».",
	["Ojo: tu clic para lanzar de Blizzard usa %d de estas teclas, y ese manda también aquí. Para igualarlos, usa «Usar también en los marcos de Blizzard»."] = "Внимание: ваши заклинания по щелчку Blizzard используют %d из этих щелчков, и здесь они имеют приоритет. Чтобы их совместить, используйте «Использовать и на рамках Blizzard».",
	["Ojo: tu equipo anda al %d%%. Un herrero te lo deja como nuevo."] = "Осторожно: прочность экипировки %d%%. Кузнец сделает ее как новую.",
	["Olas y superficie del agua. Llega hasta Ultra (3) y no más: valores mayores pueden cerrar el juego, por eso Alfa no los deja."] = "Волны и поверхность воды. Доходит до «Ультра» (3) и не выше: большие значения могут закрыть игру, поэтому Alfa их не позволяет.",
	["Olor a fogata"] = "Запах костра",
