	["Pan de plátano suave"] = "Мягкий банановый хлеб",
	["Pan recién horneado"] = "Свежеиспеченный хлеб",
	["Panel de estadísticas"] = "Панель характеристик",
	["Pantalla de película para capturas y paseos. Solo cambia cómo se ve: no da más FPS."] = "Экран в стиле кино для скриншотов и прогулок. Меняет только вид: FPS не прибавляет.",
	["Pantalla gris al morir"] = "Серый экран при смерти",
	["Pantalla limpia"] = "Чистый экран",
	["Pantalla limpia: solo lo esencial"] = "Чистый экран: только главное",
	["Para abandonar"] = "Для отказа",
	["Para abrirlo con la tecla del mapa, enciende «Abrir el mapa de Alfa con la tecla del mapa» abajo."] = "Чтобы открывать ее клавишей карты, включите ниже «Открывать карту Alfa клавишей карты».",
	["Para adoptar, tu nivel debe pasar el suyo por 10 o más."] = "Чтобы взять под опеку, твой уровень должен быть выше на 10 или больше.",
	["Para alguien de tu hermandad, agrega su rango."] = "Для члена вашей гильдии добавляет его звание.",
	["Para armar la espada legendaria de Thunderaan, el Buscavientos, hacen falta dos ataduras que sueltan Garr y el barón Geddon en el Núcleo de Magma."] = "Чтобы собрать легендарный меч Громораана, Искателя Ветра, нужны две части оков, которые роняют Гарр и барон Геддон в Огненных Недрах.",
	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Для каждого предмета Alfa сравнивает три пути: продать торговцу, выставить на аукцион или переработать (по известному вам рецепту или распылением).",
	["Para cambiar de plano con la manada, primero deja que te vea en el mapa (ajustes de La Jauría)."] = "Чтобы менять слой со стаей, сначала позволь ей видеть тебя на карте (настройки La Jauría).",
	["Para capturas y paseos. No da más FPS."] = "Для скриншотов и прогулок. FPS не прибавляет.",
	["Para cerrar tu rato con todo cobrado"] = "Завершить, собрав все награды",
	["Para cerrarle el paso a la Legión, Malfurion y sus aliados destruyeron el Pozo de la Eternidad. La explosión hundió el centro de Kalimdor."] = "Чтобы закрыть путь Легиону, Малфурион и его союзники уничтожили Источник Вечности. Взрыв погрузил под воду сердце Калимдора.",
	["Para comprar espacio, habla con un banquero."] = "Чтобы купить место, поговорите с банкиром.",
	["Para conservar"] = "Оставить",
	["Para cruzar de los Reinos del Este a Kalimdor, toma un barco en el Puerto de Menethil, en Los Humedales."] = "Чтобы попасть из Восточных королевств в Калимдор, сядь на корабль в Гавани Менетилов в Болотине.",
	["Para depositar, habla con un banquero."] = "Чтобы положить вещи в банк, поговорите с банкиром.",
	["Para empezar"] = "Чтобы начать",
	["Para encantar necesitas una vara rúnica; con el tiempo la mejoras."] = "Для наложения чар нужен рунический жезл; со временем ты его улучшаешь.",
	["Para entregar"] = "Сдать",
	["Para gastar"] = "Можно потратить",
	["Para invitar a %s a %s: abre «Hermandad y comunidades», elige %s, pulsa «Invitar a miembro» y escribe: %s"] = "Чтобы пригласить %s в %s: откройте «Гильдия и сообщества», выберите %s, нажмите «Пригласить участника» и введите: %s",
	["Para ir de Los Humedales a las Tierras Altas de Arathi cruza el Puente Thandol, pero ojo con los Hierro Negro."] = "Чтобы попасть из Болотины в Нагорье Арати, перейди Мост Тандола, но берегись Черного Железа.",
	["Para las recetas de %s."] = "Для рецептов персонажа %s.",
	["Para leer mejor"] = "Удобнее читать",
	["Para llamar a la manada, deja que te vean en el mapa (La Jauría)."] = "Чтобы позвать стаю, позволь видеть себя на карте (La Jauría).",
	["Para llegar a la Fuente del Sol, la Plaga de Arthas arrasó Quel'Thalas y su capital, Lunargenta."] = "Чтобы добраться до Солнечного Колодца, Плеть Артаса опустошила Кель'Талас и его столицу Луносвет.",
	["Para lo que elegiste no hay uno con este estilo: Alfa usa el más cercano."] = "Для вашего выбора нет билда в этом стиле: Alfa использует ближайший.",
	["Para marcarlo, clic derecho en su retrato y elige la calavera."] = "Чтобы отметить, щелкни правой кнопкой по его портрету и выбери череп.",
	["Para mi nivel (±3)"] = "Для моего уровня (±3)",
	["Para minar torio, el Cráter de Un'Goro y Cuna del Invierno tienen muchas vetas."] = "Для добычи тория много жил в кратере Ун'Горо и в Зимних Ключах.",
	["Para mí"] = "Для меня",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Чтобы не конфликтовать с ним, Alfa не заменяет ваши сумки, пока он активен. Окно Alfa все равно можно открыть отсюда.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "Чтобы случайно не сдвинуть ее. Без закрепления перетащите ее куда хотите.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Чтобы не видеть группу дважды. Меняется вне боя.",
	["Para proponer una cita, deja que la manada te vea en el mapa."] = "Чтобы предложить сбор, позволь стае видеть тебя на карте.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Чтобы они не конфликтовали, Alfa не берет вашу клавишу и не меняет настройки. Отключите один из двух аддонов в списке модификаций (на экране выбора персонажа) и перезагрузите интерфейс. Если оставите Alfa, он сам возьмет клавишу, которую вы использовали в другом аддоне.",
	["Para que no dejes botín tirado por falta de espacio."] = "Чтобы не бросать добычу из-за нехватки места.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Для тех, кто предпочитает выбирать цель левой кнопкой: лечение с этого щелчка переходит на среднюю кнопку. Ваш набор применяется заново.",
	["Para recoger ahora"] = "Взять сейчас",
	["Para subir de nivel"] = "До следующего уровня",
	["Para subir solo, el daño de las sombras ayuda mucho: los hechizos que dañan con el tiempo trabajan por ti."] = "Для одиночной прокачки очень помогает урон от темной магии: заклинания периодического урона работают за тебя.",
	["Para tela de nivel bajo, los Defias de los Páramos de Poniente sueltan lino y lana a montones."] = "Для ткани низкого уровня бандиты Братства Справедливости в Западном Крае роняют горы льна и шерсти.",
	["Para templar la espada élfica Quel'Serrar hay que dejarla en el piso y que Onyxia le eche su aliento de fuego encima."] = "Чтобы закалить эльфийский меч Кель'Серрар, его нужно бросить на землю, чтобы Ониксия дохнула на него огнем.",
	["Para ti"] = "Для вас",
	["Para ti ahora"] = "Для вас сейчас",
	["Para tu %s"] = "Ваш класс: %s",
	["Para tu habilidad conviene pescar en: %s."] = "Для вашего навыка стоит рыбачить здесь: %s.",
	["Para tu nivel"] = "Для вашего уровня",
	["Para tu nivel (%d)"] = "Для вашего уровня (%d)",
	["Para tu nivel ahora"] = "Для вашего уровня сейчас",
	["Para tu personaje de nivel %d"] = "Для вашего персонажа %d-го уровня",
	["Para vender"] = "Продать",
	["Para vender, habla con un comerciante."] = "Чтобы продать, поговорите с торговцем.",
	["Para ver cuánto procesador usa cada parte, escribe /console scriptProfile 1 y luego /reload. Hace el juego un poco más lento: cuando termines, /console scriptProfile 0 y /reload."] = "Чтобы видеть, сколько процессора тратит каждая часть, введи /console scriptProfile 1 и затем /reload. Игра станет чуть медленнее: когда закончишь, /console scriptProfile 0 и /reload.",
	["Para ver las guaridas de la manada, deja que te vean en el mapa."] = "Чтобы видеть логова стаи, позволь видеть себя на карте.",
	["Para ver y romper los tótems enemigos."] = "Чтобы видеть и разбивать вражеские тотемы.",
	["Para verlas mejor"] = "Чтобы лучше их видеть",
	["Para volver a acumularla, descansa (o cierra sesión) en una posada o una ciudad."] = "Чтобы снова его накопить, отдохните (или выйдите из игры) в таверне или городе.",
	["Para: %s."] = "Для: %s.",
	["Parada"] = "Парирование",
	["Parada %d de %d"] = "Остановка %d из %d",
	["Parar"] = "Парирование",
	["Paras más golpes de otros guerreros y pícaros."] = "Вы чаще парируете удары других воинов и разбойников.",
	["Paras más golpes."] = "Вы чаще парируете удары.",
	["Paras más golpes: recibes menos daño desde el principio."] = "Вы чаще парируете удары: получаете меньше урона с самого начала.",
	["Paras un poco más."] = "Вы парируете чуть чаще.",
	["Paraste un golpe: el contraataque está listo."] = "Вы парировали удар: контратака готова.",
	["Paraste un golpe: tu contraataque está listo y desarma al enemigo."] = "Вы парировали удар: контратака готова и обезоруживает противника.",
	["Paraste un golpe: tu contraataque inmoviliza al enemigo."] = "Вы парировали удар: ваша контратака обездвиживает противника.",
	["Partes de Alfa apagadas"] = "Выключенные части Alfa",
	["Partes de Alfa de otra versión"] = "Части Alfa из другой версии",
	["Partes de Alfa que no cargaron"] = "Части Alfa, которые не загрузились",
	["Paré por el combate: lo demás sigue en el buzón."] = "Остановлено из-за боя: остальное лежит в почтовом ящике.",
	["Pasa el ratón por cualquier cosa de Alfa y te digo para qué sirve. Pulsa tu tecla otra vez para terminar."] = "Наведи курсор на что угодно в Alfa, и я скажу, для чего это. Нажми клавишу еще раз, чтобы закончить.",
	["Pasa el ratón sobre un compañero y cúralo con un clic."] = "Наведите курсор на союзника и вылечите его щелчком.",
	["Pasa el ratón sobre un compañero y haz clic: el izquierdo %s y el derecho %s."] = "Наведите курсор на союзника и щелкните: левая — %s, правая — %s.",
	["Pasa enfermedades: quítalas si tu clase puede."] = "Заражает болезнями: снимайте их, если ваш класс это умеет.",
	["Pasa tu build a un amigo o usa el que te pasen."] = "Передайте свой билд другу или используйте тот, что дадут вам.",
	["Pasar solo al siguiente paso"] = "Переходить к следующему шагу самому",
	["Pasas tu vida a tu demonio para curarlo."] = "Направляет твое здоровье в демона, чтобы вылечить его.",
	["Paso %d"] = "Шаг %d",
	["Paso %d de %d"] = "Шаг %d из %d",
	["Paso a paso"] = "Шаг за шагом",
	["Pasos de nivel claros"] = "Шаги уровня понятнее",
	["Pasos que siguen, numerados"] = "Следующие шаги с номерами",
	["Pastel de cerezas casero"] = "Домашний вишневый пирог",
	["Pata de jabalí salvaje"] = "Окорок дикого кабана",
	["Pausa"] = "Пауза",
	["Pausa para el lunch: tú comes, yo miro con ojitos tiernos."] = "Перерыв на обед: ты ешь, я смотрю жалобными глазками.",
	["Peces"] = "Рыбы",
	["Pecho"] = "Грудь",
	["Pedazo de pan duro"] = "Ломоть черствого хлеба",
	["Pedir ayuda a la manada"] = "Попросить стаю о помощи",
	["Pedir entrar"] = "Попроситься",
	["Pedir entrar a su guarida (%s)"] = "Попроситься в его логово (%s)",
	["Pedirle un consejo"] = "Попросить совет",
	["Pediste %s; el juego lo dejó en %s."] = "Вы просили %s; игра установила %s.",
	["Pediste ayuda con %s. Te aviso quién viene."] = "Ты попросил помощи с: %s. Я скажу, кто идёт.",
	["Pega aquí (Ctrl+V) el texto de una ruta de Alfa."] = "Вставьте сюда (Ctrl+V) текст маршрута Alfa.",
	["Pega aquí el texto que copiaste con «Exportar»"] = "Вставь сюда текст, скопированный через «Экспорт»",
	["Pega aquí una cadena que empiece con ALFA1; (Ctrl + V) y pulsa Importar. Alfa revisa cada talento contra tu árbol."] = "Вставьте сюда строку, начинающуюся с ALFA1; (Ctrl + V), и нажмите «Импорт». Alfa сверит каждый талант с вашим деревом.",
	["Pega el texto de «Exportar» para traer esa configuración. Lo de ahora queda guardado como perfil por si acaso."] = "Вставь текст из «Экспорт», чтобы вернуть те настройки. Текущие сохранятся как профиль на всякий случай.",
	["Pega fuerte pero no tiene trucos: es un buen jefe para aprender."] = "Бьет сильно, но без хитростей: хороший босс для обучения.",
	["Pega fuerte y se protege con un escudo de luz: empieza con la vida llena."] = "Бьет сильно и закрывается щитом Света: начинайте бой с полным здоровьем.",
	["Pega fuerte: ve con cuidado y con la vida llena."] = "Бьет сильно: будь осторожен и иди с полным здоровьем.",
	["Pega muchas veces seguidas al tanque: no dejes que su vida baje de la mitad."] = "Бьет танка много раз подряд: не давайте его здоровью опуститься ниже половины.",
	["Pega muy fuerte: empieza la pelea con la vida llena."] = "Бьет очень сильно: начинайте бой с полным здоровьем.",
	["Pega primero una cadena de build de Alfa."] = "Сначала вставьте строку билда Alfa.",
	["Pega primero una cadena de escala de estadísticas."] = "Сначала вставьте строку шкалы характеристик.",
	["Pega una cadena de escala de estadísticas (Ctrl+V), la que copiaste desde donde la compartieron."] = "Вставьте строку шкалы характеристик (Ctrl+V), скопированную оттуда, где ею поделились.",
	["Pega varias veces seguidas: empieza con la vida llena."] = "Бьет несколько раз подряд: начинайте с полным здоровьем.",
	["Pegas a dos: útil contra mascotas y grupos."] = "Вы бьете двоих: полезно против питомцев и групп.",
	["Pegas más después de recibir críticos."] = "Вы бьете сильнее после получения критических ударов.",
	["Pegas más fuerte después de recibir críticos."] = "Вы бьете сильнее после получения критических ударов.",
	["Pegas más fuerte después de recibir un golpe crítico."] = "Вы бьете сильнее после получения критического удара.",
	["Pelea con un solo monstruo a la vez; si vienen dos, usa Golpes de barrido."] = "Сражайтесь с одним монстром за раз; если пришли двое, используйте Размашистые удары.",
	["Pelea siempre con la vida llena; no encadenes monstruos sin descansar."] = "Всегда начинайте бой с полным здоровьем; не берите монстров одного за другим без отдыха.",
	["Pelear contra otros jugadores: aguantar, frenar y rematar."] = "Сражаться с другими игроками: выдержать, замедлить и добить.",
	["Peletería"] = "Кожевничество",
	["Peletería hace cuero con armadura y aguante para la forma de oso."] = "Кожевничество создает кожаные вещи с броней и выносливостью для облика медведя.",
	["Peletería hace malla para ti; Desuello te da el material sin gastar oro."] = "Кожевничество создает для вас кольчугу; Снятие шкур дает материалы, не тратя золото.",
	["Peletería hace piezas de cuero con agilidad y aguante; Desuello te da el cuero."] = "Кожевничество создает кожаные вещи с ловкостью и выносливостью; Снятие шкур дает кожу.",
	["Peligro"] = "Опасность",
	["Peligros"] = "Опасности",
	["Peligrosa para tu nivel"] = "Опасно для вашего уровня",
	["Pendiente"] = "Не выполнено",
	["Pequeñas tareas que Alfa hace por ti al abrir un comerciante, al despojar y al viajar."] = "Мелкие дела, которые Alfa делает за вас у торговца, при сборе добычи и в пути.",
	["Pequeños íconos en cada ataque: si es para el tanque, para quien cura, si se puede quitar o si es mortal."] = "Маленькие значки на каждой атаке: для танка ли она, для лекаря, можно ли ее снять и смертельна ли она.",
	["Perdimos el rastro de %s: ya no sabemos dónde está."] = "След потерян: %s — местоположение больше неизвестно.",
	["Perfil guardado"] = "Профиль сохранен",
	["Perjuicios que puedes quitar"] = "Снимаемые отрицательные эффекты",
	["Personaje"] = "Персонаж",
	["Pesca"] = "Рыбная ловля",
	["Pesca %d/%d"] = "Рыбная ловля %d/%d",
	["Pesca 10 de oro en valor en una sola sesión."] = "Наловите на 10 золотых за один сеанс.",
	["Pesca 25 especies distintas."] = "Поймайте 25 разных видов.",
	["Pesca 5 especies distintas en una misma zona."] = "Поймайте 5 разных видов в одной зоне.",
	["Pesca 5 especies distintas."] = "Поймайте 5 разных видов.",
	["Pesca de Alfa apagada. Tu tecla y tus ajustes quedan como siempre."] = "Рыбалка Alfa выключена. Ваша клавиша и настройки остаются как обычно.",
	["Pesca de Alfa encendida, pero en pausa mientras otro addon de pesca esté activo."] = "Рыбалка Alfa включена, но на паузе, пока включен другой аддон рыбалки.",
	["Pesca de Alfa encendida."] = "Рыбалка Alfa включена.",
	["Pesca en 10 zonas distintas."] = "Порыбачьте в 10 разных зонах.",
	["Pesca en los bancos de peces que flotan en el agua: dan más que pescar en cualquier lado."] = "Лови рыбу в косяках на поверхности воды: они дают больше, чем ловля где попало.",
	["Pesca en los bancos de peces que flotan en el agua: dan más y a veces sorpresas."] = "Лови рыбу в косяках на поверхности воды: они дают больше, а иногда и сюрпризы.",
	["Pesca un trofeo o un pez de concurso."] = "Поймайте трофей или рыбу для состязания.",
	["Pesca una hora en una sola sesión."] = "Рыбачьте час за один сеанс.",
	["Pesca: si te atacan mientras vuelve tu equipo normal, ya no pierdes piezas."] = "Рыбалка: если на вас нападут, пока возвращается обычная экипировка, вы больше не теряете вещи.",
	["Pescando"] = "Рыбалка",
