	["Picadura de serpiente: daño con el tiempo."] = "Укус змеи: периодический урон.",
	["Pide %d de Cocina y aprender la receta."] = "Нужна кулинария %d и изученный рецепт.",
	["Pide %d de habilidad de pesca."] = "Нужен навык рыбной ловли %d.",
	["Pide al grupo que espere unos segundos antes de atacar."] = "Попросите группу подождать несколько секунд перед атакой.",
	["Pide ayuda con %s."] = "Просит помощи с: %s.",
	["Pide ayuda con un élite o un raro: los lobos de tu zona reciben tu lugar y te avisa quién viene."] = "Попроси помощи с элитным или редким: волки твоей зоны получат твоё место, и ты узнаешь, кто идёт.",
	["Pide ayuda donde está."] = "Просит помощи там, где находится.",
	["Pide grupo"] = "Нужна группа",
	["Pide «Cerrar mis misiones» en Ruta: te llevo a terminar las que llevas y luego a entregarlas, en el mejor orden."] = "Выбери «Закрыть мои задания» в «Маршруте»: отведу доделать их, а потом сдать, в лучшем порядке.",
	["Pidiendo los precios a la subasta..."] = "Запрашиваем цены у аукциона...",
