	["Pocos lugares de %s en %s"] = "Мало мест для «%s» в зоне %s",
	["Pocos precios"] = "Мало цен",
	["Poder a distancia"] = "Сила атаки дальнего боя",
	["Poder arcano: más daño un rato, mientras te sobre maná."] = "Мощь тайной магии: больше урона на время, пока маны с избытком.",
	["Poder con hechizos"] = "Сила заклинаний",
	["Poder de ataque"] = "Сила атаки",
