	["Polestar es de código abierto:"] = "Polestar — открытый код:",
	["Polvo arcano"] = "Чародейский порошок",
	["Polvo cegador"] = "Воспламеняющийся порошок",
	["Pon Seccionar en cuanto llegues al rival y mantenlo puesto."] = "Наложите Подрезать сухожилия, как только доберетесь до противника, и поддерживайте.",
	["Pon ahora"] = "Взять сейчас",
	["Pon todos tus hechizos de daño en el tiempo y deja que tu demonio aguante."] = "Наложите все заклинания периодического урона и дайте демону держать противника.",
	["Pon tu escudo y tu daño en el tiempo antes de que el monstruo llegue."] = "Наложите щит и периодический урон, пока монстр не добрался до вас.",
	["Pon tu objeto en la pestaña de vender: a un lado te digo su precio sugerido, cómo le fue estos días y te aviso si lo das muy barato. El precio lo pones tú."] = "Положи предмет во вкладку продажи: сбоку я покажу рекомендуемую цену, как она менялась в эти дни, и предупрежу, если продаешь слишком дешево. Цену ставишь ты.",
	["Pon tu piedra de hogar en la posada donde tengas más misiones."] = "Привяжи камень возвращения к таверне, где у тебя больше всего заданий.",
	["Pon tu tótem abrasador: dispara al enemigo por ti."] = "Поставьте Тотем опаляющего жара: он стреляет в противника за вас.",
	["Pon tus tótems al empezar cada pelea grande."] = "Ставьте тотемы в начале каждого крупного боя.",
	["Pon un cebo 10 veces."] = "Наложите приманку 10 раз.",
	["Pon un tótem antes de empezar la pelea."] = "Поставьте тотем перед началом боя.",
	["Pon una trampa antes de empezar la pelea y lleva al monstruo hacia ella."] = "Поставьте ловушку перед боем и приведите в нее монстра.",
	["Pon venenos en tus armas siempre."] = "Всегда наносите яды на оружие.",
	["Pone el enlace en el chat."] = "Вставляет ссылку в чат.",
	["Pone la flecha ahí."] = "Ставит туда стрелку.",
	["Pone los ajustes de un perfil que guardaste. Algunas cosas se ven completas al recargar."] = "Применяет настройки сохраненного профиля. Кое-что полностью появится после перезагрузки.",
	["Pone los marcos donde estaban al instalar Alfa."] = "Возвращает рамки туда, где они были при установке Alfa.",
	["Pone tres ataques de prueba en la línea de tiempo para que veas dónde sale. Se borran solos. Para moverla: menú del juego (Esc) > Modo de edición."] = "Добавляет на шкалу времени три тестовые атаки, чтобы вы увидели, где она появляется. Они исчезнут сами. Чтобы передвинуть ее: меню игры (Esc) > Режим редактирования.",
	["Pone una maldición que baja la curación que recibes: quítala si tu clase puede."] = "Накладывает проклятие, снижающее получаемое исцеление: снимайте его, если ваш класс это умеет.",
	["Pone una maldición que te debilita y un fuego que quema poco a poco: quita la maldición si puedes."] = "Накладывает ослабляющее проклятие и огонь, который жжет понемногу: снимайте проклятие, если можете.",
	["Poner el cebo"] = "Наложить приманку",
	["Poner la flecha aquí"] = "Поставить стрелку сюда",
	["Poner la flecha hasta ahí"] = "Направить стрелку туда",
	["Ponerme el equipo de pesca"] = "Надеть рыболовное снаряжение",
	["Ponerme lo de pesca"] = "Надеть все для рыбалки",
	["Ponerme una meta"] = "Поставить себе цель",
	["Ponerte la recompensa si es mejor"] = "Надевать награду, если она лучше",
	["Ponlo de espaldas al grupo para que su golpe solo te dé a ti."] = "Разверните его спиной к группе, чтобы его удар попадал только по вам.",
	["Ponlo de espaldas al grupo y aguanta: la pelea es corta."] = "Разверните его спиной к группе и держитесь: бой короткий.",
	["Ponlos al empezar a pelear."] = "Ставьте их в начале боя.",
	["Ponte esto"] = "Надень это",
	["Ponte la caña primero."] = "Сначала наденьте удочку.",
	["Ponte un conjunto guardado o guarda lo que llevas puesto."] = "Надень сохраненный комплект или сохрани надетое.",
	["Ponte un escudo antes de empezar cada pelea."] = "Накладывайте на себя щит перед каждым боем.",
	["Ponte una meta: un pez, capturas, tiempo o valor."] = "Поставьте цель: рыба, улов, время или стоимость.",
	["Ponérmelo"] = "Надеть",
	["Por Costa Oscura anda un explorador de la Liga muy despistado, que siempre necesita que alguien le eche la mano."] = "По Темным берегам бродит очень рассеянный исследователь Лиги, которому вечно нужна чья-нибудь помощь.",
	["Por ahora, guárdalo todo"] = "Пока оставьте все",
	["Por bolsa"] = "По сумкам",
	["Por categorías"] = "По категориям",
	["Por clase"] = "По классу",
	["Por debajo de tu nivel"] = "Ниже вашего уровня",
	["Por defecto"] = "По умолчанию",
	["Por dentro, Alfa está construido sobre Polestar, de fitzforge y The Polestar authors (GPL-3.0): su motor de guías, flecha y datos. Alfa lo adapta, le suma sus propios módulos y sigue siendo libre."] = "Внутри Alfa построен на Polestar от fitzforge и The Polestar authors (GPL-3.0): его движок руководств, стрелки и данных. Alfa его адаптирует, добавляет свои модули и остается свободным.",
	["Por descubrir"] = "Не открыто",
	["Por dónde sale: %s"] = "Передается через: %s",
	["Por dónde se pasa a otra zona (caminos, pasos, túneles y puertas), con una flecha hacia ella y su rango de niveles. Se ven al acercarte a una zona."] = "Где переходить в другую зону (дороги, перевалы, туннели и ворота), со стрелкой к ней и ее диапазоном уровней. Видны при приближении к зоне.",
	["Por ejemplo: primero un objeto, luego 10 de oro, luego subir cocina y al final el banco."] = "Например: сначала предмет, затем 10 золотых, потом прокачать кулинарию и в конце банк.",
	["Por eso empezamos con esta configuración: para que cada quien arme su experiencia a su gusto. Todo se puede cambiar después."] = "Поэтому мы начинаем с этой настройки: чтобы каждый собрал игру под себя. Все можно изменить позже.",
	["Por estas montañas se llega al Valle de Alterac, donde la Guardia Pico Tormenta y el clan Lobo Gélido pelean sin descanso."] = "Через эти горы можно попасть в Альтеракскую долину, где Стража Грозовой Вершины и клан Северного Волка сражаются без передышки.",
	["Por grupo"] = "По группе",
	["Por honor (JcJ)"] = "За честь (PvP)",
	["Por hora"] = "В час",
	["Por hora: %s"] = "В час: %s",
	["Por la Alianza mandan Bolvar como regente en Ventormenta, Magni en Forjaz, Tyrande en Darnassus y Mekkatorque con los gnomos."] = "В Альянсе Болвар правит как регент Штормграда, Магни — в Стальгорне, Тиранда — в Дарнасе, а Меккаторк ведет гномов.",
	["Por la selva de Feralas caminan gigantes enormes. ¡Cuidado con sus pisadas!"] = "По джунглям Фераласа ходят огромные великаны. Берегись их шагов!",
	["Por lograr"] = "Еще не получено",
	["Por los canales de Entrañas corre una baba verde que mejor ni probar."] = "По каналам Подгорода течет зеленая слизь, которую лучше не пробовать.",
	["Por mazmorra"] = "По подземельям",
	["Por nivel: jefes, botín, misiones, la entrada y consejos."] = "По уровню: боссы, добыча, задания, вход и советы.",
	["Por nombre"] = "По имени",
	["Por nombre, tipo o calidad (verde, azul...) y por nivel de objeto: 20, >20, 20-30. Lo que coincide se resalta."] = "По названию, типу или качеству (зеленые, синие...) и уровню предмета: 20, >20, 20-30. Совпадения подсвечиваются.",
	["Por reputación"] = "За репутацию",
	["Por rol"] = "По роли",
	["Por terminar"] = "В процессе",
	["Por una salchicha te sigo hasta Rasganorte. Bueno, te seguiría igual."] = "За сосиску я пойду за тобой хоть в Нордскол. Ну, я бы и так пошла.",
	["Por unos segundos no recibes daño físico. Tu salvavidas cuando las cosas se ponen feas."] = "Несколько секунд ты не получаешь физического урона. Спасение, когда все плохо.",
	["Por zona (este personaje)"] = "По зонам (этот персонаж)",
	["Porcentaje de vida"] = "Процент здоровья",
	["Portal a %s"] = "Портал: %s",
	["Portales"] = "Порталы",
	["Posada"] = "Таверна",
	["Posada de %s"] = "Таверна: %s",
	["Posadas"] = "Таверны",
	["Posadero"] = "Хозяин таверны",
	["Posaderos"] = "Хозяева таверн",
	["Posaderos; se marca el de tu piedra de hogar."] = "Хозяева таверн; отмечен тот, к кому привязан ваш камень возвращения.",
	["Preajuste «%s» listo para tus clics."] = "Набор «%s» назначен на ваши щелчки.",
	["Preajustes"] = "Наборы",
	["Preajustes listos para usar"] = "Готовые наборы",
	["Preajustes, ajustes escondidos del juego, cámara, placas y filtros para que el mundo se vea mejor."] = "Наборы, скрытые настройки игры, камера, индикаторы здоровья и фильтры, чтобы мир выглядел лучше.",
	["Precio"] = "Цена",
	["Precio de %s"] = "Цена из %s",
	["Precio sugerido"] = "Рекомендуемая цена",
	["Precios %s · %s objetos"] = "Цены %s · предметов: %s",
	["Precios al día"] = "Цены актуальны",
	["Precios de la subasta"] = "Аукционные цены",
	["Precios viejos"] = "Цены устарели",
	["Precios y qué conviene vender."] = "Цены и что выгодно продать.",
	["Precisión"] = "Меткость",
	["Precisión con hechizos"] = "Меткость заклинаний",
	["Preguntar a la manada"] = "Спросить стаю",
	["Preguntas"] = "Вопросы",
	["Pregúntale a Lya"] = "Спроси Лию",
	["Pregúntale a Lya: clic derecho en ella y «¿En qué te ayudo?». Te explica cada parte de Alfa y te lleva con un clic."] = "Спроси Лию: правый клик по ней и «Чем помочь?». Она объяснит каждую часть Alfa и отведёт туда в один клик.",
	["Pregúntale a Lya: todo lo de Alfa explicado y a un clic"] = "Спроси Лию: всё об Alfa с объяснением и в один клик",
	["Pregúntale a la manada"] = "Спросить стаю",
	["Pregúntale a un guardia de la ciudad por el instructor de la profesión."] = "Спросите у городского стражника, где найти учителя профессии.",
	["Premio final: %s"] = "Итоговая награда: %s",
	["Premio final: %s de experiencia"] = "Итоговая награда: %s опыта",
	["Premio: %s"] = "Награда: %s",
	["Prendas de lana que te enseñe tu instructor."] = "Шерстяная одежда, которой учит учитель.",
	["Prendas de seda que te enseñe tu instructor."] = "Шелковая одежда, которой учит учитель.",
	["Prendas de tejido mágico que te enseñe tu instructor."] = "Одежда из магической ткани, которой учит учитель.",
	["Prendas de tela rúnica que te enseñe tu instructor."] = "Одежда из рунической ткани, которой учит учитель.",
	["Prende la ayuda de rotación en Combate: te sugiero qué usar ahora y qué sigue. Solo sugiero; los botones los presionas tú."] = "Включи помощь с ротацией в «Бою»: подскажу, что использовать сейчас и дальше. Только подсказываю; жмёшь ты.",
	["Prende la línea de tiempo, los íconos de ayuda y los mensajes medianos y graves."] = "Включает шкалу времени, значки-подсказки и средние и серьезные сообщения.",
	["Prende los marcos de Curación: pasas el ratón sobre un compañero y con un clic lo curas."] = "Включи рамки «Лечения»: наведи на товарища и вылечи одним кликом.",
	["Prende todo el sistema de avisos de jefes de Blizzard: la línea de tiempo y los mensajes en pantalla. Sin esto, lo demás no se ve."] = "Включает всю систему предупреждений о боссах от Blizzard: шкалу времени и сообщения на экране. Без этого остальное не видно.",
	["Prender o apagar"] = "Включить или выключить",
	["Prenderlo"] = "Включить",
	["Prepara tus marcos de curación"] = "Настройте рамки исцеления",
	["Prepara tus marcos en 3 pasos"] = "Настройте рамки за 3 шага",
	["Preparando %s… %s"] = "Подготовка: %s… %s",
	["Preparando %s… la ficha se completa sola."] = "Подготовка: %s… страница заполнится сама.",
	["Preparando la enciclopedia…"] = "Подготовка энциклопедии…",
	["Preparando lo que contiene… la ficha se completa sola."] = "Подготовка содержимого… страница заполнится сама.",
	["Preparando lo que da… la ficha se completa sola."] = "Подготовка того, что он дает… страница заполнится сама.",
	["Preparando lo que vende y suelta… la ficha se completa sola."] = "Подготовка того, что он продает и роняет… страница заполнится сама.",
	["Preparar la mazmorra"] = "Подготовиться к подземелью",
	["Prepárame"] = "Подготовь меня",
	["Prepárate para entrar"] = "Подготовьтесь ко входу",
	["Prepárate: llega en %s"] = "Готовься: прибудет через %s",
	["Presencia mental: tu siguiente hechizo es instantáneo."] = "Присутствие разума: следующее заклинание будет мгновенным.",
	["Primer aviso"] = "Первое предупреждение",
	["Primer tirón"] = "Первая поклевка",
	["Primero cobra lo que ya hiciste: una ruta por el camino más corto, junta por PNJ."] = "Сначала сдайте то, что уже выполнили: один маршрут по самому короткому пути, по NPC.",
	["Primero con el banco de la hermandad"] = "Сначала за счет банка гильдии",
	["Primero crea una ruta: /alfa recoleccion ruta"] = "Сначала создайте маршрут: /alfa recoleccion ruta",
	["Primero defensa: paras muchos más golpes y descansas menos."] = "Сначала защита: вы парируете гораздо больше ударов и меньше отдыхаете.",
	["Primero elige tu build"] = "Сначала выберите билд",
	["Primero necesitas %s, que se toma a nivel %d."] = "Сначала нужно задание %s, его берут на %d-м уровне.",
	["Primero pelean contra el Comandante Mograine; cuando cae, ella llega y lo resucita."] = "Сначала вы сражаетесь с Командиром Могрейном; когда он падает, приходит она и воскрешает его.",
	["Primero prende la línea de tiempo del jefe."] = "Сначала включите шкалу времени босса.",
	["Primero sale su trituradora; al romperla, Sneed baja y pelea a pie."] = "Сначала выходит его крошшер; когда он сломан, Снид выпрыгивает и сражается пешим.",
	["Primero toma %s"] = "Сначала возьмите %s",
	["Primero un objeto, luego oro, luego una profesión y al final el banco: tú eliges el orden."] = "Сначала предмет, потом золото, потом профессия и в конце банк: порядок выбираете вы.",
	["Primero: %s"] = "Сначала: %s",
	["Primeros auxilios"] = "Первая помощь",
	["Primeros auxilios le sirve a cualquier clase, sobre todo a las que no se curan solas."] = "Первая помощь пригодится любому классу, особенно тем, кто не лечит себя сам.",
	["Primeros auxilios sirve a cualquier clase: unas vendas te sacan de apuros."] = "Первая помощь полезна любому классу: пара бинтов выручит в беде.",
	["Principal"] = "Основная",
	["Principal [mano]"] = "Правая рука",
	["Probador"] = "Примерочная",
	["Probar"] = "Проверить",
	["Probar con 20"] = "Тест на 20",
	["Probar con 5"] = "Тест на 5",
	["Probar el aviso"] = "Проверить оповещение",
	["Probar la línea de tiempo"] = "Проверить шкалу времени",
	["Probar la pantalla limpia"] = "Попробовать чистый экран",
	["Probar la ventana"] = "Попробовать окно",
	["Probar otra vez"] = "Попробовать снова",
	["Probar un aviso"] = "Проверить оповещение",
	["Procesador: Alfa usa %.2f ms por cuadro ahora. Lo que más usa:"] = "Процессор: сейчас Alfa тратит %.2f мс на кадр. Больше всего:",
	["Procesador: Alfa usó %.0f ms desde que entraste o recargaste. Lo que más usa:"] = "Процессор: Alfa потратил %.0f мс с момента входа или перезагрузки. Больше всего:",
	["Profesiones"] = "Профессии",
	["Profesiones (18): llegar a 150, 225 y 300 en Alquimia, Herrería, Encantamiento, Ingeniería, Peletería y Sastrería."] = "Профессии (18): достичь 150, 225 и 300 в алхимии, кузнечном деле, наложении чар, инженерном деле, кожевничестве и портняжном деле.",
	["Profesiones que te sirven"] = "Полезные вам профессии",
	["Profesiones: más puntos de habilidad, más recursos al recolectar, mejores precios con los vendedores, más platos y más peces."] = "Профессии: больше очков навыка, больше ресурсов при сборе, лучше цены у торговцев, больше блюд и больше рыбы.",
	["Profesión"] = "Профессия",
	["Promedio de la sesión: %s XP por hora."] = "В среднем за сеанс: %s опыта в час.",
	["Promedio de la sesión: %s XP por hora. XP ganada: %s."] = "Среднее за сеанс: %s опыта в час. Получено опыта: %s.",
	["Proponer"] = "Предложить",
	["Proponer la siguiente guía"] = "Предлагать следующий гид",
	["Propusiste una cita"] = "Сбор предложен",
	["Propón qué, el día y la hora: a los lobos de tu hermandad con Alfa les llega con «Voy». Te recuerdo 15 minutos antes."] = "Предложи что, день и время: волки твоей гильдии с Alfa получат это с кнопкой «Иду». Напомню за 15 минут.",
	["Propón una salida a la manada (/alfa cita mañana 21:30 Minas)"] = "Предложи стае вылазку (/alfa cita tomorrow 21:30 Копи)",
	["Propón una salida con día y hora y recibe las de tu hermandad con «Voy». Lya te la recuerda 15 minutos antes."] = "Предложи вылазку с днем и временем и получай вылазки своей гильдии с кнопкой «Иду». Лия напомнит за 15 минут.",
	["Protección"] = "Защита",
	["Protección [paladín]"] = "Защита",
	["Protección para subir"] = "Защита для прокачки",
	["Protección para subir [paladín]"] = "Защита для прокачки",
	["Protege a un aliado de todo daño físico un momento. Salva a quien cura."] = "Защищает союзника от всего физического урона на мгновение. Спаси своего лекаря.",
	["Proyectiles"] = "Снаряды",
	["Prueba"] = "Тест",
	["Prueba con %d: arrastra para mover"] = "Тест на %d: перетащите, чтобы передвинуть",
	["Prueba con el nombre del pueblo o de la zona."] = "Попробуй название города или зоны.",
	["Prueba con otra búsqueda o quita un filtro."] = "Попробуйте другой запрос или уберите фильтр.",
	["Prueba con otra palabra o elige Todas."] = "Попробуйте другое слово или выберите «Все».",
	["Prueba con otra palabra o quita el filtro."] = "Попробуйте другое слово или уберите фильтр.",
	["Prueba con otra palabra, como «pasto», «niebla» o «sombras»."] = "Попробуйте другое слово, например «трава», «туман» или «тени».",
	["Prueba con otra palabra, en español o en inglés, o quita un filtro."] = "Попробуйте другое слово, на испанском или английском, или уберите фильтр.",
	["Prueba con otra palabra."] = "Попробуйте другое слово.",
	["Prueba con otro filtro."] = "Попробуйте другой фильтр.",
	["Prueba de Alfa %d"] = "Тест Alfa %d",
	["Prueba tus clics"] = "Проверьте щелчки",
	["Pruébala fuera de mazmorras y bandas."] = "Проверяйте ее вне подземелий и рейдов.",
	["Préndelo para ver jefes, botín, misiones y consejos de cada mazmorra."] = "Включите, чтобы видеть боссов, добычу, задания и советы каждого подземелья.",
	["Préndelos abajo, en «Lya y su manada»."] = "Включи их ниже, в «Лия и ее стая».",
	["Publicar"] = "Опубликовать",
	["Puede controlar la mente de un jugador: no lo ataquen, esperen a que se le pase."] = "Может подчинить разум игрока: не атакуйте этого игрока, подождите, пока эффект пройдет.",
	["Puede convertir a alguien en huargo: no ataquen a ese jugador, se le pasa solo."] = "Может превратить кого-то в воргена: не атакуйте этого игрока, это пройдет само.",
	["Puede dormir a alguien del grupo: sigue peleando, se despierta solo."] = "Может усыпить кого-то из группы: продолжайте бой, он проснется сам.",
	["Puede dormir a alguien y golpear a todos los que están cerca."] = "Может усыпить кого-то и ударить всех рядом.",
	["Puede lanzarte por los aires con un gancho: regresa rápido para que no vaya tras quien cura."] = "Может подбросить вас апперкотом: быстро возвращайтесь, чтобы он не пошел на лекаря.",
	["Puede pisotear a los que pelean cuerpo a cuerpo: mantén su vida alta."] = "Может растоптать бойцов ближнего боя: держите их здоровье высоким.",
	["Puede que el archivo se dañara. Tienes un respaldo del %s."] = "Возможно, файл поврежден. У тебя есть копия от %s.",
	["Puede que hayas omitido lo que queda o que aún no te toque. Elige otra guía o vuelve a esta más adelante."] = "Возможно, вы пропустили оставшееся или ещё не время. Выберите другое руководство или вернитесь к этому позже.",
	["Puedes Cargar en actitud defensiva: empiezas a tanquear sin cambiar de actitud."] = "Можно делать Рывок в Оборонительной стойке: вы начинаете танковать, не меняя стойку.",
	["Puedes abrir cerraduras: practica con cajas fuertes y cofres, y ofrécele el servicio a tu grupo."] = "Ты умеешь вскрывать замки: тренируйся на сейфах и сундуках и предлагай эту услугу группе.",
	["Puedes cambiar cada tramo."] = "Каждый этап можно изменить.",
	["Puedes crear comida y agua para todo el grupo. ¡Y si un día aprendes a hacer salchichas, me avisas!"] = "Ты можешь сотворить еду и воду для всей группы. А если когда-нибудь научишься делать сосиски — скажи мне!",
	["Puedes desollar casi cualquier bestia que mates: el cuero sale de todos lados."] = "Шкуру можно снять почти с любого убитого зверя: кожа добывается повсюду.",
	["Puedes hacerte amigo de los piratas Velasangre matando goblins de Bahía del Botín... aunque luego los guardias goblin te odiarán."] = "С пиратами Кровавого Паруса можно подружиться, убивая гоблинов Пиратской Бухты... хотя потом гоблинская стража тебя возненавидит.",
	["Puedes revivir a tus compañeros fuera de combate: en una mazmorra eres de lo más valioso."] = "Ты можешь воскрешать соратников вне боя: в подземелье тебе цены нет.",
	["Puedes revivirte tú solo al morir. Necesitas un ankh."] = "Ты можешь сам вернуться к жизни после смерти. Нужен анкх.",
	["Puedes tomarla"] = "Можно взять",
	["Puedes usarlo"] = "Вы можете это использовать",
	["Puedes vender %d cosas por unos %s."] = "Можно продать вещей: %d — примерно за %s.",
	["Puedes vender %s (unos %s)."] = "Можно продать %s (примерно %s).",
	["Puedes vender %s por %s."] = "Можно продать %s за %s.",
	["Puedes volver a ese paso desde «Ver detalle»."] = "Ты можешь вернуться к этому шагу через «Подробнее».",
	["Puedo usar"] = "Могу использовать",
	["Puesto"] = "Применено",
	["Pulsa %s %s"] = "Нажмите %s %s",
	["Pulsa Cocinar: cada clic hace un lote. Tienes que estar junto a un fuego."] = "Нажмите «Приготовить»: каждый щелчок — одна партия. Нужно стоять у огня.",
	["Pulsa Guiarme y la flecha te lleva de parada en parada desde la más cercana."] = "Нажмите «Вести меня», и стрелка поведет вас от остановки к остановке, начиная с ближайшей.",
	["Pulsa una tecla…"] = "Нажмите клавишу…",
	["Pulsa «Cambiar de plano» en La Jauría o escribe /alfa plano: le pido a un lobo con su guarida abierta en otro plano que te invite. Acepta, y al llegar sales del grupo."] = "Нажми «Сменить слой» в La Jauría или введи /alfa plano: я попрошу волка с открытым логовом в другом слое пригласить тебя. Прими, а когда окажешься там, выйди из группы.",
	["Punta de Torio es el campamento de la Hermandad del Torio, y ahí se juntan Alianza y Horda para hacer negocios."] = "Ториевая Застава — лагерь Братства Тория, где Альянс и Орда сходятся, чтобы вести дела.",
	["Puntería"] = "Стрельба",
	["Puntería para subir"] = "Стрельба для прокачки",
	["Punto %d de tu build (nivel %d), hasta %d/%d."] = "Очко %d вашего билда (уровень %d), до %d/%d.",
	["Puntos %d a %d de tu build (niveles %d a %d)."] = "Очки %d–%d вашего билда (уровни %d–%d).",
	["Puntos de ruta"] = "Путевые точки",
	["Puntos de vuelo"] = "Точки полетов",
	["Puntos del legado"] = "Очки «Наследия»",
	["Puntos por gastar"] = "Есть свободные очки",
	["Página Ruta"] = "Страница «Маршрут»",
	["Pásale el ratón: en su cuadro te digo lo que ganas y lo que pierdes contra lo que llevas puesto, con números. Lo primero es lo que más le sirve a tu clase."] = "Наведи курсор: в подсказке я покажу, что ты получишь и потеряешь по сравнению с надетым, в цифрах. Сначала — самое полезное для твоего класса.",
	["Pégalo en %s del Discord de La Jauría."] = "Вставьте его в %s в Discord La Jauría.",
	["Pícaro"] = "Разбойник",
	["Pídeme el «Circuito de la zona» (página Ruta o el menú del rastreador): junto las que llevas y las que puedes tomar aquí y te llevo por el camino más corto."] = "Попроси у меня «Обход зоны» (страница «Маршрут» или меню отслеживания): я соберу те, что у тебя есть, и те, что можно взять здесь, и поведу кратчайшим путем.",
	["Que Lya te la cuente"] = "Пусть Лия расскажет",
	["Que a ese compañero le falta el buff de tu clase. Pasa el ratón sobre su marco: te digo con qué clic se lo das."] = "Что у союзника нет положительного эффекта твоего класса. Наведи курсор на его рамку: я скажу, каким щелчком его наложить.",
	["Que la manada vea a mi personaje en el mapa"] = "Пусть стая видит моего персонажа на карте",
	["Que me vean en el mapa"] = "Пусть меня видят на карте",
	["Que suene también cuando vas solo por el mundo."] = "Звучать и тогда, когда вы путешествуете по миру в одиночку.",
	["Queda 1"] = "Осталась 1",
	["Queda lejos: unos %s de camino"] = "Далеко: примерно %s пути",
	["Quedan %d"] = "Осталось: %d",
	["Quedan %d casillas libres y no llevas nada que convenga vender: guarda algo en el banco."] = "Осталось свободных ячеек: %d, а выгодно продать нечего: положите что-нибудь в банк.",
	["Quedan %d casillas libres. Puedes vender %s (unos %s)."] = "Осталось свободных ячеек: %d. Можно продать %s (примерно %s).",
	["Quedan %s"] = "Осталось %s",
	["Quedó sin pasos: agrega tramos o recalcula."] = "Не осталось шагов: добавьте этапы или пересчитайте.",
	["Quema al enemigo de golpe y durante un rato. Buen inicio de pelea."] = "Обжигает врага сразу и со временем. Хорошее начало.",
	["Quema al enemigo un rato."] = "Поджигает противника на время.",
	["Quien instala Alfa ya tiene encendidos los colores de clase, el cuadro de información, el probador, el minimapa y las barras con el estilo de Alfa."] = "В новых установках уже включены цвета классов, подсказка, примерочная, мини-карта и панели в стиле Alfa.",
	["Quien lleva la insignia de La Jauría la luce en el borde de su retrato: en el tuyo, el de tu objetivo y el de tu foco."] = "У кого есть значок La Jauría, тот носит его на краю портрета: вашего, вашей цели и вашего фокуса.",
	["Quien recibe la misión"] = "Кому сдавать задание",
	["Quien repara tu equipo"] = "Тот, кто чинит экипировку",
	["Quien te pegue cuerpo a cuerpo se lastima. Pónsela al que tanquea."] = "Тот, кто бьет в ближнем бою, получает урон. Наложи на своего танка.",
	["Quien use Alfa en tu grupo lo recibe y puede seguirlo."] = "Тот, кто пользуется Alfa в вашей группе, получит его и сможет следовать.",
	["Quienes apoyan y construyen Polestar, el motor en el que se basa Alfa."] = "Те, кто поддерживает и создает Polestar — движок, на котором построен Alfa.",
	["Quienes apoyan, construyen y reportan errores de Polestar, el motor en el que se basa Alfa."] = "Те, кто поддерживает и создает Polestar — движок, на котором построен Alfa, — и сообщает о его ошибках.",
	["Quienes usan Alfa y comparten te ven en su mapa y pueden seguirte, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase cada 10 segundos mientras te mueves (cada 4 minutos si estás quieto), nunca dentro de mazmorras. Va por un canal oculto de Alfa: no sale en el chat, pero alguien que entre a ese canal con otro addon podría leerlo."] = "Те, кто пользуется Alfa и делится, видят вас на своей карте и могут следовать за вами, а вы за ними. Ваша зона, позиция, уровень и класс отправляются каждые 10 секунд, пока вы двигаетесь (каждые 4 минуты, если стоите), никогда в подземельях. Это идёт через скрытый канал Alfa: в чате ничего не видно, но тот, кто войдёт в этот канал с другим аддоном, сможет это прочитать.",
	["Quienes van contigo y usan Alfa ven cómo vas en las misiones que comparten."] = "Спутники, которые пользуются Alfa, видят ваш прогресс в общих заданиях.",
	["Quiero"] = "Я хочу",
	["Quiero unirme"] = "Хочу вступить",
	["Quieto"] = "Стоять",
	["Quita el corte visible donde termina una capa de sombra y empieza la siguiente."] = "Убирает видимый шов там, где кончается один слой теней и начинается следующий.",
	["Quita la columna de botones junto al chat (menú, canales y voz). Los comandos como /s, /g o /canal siguen igual."] = "Убирает столбец кнопок рядом с чатом (меню, каналы и голос). Команды вроде /s, /g или /канал работают как прежде.",
	["Quita los grifos de los lados de la barra principal. Edit Mode también tiene su propia opción para esto."] = "Убирает грифонов по бокам основной панели. В режиме редактирования (Edit Mode) для этого тоже есть своя настройка.",
	["Quita magia mala a un aliado, o magia buena a un enemigo."] = "Снимает вредную магию с союзника или полезную с врага.",
	["Quita un perfil que ya no usas. Tus ajustes de ahora no cambian."] = "Удаляет профиль, которым ты больше не пользуешься. Текущие настройки не меняются.",
	["Quita un veneno a un aliado."] = "Снимает яд с союзника.",
	["Quita un veneno o una enfermedad a un aliado."] = "Снимает яд или болезнь с союзника.",
	["Quita una enfermedad. Úsala en lugares llenos de no-muertos."] = "Снимает болезнь. Применяй там, где полно нежити.",
	["Quita una maldición a un aliado."] = "Снимает проклятие с союзника.",
	["Quita veneno, enfermedad y magia. Úsalo cuando alguien trae algo malo encima."] = "Снимает яд, болезнь и магию. Применяй, когда на ком-то что-то неприятное.",
	["Quitar"] = "Убрать",
	["Quitar de Cerrar mis misiones"] = "Убрать из «Закрыть мои задания»",
	["Quitar del mapa"] = "Убрать с карты",
	["Quitar del plan"] = "Убрать из плана",
	["Quitar el silencio"] = "Включить звук",
	["Quitar esta meta"] = "Удалить эту цель",
	["Quitar este tramo"] = "Убрать этот этап",
	["Quitar filtros"] = "Сбросить фильтры",
	["Quitar la meta"] = "Убрать цель",
	["Quitar la niebla del horizonte"] = "Убрать туман на горизонте",
	["Quitar la prueba"] = "Завершить тест",
	["Quitar perjuicios"] = "Снимать отрицательные эффекты",
	["Quitar todos los filtros"] = "Убрать все фильтры",
	["Quién la da"] = "Кто выдает",
	["Quién la da, qué pide, qué te dan y qué necesitas antes."] = "Кто выдает, что требует, что дают и что нужно сначала.",
	["Quién tiene «%s»"] = "У кого есть «%s»",
	["Quién vende cañas y cebos. Se llenan al abrir la guía de pesca."] = "Кто продает удочки и приманки. Заполняется, когда вы открываете гайд по рыбалке.",
	["Qué es Alfa"] = "Что такое Alfa",
	["Qué estadísticas buscar"] = "Какие характеристики искать",
	["Qué estadísticas buscar y lo mejor que puedes usar en tu nivel."] = "Какие характеристики искать и лучшее, что вам доступно на вашем уровне.",
	["Qué está confirmado"] = "Что подтверждено",
	["Qué fabricar con lo que tienes"] = "Что создать из того, что есть",
	["Qué guardar"] = "Что убрать в банк",
	["Qué habilidad presionar ahora y cuáles siguen, avisos de reacción y el top de daño de tu grupo."] = "Какую способность нажать сейчас и какие дальше, оповещения о реакциях и топ урона группы.",
	["Qué habilidad presionar ahora, cuándo cortar, tu amenaza, tus recargas y el resumen de cada pelea."] = "Какую способность нажать сейчас, когда прерывать, твоя угроза, восстановление и итог каждого боя.",
	["Qué hace: %s"] = "Что дает: %s",
	["Qué hacer ahora, cerrar tus misiones y tus rutas propias."] = "Что делать сейчас, закрытие ваших заданий и ваши собственные маршруты.",
	["Qué hacer con ella"] = "Что с ним сделать",
	["Qué hacer con lo que llevas"] = "Что делать с тем, что при вас",
	["Qué hacías, qué esperabas y qué pasó. Si puedes, cómo hacer que vuelva a pasar."] = "Что вы делали, чего ожидали и что произошло. Если можете — как это повторить.",
	["Qué hay que hacer"] = "Что нужно сделать",
	["Qué lugar"] = "Какое место",
	["Qué me falta"] = "Чего мне не хватает",
	["Qué mensajes mostrar"] = "Какие сообщения показывать",
	["Qué muestran"] = "Что показывают",
	["Qué necesitas a tu nivel, paso a paso."] = "Что вам нужно на вашем уровне, шаг за шагом.",
	["Qué necesitas a tu nivel: equitación, oro y a quién ir."] = "Что вам нужно на вашем уровне: верховая езда, золото и к кому идти.",
	["Qué necesitas a tu nivel: la equitación, el oro, a quién ir y tu montura de clase."] = "Что вам нужно на вашем уровне: верховая езда, золото, к кому идти и ваш классовый транспорт.",
	["Qué nivel"] = "Какой уровень",
	["Qué pide"] = "Требования",
	["Qué presionar y en qué orden, avisos de reacción, la barra de golpe y el medidor de daño."] = "Что нажимать и в каком порядке, оповещения о реакциях, полоса удара и измеритель урона.",
	["Qué quieres buscar"] = "Что вы хотите найти",
	["Qué recolectar"] = "Что собирать",
	["Qué recolectar, fabricar o vender hoy."] = "Что собрать, создать или продать сегодня.",
	["Qué se pinta en tus mapas"] = "Что отображается на картах",
	["Qué se refleja en el agua: el cielo, el terreno y lo demás."] = "Что отражается в воде: небо, рельеф и все остальное.",
	["Qué se ve"] = "Что показывать",
	["Qué son"] = "Что это",
	["Qué son, cómo se gana cada uno, en qué se gastan y cuántos tienes."] = "Что это, как зарабатывается каждое, на что тратятся и сколько их у вас.",
	["Qué talento poner ahora y por qué, tu build en dos clics, tu árbol y tu equipo."] = "Какой талант взять сейчас и почему, ваш билд в два щелчка, ваше дерево и снаряжение.",
	["Qué talento poner y por qué, ayuda de rotación y el daño del grupo."] = "Какой талант взять и почему, помощник ротации и урон группы.",
	["Qué tan definidas se ven las sombras del mundo y de los personajes."] = "Насколько четкими выглядят тени мира и персонажей.",
	["Qué tan difíciles pueden ser las misiones que Alfa elige (siempre de las que ya puedes tomar)."] = "Насколько сложными могут быть задания, которые выбирает Alfa (всегда из тех, что уже можно взять).",
	["Qué tan grande escribe Lya en su globo. También con clic derecho sobre ella."] = "Насколько крупно пишет Лия в облачке. Также правым кликом по ней.",
	["Qué tan grande se ve Lya."] = "Насколько большой видна Lya.",
	["Qué tan grande se ve cada casilla."] = "Насколько крупно выглядит каждая ячейка.",
	["Qué tan grandes salen las que vienen después, comparadas con el ícono principal."] = "Насколько крупными будут следующие по сравнению с главным значком.",
	["Qué tan rápido se acerca y aleja la cámara."] = "Как быстро камера приближается и отдаляется.",
	["Qué tanto se ve el ícono mientras no peleas."] = "Насколько виден значок вне боя.",
	["Qué te gustaría que Alfa hiciera, o hiciera mejor, y para qué te serviría."] = "Что бы вы хотели, чтобы Alfa делал или делал лучше, и чем это вам поможет.",
	["Qué vender y qué conservar"] = "Что продать и что оставить",
	["Rama"] = "Ветка",
	["Rango %d de %d"] = "Ранг %d из %d",
	["Rango de honor %d"] = "PvP-звание %d",
	["Rango en tu hermandad:"] = "Звание в гильдии:",
	["Ranura vacía"] = "Пустая ячейка",
	["Ranura vacía:"] = "Пустая ячейка:",
	["Rapidez del doble clic"] = "Скорость двойного щелчка",
	["Raro"] = "Редкий",
	["Raro de la manada: %s"] = "Редкий стаи: %s",
	["Raro élite"] = "Редкий элитный",
	["Raros"] = "Редкие",
	["Raros con reloj"] = "Таймеры редких",
	["Raros de la manada"] = "Редкие стаи",
	["Raros de la manada: cuando un lobo encuentra un raro en tu zona, te avisa en qué guarida está, con «Ir de caza» o «Pedir entrar»."] = "Редкие стаи: когда волк находит редкого в твоей зоне, ты узнаёшь, в каком он логове, с кнопками «На охоту» или «Попроситься».",
	["Raros en el mapa"] = "Редкие на карте",
	["Raros en el minimapa"] = "Редкие на мини-карте",
	["Raros y tesoros"] = "Редкие и сокровища",
	["Rasganorte es el continente helado del norte. En su centro está la Corona de Hielo, el trono del Rey Exánime."] = "Нордскол — ледяной континент на севере. В его сердце — Ледяная Корона, трон Короля-лича.",
	["Rastreador propio y misiones que se liberan o se recogen en un clic."] = "Собственный трекер и задания, которые убираются или берутся в один щелчок.",
	["Ravenholdt, la casa de los pícaros, se esconde en las Montañas de Alterac."] = "Черный Ворон, дом разбойников, скрыт в Альтеракских горах.",
	["Ravenholdt, la mansión de los pícaros, se esconde en las montañas de Alterac. Si no te invitan, ni la buscas."] = "Поместье Черного Ворона, обитель разбойников, прячется в Альтеракских горах. Если тебя не пригласили — даже не ищи.",
	["Rayos de sol"] = "Солнечные лучи",
	["Rayos que dañan a quien te pegue. Mantenlo puesto."] = "Молнии, которые ранят того, кто бьет тебя. Держи их постоянно.",
	["Rayos y fuego desde lejos: mucho daño de golpe."] = "Молнии и огонь издалека: много урона разом.",
	["Razas"] = "Расы",
