	["Recolección"] = "Сбор",
	["Recolección te marca en el mapa y el minimapa las de tus profesiones, y recuerda dónde las encontraste."] = "«Сбор» отмечает на карте и миникарте нужное твоим профессиям и помнит, где ты это находил.",
