	["Recolectar"] = "Сбор",
	["Recolectar en zonas de tu nivel o un poco más bajas es más tranquilo: menos peleas, más nodos."] = "Собирать в зонах своего уровня или чуть ниже спокойнее: меньше боев, больше точек.",
	["Recomendada para ti"] = "Рекомендуем вам",
