	["Recomendado"] = "Рекомендуется",
	["Recomendado por Alfa"] = "Рекомендовано Alfa",
	["Recomienda el camino que te deja más oro, si gana por lo menos un 10 % a venderlo. Si nada da oro, te dice que lo guardes. Alfa nunca vende ni compra por ti."] = "Советует путь, который приносит больше всего золота, если он выгоднее продажи торговцу хотя бы на 10 %. Если ничего не приносит золота, советует оставить предмет. Alfa никогда не продает и не покупает за вас.",
	["Recompensa de misión"] = "Награда за задание",
