	["Recuperas maná incluso mientras peleas."] = "Вы восполняете ману даже во время боя.",
	["Recuperas mucho maná en unos segundos. Úsalo cuando estés casi vacío."] = "Восстанавливает много маны за несколько секунд. Применяй, когда она почти на нуле.",
	["Recuperas vida después de recibir críticos."] = "Вы восстанавливаете здоровье после получения критических ударов.",
