	["Revisa la lista antes de abandonar."] = "Проверьте список перед отказом.",
	["Revisa lo que elegiste. Cada cosa se cambia aquí con «Cambiar» o después en Ajustes."] = "Проверьте, что вы выбрали. Любой пункт можно изменить здесь кнопкой «Сменить» или позже в настройках.",
	["Revisa miles de misiones para elegir las que sí puedes tomar: tarda unos segundos."] = "Проверяет тысячи заданий, чтобы выбрать те, что вы действительно можете взять: это займет несколько секунд.",
	["Revisa tu equipo al subir de nivel: una mejora pequeña también cuenta."] = "Проверяй экипировку с каждым уровнем: даже небольшое улучшение важно.",
