	["Revive a un aliado en pleno combate. Tarda en volver a estar lista."] = "Возвращает союзника прямо посреди боя. Потом долго восстанавливается.",
	["Revivir"] = "Воскресить",
	["Rexxar, el señor de las bestias, recorre los caminos de Desolace con su osa Misha."] = "Рексар, повелитель зверей, бродит по дорогам Пустошей со своей медведицей Мишей.",
	["Rexxar, mitad orco y mitad ogro, es un señor de las bestias que ayudó a fundar Durotar. Siempre lo acompaña su osa Misha."] = "Рексар, наполовину орк, наполовину огр, — повелитель зверей, который помог основать Дуротар. С ним всегда его медведица Миша.",
	["Reír"] = "Смех",
	["Ritmo: %s XP por hora; subes de nivel en %s."] = "Темп: %s опыта в час; новый уровень через %s.",
	["Roba al enemigo sin que se dé cuenta. Hazlo en sigilo antes de atacar."] = "Обворуй врага незаметно. Делай это в незаметности перед атакой.",
	["Roble"] = "Дуб",
	["Rocal es el gran bastión de la Horda en el sur de los Reinos del Este."] = "Каменор — главный оплот Орды на юге Восточных королевств.",
	["Rocío de gloria de la mañana"] = "Роса ипомеи",
