	["Saca una captura en Tuercespina durante el concurso de pesca."] = "Поймайте рыбу в Тернистой долине во время рыболовного состязания.",
	["Sacarla"] = "Убрать",
	["Sacerdote"] = "Жрец",
	["Sagrado"] = "Свет",
	["Sagrado para subir"] = "Свет для прокачки",
	["Sal a explorar"] = "Иди исследовать",
	["Sal de combate y vuelve a intentarlo."] = "Выйдите из боя и попробуйте снова.",
	["Sal de tu grupo primero: el juego te pasa a la guarida de quien te invita."] = "Сначала выйди из группы: игра переносит тебя в логово того, кто пригласил.",
	["Sal de tu grupo primero: el juego te pasa al plano de quien te invita."] = "Сначала выйди из группы: игра переносит тебя в слой того, кто приглашает.",
	["Salchichas que le diste"] = "Сосиски, которые ты ей дал",
	["Sale de tu registro. Para hacerla otra vez tendrías que volver a pedirla."] = "Оно уйдет из журнала. Чтобы выполнить его снова, придется взять его заново.",
	["Sale en aguas abiertas; los datos del juego no dicen dónde. Tu diario lo anota cuando lo saques."] = "Ловится в открытой воде; данные игры не говорят где. Журнал запишет это, когда вы ее поймаете.",
	["Salen de tu registro. Para hacerlas otra vez tendrías que volver a pedirlas."] = "Они удалятся из журнала. Чтобы выполнить их снова, придется взять их заново.",
