	["Sanación"] = "Исцеление",
	["Sanador"] = "Лекарь",
	["Sangrado fuerte desde el nivel 13; lo necesitas para Heridas profundas."] = "Сильное кровотечение с 13 уровня; оно нужно для Глубоких ран.",
	["Sangrado fuerte; abre Heridas profundas."] = "Сильное кровотечение; открывает Глубокие раны.",
	["Sangre fría: tu siguiente remate es crítico seguro."] = "Хладнокровие: следующий завершающий прием гарантированно критический.",
	["Sapphiron, el dragón de escarcha de Naxxramas, fue un dragón azul antes de que la Plaga lo levantara."] = "Сапфирон, ледяной змей Наксрамаса, был синим драконом, пока Плеть его не подняла.",
	["Sargeras fue el gran campeón del Panteón. De tanto pelear contra demonios concluyó que la creación no tenía remedio, y fundó la Legión Ardiente."] = "Саргерас был великим защитником Пантеона. Сражаясь с демонами так долго, он решил, что творение не спасти, и основал Пылающий Легион.",
	["Sastrería"] = "Портняжное дело",
	["Sastrería hace tu ropa con lo que cae en mazmorras, y Encantamiento deshace lo que no usas y mejora tu equipo."] = "Портняжное дело шьет вам одежду из того, что падает в подземельях, а Наложение чар распыляет ненужное и улучшает вашу экипировку.",
	["Sastrería y Encantamiento: tu equipo siempre al día."] = "Портняжное дело и Наложение чар: ваша экипировка всегда актуальна.",
	["Scholomance, en la isla de Caer Darrow, es la escuela donde la Plaga enseña nigromancia. Antes fue el hogar de la familia Barov."] = "Некроситет на острове Каэр Дарроу — школа, где Плеть учит некромантии. Раньше это был дом семьи Баровых.",
	["Se abandona con «Abandonar marcadas», que pide confirmación."] = "От задания отказываются кнопкой «Отказаться от отмеченных», она запросит подтверждение.",
	["Se abre a nivel %d: te faltan %d niveles. Mientras, sigue tu ruta."] = "Открывается на %d-м уровне: осталось %d ур. А пока идите по маршруту.",
	["Se abre al salir de combate."] = "Откроется после выхода из боя.",
	["Se abre al terminar %s."] = "Открывается после %s.",
	["Se abren con la B. Elige la vista (todo junto, por categorías o por bolsa), busca por nombre o nivel y arrastra tus bolsas en su barra para cambiarlas."] = "Открываются клавишей B. Выберите вид (все вместе, по категориям или по сумкам), ищите по названию или уровню и перетаскивайте сумки на их панели, чтобы заменить.",
	["Se acabaron los textos cortados con «…» en Hoy, La Jauría, Buscar cerca y la Enciclopedia."] = "Больше никаких обрезанных «…» текстов в «Сегодня», La Jauría, «Найти рядом» и «Энциклопедии».",
	["Se acabó el aviso «Alfa_Builds se ha bloqueado…»: la ventana de talentos, el clic para lanzar y el Legado ahora los abre el juego, y tus hechizos se lanzan sin problema desde el libro."] = "Больше никакого сообщения «Alfa_Builds заблокирован…»: окно талантов, заклинания по щелчку и «Наследие» теперь открывает сама игра, а заклинания без проблем применяются из книги.",
	["Se acabó tu XP descansada"] = "Опыт за отдых закончился",
	["Se acelera a sí mismo y lanza rayos: interrúmpelo."] = "Ускоряет себя и бьет молниями: прерывайте его.",
	["Se acelera a sí mismo: interrúmpelo si puedes."] = "Ускоряет себя: прерывайте его, если можете.",
	["Se activó Claridad: tu siguiente hechizo es gratis."] = "Сработала Ясность мысли: следующее заклинание бесплатно.",
	["Se activó Claridad: tus Misiles arcanos salen gratis."] = "Сработала Ясность мысли: Чародейские стрелы бесплатны.",
	["Se activó Trance de las Sombras: tu Descarga de las Sombras es instantánea."] = "Сработал Теневой транс: Стрела Тьмы применяется мгновенно.",
	["Se agregó el sonido %d a tu lista."] = "Звук %d добавлен в ваш список.",
	["Se aplica al salir de combate."] = "Применится после выхода из боя.",
	["Se aprende con %s"] = "Изучается у: %s",
	["Se borra el progreso de mazmorras de este personaje. No se puede deshacer."] = "Прогресс подземелий этого персонажа будет удален. Отменить это нельзя.",
	["Se borran las sesiones guardadas de este personaje. La sesión de ahora sigue contando."] = "Сохраненные сеансы этого персонажа будут удалены. Текущий сеанс продолжит считаться.",
	["Se borran las sesiones, las zonas y los objetos de este personaje. No se puede deshacer."] = "Сеансы, зоны и предметы этого персонажа будут удалены. Отменить это нельзя.",
	["Se borran los %d marcadores de todos tus personajes. No se puede deshacer."] = "Удаляются все маркеры (%d) у всех ваших персонажей. Отменить нельзя.",
	["Se borran los jefes vencidos, las veces completada y el botín anotado de %s para este personaje."] = "Будут удалены побежденные боссы, число прохождений и записанная добыча (%s) для этого персонажа.",
	["Se borran los precios guardados de la subasta de este reino y facción. Tus recetas se quedan."] = "Сохраненные аукционные цены этого игрового мира и фракции будут удалены. Ваши рецепты останутся.",
	["Se borran todas las peleas guardadas, también en la ventana del medidor del juego."] = "Удаляются все сохраненные бои, в том числе в окне игрового измерителя.",
	["Se borran tus sesiones, tu diario, tus logros y tus metas de este personaje. Tu habilidad de pesca no cambia."] = "Удаляются сеансы, журнал, достижения и цели этого персонажа. Навык рыбной ловли не меняется.",
	["Se carga al salir de combate"] = "Загрузится после выхода из боя",
	["Se cerró el buzón antes de terminar."] = "Почтовый ящик закрылся раньше времени.",
	["Se cerró la subasta antes de recibir los precios. Vuelve a intentarlo después."] = "Аукцион закрылся до получения цен. Попробуйте позже.",
	["Se cerró la ventana de clic para lanzar de Blizzard. Vuelve a pulsar «Abrir clic para lanzar» para abrirla."] = "Окно заклинаний по щелчку Blizzard закрылось. Снова нажмите «Открыть заклинания по щелчку», чтобы открыть его.",
	["Se cumple al llegar a ese nivel."] = "Выполняется при достижении этого уровня.",
	["Se cura a sí mismo: interrumpe su curación."] = "Лечит себя: прерывайте его лечение.",
	["Se cura comiendo: mátenlo rápido."] = "Лечится едой: убейте его быстро.",
	["Se cura: interrúmpelo."] = "Лечит себя: прерывайте его.",
	["Se descubren todos los jefes de %s, como si la hubieras terminado. Si te equivocas, puedes olvidar tu progreso aquí."] = "Открываются все боссы подземелья %s, как если бы вы его прошли. Если это ошибка, прогресс можно сбросить здесь.",
	["Se detuvo al cerrar el banco: guardaste %d y faltaron %d."] = "Остановлено при закрытии банка: положено %d, осталось %d.",
	["Se detuvo al entrar en combate: guardaste %d y faltaron %d."] = "Остановлено с началом боя: положено %d, осталось %d.",
	["Se enciende cuando el enemigo esquiva: pega fuerte y no se puede esquivar. Úsalo en cuanto brille."] = "Загорается, когда враг уклоняется: бьет сильно, и от него не уклониться. Применяй, как только засветится.",
	["Se enciende tras bloquear, esquivar o parar. Barato y con mucha amenaza: el favorito del tanque."] = "Загорается после блока, уклонения или парирования. Дешево и много угрозы: любимец танков.",
	["Se enfurece al final: guarden su mejor daño."] = "В конце впадает в ярость: приберегите самый сильный урон.",
	["Se enfurece con poca vida: termínenlo rápido."] = "При малом запасе здоровья впадает в ярость: добейте его быстро.",
	["Se enfurece y pega más fuerte con el tiempo: mátenlo rápido."] = "Со временем злится и бьет сильнее: убейте его быстро.",
	["Se entrega con %s"] = "Сдать: %s",
	["Se entrega dentro"] = "Сдается внутри",
	["Se escapó"] = "Сорвалась",
	["Se fabrica"] = "Создается",
	["Se marcan como chatarra"] = "Отмечаются как хлам",
	["Se me antoja un buen filete de jabalí. Solo digo."] = "Так хочется кабаньего стейка. Просто говорю.",
	["Se pelea bajo el agua: vigila tu barra de respiración y sube a tomar aire si hace falta."] = "Бой идет под водой: следите за полосой дыхания и всплывайте за воздухом, если нужно.",
	["Se pesca"] = "Ловится",
	["Se protege con su escudo y aturde: ataquen a los otros dos primero."] = "Закрывается щитом и оглушает: сначала атакуйте двух других.",
	["Se puede al salir de combate."] = "Можно после выхода из боя.",
	["Se puede anunciar al salir de combate."] = "Объявить можно после выхода из боя.",
	["Se puede enviar ahora: %s"] = "Можно отправлять сейчас: %s",
	["Se pueden conseguir"] = "Можно получить",
	["Se pusieron %d ajustes. Algunas cosas se ven completas al recargar."] = "Применено настроек: %d. Кое-что полностью появится после перезагрузки.",
	["Se pusieron %d ajustes. Las líneas que no eran válidas (%d) se dejaron fuera."] = "Применено настроек: %d. Неверные строки (%d) пропущены.",
	["Se pusieron %d de %d opciones"] = "Установлено параметров: %d из %d",
	["Se queda en el modo limpio."] = "Остается в чистом режиме.",
	["Se quita %s de tu lista de compras."] = "%s удален из списка покупок.",
	["Se quita de tu lista. Si lo necesitas otra vez, vuelve a importar su cadena."] = "Он будет убран из вашего списка. Если понадобится снова, импортируйте его строку еще раз.",
	["Se quitan los nodos que anotaste al recolectar y cuántas veces los recolectaste. La base incluida se queda. No se puede deshacer."] = "Удаляются узлы, которые вы записали при сборе, и сколько раз вы их собирали. Встроенная база остается. Отменить нельзя.",
	["Se quitan todas las metas. Tus objetos no se tocan."] = "Все цели удаляются. Твои предметы не трогаются.",
	["Se quitó el sonido %d de tu lista."] = "Звук %d убран из вашего списка.",
	["Se saltan (no están en tu árbol): %s."] = "Пропускаются (нет в вашем дереве): %s.",
	["Se teletransporta a las orillas de la sala: si peleas cuerpo a cuerpo, síguelo."] = "Телепортируется к краям зала: если сражаетесь в ближнем бою, следуйте за ним.",
	["Se toma dentro de la mazmorra: ahí la verás."] = "Берется внутри подземелья: там вы его увидите.",
	["Se ve completo al recargar."] = "Покажется полностью после перезагрузки.",
	["Se ve después de reiniciar los gráficos."] = "Будет видно после перезапуска графики.",
	["Se vende ahora"] = "Продается сейчас",
	["Se vende en"] = "Продается у",
	["Se vende en %s cada uno."] = "Продается по %s за штуку.",
	["Seccionar puede inmovilizar al rival: no se te escapa."] = "Подрезать сухожилия может обездвижить противника: он не сбежит.",
	["Seccionar puede inmovilizar: nadie se te escapa para traer amigos."] = "Подрезать сухожилия может обездвижить: никто не сбежит за подмогой.",
	["Secundaria"] = "Второстепенная",
	["Secundaria [mano]"] = "Левая рука",
	["Secundario: no cuenta en tus dos"] = "Вторичная: не входит в твои две",
	["Sed de sangre: tu golpe más fuerte, cada vez que esté listo."] = "Жажда крови: ваш самый сильный удар, применяйте при каждой готовности.",
	["Seguimiento"] = "Следование",
	["Seguir"] = "Следовать",
	["Seguir (flecha y ruta)"] = "Следовать (стрелка и маршрут)",
	["Seguir a %s"] = "Следовать за: %s",
	["Seguir con %s"] = "Продолжить: %s",
	["Seguir el terreno"] = "Следовать рельефу",
	["Seguir esta guía"] = "Следовать этому гайду",
	["Seguir esta ruta"] = "Идти по этому маршруту",
	["Seguir este build"] = "Следовать этому билду",
	["Seguir este plan"] = "Следовать этому плану",
	["Seguir jugando"] = "Продолжить игру",
	["Seguir muestra tu guía y la flecha, y cierra esta ventana para que las veas."] = "«Следовать» показывает гайд и стрелку и закрывает это окно, чтобы их было видно.",
	["Seguir por aquí"] = "Идти сюда",
	["Seguir ruta"] = "Идти по маршруту",
	["Seguir sola con la siguiente guía"] = "Сам переходить к следующему гайду",
	["Seguir un build de %s"] = "Следовать билду: %s",
	["Segundos junto a la barra"] = "Секунды рядом с полосой",
	["Según su leyenda, los jabaespines nacieron de la sangre de Agamaggan, el gran jabalí semidiós. Por eso viven entre espinas gigantes."] = "По легенде, свинобразы родились из крови Агамаггана, великого полубога-вепря. Поэтому они живут среди гигантских шипов.",
	["Seleccionar objetivo"] = "Выбрать цель",
	["Seleccionar para copiar"] = "Выделить для копирования",
	["Seleccionar todo"] = "Выбрать все",
	["Seleccionarlo"] = "Выбрать цель",
	["Sello"] = "Печать",
	["Semilla de Tuercespina"] = "Семя Тернистой долины",
	["Semilla de arce"] = "Семя клена",
	["Semilla de carpe"] = "Семя граба",
	["Semilla de fresno"] = "Семя ясеня",
	["Semilla de palo de hierro"] = "Семя железного дерева",
	["Sencillo"] = "Простой",
	["Sencillo: solo Hoy, Ruta, Mapa, Bolsas y Lya a la vista, y menos avisos. Completo: todo Alfa. Lo demás sigue funcionando."] = "Простой: на виду только «Сегодня», «Маршрут», «Карта», «Сумки» и Лия, и меньше напоминаний. Полный: весь Alfa. Остальное продолжает работать.",
	["Sepia"] = "Сепия",
	["Servicio"] = "Услуга",
	["Servicios"] = "Услуги",
	["Servicios en el minimapa"] = "Услуги на мини-карте",
	["Será una mejora más adelante"] = "Станет улучшением позже",
	["Sesiones anteriores"] = "Прошлые сеансы",
	["Sesiones que guarda el diario"] = "Сколько сеансов хранит дневник",
	["Sesiones, diario, logros y metas de este personaje. No se puede deshacer."] = "Сеансы, журнал, достижения и цели этого персонажа. Отменить нельзя.",
	["Sesión de pesca nueva."] = "Новый сеанс рыбалки.",
	["Señalar"] = "Указать",
	["Señor de las aguas"] = "Повелитель вод",
	["Si Toxic, el fundador de La Jauría, anda cerca, Alfa te avisa para que lo saludes."] = "Если Toxic, основатель La Jauría, рядом, Alfa скажет, чтобы ты мог поздороваться.",
	["Si aguantas bien, usa Golpe heroico con la ira sobrante para más amenaza."] = "Если держитесь хорошо, тратьте лишнюю ярость на Удар героя ради угрозы.",
	["Si algo sale mal, tu habilidad para desaparecer te saca de la pelea. Úsala antes de que sea tarde."] = "Если что-то пошло не так, умение исчезать вытащит тебя из боя. Используй его, пока не поздно.",
	["Si alguien de la manada te pasa uno, impórtalo y Alfa te guía con él punto por punto."] = "Если кто-то из стаи даст вам билд, импортируйте его, и Alfa проведет вас по нему очко за очком.",
	["Si alguien de tu grupo también trae Alfa, nuestras Lyas se saludan al juntarse y a veces platican. Es poquito y nunca en combate. Se apaga en mi página: «Lya y su manada»."] = "Если у кого-то в группе тоже есть Alfa, наши Лии здороваются при встрече и иногда болтают. Немножко и никогда в бою. Выключается на моей странице: «Лия и ее стая».",
	["Si alguien de tu grupo también trae Alfa, sus Lyas se saludan y a veces platican. Poquito y nunca en combate."] = "Если у кого-то в группе тоже есть Alfa, ваши Лии здороваются и иногда болтают. Немножко и никогда в бою.",
	["Si alguien huye, puede traer a más presos: deténganlo con un ataque que lo frene."] = "Если кто-то убегает, он может привести еще заключенных: остановите его замедляющей атакой.",
	["Si alguna vez ves salchichas en una posada, guárdame una… o dos."] = "Если увидишь сосиски в таверне, оставь мне одну… или две.",
	["Si bajas por el Gran Elevador, verás por qué se llama así: cientos de agujas de roca."] = "Если спуститься на Великом подъемнике, поймешь, откуда название: сотни каменных игл.",
	["Si casi todo lo que vas a entregar está en el pueblo de tu piedra y estás lejos, Lya te lo dice."] = "Если почти все, что нужно сдать, — в городе твоего камня, а ты далеко, Лия скажет.",
	["Si cierras tres veces el mismo tipo de consejo, Lya te pregunta si ya no quieres que te lo diga."] = "Если трижды закрыть совет одного вида, Лия спросит, не перестать ли его говорить.",
	["Si en estas fechas ves calabazas en las posadas, es Halloween: los posaderos te dan dulces con truco o trato, y a veces un disfraz."] = "Если в это время видишь тыквы в тавернах — это Тыквовин: трактирщики дают сладости за «сладость или гадость», а иногда и костюм.",
	["Si en estas fechas ves faroles y fuegos artificiales, es el Festival Lunar: visita a los Ancestros por el mundo, que cada uno te da una moneda."] = "Если в это время видишь фонари и фейерверки — это Лунный фестиваль: навести Старейшин по всему миру, каждый даст монету.",
	["Si en febrero las ciudades huelen a perfume, es «Amor en el aire»: la gente reparte regalos y hasta los guardias reciben detalles."] = "Если в феврале города пахнут духами — это «Любовная лихорадка»: люди дарят подарки, и даже стражникам что-то перепадает.",
	["Si encuentras un hueso, es mío. ¿Trato hecho?"] = "Найдёшь косточку — она моя. Договорились?",
	["Si eres desollador, las zonas llenas de bestias, como raptores, kodos o felinos, te dan cuero sin parar."] = "Если ты снимаешь шкуры, зоны, полные зверей — ящеров, кодо или кошек, — дают кожу без конца.",
	["Si está fuera de tu alcance, su marco se ve más tenue."] = "Если союзник вне досягаемости, его рамка выглядит бледнее.",
	["Si estás en combate, espera a que termine."] = "Если ты в бою, подожди его окончания.",
	["Si fabricas para otros, cobra justo: la gente vuelve y te recomienda."] = "Если мастеришь для других, бери честную цену: люди вернутся и порекомендуют тебя.",
	["Si hay fiesta te lo digo al entrar. Y según la hora y la zona te cuento lo que pasa por ahí."] = "Если сегодня праздник, скажу тебе при входе. А в зависимости от времени и зоны расскажу, что происходит вокруг.",
	["Si hoy cuesta, mañana sale. Aquí sigo contigo."] = "Если сегодня трудно, завтра получится. Я все еще с тобой.",
	["Si juegas sin grupo, la ventana se esconde."] = "Если вы играете без группы, окно скрывается.",
	["Si la abandonas, pierdes la cadena: después sigue “%s”."] = "Если отменишь его, потеряешь цепочку: дальше идет «%s».",
	["Si la pelea va mal, desvanécete y vuelve a empezar."] = "Если бой идет плохо, используйте Исчезновение и начните заново.",
	["Si la recompensa tiene varias opciones, eliges tú."] = "Если в награде несколько вариантов, выбираете вы.",
	["Si la terminas"] = "Если пройдете его",
	["Si la vida baja de la mitad y el sanador no llega, usa Último recurso."] = "Если здоровье упало ниже половины, а лекарь не успевает, используйте «Ни шагу назад».",
	["Si le dices «Ya no» a un consejo, sale aquí para que puedas devolverlo cuando quieras."] = "Если сказать «Хватит» какому-то совету, он появится здесь, и его можно вернуть когда угодно.",
	["Si le haces el gesto de gallina a una gallina de granja muchas veces, a veces te pide ayuda... y la historia termina en mascota."] = "Если много раз показать фермерской курице эмоцию «курица», иногда она просит о помощи... и история заканчивается питомцем.",
	["Si levantas algo que se puede regalar y le sirve a un lobo conectado, Alfa te lo dice con «Regalárselo»."] = "Если поднимешь то, что можно подарить и что пригодится волку в сети, Alfa подскажет кнопкой «Подарить».",
	["Si llega a 0 % se rompe y deja de darte sus estadísticas. Repara cuanto antes con un herrero o un vendedor que repare."] = "При 0 % вещь ломается и перестаёт давать свои характеристики. Почините её как можно скорее у кузнеца или торговца, который чинит.",
	["Si llegas a exaltado con otra raza de tu bando, te venden sus monturas. ¡Un kodo para un orco o un sable de la noche para un humano!"] = "Если достичь превознесения у другой расы своей фракции, тебе продадут их транспорт. Кодо для орка или ночной саблезуб для человека!",
	["Si llevas puesto el abalorio del Alba Argenta, los no-muertos de las Tierras de la Peste sueltan piedras que cambias por reputación y fichas."] = "Если надет аксессуар Серебряного Рассвета, нежить Чумных земель роняет камни, которые меняют на репутацию и жетоны.",
	["Si lo que te dan mejora tu equipo, te lo pones al salir de combate."] = "Если полученное улучшает экипировку, вы наденете это после выхода из боя.",
	["Si moviste los avisos y ya no los encuentras."] = "Если вы передвинули оповещения и не можете их найти.",
	["Si mueres seguido, cambia al estilo Tranquilo."] = "Если часто умираете, перейдите на стиль «Спокойно».",
	["Si necesitas silencio, con clic derecho me callas un rato."] = "Если нужна тишина, щёлкни по мне правой кнопкой — я ненадолго замолчу.",
	["Si no eres druida, al Claro de la Luna se llega por los túneles de los Fauces de Madera, desde Frondavil."] = "Если ты не друид, на Лунную поляну можно пройти через туннели Древобрюхих из Оскверненного леса.",
	["Si no eres tanque: con cuánta amenaza se pone amarilla."] = "Если ты не танк: при какой угрозе полоса желтеет.",
	["Si no tienes ninguna abierta, abre la recomendada para tu nivel."] = "Если ни один не открыт, открывает рекомендуемый для вашего уровня.",
	["Si nos perdemos en %s, tú lees el mapa y yo sigo el rastro."] = "Если мы заблудимся в %s, ты читаешь карту, а я иду по следу.",
	["Si peleas de lejos, quédate lejos de ella."] = "Если сражаетесь на расстоянии, держитесь от нее подальше.",
	["Si quieres matar más rápido en solitario, cambia a Armas cuando tengas oro para reiniciar."] = "Если хотите быстрее убивать в одиночку, перейдите на Оружие, когда будет золото на сброс талантов.",
	["Si quieres, tu personaje aparece en el mapa del juego de los lobos que usan Alfa, y ellos en el tuyo: quién anda cerca, dónde y, con un clic, la flecha te lleva. Solo es el lugar de tu personaje dentro de WoW, nunca tu ubicación real. Tu grupo se ve siempre."] = "Если хотите, ваш персонаж появится на карте игры у волков, которые пользуются Alfa, а они — на вашей: кто рядом, где, и одним щелчком стрелка ведет к ним. Это только место персонажа в WoW, никогда ваше реальное местоположение. Ваша группа видна всегда.",
	["Si sigues el consejo"] = "Если последовать совету",
	["Si sigues la cadena del mariscal Windsor, en Ventormenta destaparás quién es en realidad Lady Prestor."] = "Если пройти цепочку маршала Виндзора, в Штормграде ты разоблачишь, кто на самом деле леди Престор.",
	["Si sigues la historia del Templo Sumergido, en el pantano te espera Itharius, un dragón verde."] = "Если следовать истории Затонувшего храма, на болоте тебя ждет Итариус, зеленый дракон.",
	["Si sigues los consejos"] = "Если следовать советам",
	["Si sigues los consejos ganas %s"] = "Если следовать советам, вы получите %s",
	["Si sueltan poco, no te desesperes. Pasa en toda buena caza."] = "Если выпадает мало, не отчаивайся. Так бывает на любой хорошей охоте.",
	["Si te alcanzan, usa tus golpes cuerpo a cuerpo y aléjate otra vez."] = "Если вас догнали, используйте удары ближнего боя и снова отойдите.",
	["Si te baja mucho la vida, cambia a actitud defensiva: tu ira no se pierde."] = "Если здоровье сильно упало, перейдите в Оборонительную стойку: ярость не теряется.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su guarida al rato."] = "Если тебя пригласят в группу, прими кнопкой игры: вскоре игра перенесёт тебя в их логово.",
	["Si te invitan a su grupo, acepta con el botón del juego: el juego te pasa a su plano al rato."] = "Если тебя пригласят в группу, прими кнопкой игры: вскоре игра перенесет тебя в их слой.",
	["Si te llega equipo mejor que lo que llevas, te aviso con «Ponte esto» y un botón para ponértelo. Solo con tu clic, y nunca en combate."] = "Если тебе попадется снаряжение лучше надетого, я скажу «Надень это» и дам кнопку. Только по твоему щелчку и никогда в бою.",
	["Si te pegan mientras te vendas, se corta: aléjate un poco antes de usarla."] = "Если тебя ударят во время перевязки, она прервется: отойди немного, прежде чем ее использовать.",
	["Si te quedas sin lanzar"] = "Если вы перестали забрасывать",
	["Si te sobra un pedacito de carne, aquí hay una panza que lo recibe con gusto."] = "Если у тебя лишний кусочек мяса, тут есть животик, который с радостью его примет.",
	["Si tienes poco tiempo, si no tienes con quién jugar o quién te ayude, puedes apoyarte en Alfa y en Lya en tu travesía."] = "Если у вас мало времени, не с кем играть или некому помочь, в пути можно положиться на Alfa и Lya.",
	["Si tu caña no tiene cebo, tu tecla pone el mejor que tengas (o el que prefieras) antes de lanzar."] = "Если на удочке нет приманки, клавиша перед забросом наложит лучшую из имеющихся (или любимую).",
	["Si tu clase lo puede quitar, su marco se pinta del color del perjuicio y sale su ícono arriba a la derecha. Pasa el ratón y te digo con qué clic se quita; si ningún clic lo hace, elígelo en «Tus clics»."] = "Если твой класс может это снять, рамка окрасится в цвет эффекта, а справа вверху появится его значок. Наведи курсор, и я скажу, каким щелчком снять; если ни одним — выбери его в «Ваши щелчки».",
	["Si tu objetivo es un jugador, su fondo toma el color de su clase en lugar del de su reacción."] = "Если ваша цель — игрок, ее фон окрашивается в цвет класса, а не в цвет отношения.",
	["Si tu plano se llena de cazadores, Lya te propone pasarte al de un lobo de la manada con su guarida abierta. Una vez cada 15 minutos."] = "Если твой слой заполнится охотниками, Лия предложит перейти в слой волка из стаи с открытым логовом. Раз в 15 минут.",
	["Si tu rango lo permite, la hermandad paga y tu dinero pone el resto."] = "Если звание позволяет, платит гильдия, а остальное — из ваших денег.",
	["Si tú o tus personajes pueden"] = "Если можете вы или ваши персонажи",
	["Si un día ganamos mucho oro, yo ya sé en qué gastarlo: salchichas."] = "Если мы когда-нибудь заработаем много золота, я уже знаю, на что его потратить: на сосиски.",
	["Si un enemigo te persigue, no corras: acércate al tanque."] = "Если противник гонится за вами, не убегайте: подойдите к танку.",
	["Si un enemigo viene hacia ti, llévalo hacia el tanque: no corras lejos."] = "Если противник идет на вас, ведите его к танку: не убегайте далеко.",
	["Si un lobo de tu hermandad busca un objeto que llevas, Alfa le dice cuántos tienes. Solo eso y solo cuando pregunta."] = "Если волк твоей гильдии ищет предмет, который есть у тебя, Alfa скажет ему, сколько у тебя. Только это и только по запросу.",
	["Si un lugar está lleno de jugadores farmeando lo mismo, cámbiate de zona: te rinde más."] = "Если место забито игроками, которые фармят то же самое, смени зону: выйдет выгоднее.",
	["Si un monstruo esquiva, usa Abrumar enseguida (Alfa te avisa)."] = "Если монстр уклонился, сразу используйте Превосходство (Alfa подскажет).",
	["Si una misión se pone difícil, pide ayuda en el chat. En manada todo pesa menos."] = "Если задание стало трудным, попроси помощи в чате. В стае все легче.",
	["Si una subasta no se vende, pierdes el depósito: no pongas precios fuera de la realidad."] = "Если лот на аукционе не продастся, ты теряешь залог: не ставь нереальные цены.",
	["Si vendes todo al comerciante"] = "Если продать все торговцу",
	["Si ves a otro lobo por ahí, salúdalo de mi parte."] = "Если увидишь где-нибудь другого волка, передай ему привет от меня.",
	["Si ves carpas de colores en Villadorada o en Mulgore, llegó la Feria de la Luna Negra: hay juegos, premios y cartas que se juntan en mazos."] = "Если в Златоземье или Мулгоре видишь пестрые шатры — приехала Ярмарка Новолуния: игры, призы и карты, которые собирают в колоды.",
	["Si viajas con un mago, pídele un portal a la capital: te ahorra mucho camino."] = "Если путешествуешь с магом, попроси портал в столицу: сэкономишь много дороги.",
	["Siempre"] = "Всегда",
	["Siempre con cebo"] = "Всегда с приманкой",
	["Siempre: te ofrece la historia de cada misión y un dato de cada zona nueva. A veces: de las misiones que tomas sin leer, y no siempre. Solo si le pido: con clic derecho, «Cuéntame algo de aquí». Las historias se guardan igual."] = "Всегда: предлагает историю каждого задания и факт о каждой новой зоне. Иногда: о заданиях, которые вы берете не читая, и не каждый раз. Только по просьбе: правый щелчок, «Расскажи что-нибудь об этом месте». Истории сохраняются в любом случае.",
	["Siete días de caza contigo. Esto ya es costumbre, y me encanta."] = "Семь дней охоты с тобой. Это уже привычка, и я ее обожаю.",
	["Sigilo"] = "Незаметность",
	["Sigilo y emboscadas: tú eliges cuándo pelear y desapareces cuando quieres."] = "Незаметность и засады: вы сами выбираете, когда сражаться, и исчезаете, когда хотите.",
	["Siglos después de la División, los Altonato que no soltaban la magia arcana fueron desterrados. Cruzaron el mar y fundaron Quel'Thalas: son los altos elfos."] = "Через века после Раскола высокорожденных, не желавших отказаться от тайной магии, изгнали. Они пересекли море и основали Кель'Талас: это высшие эльфы.",
	["Siglos después, los orcos Faucedraco usaron el Alma de Demonio para tener presa a Alexstrasza y criar dragones de guerra para la Horda."] = "Века спустя орки Драконьей Пасти с помощью Души Демона держали Алекстразу в плену и разводили боевых драконов для Орды.",
	["Sigue a tu lado, pero no habla hasta las %s."] = "Она все еще рядом, но молчит до %s.",
	["Sigue a tu lado, pero no habla por un rato."] = "Она все еще рядом, но какое-то время молчит.",
	["Sigue con los pasos de la guía"] = "Продолжай по шагам гида",
	["Sigue donde ibas"] = "Продолжите, где остановились",
	["Sigue la flecha."] = "Следуйте за стрелкой.",
	["Sigue la flecha: las paradas van en el orden más corto, juntas por PNJ."] = "Следуйте за стрелкой: остановки идут в самом коротком порядке, по NPC.",
	["Sigue subiendo: %d de %d"] = "Продолжайте качать: %d из %d",
	["Sigue tu guía"] = "Следуй гиду",
	["Sigue: %s"] = "Далее: %s",
	["Sigue: %s. Lee sus consejos antes de la pelea."] = "Далее: %s. Прочтите советы перед боем.",
	["Sigues a %s"] = "Вы следуете: %s",
	["Sigues con tu equipo de pesca."] = "На вас все еще рыболовное снаряжение.",
	["Siguiendo"] = "Следование",
	["Siguiendo a %s."] = "Вы следуете за %s.",
	["Siguiendo el rastro"] = "Идем по следу",
	["Siguiendo el rastro de %s. La flecha te lleva hasta su posición."] = "Идем по следу: %s. Стрелка ведет вас к этому игроку.",
	["Siguiendo tu ruta de %s"] = "Идем по маршруту: %s",
	["Siguiente"] = "Далее",
	["Siguiente lugar"] = "Следующее место",
	["Siguiente parada:"] = "Следующая остановка:",
	["Siguiente paso de la guía"] = "Следующий шаг гайда",
	["Siguiente rango: %s"] = "Следующая ступень: %s",
	["Siguiente: %s (%d de %d)"] = "Далее: %s (%d из %d)",
	["Silencia los sonidos que agregues por su número de archivo (FileDataID): /alfa silenciar <número>; /alfa silenciar quitar <número> lo quita."] = "Заглушает звуки, которые вы добавите по номеру файла (FileDataID): /alfa silenciar <номер>; /alfa silenciar quitar <номер> убирает его.",
	["Silenciar 1 hora"] = "Отключить звук на 1 час",
	["Silenciar sonidos"] = "Заглушить звуки",
	["Silenciar un sonido por su número (FileDataID)"] = "Заглушить звук по номеру (FileDataID)",
	["Silithus es la puerta de Ahn'Qiraj, donde los silítidos y los qiraji sirven al dios antiguo C'Thun."] = "Силитус — врата Ан'Киража, где силитиды и киражи служат Древнему богу К'Туну.",
	["Sin Minería no ves filones; sin Herboristería, hierbas; sin Pesca, bancos. Los tesoros siempre se ven."] = "Без горного дела не видны жилы, без травничества — травы, без рыбной ловли — косяки. Сокровища видны всегда.",
	["Sin Pesca"] = "Без рыбной ловли",
	["Sin XP descansada"] = "Нет опыта за отдых",
	["Sin acción"] = "Без действия",
	["Sin activar"] = "Выключено",
	["Sin aprender"] = "Не изучено",
	["Sin aullido"] = "Без воя",
	["Sin bloqueos y más claro"] = "Без блокировок и понятнее",
	["Sin cadena"] = "Без цепочки",
	["Sin cambiar de forma."] = "Вы не в облике.",
	["Sin cambios"] = "Без изменений",
	["Sin consejos para este jefe: vayan con calma y escuchen al tanque."] = "Для этого босса советов нет: не спеши и слушай танка.",
	["Sin datos"] = "Нет данных",
	["Sin demonio"] = "Нет демона",
	["Sin el ratón encima, la barra guarda sus botones y deja solo lo que pasa."] = "Без курсора над ней полоса прячет кнопки и показывает только происходящее.",
	["Sin encantar"] = "Не зачаровано",
	["Sin fuente conocida"] = "Источник неизвестен",
	["Sin grupo"] = "Без группы",
	["Sin historial todavía."] = "Истории пока нет.",
	["Sin límite de tiempo"] = "Без ограничения по времени",
	["Sin mascota"] = "Нет питомца",
	["Sin metas todavía"] = "Целей пока нет",
	["Sin metas todavía. Pulsa + para ponerte una: un pez, capturas, tiempo o valor."] = "Целей пока нет. Нажмите +, чтобы поставить: рыба, улов, время или стоимость.",
	["Sin metas todavía: ábrelo y agrégale una."] = "Целей пока нет: откройте его и добавьте цель.",
	["Sin munición"] = "Нет боеприпасов",
	["Sin objeto"] = "Без предмета",
	["Sin otros personajes, uno solo puede ganar 29: 3 por subir de nivel, 6 de profesiones, 12 de JcJ, 2 de aventura y 6 de mazmorras y bandas. El resto sale de subir otras clases."] = "Без других персонажей один может заработать 29: 3 за уровни, 6 за профессии, 12 за PvP, 2 за приключения и 6 за подземелья и рейды. Остальное — за прокачку других классов.",
	["Sin precio todavía: escanea la subasta."] = "Цены пока нет: просканируйте аукцион.",
	["Sin precios"] = "Нет цен",
	["Sin precios todavía"] = "Цен пока нет",
	["Sin profesión"] = "Без профессии",
	["Sin sello"] = "Нет печати",
	["Sin tecla"] = "Без клавиши",
	["Sin tener una tecla abajo: lo prendes o lo apagas con su atajo, o aquí."] = "Не удерживая клавишу: включай и выключай горячей клавишей или здесь.",
	["Sin tinte"] = "Без оттенка",
	["Sin ubicación"] = "Нет местоположения",
	["Sin ubicación ahora: en una instancia o fuera del mapa"] = "Сейчас нет местоположения: в подземелье или вне карты",
	["Sin veneno"] = "Нет яда",
	["Sin zona"] = "Без зоны",
	["Sobre Lya"] = "О Lya",
	["Sobre tu compañero, este clic %s."] = "На союзнике этот щелчок %s.",
	["Solo %s"] = "Только %s",
	["Solo al acabarse"] = "Только когда закончится",
	["Solo al moverte"] = "Только в движении",
	["Solo buffs"] = "Только баффы",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Только с теми, кто пользуется Alfa и согласился делиться. Решаете вы.",
	["Solo cuando estás en grupo"] = "Только в группе",
	["Solo cuando te llame"] = "Только когда позову",
	["Solo el botín que me sirve"] = "Только подходящая мне добыча",
	["Solo ellos: tú no la tienes."] = "Только у них: у тебя его нет.",
	["Solo en una fiesta del año"] = "Только во время ежегодного праздника",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "Только на warcraft.wiki.gg и Icy Veins: сколько очков нужно для каждой награды (15, 25, 40 и 55). Ни один источник не публикует, сколько стоит каждый ранг деревьев: смотрите в окне «Наследия».",
	["Solo encontré %d misiones que te sirvan ahora."] = "Сейчас подходящих заданий найдено только: %d.",
	["Solo hay que llevar el recado. ¡Fácil, como pedirme una salchicha!"] = "Нужно только отнести весточку. Легко, как выпросить у меня сосиску!",
	["Solo importantes"] = "Только важные",
	["Solo la entrada"] = "Только вход",
	["Solo las misiones de tu ruta"] = "Только задания вашего маршрута",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "Только те, что можно взять: ваша фракция, раса, класс и уровень, и еще не выполненные.",
	["Solo lo de mi papel"] = "Только для моей роли",
	["Solo lo esencial a la vista. Las barras y retratos se esconden al terminar el combate."] = "На виду только главное. Панели и портреты спрячутся после боя.",
	["Solo lo esencial a la vista. Pulsa tu tecla otra vez para ver todo."] = "На виду только главное. Нажми клавишу еще раз, чтобы увидеть все.",
	["Solo lo esencial a la vista: Hoy, Ruta, Mapa, Bolsas y Lya, y menos avisos. Lo demás sigue ahí cuando lo busques."] = "На виду только главное: «Сегодня», «Маршрут», «Карта», «Сумки» и Лия, и меньше напоминаний. Остальное на месте, когда понадобится.",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "Только то, что может использовать ваш класс и что подходит вашей специализации.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "Только то, что ваш персонаж может использовать сегодня: класс, доспехи, оружие, уровень и профессия.",
	["Solo lo que ya puedes recolectar"] = "Только то, что уже можете собрать",
	["Solo los consejos importantes"] = "Только важные советы",
	["Solo los de la zona donde estás."] = "Только те, что в вашей текущей зоне.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "Только для ваших профессий, на карте мира и мини-карте.",
	["Solo los graves"] = "Только серьезные",
	["Solo los que me apuntan a mí"] = "Только направленные на меня",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "Только задания на опыт, лучшие рядом с вами, в три захода.",
	["Solo para %s."] = "Только для: %s.",
	["Solo para mirar: tu paso de ahora no cambia. Alfa avanza sola cuando lo cumples."] = "Только посмотреть: текущий шаг не меняется. Alfa сам перейдет дальше, когда вы его выполните.",
	["Solo peleas de al menos"] = "Только бои не короче",
	["Solo pide tela: guarda la que te sale de los enemigos y sube mientras viajas."] = "Нужна только ткань: храни то, что падает с врагов, и прокачивай в пути.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "Основных профессий одновременно может быть только две; вспомогательные — без ограничений. Их изучают у учителей в городах.",
	["Solo salen los clanes donde puedes invitar, y Alfa te confirma en el chat a quién invitaste. Lo apagas en La Jauría > Invitar."] = "Показываются только те места, куда вы можете приглашать, а Alfa подтверждает в чате, кого вы пригласили. Отключается в La Jauría > Пригласить.",
	["Solo se admite la versión 1 de la cadena de escala."] = "Поддерживается только версия 1 строки шкалы.",
	["Solo si falta"] = "Только если нет",
	["Solo si le pido"] = "Только по просьбе",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "Работает только с HDR-монитором и включенным HDR в Windows (Параметры > Дисплей). Без этого оставьте выключенным: цвета будут блеклыми.",
	["Solo su atajo"] = "Только горячей клавишей",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "Меняют только графику: никогда камеру, мышь или интерфейс. «Отменить» возвращает то, что было до последнего примененного набора.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "Только ваша группа и те, кто пользуется Alfa и согласился делиться.",
	["Solo tú"] = "Только вы",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Только вы, ваша группа, ваши маркеры и следующий шаг гайда.",
	["Solo él ve tu nivel, tu zona y tu misión de ahora."] = "Только он видит твой уровень, зону и текущее задание.",
	["Sombra"] = "Тьма",
	["Sombra para subir"] = "Тьма для прокачки",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Мягкая тень в углах, складках и под объектами: придает всему объем.",
	["Sombras"] = "Тени",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Тени с более тонкими краями. Использует больше видеопамяти.",
	["Sombras suaves"] = "Мягкие тени",
	["Son %s más que venderlo todo al comerciante."] = "Это на %s больше, чем продать все торговцу.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "Это очки учетной записи: вы зарабатываете их испытаниями «Наследия» (достижения Forever) любым персонажем, а каждый персонаж тратит их сам в своих деревьях.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "Это три дворфа, которые сражаются вместе: один стреляет издалека, другой очень быстрый, а третий закрывается щитом. Убивайте их по одному.",
	["Sonido"] = "Звук",
	["Sonido con el juego en segundo plano"] = "Звук, когда игра в фоне",
	["Sonido de los avisos"] = "Звук оповещений",
	["Sonido en los avisos urgentes"] = "Звук для срочных оповещений",
	["Sonido suave"] = "Мягкий звук",
	["Sonido y avisos"] = "Звук и оповещения",
	["Sonidos de gestos"] = "Звуки эмоций",
	["Sonidos de mascotas"] = "Звуки питомцев",
	["Sonidos en tu lista (%d): %s"] = "Звуки в вашем списке (%d): %s",
	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "Мягкие звуки игры: без голосов и повторяющихся звуков.",
	["Sorpresa"] = "Сюрприз",
	["Sorpresas y cofres"] = "Сюрпризы и сундуки",
	["Soy Lya, la loba de confianza del Alfa. Te acompaño, te cuento el lore de cada lugar y te ayudo con todo lo de Alfa. Y me encantan las salchichas."] = "Я Лия, верная волчица Альфы. Я рядом, рассказываю историю каждого места и помогаю со всем в Alfa. И обожаю сосиски.",
	["Spot aquí"] = "Место тут",
	["Spot de farmeo"] = "Место фарма",
	["Spot de farmeo de %s"] = "Место фарма от %s",
	["Spots de farmeo"] = "Места фарма",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Стромгард, наследник Строма, едва держится: тролли, огры и Синдикат дерутся за его руины.",
	["Su arpón envenena: quita el veneno si puedes."] = "Его гарпун отравляет: снимайте яд, если можете.",
	["Su botín está por descubrir"] = "Добычу еще предстоит открыть",
	["Su electricidad salta de un jugador a otro: sepárense."] = "Его электричество перескакивает с игрока на игрока: разойдитесь.",
	["Su ficha"] = "Его карточка",
	["Su final no alcanzó a guardarse."] = "Ее концовку не успели сохранить.",
	["Su grupo está lleno o no puede invitar."] = "Его группа полна или он не может приглашать.",
	["Su guarida ya no está abierta."] = "Его логово больше не открыто.",
	["Su mordida envenena: quita el veneno si puedes."] = "Его укус ядовит: снимайте яд, если можете.",
	["Su nombre ya está en el correo: pon %s y envíalo."] = "Его имя уже в письме: добавь %s и отправь.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "Их золото и награды уже ваши: осталось только сдать.",
	["Su plano está lleno de gente. Si le abres tu guarida, Alfa lo invita a tu grupo y sale solo al llegar."] = "В их слое людно. Если откроешь логово, Alfa пригласит их в твою группу, и они выйдут, когда окажутся там.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "Его молния перескакивает с игрока на игрока: не стойте все вместе.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "Его молния перескакивает с игрока на игрока: немного разойдитесь.",
	["Suave"] = "Мягкий",
	["Subasta"] = "Аукцион",
	["Subasta:"] = "Аукцион:",
	["Subastador"] = "Аукционист",
	["Subastadores"] = "Аукционисты",
	["Subastar"] = "На аукцион",
	["Subastar %d"] = "На аукцион %d",
	["Sube %d nivel"] = "Подними уровней: %d",
	["Sube %d niveles"] = "Подними уровней: %d",
	["Sube al nivel"] = "Достичь уровня",
	["Sube al nivel %d"] = "Достичь уровня %d",
	["Sube al nivel %d: te falta %d%%"] = "Уровень %d: осталось %d%%",
	["Sube al nivel %d: te faltan %s de experiencia"] = "Уровень %d: осталось %s опыта",
	["Sube hasta %d con los pasos de abajo."] = "Подними до %d по шагам ниже.",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "Повышает громкость эффектов и снижает музыку и окружение, чтобы был слышен всплеск. По окончании все вернется как было.",
	["Sube tu profesión o junta sus materiales donde más hay."] = "Прокачайте профессию или соберите материалы там, где их больше всего.",
	["Sube tus oficios con lo que tienes cerca."] = "Прокачивайте профессии тем, что рядом.",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "Выброс адреналина: энергия восстанавливается намного быстрее.",
	["Subir"] = "Вверх",
	["Subir %s"] = "Уровень: %s",
	["Subir %s a %d"] = "Поднять %s до %d",
	["Subir cocina y pesca juntas"] = "Качать кулинарию и рыбную ловлю вместе",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "Прокачка танком: медленнее, чем Оружие, но вы почти никогда не умираете, берете нескольких монстров сразу и приходите готовым танковать любое подземелье.",
	["Subir de nivel"] = "Повысить уровень",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "Прокачка, профессии, золото или подземелья: два щелчка, и Alfa отведет вас.",
	["Subir de nivel, profesiones, oro o mazmorras."] = "Прокачка, профессии, золото или подземелья.",
	["Subir el sonido al pescar"] = "Громче звук во время рыбалки",
	["Subir rápido"] = "Быстрая прокачка",
	["Subir solo"] = "Прокачка в одиночку",
	["Subir una profesión"] = "Развить профессию",
	["Succionar vida: daño con el tiempo que te cura."] = "Вытягивание жизни: периодический урон, который лечит вас.",
	["Suelta"] = "Роняет",
	["Suelta el lanzamiento de ahora y lanza otra vez, sin poner equipo ni cebo."] = "Отменяет текущий заброс и забрасывает снова, без снаряжения и приманки.",
	["Suelta lo que tienes en el cursor y vuelve a intentarlo."] = "Отпустите то, что держите на курсоре, и попробуйте снова.",
	["Suelta una carta que empieza una misión: revisa su botín."] = "С него падает письмо, которое начинает задание: проверьте его добычу.",
	["Suelta una llave que abre una puerta más adelante: alguien debe recogerla."] = "С него падает ключ, который открывает дверь дальше: кто-то должен его подобрать.",
	["Suelta una nube de enfermedad a su alrededor: quiten enfermedades."] = "Выпускает вокруг себя облако болезни: снимайте болезни.",
	["Suelta una ola de fuego a su alrededor: si peleas de lejos, quédate lejos de él."] = "Выпускает вокруг себя волну огня: если сражаетесь на расстоянии, держитесь от него подальше.",
	["Suena ahora, aunque el aullido esté apagado."] = "Воспроизводит сейчас, даже если вой выключен.",
	["Sueño con una montaña de salchichas... y yo en la punta, feliz."] = "Мне снится гора сосисок... и я на самой вершине, счастливая.",
	["Sugerida para ti: %s"] = "Рекомендуем: %s",
	["Sugerir la piedra de hogar"] = "Предлагать камень возвращения",
	["Sugerir qué guardar"] = "Подсказывать, что убрать в банк",
	["Sugerir qué vender"] = "Подсказывать, что продать",
	["Sugiere con la prioridad de Alfa para tu clase. Apagado, usa la ayuda de Blizzard cuando el juego da una sugerencia que Alfa puede leer; en combate Forever la oculta, así que ahí sigue la de Alfa."] = "Подсказывает по приоритету Alfa для вашего класса. Если выключено, использует помощь Blizzard, когда игра даёт подсказку, которую Alfa может прочитать; в бою Forever её скрывает, поэтому там остаётся Alfa.",
	["Sulfuras es el martillo de Ragnaros. Con su ojo, los más valientes pueden forjar una versión legendaria."] = "Сульфурас — молот Рагнароса. С его глазом самые смелые могут выковать легендарную версию.",
	["Suma tus sesiones de hoy con este personaje."] = "Сумма за сегодняшние сеансы этого персонажа.",
	["Suma «conseguir este objeto» a tu plan de ahora (o a uno nuevo)."] = "Добавляет «получить этот предмет» в текущий план (или в новый).",
	["Supervivencia"] = "Выживание",
	["Supervivencia para subir"] = "Выживание для прокачки",
	["Sus antojos y salchichas"] = "Ее капризы и сосиски",
	["Sus bolas de sombra pegan mucho: interrúmpelo."] = "Его стрелы Тьмы бьют сильно: прерывайте его.",
	["Sus cariñitos"] = "Ее ласковые слова",
	["Sus consejos"] = "Ее советы",
	["Sus consejos te esperan en Alfa."] = "Его советы ждут вас в Alfa.",
	["Sus jefes, su botín, sus misiones y cómo llegar."] = "Его боссы, добыча, задания и как туда добраться.",
	["Sus misiones dan"] = "Его задания дают",
	["Sus rayos saltan entre jugadores: sepárense."] = "Ее молнии перескакивают между игроками: разойдитесь.",
	["Susurrar"] = "Шепнуть",
	["Sutileza"] = "Скрытность",
	["Sutileza para subir"] = "Скрытность для прокачки",
	["Sylvanas era hermana de Alleria y de Vereesa Brisaveloz. Hoy guía a los Renegados con mano firme."] = "Сильвана была сестрой Аллерии и Верисы Ветрокрылых. Сегодня она твердой рукой ведет Отрекшихся.",
	["Sylvanas recibe en el Barrio Real de Entrañas, con Varimathras a su lado."] = "Сильвана принимает в Королевском квартале Подгорода, а рядом с ней Вариматрас.",
	["Sylvanas tiene dos hermanas: Alleria, que se fue más allá del Portal Oscuro, y Vereesa, que se casó con el mago Rhonin."] = "У Сильваны две сестры: Аллерия, ушедшая за Темный портал, и Вериса, вышедшая замуж за мага Ронина.",
	["Sábado"] = "Суббота",
	["Sí"] = "Да",
	["Sí, que la manada me vea"] = "Да, пусть стая меня видит",
	["Sí, que me vean"] = "Да, пусть видят",
	["Sí, sígueme diciendo"] = "Да, говори дальше",
	["Sí, ya la hice"] = "Да, уже проходил",
	["Sí: Alfa, Clásico WoW o Cristal, con tu color. También puede vestir el chat, el minimapa y las barras."] = "Да: Alfa, Классический WoW или Кристалл, с твоим цветом. Ещё можно оформить чат, миникарту и панели.",
	["Sí: con /alfa limpia, o con tu tecla de pantalla limpia, escondo el chat, el minimapa y lo demás que elijas. Otra vez y vuelve todo."] = "Да: командой /alfa limpia или клавишей чистого экрана я спрячу чат, мини-карту и все, что ты выберешь. Еще раз — и все вернется.",
	["Sí: con el modo foco, en mazmorras y en combate me hago chiquita y me callo. Al terminar vuelvo. Está en mis ajustes."] = "Да: в режиме фокуса в подземельях и в бою я становлюсь маленькой и тихой. Потом возвращаюсь. Это в моих настройках.",
	["Sí: en Ajustes > Estilo y sonido elige «Sencillo» en «Cómo ves Alfa». Dejo a la vista solo lo esencial y te aviso menos."] = "Да: в «Настройки > Стиль и звук» выбери «Простой» в «Как ты видишь Alfa». Я оставлю на виду только главное и буду реже напоминать.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya» y otra a «Lo que te ofrece Lya», que hace lo de su botón."] = "Да: в назначении клавиш игры, раздел Alfa, назначь клавишу для «Спроси Лию» и ещё одну для «Что предлагает Лия» — она делает то же, что её кнопка.",
	["Sí: en las asignaciones de teclas del juego, en la sección Alfa, ponle una tecla a «Pregúntale a Lya»."] = "Да: в назначении клавиш игры, раздел Alfa, назначь клавишу для «Спроси Лию».",
	["Sí: en «Mentor», pulsa «Adoptar» junto a un lobo 10 niveles menor. Si acepta, ves cómo va y te aviso si se atora."] = "Да: в «Наставник» нажми «Опекать» рядом с волком на 10 уровней младше. Если согласится, ты увидишь, как у него дела, а я скажу, если он застрянет.",
	["Sí: escribe /alfa nota y tu texto, o usa «Nota aquí» en La Jauría. Sale en tu mapa donde estás; un clic y la flecha te lleva."] = "Да: набери /alfa nota и свой текст или нажми «Заметка тут» в La Jauría. Она появится на карте там, где ты стоишь; щелчок — и стрелка поведет тебя.",
	["Sí: sale «[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo. Solo, te sale a ti."] = "Да: «[Задание] можно сдать» и «Задание выполнено!» появляются в чате группы. В одиночку — только у тебя.",
	["Símbolo de reyes"] = "Символ королей",
	["Tabardo"] = "Гербовая накидка",
	["Talentos"] = "Таланты",
	["Talentos de %s"] = "Таланты: %s",
	["Talentos te dice cuál sigue."] = "«Таланты» подскажут, что дальше.",
	["Talentos y combate"] = "Таланты и бой",
	["Talentos: qué poner ahora y tu build (/alfa builds aplicar | equipo | compartir)"] = "Таланты: что взять сейчас и ваш билд (/alfa builds aplicar | equipo | compartir)",
	["Tamaño"] = "Размер",
	["Tamaño de la barra"] = "Размер полосы",
	["Tamaño de las casillas"] = "Размер ячеек",
	["Tamaño de las que siguen"] = "Размер следующих",
	["Tamaño de lo que atraviesa"] = "Размер проходимых объектов",
	["Tamaño de su letra"] = "Размер шрифта",
	["Tamaño del ícono"] = "Размер значка",
	["Tamaño en el mapa"] = "Размер на карте",
	["Tamaño en el minimapa"] = "Размер на мини-карте",
	["También con /alfa dps. No se cierra con Esc, para que la tengas a la vista al pelear."] = "Также через /alfa dps. Не закрывается клавишей Esc, чтобы оставаться на виду в бою.",
	["También con /alfa limpia."] = "Также через /alfa limpia.",
	["También cuando el juego hace brillar otra habilidad"] = "Также когда игра подсвечивает другую способность",
	["También dentro de cuevas, criptas y edificios."] = "Также в пещерах, склепах и зданиях.",
	["También el de venenos, sangrados y efectos que duran."] = "Также от ядов, кровотечений и длительных эффектов.",
	["También en el minimapa"] = "И на мини-карте",
	["También en montura"] = "И верхом",
	["También está en el menú de opciones del juego."] = "Также есть в меню настроек игры.",
	["También fuera de combate"] = "И вне боя",
	["También las de las mascotas de enemigos."] = "Также у питомцев противников.",
	["También las que no son de la guía (de esas se encarga \"Aceptar misiones de la guía\"). No toma misiones grises, no entrega las que piden oro, monedas o materiales de oficio, y si hay varias recompensas eliges tú. Mantén presionado Mayús para hacerlo tú."] = "Также те, что не входят в гайд (ими занимается «Принимать задания гайда»). Серые задания не берутся, задания, требующие золото, валюту или материалы для профессий, не сдаются, а если наград несколько, выбираете вы. Удерживайте Shift, чтобы сделать все самому.",
	["También las que no son de tu guía"] = "И те, что не из гайда",
	["También tu foco"] = "И фокус тоже",
	["También usa Alfa: salúdalo."] = "Тоже пользуется Alfa: поздоровайся.",
	["También yendo solo"] = "И когда вы одни",
	["Tanque"] = "Танк",
	["Tanque de amenaza"] = "Танк на угрозу",
	["Tanque de escudo"] = "Танк со щитом",
	["Tanque en apuros"] = "Танк в беде",
	["Tanque muralla"] = "Танк-стена",
	["Tanqueas"] = "Ты танкуешь",
	["Taretha Foxton, una muchacha humana de Durnholde, fue la amiga de Thrall y lo ayudó a escapar."] = "Тарета Фокстон, девушка-человек из Дарнхольда, была подругой Тралла и помогла ему бежать.",
	["Tarjeta de habilidades nuevas al subir de nivel"] = "Карточка новых навыков при повышении уровня",
	["Tauren"] = "Таурены",
	["Te abrimos un susurro para %s con tu mensaje. Revísalo y pulsa Intro para enviarlo."] = "Открыт шепот для %s с вашим сообщением. Проверьте его и нажмите Enter, чтобы отправить.",
	["Te acompaña"] = "Всегда рядом",
	["Te avisa al momento de %s."] = "Подсказывает, когда пора применить %s.",
	["Te avisa cuando tu clase tiene algo que aprovechar ahora, como una habilidad que se encendió."] = "Сообщает, когда у вашего класса есть что использовать прямо сейчас, например способность, которая подсветилась.",
	["Te aviso con «Regalárselo»: abre el comercio si está a tu lado o te deja su nombre en el correo. Necesitan compartir su clase y nivel."] = "Я подскажу кнопкой «Подарить»: она откроет обмен, если он рядом, или впишет его имя в письмо. Им нужно делиться классом и уровнем.",
	["Te conviertes en felino: mucho daño cuerpo a cuerpo y puedes acechar."] = "Ты превращаешься в кошку: много урона в ближнем бою, и можно красться.",
	["Te conviertes en foca: nadas rápido y respiras bajo el agua."] = "Ты превращаешься в тюленя: быстро плаваешь и дышишь под водой.",
	["Te conviertes en guepardo y corres más rápido. Solo al aire libre."] = "Ты превращаешься в гепарда и бегаешь быстрее. Только на открытом воздухе.",
	["Te conviertes en lobo y corres más rápido. ¡Como yo!"] = "Ты превращаешься в волка и бегаешь быстрее. Совсем как я!",
	["Te conviertes en oso: más armadura y más vida. Para tanquear y aguantar."] = "Ты превращаешься в медведя: больше брони и здоровья. Чтобы танковать и выстоять.",
	["Te cura toda la vida a cambio de tu maná. Guárdalo para una emergencia."] = "Полностью лечит тебя ценой маны. Береги на крайний случай.",
	["Te da %s."] = "Дает: %s.",
	["Te da consejos cortos y ánimo sin repetirse: cada frase sale tres veces como mucho. Dale clic para pedirle uno; clic derecho para sus opciones."] = "Она дает короткие советы и подбадривает, не повторяясь: каждая фраза звучит не больше трех раз. Щелкните по ней, чтобы попросить совет; правый щелчок — ее настройки.",
	["Te da ira a cambio de un poco de vida. Úsala para empezar una pelea con ira."] = "Дает ярость ценой немного здоровья. Применяй, чтобы начать бой с яростью.",
	["Te da poder de ataque: cada golpe pega más. Para el guerrero también sube el bloqueo con escudo."] = "Дает силу атаки: каждый удар бьет сильнее. Воину также повышает блок щитом.",
	["Te damos la bienvenida a Alfa, el todo en uno de La Jauría."] = "Добро пожаловать в Alfa — универсальный аддон от La Jauría.",
	["Te dice qué comprar a tu nivel y te lleva al vendedor de comida más cercano. El agua, solo si usas maná."] = "Подскажет, что купить для твоего уровня, и отведет к ближайшему торговцу едой. Вода — только если у тебя мана.",
	["Te dice qué pieza está por romperse, para que la repares a tiempo."] = "Сообщает, какая вещь скоро сломается, чтобы вы успели ее починить.",
	["Te enseña %s."] = "Обучает: %s.",
	["Te enseña Pesca y sus rangos. También vende la caña básica."] = "Обучает рыбной ловле и ее ступеням. Также продает простую удочку.",
	["Te falta"] = "Отсутствует",
	["Te falta %s"] = "Нет: %s",
	["Te falta 1 nivel para el 60"] = "До 60 остался 1 уровень",
	["Te falta 1 nivel para tomarla."] = "Чтобы взять его, остался 1 уровень.",
	["Te falta 1 paso"] = "Остался 1 шаг",
	["Te falta 1 rincón."] = "Остался 1 уголок.",
	["Te falta Aspecto del halcón: más poder a distancia."] = "Нет эффекта «Дух ястреба»: больше силы атаки дальнего боя.",
	["Te falta Aura de disparo certero: más poder a distancia para tu grupo."] = "Нет Ауры меткого выстрела: больше силы атаки дальнего боя для группы.",
	["Te falta Bendición de poderío: más poder de ataque."] = "Нет эффекта «Благословение могущества»: больше силы атаки.",
	["Te falta Escudo de relámpagos."] = "Нет эффекта «Щит молний».",
	["Te falta Escudo sagrado: bloqueas más."] = "Нет эффекта «Щит небес»: больше блока.",
	["Te falta Espinas."] = "Нет эффекта «Шипы».",
	["Te falta Fuego interior: más armadura."] = "Нет эффекта «Внутренний огонь»: больше брони.",
	["Te falta Grito de batalla: más poder de ataque para ti y tu grupo."] = "Нет эффекта «Боевой крик»: больше силы атаки для вас и группы.",
	["Te falta Intelecto Arcano: más maná."] = "Нет эффекта «Чародейский интеллект»: больше маны.",
	["Te falta Marca de lo Salvaje."] = "Нет эффекта «Знак дикой природы».",
	["Te falta Palabra de poder: entereza: más vida."] = "Нет эффекта «Слово силы: Стойкость»: больше здоровья.",
	["Te falta aprender la receta."] = "Нужно изучить рецепт.",
	["Te falta el tótem de Fuerza de la tierra: más fuerza."] = "Нет Тотема силы земли: больше силы.",
	["Te falta este vuelo: háblale al maestro de vuelo para aprenderlo."] = "У тебя нет этой точки полета: поговори с распорядителем полетов, чтобы открыть ее.",
	["Te falta ira: Enfurecer te la da."] = "Не хватает ярости: Исступление дает ее.",
	["Te falta ira: Ira sangrienta te la da gratis."] = "Не хватает ярости: Кровавая ярость даст ее бесплатно.",
	["Te falta ira: esta habilidad te la da al recibir golpes."] = "Не хватает ярости: эта способность дает ее, когда вы получаете удары.",
	["Te falta la forma de las Sombras: más daño de sombras y menos daño recibido."] = "Нет Облика Тьмы: больше урона от темной магии и меньше получаемого урона.",
	["Te falta la forma de lechúcico lunar: más daño con tus hechizos."] = "Нет Облика лунного совуха: больше урона от заклинаний.",
	["Te falta la profesión"] = "Нужна профессия",
	["Te falta reputación"] = "Не хватает репутации",
	["Te falta tu armadura demoníaca."] = "Нет Демонического доспеха.",
	["Te falta tu armadura: ponte una."] = "Нет доспеха: наложите его.",
	["Te falta un aspecto: el del halcón da más poder a distancia."] = "Нет духа: Дух ястреба дает больше силы атаки дальнего боя.",
	["Te falta un aspecto: el del mono te ayuda a esquivar."] = "Нет духа: Дух обезьяны помогает уклоняться.",
	["Te falta una bendición: Poderío da más poder de ataque."] = "Нет благословения: Благословение могущества дает больше силы атаки.",
	["Te falta una bendición: Sabiduría te devuelve maná."] = "Нет благословения: Благословение мудрости восполняет ману.",
	["Te falta una bendición: Santuario reduce el daño que recibes."] = "Нет благословения: Благословение неприкосновенности снижает получаемый урон.",
	["Te faltan %d de %d materiales"] = "Не хватает материалов: %d из %d",
	["Te faltan %d niveles para tomarla."] = "Чтобы взять его, осталось уровней: %d.",
	["Te faltan %d pasos"] = "Осталось шагов: %d",
	["Te faltan %d rincones."] = "Осталось уголков: %d.",
	["Te faltan %s"] = "Не хватает: %s",
	["Te faltan %s XP para el nivel %d"] = "Осталось %s опыта до уровня %d",
	["Te faltan %s XP para el nivel %d, a tu ritmo actual."] = "Осталось %s опыта до уровня %d при вашем текущем темпе.",
	["Te faltan %s de experiencia para el nivel %d"] = "%s опыта до %d-го уровня",
	["Te faltan %s niveles para el %d"] = "Осталось уровней: %s до %d",
	["Te faltan ingredientes para el siguiente lote."] = "Не хватает ингредиентов для следующей партии.",
	["Te faltan ingredientes."] = "Не хватает ингредиентов.",
	["Te faltan niveles para llegar a %d: la guía te lo marca y sigues subiendo con tu ruta."] = "До уровня %d еще далеко: гайд отметит это, а вы продолжите качаться по маршруту.",
	["Te faltan niveles: cada nivel desde el 10 te da un punto."] = "Не хватает уровней: каждый уровень начиная с 10 дает одно очко.",
	["Te haces el muerto y los enemigos te olvidan. Tu mejor salida si algo sale mal."] = "Ты притворяешься мертвым, и враги о тебе забывают. Лучший выход, когда все идет не так.",
	["Te la da %s, en %s."] = "Выдает: %s, %s.",
	["Te la da %s."] = "Выдает: %s.",
	["Te la dio %s"] = "Выдал: %s",
	["Te la dio %s · Se entrega con %s"] = "Выдал: %s · Сдать: %s",
	["Te la dio y la recibe %s"] = "Выдает и принимает: %s",
	["Te lleva a las misiones de tu ruta que ya puedes tomar."] = "Ведет к заданиям вашего маршрута, которые уже можно взять.",
	["Te lleva al Claro de la Luna, un lugar tranquilo para entrenar."] = "Переносит тебя на Лунную поляну, в тихое место для обучения.",
	["Te llevo a %s"] = "Веду вас: %s",
	["Te llevo a entregarlas todas en el mejor orden."] = "Отведу сдать их все в лучшем порядке.",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Веду вас к лучшему источнику. Помните: для верхового животного нужны уровень, верховая езда и золото.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Отведу вас к тому, кто принимает каждое задание, и вы возьмете следующие.",
	["Te llevo la cuenta de tu día de caza: misiones, niveles, oro, raros y el tiempo. Escribe /alfa lya dia y te lo cuento."] = "Я веду счёт твоего охотничьего дня: задания, уровни, золото, редкие и время. Напиши /alfa lya dia, и я расскажу.",
	["Te llevo la cuenta de tu semana de caza y tu mejor día. Escribe /alfa lya semana y te lo cuento."] = "Я веду счёт твоей охотничьей недели и лучшего дня. Напиши /alfa lya semana, и я расскажу.",
	["Te lo da un PNJ"] = "Выдает NPC",
	["Te lo enseña cualquier instructor de este oficio en las ciudades. Puedes tener dos oficios principales; Cocina y Primeros auxilios no cuentan."] = "Этому учит любой учитель этой профессии в городах. Основных профессий может быть две; кулинария и первая помощь не считаются.",
	["Te lo enseña cualquier instructor de pesca. Hasta que lo aprendas, tu habilidad no pasa del tope."] = "Обучит любой учитель рыбной ловли. Пока вы не изучите, навык не поднимется выше предела.",
	["Te lo enseña tu entrenador."] = "Изучается у учителя.",
	["Te lo enseñan desde el nivel %d."] = "Обучают с %d-го уровня.",
	["Te lo pido de corazón: nunca desuelles a un lobo enfrente de mí, ¿sí?"] = "Прошу от всего сердца: никогда не снимай шкуру с волка при мне, ладно?",
	["Te los enseña tu entrenador."] = "Изучаются у учителя.",
	["Te presento a Lya"] = "Знакомься: Лия",
	["Te pusiste «%s»: %d piezas."] = "Ты надел «%s»: предметов %d.",
	["Te queda 1 casilla libre."] = "Осталась 1 свободная ячейка.",
	["Te queda 1 espacio"] = "Осталась 1 ячейка",
	["Te queda 1."] = "Остался 1.",
	["Te queda muy poco maná: Estimular lo recupera."] = "Маны очень мало: Озарение восполнит ее.",
	["Te queda muy poco maná: Evocación lo recupera."] = "Маны очень мало: Прилив сил восполнит ее.",
	["Te queda poca XP descansada"] = "Опыт за отдых заканчивается",
	["Te queda poca agua"] = "У тебя мало воды",
	["Te queda poca comida"] = "У тебя мало еды",
	["Te queda poca comida y agua"] = "У тебя мало еды и воды",
	["Te queda poco maná y te sobra vida: cambia vida por maná."] = "Маны мало, а здоровья с избытком: обменяйте здоровье на ману.",
	["Te queda poco maná: cambia vida por maná."] = "Мало маны: обменяйте здоровье на ману.",
	["Te queda poco maná: usa tu varita."] = "Маны мало: используйте жезл.",
	["Te quedan %d casillas libres."] = "Свободных ячеек: %d.",
	["Te quedan %d de %d espacios"] = "Осталось ячеек: %d из %d",
	["Te quedan %d espacios en las bolsas. Vende lo gris o guarda en el banco."] = "В сумках осталось мест: %d. Продай серое или положи в банк.",
	["Te quedan %d."] = "Осталось: %d.",
	["Te quedaste sin agua"] = "У тебя кончилась вода",
	["Te quedaste sin comida"] = "У тебя кончилась еда",
	["Te quedaste sin comida ni agua"] = "У тебя кончились еда и вода",
	["Te saluda según la hora, comenta la zona y a veces se sienta a pedirte algo con su huesito."] = "Она здоровается по времени суток, говорит о зоне, а иногда садится и выпрашивает что-нибудь со своей косточкой.",
	["Te sobra ira y hay varios enemigos: tu siguiente golpe alcanza a dos."] = "Ярости в избытке и противников несколько: следующий удар заденет двоих.",
	["Te sobra ira: gástala en tu siguiente golpe."] = "Ярости в избытке: потратьте ее на следующий удар.",
	["Te sobra ira: tu siguiente golpe es más fuerte."] = "Ярости в избытке: следующий удар будет сильнее.",
	["Te sugiere objetivos de pasos más adelante que tienes muy cerca."] = "Предлагает цели следующих шагов, которые совсем рядом.",
	["Te sugiere qué habilidad usar ahora y cuáles siguen. Solo sugiere: nunca presiona nada por ti."] = "Подсказывает, какую способность использовать сейчас и какие дальше. Только подсказывает: никогда ничего не нажимает за вас.",
	["Te teletransporta a tu ciudad. Necesitas una runa de teletransporte."] = "Переносит тебя в твой город. Нужна руна телепортации.",
	["Te teletransportas unos metros hacia adelante. Para escapar de raíces y aturdimientos."] = "Переносит тебя на несколько метров вперед. Спасает от обездвиживания и оглушения.",
	["Te vuelve inmune un rato. Úsalo para salvarte o para escapar."] = "Делает тебя неуязвимым на время. Применяй, чтобы спастись или уйти.",
	["Te vuelves invisible al caminar. Acércate sin que te vean y elige cómo empezar."] = "Ты становишься невидимым на ходу. Подкрадись и выбери, как начать.",
	["Tecla del modo pesca"] = "Клавиша режима рыбалки",
	["Tecla fija para pescar"] = "Постоянная клавиша для рыбалки",
	["Tecla grande"] = "Крупная клавиша",
	["Tecla para abrir o cerrar el modo"] = "Клавиша, чтобы открыть или закрыть режим",
	["Tecla para volver a lanzar"] = "Клавиша перезаброса",
	["Tecla y modo pesca"] = "Клавиша и режим рыбалки",
	["Tela"] = "Ткань",
	["Teldrassil es tan grande que entre sus ramas hay colinas, lagos y cuevas."] = "Тельдрассил так огромен, что в его ветвях есть холмы, озера и пещеры.",
	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "Тельдрассил — мировое древо, которое ночные эльфы посадили без благословения драконов. Поэтому оно не дало им бессмертия.",
	["Teldrassil se plantó para recuperar la inmortalidad, pero sin la bendición de los dragones. Algo en él no anda bien."] = "Тельдрассил посадили, чтобы вернуть бессмертие, но без благословения драконов. С ним что-то не так.",
	["Teldrassil siempre tiene una luz suave, como si el árbol mismo nos cuidara."] = "В Тельдрассиле всегда мягкий свет, будто само древо присматривает за нами.",
	["Ten siempre a mano una poción de vida: este build no perdona errores."] = "Всегда держите под рукой зелье здоровья: этот билд не прощает ошибок.",
	["Tenga o no"] = "Есть или нет",
	["Tengo hambre… ¿me compartes algo de tu mochila?"] = "Я проголодалась… поделишься чем-нибудь из сумки?",
	["Tengo muchas misiones a medias, ¿qué hago?"] = "У меня куча недоделанных заданий, что делать?",
	["Tengo poco tiempo, ¿qué hago?"] = "У меня мало времени, что делать?",
	["Terenas Menethil, rey de Lordaeron, unió a los reinos en la Alianza de Lordaeron. Años después, su propio hijo Arthas lo mató en su trono."] = "Теренас Менетил, король Лордерона, объединил королевства в Альянс Лордерона. Годы спустя собственный сын Артас убил его на троне.",
	["Termina la configuración para usar Alfa (2 minutos)."] = "Завершите настройку, чтобы пользоваться Alfa (2 минуты).",
	["Terminada"] = "Выполнено",
	["Terminado: cumpliste todas sus metas."] = "Готово: вы выполнили все его цели.",
	["Terminar"] = "Закончить",
	["Terminar la cadena de Lord Valthalak también es un reto del Legado."] = "Пройти цепочку Лорда Вальталака — тоже испытание «Наследия».",
	["Terminaste %d de sus misiones: entrégalas y recoge las que siguen."] = "Выполнено его заданий: %d. Сдайте их и возьмите следующие.",
	["Terminaste 1 de sus misiones: entrégala y recoge las que siguen."] = "Выполнено 1 его задание: сдайте его и возьмите следующие.",
	["Terminaste esta guía."] = "Вы прошли этот гайд.",
	["Terminaste esta guía. Elige la siguiente para seguir subiendo."] = "Вы прошли этот гайд. Выберите следующий, чтобы продолжить прокачку.",
	["Termínala antes de entregarla."] = "Выполните его, прежде чем сдавать.",
	["Terreno, como el minimapa"] = "Рельеф, как на мини-карте",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "Рельеф: при приближении видна настоящая земля мини-карты с горами, реками и оттенками. Классическая: только нарисованная карта игры.",
	["Tesoro"] = "Сокровище",
	["Tesoro de la manada: %s"] = "Сокровище стаи: %s",
	["Tesoros"] = "Сокровища",
	["Tesoros en el mapa"] = "Сокровища на карте",
	["Tesoros en el minimapa"] = "Сокровища на мини-карте",
	["Texto de combate flotante"] = "Всплывающий текст боя",
	["Texto sobre tu personaje"] = "Текст над персонажем",
	["Textos y cajas mejor alineados en las ventanas de Alfa."] = "Тексты и поля лучше выровнены в окнах Alfa.",
	["Texturas del mundo"] = "Текстуры мира",
	["Texturas del suelo"] = "Текстуры земли",
	["Texturas proyectadas"] = "Проецируемые текстуры",
	["Texturas y nitidez"] = "Текстуры и резкость",
	["Theradras, la princesa de la tierra, es hija de Therazane. Amó a Zaetar, hijo de Cenarius, y sus hijos, los centauros, terminaron matándolo."] = "Терадрас, принцесса земли, — дочь Теразан. Она любила Зейтара, сына Кенария, а их дети, кентавры, в итоге убили его.",
	["Theramore la fundó Jaina Valiente con los humanos que salieron de Lordaeron antes de su caída."] = "Терамор основала Джайна Праудмур с людьми, покинувшими Лордерон до его падения.",
	["Thrall eligió esta tierra roja y seca para que los orcos libres empezaran de nuevo, lejos de los campos de internamiento de los humanos."] = "Тралл выбрал эту красную сухую землю, чтобы свободные орки начали заново, вдали от лагерей для интернированных.",
	["Thrall es el chamán más famoso: los elementos le responden como a nadie."] = "Тралл — самый знаменитый шаман: стихии откликаются ему как никому.",
	["Thrall gobierna la Horda desde Orgrimmar como jefe de guerra, con la mirada puesta en la paz."] = "Тралл правит Ордой из Оргриммара как вождь, думая о мире.",
	["Thrall liberó a los orcos de los campos de internamiento con la ayuda de Grom Grito Infernal y de Orgrim Martillo Maldito."] = "Тралл освободил орков из лагерей для интернированных с помощью Грома Адского Крика и Оргрима Молота Рока.",
	["Thrall nació en Draenor, hijo de Durotan y Draka. Aedelas Blackmoore lo encontró de bebé y lo llamó «Thrall», que quiere decir esclavo."] = "Тралл родился на Дреноре, сын Дуротана и Дреки. Эделас Блэкмур нашел его младенцем и назвал «Траллом», что значит «раб».",
	["Thrall quiere que los orcos recuperen el honor que tenían antes de la corrupción demoníaca."] = "Тралл хочет, чтобы орки вернули честь, которая была у них до демонической порчи.",
	["Tiempo"] = "Время",
	["Tiempo de juego por sesión"] = "Время игры за сеанс",
	["Tiempo hasta que pica"] = "Время до поклевки",
	["Tiempo máximo entre los dos clics. Súbelo si tus dobles clics no lanzan."] = "Наибольшее время между двумя щелчками. Увеличьте его, если двойной щелчок не забрасывает.",
	["Tiempo pescando"] = "Время за рыбалкой",
	["Tiempo: %s"] = "Время: %s",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Состоит из четырех частей, которые проходятся отдельно: Кладбище, Библиотека, Оружейная и Собор, от самой легкой к самой трудной.",
	["Tienes"] = "У вас",
	["Tienes %d"] = "У вас %d",
	["Tienes %d  ·  en %s"] = "У вас %d  ·  в %s",
	["Tienes %d casillas libres"] = "Свободных ячеек: %d",
	["Tienes %d de %d"] = "У вас %d из %d",
	["Tienes %d de %d casillas de bolsa en el banco."] = "Ячеек для сумок в банке: %d из %d.",
	["Tienes %d de %d casillas de bolsa. La siguiente cuesta %s; después pon una bolsa en ella."] = "Ячеек для сумок: %d из %d. Следующая стоит %s; затем положите в нее сумку.",
	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "Включено: %d. Ниже каждая — с описанием, если захотите что-то изменить.",
	["Tienes %d misiones listas"] = "Готовых заданий: %d",
	["Tienes %d misiones listas para entregar"] = "Заданий, готовых к сдаче: %d",
	["Tienes %d misiones listas para entregar. ¿Las juntamos en una ruta?"] = "Готовых к сдаче заданий: %d. Соберем их в один маршрут?",
	["Tienes %d para gastar"] = "Можно потратить: %d",
	["Tienes %d piezas mejores para pescar en tus bolsas."] = "В сумках есть лучшие предметы для рыбалки: %d.",
	["Tienes %d puntos de talento: empieza por %s"] = "Очков талантов: %d. Начните с «%s»",
	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Очков вне ветки: %d (%s). Alfa никогда не сбрасывает таланты: чтобы следовать этому билду, сбросьте таланты у учителя класса, и Alfa расставит их заново в один щелчок. Или выберите билд ветки, в которую вы уже вложились.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Свободных очков: %d, но следующих талантов из «%s» нет в вашем дереве (возможно, их изменил патч). Распределите их вручную в окне игры или попробуйте другой стиль.",
	["Tienes %s de %s"] = "У вас %s из %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "У вас цен из ваших поисков: %s. Чтобы знать все, просканируйте аукцион.",
	["Tienes 1 misión lista para entregar"] = "1 задание готово к сдаче",
	["Tienes 5 puntos de combo y estás en grupo: el sangrado rinde más."] = "У вас 5 очков серии и вы в группе: кровотечение выгоднее.",
	["Tienes 5 puntos de combo: el remate más fuerte."] = "У вас 5 очков серии: самый сильный завершающий прием.",
	["Tienes 5 puntos de combo: muerde fuerte."] = "У вас 5 очков серии: кусайте сильнее.",
	["Tienes 6 guías abiertas"] = "У вас открыто 6 гайдов",
	["Tienes activado «Rechazar invitaciones a hermandad» en Ajustes > Comodidades > Social: apágalo para que te llegue la invitación."] = "У вас включено «Отклонять приглашения в гильдию» в Настройки > Удобства > Общение: выключите, чтобы приглашение дошло до вас.",
	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "В окне талантов есть неподтвержденные изменения: они будут отброшены перед применением.",
	["Tienes cambios sin guardar en la ventana de talentos del juego: guárdalos o deshazlos ahí primero"] = "В окне талантов игры есть несохранённые изменения: сначала сохраните или отмените их там",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Включено «только задания моего маршрута»: принимаются только задания вашего маршрута.",
	["Tienes furia: úsalo antes de la siguiente pelea, te da más poder de ataque a ti y a tu grupo."] = "У вас есть ярость: используйте его до следующего боя, он дает больше силы атаки вам и вашей группе.",
	["Tienes habilidades nuevas"] = "У вас есть новые навыки",
	["Tienes habilidades sin aprender (%d). Aprenderlas te hace más fuerte."] = "Есть неизученные способности (%d). Изучи их — станешь сильнее.",
	["Tienes la %s, %d versiones atrás."] = "У вас версия %s (новых версий с тех пор: %d).",
	["Tienes la %s."] = "У вас версия %s.",
	["Tienes misiones grises: mira cuáles ya no valen la pena y suéltalas para hacer espacio."] = "У тебя есть серые задания: посмотри, какие уже не стоят того, и откажись от них, чтобы освободить место.",
	["Tienes más rangos de los que pide tu build."] = "У вас больше рангов, чем требует билд.",
	["Tienes puesto «%s». Abre la ventana para afinar cada detalle: distancia, pasto, niebla, agua, cámara, placas y filtros."] = "Применен набор «%s». Откройте окно, чтобы настроить каждую мелочь: дальность, траву, туман, воду, камеру, индикаторы и фильтры.",
	["Tienes puntos fuera del plan: Alfa no los quita, solo agrega."] = "У вас есть очки вне плана: Alfa их не убирает, только добавляет.",
	["Tienes seis guías abiertas: cierra una y vuelve a intentarlo."] = "У вас открыто шесть гайдов: закройте один и попробуйте снова.",
	["Tienes todo %s"] = "У вас есть все: %s",
	["Tienes un hechizo para ir al Claro de la Luna, el santuario de los druidas."] = "У тебя есть заклинание, переносящее на Лунную поляну, святилище друидов.",
	["Tienes un punto de talento: %s"] = "У вас 1 очко таланта: %s",
	["Tienes una misión de clase"] = "У вас есть классовое задание",
	["Tinte de color"] = "Цветовой оттенок",
	["Tipo"] = "Тип",
	["Tirion Vadín fue expulsado de la Mano de Plata por defender a Eitrigg, un orco que le salvó la vida. Hoy Eitrigg aconseja a Thrall en Orgrimmar."] = "Тириона Фордринга изгнали из ордена Серебряной Длани за то, что он заступился за Эйтригга, орка, спасшего ему жизнь. Сегодня Эйтригг советник Тралла в Оргриммаре.",
	["Tirion Vadín, el paladín expulsado de la orden, vive solo en una cabaña de estas tierras."] = "Тирион Фордринг, изгнанный из ордена паладин, живет один в хижине в этих краях.",
	["Toca %s."] = "Пора %s.",
	["Toca ahora"] = "Сейчас",
	["Toca el interruptor para poner o quitar una; lo que tocas manda sobre el filtro."] = "Переключите тумблер, чтобы добавить или убрать задание; ваш выбор важнее фильтра.",
	["Toca una tarjeta para prenderla o apagarla. Las encendidas llevan el borde de color."] = "Нажми на карточку, чтобы включить или выключить. У включённых цветная рамка.",
	["Toca «Seleccionarlo» otra vez, o usa el botón de raros."] = "Нажми «Выбрать цель» ещё раз или используй кнопку редких.",
	["Tocando a la puerta de la %s"] = "Стучишь в дверь: %s",
	["Toda calidad"] = "Любое качество",
	["Toda fuente"] = "Любой источник",
	["Toda la cuenta"] = "Вся учетная запись",
	["Toda ranura"] = "Любая ячейка",
	["Todas"] = "Все",
	["Todas (%d)"] = "Все (%d)",
	["Todas las calidades"] = "Любое качество",
	["Todas las guías de profesiones"] = "Все гайды профессий",
	["Todas las guías por zona y nivel, con la que Alfa te sugiere para ti."] = "Все гайды по зонам и уровням — с тем, который Alfa рекомендует вам.",
	["Todas las mascotas de compañía: dónde salen, cuánto cuestan y cuáles te faltan."] = "Все питомцы: откуда берутся, сколько стоят и каких у вас нет.",
	["Todas las mazmorras"] = "Все подземелья",
	["Todas las metas, notas y pasos de esta guía en otra ventana."] = "Все цели, заметки и шаги этого гайда в отдельном окне.",
	["Todas las misiones"] = "Все задания",
	["Todas las misiones de aquí en el mejor orden, con la flecha."] = "Все здешние задания в лучшем порядке, со стрелкой.",
	["Todas las misiones de la zona en el mejor orden."] = "Все задания зоны в лучшем порядке.",
	["Todas las misiones de tu zona (las que llevas y las que puedes tomar) en el mejor orden, como una guía."] = "Все задания твоей зоны (те, что есть, и те, что можно взять) в лучшем порядке, как гид.",
	["Todas las misiones que Lya te guardó, por zona, con su historia completa. También con /alfa historias."] = "Все задания, которые Lya сохранила для вас, по зонам, с полной историей. Также командой /alfa historias.",
	["Todas las monturas: cómo se consigue cada una, qué pide y si ya la tienes."] = "Весь транспорт: как получить каждый, что он требует и есть ли он у вас.",
	["Todas las profesiones"] = "Все профессии",
	["Todas las páginas de Alfa a la vista: mazmorras, talentos, combate, oficios, la manada y más."] = "Все страницы Alfa на виду: подземелья, таланты, бой, профессии, стая и многое другое.",
	["Todas las secciones"] = "Все разделы",
	["Todas las teclas de Alfa en un lugar"] = "Все клавиши Alfa в одном месте",
	["Todas las teclas de Alfa en un lugar, para cambiarlas ahí mismo. También con /alfa teclas."] = "Все клавиши Alfa в одном месте, чтобы сразу их изменить. Также через /alfa teclas.",
	["Todas las zonas"] = "Все зоны",
	["Todas las zonas y razas"] = "Все зоны и расы",
	["Todavía es pronto"] = "Пока рано",
	["Todavía nada en esta sesión"] = "В этом сеансе пока ничего",
	["Todavía no"] = "Пока нет",
	["Todavía no cambias de guarida"] = "Ты ещё не сменил логово",
	["Todavía no conoces sus hechizos: se llenan al aprenderlos."] = "Вы еще не знаете этих заклинаний: они появятся, когда вы их изучите.",
	["Todavía no conozco tus recetas"] = "Я пока не знаю ваших рецептов",
	["Todavía no es para ti"] = "Пока не для вас",
	["Todavía no escribimos nada en tu historia. ¡Vamos a hacer algo grande!"] = "Мы еще ничего не написали в твоей истории. Давай сделаем что-то большое!",
	["Todavía no estás en una hermandad. En la página La Jauría ves cómo unirte a la manada."] = "Вы пока не состоите в гильдии. На странице La Jauría рассказано, как вступить в стаю.",
	["Todavía no has pescado nada en esta sesión"] = "В этом сеансе вы еще ничего не поймали",
	["Todavía no hay ayuda de rotación para ti"] = "Для вас пока нет помощника ротации",
	["Todavía no hay datos de este personaje"] = "Данных об этом персонаже пока нет",
	["Todavía no hay datos para esta gráfica."] = "Для этого графика пока нет данных.",
	["Todavía no hay foto de este banco"] = "Снимка этого банка пока нет",
	["Todavía no hay guías para tu camino"] = "Для твоего пути пока нет гидов",
	["Todavía no hay peleas"] = "Боев пока нет",
	["Todavía no hay progreso"] = "Прогресса пока нет",
	["Todavía no hay una pelea anterior"] = "Предыдущего боя пока нет",
	["Todavía no hay una pelea que anunciar."] = "Пока нечего объявлять.",
	["Todavía no hay una pelea que resumir."] = "Пока нет боя для итога.",
	["Todavía no lo pescas"] = "Еще не поймано",
	["Todavía no lo recolectas"] = "Еще не собирали",
	["Todavía no lo sacas del agua. Cuando lo hagas, aquí verás cuántos llevas, cuándo y dónde."] = "Вы ее еще не вытащили. Когда вытащите, здесь будет видно, сколько, когда и где.",
	["Todavía no pescas en %s. Lo que saques aquí se anota por zona."] = "Вы еще не рыбачили в %s. Улов здесь записывается по зонам.",
	["Todavía no puedes conseguirlo: %s."] = "Пока нельзя получить: %s.",
	["Todavía no recolectas nada"] = "Вы еще ничего не собрали",
	["Todavía no sabes pescar"] = "Вы еще не умеете рыбачить",
	["Todavía no se puede tomar: Alfa la recoge cuando se abra."] = "Пока нельзя взять: Alfa возьмет его, когда откроется.",
	["Todavía no sigues ninguna guía. Elige una y Alfa te lleva paso a paso, con la flecha y la ruta."] = "Вы пока не идете ни по одному гайду. Выберите гайд, и Alfa поведет вас шаг за шагом — стрелкой и маршрутом.",
	["Todavía no te alcanza."] = "Денег пока не хватает.",
	["Todavía no tienes escalas propias. Pega una cadena de escala arriba."] = "Своих шкал пока нет. Вставьте строку шкалы выше.",
	["Todavía no tienes marcadores"] = "Маркеров пока нет",
	["Todavía no tienes rutas propias"] = "Собственных маршрутов пока нет",
	["Todavía no tienes talentos para compartir."] = "Пока нет талантов, которыми можно поделиться.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "У вас еще нет открытого гайда. Выберите его, и Alfa поведет вас шаг за шагом: куда идти, что делать и с кем говорить.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "В кратере до сих пор стоят пилоны титанов, и они работают на цветных кристаллах.",
	["Todo"] = "Всё",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Весь Азерот на одном холсте: приближайте колесом, перетаскивайте, чтобы двигаться, и ставьте маркеры правым щелчком.",
	["Todo a la mano"] = "Всё под рукой",
	["Todo a la vista otra vez"] = "Снова все на виду",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "Все на безопасном максимуме. Нужна мощная видеокарта.",
	["Todo bien (lo más gastado: %d%%)"] = "Все в порядке (самое изношенное: %d%%)",
	["Todo como estaba antes de Alfa"] = "Все как было до Alfa",
	["Todo con tu estilo"] = "Все в вашем стиле",
	["Todo el juego, aunque no lo tengas"] = "Вся игра, даже то, чего у вас нет",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "Вся игра, даже то, чего у вас нет: предметы, NPC, задания, зоны и редкие.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "Вся игра, даже то, чего у вас нет: предметы, транспорт, питомцы, NPC, задания, зоны и редкие существа.",
	["Todo el texto de Alfa un poco más grande, en cada ventana. Se suma al tamaño de Ajustes > Apariencia."] = "Весь текст Alfa чуть крупнее, в каждом окне. Добавляется к размеру из Настройки > Внешний вид.",
	["Todo en orden"] = "Все в порядке",
	["Todo en orden: nada choca con Alfa."] = "Все хорошо: ничего не конфликтует с Alfa.",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "Все это Alfa делает сам, когда вы говорите с тем, кто выдает или принимает задание. Удерживайте Shift, чтобы в этот момент сделать это самостоятельно.",
	["Todo junto"] = "Все вместе",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "«Все вместе» показывает каждую ячейку на своем месте; «По категориям» группирует снаряжение, расходуемые предметы, предметы заданий и материалы; «По сумкам» выводит каждую сумку отдельным блоком.",
	["Todo listo"] = "Все готово",
	["Todo lo de Alfa, explicado por Lya y a un clic"] = "Всё об Alfa, объясняет Лия, в один клик",
	["Todo lo que hay en Alfa"] = "Всё, что есть в Alfa",
	["Todo lo que no sea equipo"] = "Все, кроме снаряжения",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Все, что рисуется на ваших картах, в одном месте. Сюда попадает и то, что добавляют другие модули Alfa.",
	["Todo nivel"] = "Любой уровень",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Любой предмет, NPC, задание, зона и редкий — с тем, где это получить, и «Веди меня».",
	["Todo oficio"] = "Все роли",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Все ради урона: критические удары, кровотечения и очень частое Превосходство. Вы убиваете очень быстро, но дополнительной защиты нет: если на вас навалилось много противников, бегите.",
	["Todo subtipo"] = "Любой подтип",
	["Todo tipo"] = "Любой тип",
	["Todos"] = "Все",
	["Todos llegan a %s"] = "Все ведут к %s",
	["Todos los avisos de Alfa los dice Lya, también los de al entrar y el de hechizos nuevos, con letra más grande que cambias con su clic derecho."] = "Все оповещения Alfa говорит Лия, даже при входе и о новых заклинаниях, более крупным шрифтом, который меняется правым кликом по ней.",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Все этого типа или только один (например, только медь). В скобках — сколько их в вашей зоне.",
	["Todos los materiales"] = "Все материалы",
	["Todos los niveles"] = "Все уровни",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Все предметы, NPC, задания, зоны и редкие, даже те, что у вас нет: кто роняет и с какой вероятностью, кто продает и где, какое задание дает и как туда добраться.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Все предметы, транспорт, питомцы, NPC, задания, зоны и редкие существа, даже те, которых у вас нет: кто роняет и с каким шансом, кто продает и где, какое задание дает и как туда добраться.",
	["Todos los paladines sueñan con la Crematoria, la espada de Alexandros Mograine."] = "Все паладины мечтают об Испепелителе, мече Александроса Могрейна.",
	["Todos los pasos"] = "Все шаги",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Все шаги этого гайда; щелкните по шагу, чтобы посмотреть его.",
	["Todos los pasos de la guía en la ventana de guía."] = "Все шаги гайда — в окне гайда.",
	["Todos los que callaste"] = "Все отключенные",
	["Todos los tipos"] = "Все типы",
	["Todos tus personajes"] = "Все твои персонажи",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Все ваши очки уже потрачены, и часть из них — вне этого билда. Чтобы перейти на этот билд, сбросьте таланты у учителя своего класса; затем Alfa применит их одним щелчком.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Все: включая легкие предупреждения. Только серьезные: лишь то, что может вас убить.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Сразу забирает добычу с рыбалки, даже если в игре выключен автоматический сбор добычи.",
	["Toma el dinero y los objetos de tus cartas, una por una. Las de pago contra entrega y las de un MJ se quedan para que las abras tú."] = "Забирает деньги и предметы из твоих писем по одному. Письма с наложенным платежом и от ГМ остаются, чтобы ты открыл их сам.",
	["Toma las de tu ruta que tienes cerca"] = "Возьмите задания маршрута поблизости",
	["Toma las mejores de cerca que ya puedes hacer."] = "Возьмите лучшие задания поблизости, которые уже можно выполнить.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Возьмите лучшие задания здесь, а потом закройте их вместе.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "Забирает всю добычу сразу, когда включен автосбор добычи.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Возьмите несколько заданий поблизости, и Alfa закроет их вместе с вами по самому короткому пути.",
	["Tomando tus cartas..."] = "Забираю почту...",
	["Tomar %s"] = "Взять: %s",
	["Tomar el vuelo de tu ruta"] = "Лететь по маршруту",
	["Tomar la mejor recompensa"] = "Брать лучшую награду",
	["Tomar todo"] = "Забрать все",
	["Tomarla"] = "Взять",
	["Tomarla, completarla o entregarla."] = "Взять, выполнить или сдать.",
	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Вы взяли другое задание из этой группы: это больше не откроется.",
	["Top %d de %s"] = "Топ %d: %s",
	["Top de daño"] = "Топ урона",
	["Tope por personaje"] = "Предел на персонажа",
	["Torre de zepelines de %s"] = "Башня дирижаблей: %s",
	["Tortura mental: daño constante y frena al enemigo."] = "Пытка разума: постоянный урон и замедление противника.",
	["Total"] = "Всего",
	["Tramo %d de %d: %s."] = "Этап %d из %d: %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Ловушки, экстренные удары ближнего боя и много ловкости: охотник, которого труднее всего поймать.",
	["Tranquila, aquí nadie se queda atrás."] = "Не волнуйся, здесь никого не бросают.",
	["Tranquilo"] = "Спокойно",
	["Transformar"] = "Переработать",
	["Transformar %d"] = "Переработать %d",
	["Transmutar hierro en oro existe de verdad: el sueño de todo alquimista."] = "Превращение железа в золото действительно существует: мечта любого алхимика.",
	["Tranvía de %s"] = "Подземный поезд: %s",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "После принятия или сдачи закрывает окно NPC, если он предлагает только задания, которых нет в гайде.",
	["Tras la Guerra de los Tres Martillos, los Martillo Salvaje se fueron a Grim Batol y luego al Interior; los Hierro Negro, a la Montaña Roca Negra."] = "После Войны Трех Молотов Громовой Молот ушли в Грим Батол, а потом во Внутренние земли; Черное Железо — в Черную гору.",
	["Tras la Segunda Guerra, mantener a los orcos en los campos de internamiento costaba una fortuna. Esos impuestos ayudaron a romper la Alianza."] = "После Второй войны содержание орков в лагерях для интернированных стоило целое состояние. Эти налоги помогли расколоть Альянс.",
	["Tras las Guerras Trol, el viejo Arathor se repartió en siete reinos: Lordaeron, Ventormenta, Gilneas, Alterac, Stromgarde, Kul Tiras y Dalaran."] = "После Тролльих войн древний Аратор распался на семь королевств: Лордерон, Штормград, Гилнеас, Альтерак, Стромгард, Кул-Тирас и Даларан.",
	["Tratado"] = "Манускрипт",
	["Treinta. La manada habla de ti."] = "Тридцать. Стая говорит о тебе.",
	["Tres caminos para cada objeto"] = "Три пути для каждого предмета",
	["Tres estilos y el lobo"] = "Три стиля и волк",
	["Tres pasos y listo"] = "Три шага, и готово",
	["Tres pasos: tus clics, dónde van tus marcos y una prueba."] = "Три шага: ваши щелчки, где будут рамки, и проверка.",
	["Trescientos puntos. Eres maestro de tu oficio."] = "Триста очков. Ты мастер своего дела.",
	["Trilineal"] = "Трилинейная",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "Кабестан — нейтральный гоблинский порт: здесь терпят любого, у кого есть золото, а его корабль ходит в Пиратскую Бухту.",
	["Trofeo"] = "Трофей",
	["Trofeos y concurso"] = "Трофеи и состязание",
	["Trols"] = "Тролли",
	["Trueno"] = "Гром",
	["Tu Alfa ya está configurada. Revisa o cambia cualquier respuesta cuando quieras."] = "Ваш Alfa настроен. Проверяйте или меняйте любой ответ когда угодно.",
	["Tu Grito de batalla llega a todo el grupo y dura más."] = "Ваш Боевой крик достает всю группу и длится дольше.",
	["Tu abisario aguanta los golpes por ti: deja que empiece la pelea."] = "Ваш демон Бездны принимает удары за вас: пусть он начинает бой.",
	["Tu abisario: un demonio que aguanta golpes por ti. Perfecto para ir solo."] = "Твой демон Бездны: принимает удары за тебя. Идеален для одиночной игры.",
	["Tu anuncio ya está en el tablón de la manada. Se quita solo en una hora."] = "Твое объявление уже на доске стаи. Само исчезнет через час.",
	["Tu aprendiz no gana experiencia desde hace 20 minutos. ¿Le echas la mano?"] = "Твой ученик не получает опыт уже 20 минут. Поможешь ему?",
	["Tu aprendiz: %s"] = "Твой ученик: %s",
	["Tu arma a veces da golpes extra. De lo mejor para armas lentas."] = "Твое оружие иногда бьет дополнительно. Из лучших для медленного оружия.",
	["Tu arma no tiene encantamiento: Lengua de fuego."] = "На оружии нет чар: Язык пламени.",
	["Tu arma no tiene encantamiento: Muerdepiedras."] = "На оружии нет чар: Камнедробитель.",
	["Tu arma no tiene encantamiento: Viento furioso."] = "На оружии нет чар: Неистовство ветра.",
	["Tu arma no usa munición."] = "Вашему оружию не нужны боеприпасы.",
	["Tu arma pega con fuego. Buena para armas lentas."] = "Твое оружие бьет огнем. Хорошо для медленного оружия.",
	["Tu arma secundaria pega más."] = "Оружие в левой руке бьет сильнее.",
	["Tu armadura ya no aguanta mucho (%d%%). ¿Vamos a reparar?"] = "Доспехи долго не протянут (%d%%). Пойдем на ремонт?",
	["Tu avance arriba, el paso en una tarjeta, los dos siguientes a la vista y los botones abajo."] = "Прогресс сверху, шаг на карточке, два следующих на виду и кнопки внизу.",
	["Tu avance de misiones con tu grupo"] = "Прогресс заданий вместе с группой",
	["Tu ayuda de rotación está lista"] = "Ваш помощник ротации готов",
	["Tu banco"] = "Ваш банк",
	["Tu banco está completo"] = "Ваш банк полностью расширен",
	["Tu banco y lo que llevas"] = "Ваш банк и то, что при вас",
	["Tu banco ya tiene todas sus casillas."] = "В вашем банке уже все ячейки.",
	["Tu barra de %s está vacía"] = "Панель «%s» пуста",
	["Tu barra se llena al salir de combate."] = "Панель заполнится после боя.",
	["Tu botón de emergencia."] = "Ваша кнопка на крайний случай.",
	["Tu buff"] = "Ваш бафф",
	["Tu build"] = "Ваш билд",
	["Tu camino"] = "Ваш путь",
	["Tu camino [mapa]"] = "Твой путь",
	["Tu camino en el mapa y un aullido nuevo"] = "Твой путь на карте и новый вой",
	["Tu camino: %d tramos, %s. Escribe arriba para ir a otro lugar."] = "Твой путь: отрезков %d, %s. Напиши сверху, чтобы пойти в другое место.",
	["Tu caña tiene cebo: %s más."] = "На удочке приманка: осталось %s.",
	["Tu cita con la manada"] = "Твой сбор со стаей",
	["Tu cita, %s"] = "Твой сбор, %s",
	["Tu clase la gana con esta cadena de misiones."] = "Ваш класс получает его за эту цепочку заданий.",
	["Tu clase no lo usa: guárdalo para otro personaje o súbelo a la subasta."] = "Твой класс это не носит: оставь для другого персонажа или выставь на аукцион.",
	["Tu clase no necesita recordatorio"] = "Вашему классу напоминание не нужно",
	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "У вашего класса нет способностей-реакций. Если хотите, Alfa сообщит, когда игра подсветит одну из ваших способностей (в «Оповещениях» ниже).",
	["Tu clase todavía no tiene uno propio: Alfa usa el más parecido."] = "Для вашего класса пока нет своего: Alfa использует самый похожий.",
	["Tu cliente no deja cambiar talentos desde un addon. Usa la ventana de talentos del juego (tecla N)."] = "Ваш клиент не позволяет аддону менять таланты. Используйте игровое окно талантов (клавиша N).",
	["Tu cliente no tiene la línea de tiempo de jefes."] = "В вашем клиенте нет шкалы времени боссов.",
	["Tu cliente no trae el medidor de daño del juego."] = "В вашем клиенте нет игрового измерителя урона.",
	["Tu cliente no trae la ayuda de combate de Blizzard."] = "В вашем клиенте нет помощника в бою от Blizzard.",
	["Tu cola"] = "Ваша очередь",
	["Tu cola de cocina está vacía"] = "Очередь готовки пуста",
	["Tu color de acento"] = "Ваш акцентный цвет",
	["Tu compañera"] = "Ваша спутница",
	["Tu compañera de caza"] = "Ваш напарник на охоте",
	["Tu compañera en Alfa. Lleva el nombre de una gran perrita, en su memoria."] = "Твоя спутница в Alfa. Носит имя замечательной собачки, в её память.",
	["Tu configuración como texto: guárdalo de respaldo o pásaselo a la manada."] = "Твои настройки в виде текста: сохрани как резервную копию или передай стае.",
	["Tu configuración de Alfa"] = "Ваши настройки Alfa",
	["Tu configuración quedó guardada como «%s»."] = "Твои настройки сохранены как «%s».",
	["Tu corcel vil: una montura propia de brujo. ¡Felicidades!"] = "Твой конь Скверны: собственный скакун чернокнижника. Поздравляю!",
	["Tu correo"] = "Ваша почта",
	["Tu cuerpo"] = "Твое тело",
	["Tu cuerpo está a %s, como %s corriendo."] = "Твое тело в %s, примерно %s пешком.",
	["Tu cuerpo quedó dentro de %s: corre a su entrada."] = "Твое тело в: %s. Беги ко входу.",
	["Tu curación"] = "Ваше исцеление",
	["Tu curación básica. Úsala entre peleas o cuando estés herido."] = "Твое базовое лечение. Применяй между боями или когда ранен.",
	["Tu curación fuerte. Úsala entre peleas o cuando alguien está muy herido."] = "Твое сильное лечение. Применяй между боями или когда кто-то тяжело ранен.",
	["Tu curación más fuerte. Es lenta: empiézala antes de que sea tarde."] = "Твое самое сильное лечение. Оно медленное: начинай, пока не поздно.",
	["Tu daño"] = "Твой урон",
	["Tu demonio"] = "Ваш демон",
	["Tu demonio es más fuerte y tú más resistente: el brujo más seguro."] = "Ваш демон сильнее, а вы крепче: самый безопасный чернокнижник.",
	["Tu destino"] = "Твоя цель",
	["Tu destino y tus marcadores ya no desaparecen cuando hay muchos pines."] = "Ваша цель и маркеры больше не пропадают, когда меток много.",
	["Tu diario"] = "Ваш дневник",
	["Tu diario de mazmorras"] = "Ваш журнал подземелий",
	["Tu día con la manada: el plan, lo urgente y tu clase."] = "Ваш день со стаей: план, срочное и ваш класс.",
	["Tu día de caza"] = "Твой охотничий день",
	["Tu día de caza: Lya cuenta tus misiones, niveles, oro y raros del día. Pídeselo con /alfa lya dia."] = "Твой охотничий день: Лия считает задания, уровни, золото и редких за день. Спроси её: /alfa lya dia.",
	["Tu elección"] = "Ваш выбор",
	["Tu entrenador de clase tiene algo para ti."] = "У учителя вашего класса есть что-то для вас.",
	["Tu entrenador de equitación"] = "Ваш учитель верховой езды",
	["Tu entrenador tiene algo nuevo para ti"] = "У вашего учителя есть для вас что-то новое",
	["Tu entrenador: %s (%s)."] = "Ваш учитель: %s (%s).",
	["Tu entrenador: %s."] = "Ваш учитель: %s.",
	["Tu equipo está al %d %%: repara antes de entrar"] = "Прочность снаряжения %d %%: почини его перед входом",
	["Tu equipo está al %d%%. Mejor repararlo antes de la siguiente pelea."] = "Прочность экипировки %d%%. Лучше починить ее до следующего боя.",
	["Tu equipo está por romperse"] = "Снаряжение вот-вот сломается",
	["Tu equipo se está gastando"] = "Ваша экипировка изнашивается",
	["Tu equipo ya va en %d %%: cuídalo."] = "Прочность снаряжения уже %d %%: береги его.",
	["Tu equipo, tus bolsas y tu entrenamiento están al día."] = "Экипировка, сумки и обучение — все в порядке.",
	["Tu escudo protege mucho, pero deja al aliado con el alma debilitada un rato: no puedes ponérselo otra vez enseguida."] = "Твой щит хорошо защищает, но на время оставляет союзнику «Ослабленную душу»: сразу наложить его снова нельзя.",
	["Tu especialización"] = "Ваша специализация",
	["Tu estilo"] = "Ваш стиль",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "Ваш стиль (Alfa, Классический WoW или Стекло), акцентный цвет и вой.",
	["Tu estilo, el color de acento, el aullido, leer mejor y tus atajos."] = "Твой стиль, цвет акцента, вой, удобное чтение и горячие клавиши.",
	["Tu estilo: %s"] = "Ваш стиль: %s",
	["Tu facción (%s)"] = "Ваша фракция (%s)",
	["Tu forma de viaje es un felino veloz... pero en una carrera yo no te la pondría fácil."] = "Твой походный облик — быстрая кошка... но в гонке я бы тебе поблажек не дала.",
	["Tu gente no confía en la magia arcana: recuerda bien lo que pasó con Azshara y el Pozo de la Eternidad."] = "Твой народ не доверяет тайной магии: он хорошо помнит, что случилось с Азшарой и Источником Вечности.",
	["Tu gente, los humanos, desciende de las tribus que el rey Thoradin unió en Arathor hace miles de años."] = "Твой народ, люди, происходит от племен, которые король Торадин объединил в Араторе тысячи лет назад.",
	["Tu golpe más fuerte desde el nivel 40 hasta el 60."] = "Ваш самый сильный удар с 40 по 60 уровень.",
	["Tu golpe más fuerte desde el nivel 40."] = "Ваш самый сильный удар с 40 уровня.",
	["Tu golpe más fuerte, crece con tu bloqueo."] = "Ваш самый сильный удар, растет вместе с блоком.",
	["Tu golpe más fuerte, y además reduce las curas del enemigo."] = "Ваш самый сильный удар, который к тому же снижает исцеление противника.",
	["Tu golpe más fuerte."] = "Ваш самый сильный удар.",
	["Tu golpe principal contra jefes."] = "Ваш главный удар против боссов.",
	["Tu golpe principal."] = "Ваш главный удар.",
	["Tu grupo"] = "Ваша группа",
	["Tu grupo en el mapa"] = "Ваша группа на карте",
	["Tu grupo o banda en el mapa y el minimapa, con el color de su clase."] = "Ваша группа или рейд на карте и мини-карте, цветом их класса.",
	["Tu grupo y tu banda con su vida, para curar con un clic. Se cambia fuera de combate."] = "Ваша группа и рейд со здоровьем, чтобы лечить одним щелчком. Меняется вне боя.",
	["Tu grupo, tu hermandad y tus amigos en el mapa, con Seguir y la página del clan."] = "Ваша группа, гильдия и друзья на карте — со следованием и страницей клана.",
	["Tu guarida a la vista"] = "Твоё логово на виду",
	["Tu guarida en el rastreador y en el cuadro de los lobos, y Lya te avisa si el juego te cambia de capa."] = "Твоё логово в трекере и в подсказке волков, и Лия скажет, если игра сменит твой слой.",
	["Tu guarida está abierta: si alguien de la manada pide entrar, Alfa lo invita a tu grupo."] = "Твоё логово открыто: если кто-то из стаи попросится, Alfa пригласит его в твою группу.",
	["Tu guía"] = "Ваш гайд",
	["Tu guía deja fuera las misiones que ya no dan experiencia, salvo que otra las necesite."] = "Гайд пропускает задания, которые больше не дают опыта, если они не нужны для другого.",
	["Tu guía está lista. Ábrela para ver tu paso."] = "Ваш гайд готов. Откройте его, чтобы увидеть свой шаг.",
	["Tu guía puede elegir y avanzar sola, o preguntarte en cada cruce."] = "Гайд может сам выбирать и идти дальше или спрашивать вас на каждой развилке.",
	["Tu guía te lleva a entrenar en %d pasos."] = "Шагов до учителя по гайду: %d.",
	["Tu guía te lleva a entrenar en este paso."] = "Гайд приведет вас к учителю на этом шаге.",
	["Tu guía te lleva a tomarla."] = "Гайд приведет вас за ним.",
	["Tu guía terminó y el camino se abre"] = "Гайд окончен, и путь разветвляется",
	["Tu guía y Hoy dicen lo mismo: al terminar «Desbloquear» vuelves solo a tu guía, y el final de una guía con pasos sin hacer ya no dice «terminaste»."] = "Гайд и «Сегодня» говорят одно и то же: после «Разблокировать» ты сам возвращаешься к гайду, а конец гайда с невыполненными шагами больше не пишет «готово».",
	["Tu guía ya no te manda a entregar misiones sin terminar: primero te lleva a lo que falta, y «Cerrar mis misiones» se pone al día sola."] = "Гайд больше не отправляет вас сдавать невыполненные задания: сначала он ведет к тому, что осталось, а «Закрыть мои задания» обновляется само.",
	["Tu guía, más lista"] = "Гид поумнее",
	["Tu hechizo principal de fuego."] = "Ваше основное заклинание огня.",
	["Tu hechizo principal."] = "Ваше основное заклинание.",
	["Tu hechizo principal: daño y frena al enemigo."] = "Ваше основное заклинание: урон и замедление противника.",
	["Tu hermandad conectada"] = "Гильдия в сети",
	["Tu hermandad sabe tu clase y tu nivel, para que te avisen si les sale algo que te sirve."] = "Гильдия знает твой класс и уровень, чтобы сказать, если им выпадет что-то для тебя.",
	["Tu hermandad se entera cuando llegas al nivel 60, consigues tu primera montura o cazas un raro."] = "Твоя гильдия узнает, когда ты достигнешь 60-го уровня, получишь первого скакуна или добудешь редкого.",
	["Tu hermandad y tu grupo reciben los horarios que tomas, y tú los suyos."] = "Ваша гильдия и группа получают выбранное вами время рейсов, а вы — их.",
	["Tu hermandad ya sabe tu clase y tu nivel: te avisarán si les sale algo que te sirve."] = "Твоя гильдия теперь знает твой класс и уровень: тебе скажут, если найдут что-то для тебя.",
	["Tu historia"] = "Твоя история",
	["Tu historia empieza pronto"] = "Твоя история скоро начнется",
	["Tu historia tiene una página: %s."] = "В твоей истории одна страница: %s.",
	["Tu historial"] = "Ваша история",
	["Tu insignia de La Jauría en el borde de tu retrato, y en el de tu objetivo si la lleva."] = "Ваш значок La Jauría на краю портрета, а также у цели, если он у неё есть.",
	["Tu insignia en los retratos"] = "Ваш значок на портретах",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "Установка смешанная или неполная (%s). Закройте игру, удалите все папки Alfa в Interface/AddOns и установите Alfa заново через приложение CurseForge или свежий zip (не \"Source code\").",
	["Tu instructor más cercano: %s, en %s."] = "Ближайший учитель: %s, %s.",
	["Tu instructor más cercano: %s."] = "Ближайший учитель: %s.",
	["Tu ira se llena al pegar y al recibir golpes: entra a la pelea con Cargar para empezar con ira."] = "Ярость копится, когда ты бьешь и когда бьют тебя: начинай бой с «Рывка», чтобы сразу иметь ярость.",
	["Tu libro no tiene hechizos para aliados"] = "В вашей книге заклинаний нет заклинаний для союзников",
	["Tu lista de compras"] = "Твой список покупок",
	["Tu lista de compras no pudo agregarlo."] = "Не удалось добавить в список покупок.",
	["Tu lista de sonidos"] = "Ваш список звуков",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Ваш список звуков пуст. Добавьте звук командой /alfa silenciar <номер>.",
	["Tu lista de sonidos quedó vacía."] = "Ваш список звуков теперь пуст.",
	["Tu lista está vacía"] = "Твой список пуст",
	["Tu lista ya tiene 20 metas: termina o quita alguna primero."] = "В списке уже 20 целей: сначала заверши или убери одну.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Ваш список: следуйте за ними по стрелке, делитесь с группой, изменяйте или удаляйте.",
	["Tu loba compañera: consejos cortos, ánimo y nunca te deja atrás."] = "Ваша спутница-волчица: короткие советы, поддержка, и она никогда вас не бросит.",
	["Tu loba compañera: te da consejos y ánimo. También con /alfa lya."] = "Ваша спутница-волчица: советует и подбадривает. Также командой /alfa lya.",
	["Tu lugar resalta más: tu flecha lleva un aro y un pulso suave, y se ve bien hasta en la nieve."] = "Твоё место заметнее: у стрелки есть кольцо и мягкая пульсация, и её хорошо видно даже на снегу.",
	["Tu manada"] = "Ваша стая",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "Ваша стая на карте: ваша группа и те, кто пользуется Alfa и делится. Следуйте за ними по стрелке, приглашайте их и знакомьтесь с кланом.",
	["Tu manada está fuera del mapa"] = "Ваша стая вне карты",
	["Tu manáfago: quita magia y bloquea hechizos enemigos."] = "Твой охотник Скверны: снимает магию и блокирует заклинания врага.",
	["Tu mapa"] = "Ваша карта",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "Ваша схема мыши пуста: сначала выберите что-нибудь для ячейки.",
	["Tu marcador"] = "Ваш маркер",
	["Tu mascota"] = "Ваш питомец",
	["Tu mascota aprende habilidades de otras bestias: doma una que sepa lo que quieres y te lo enseña."] = "Твой питомец учится способностям у других зверей: приручи того, кто знает нужное, и он научит.",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Питомец делает большую часть работы и принимает удары: самый простой и безопасный способ прокачать охотника.",
	["Tu mascota tiene poca vida: cúrala."] = "У питомца мало здоровья: вылечите его.",
	["Tu mejor día: %d misiones"] = "Лучший день: заданий %d",
	["Tu mejor día: %d misiones."] = "Твой лучший день: заданий — %d.",
	["Tu mentor: %s"] = "Твой наставник: %s",
	["Tu montura de clase"] = "Ваш классовый транспорт",
	["Tu montura rápida (nivel 60)"] = "Ваш быстрый транспорт (60-й уровень)",
	["Tu munición"] = "Ваши боеприпасы",
	["Tu nivel"] = "Ваш уровень",
	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "Ваш уровень, ремонт, еда и напитки и вход в подходящее вам подземелье.",
	["Tu nota"] = "Ваша заметка",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Ваша цель уклонилась: от Превосходства нельзя уклониться, и оно бьет сильно. Нужна Боевая стойка.",
	["Tu oro"] = "Ваше золото",
	["Tu pantalla y tu compañera"] = "Ваш экран и ваша спутница",
	["Tu papel"] = "Твоя роль",
	["Tu paso de ahora es el %d."] = "Ваш текущий шаг — %d.",
	["Tu paso de ahora es el %d: %s."] = "Ваш текущий шаг — %d: %s.",
	["Tu pelea"] = "Твой бой",
	["Tu personaje"] = "Ваш персонаж",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego y nunca dentro de mazmorras; va por un canal oculto que alguien con otro addon podría leer."] = "Ваш персонаж появляется на карте тех, кто тоже показывает себя. Только его место в игре и никогда в подземельях; это идёт через скрытый канал, который кто-то с другим аддоном может прочитать.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Ваш персонаж перестает говорить «Недостаточно маны», «Это еще не готово» и подобное. Красный текст остается.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "Ваш персонаж не появляется на карте ни у кого из La Jauría. Это можно изменить в любой момент на странице La Jauría.",
	["Tu personaje todavía no recolecta. Con Minería o Herboristería, Alfa une las minas o las hierbas de tu zona en una vuelta corta. Te las enseña un instructor de profesión."] = "Ваш персонаж пока ничего не собирает. С горным делом или травничеством Alfa соединит залежи или травы вашей зоны в короткий круг. Обучиться этим профессиям можно у учителя профессии.",
	["Tu pesca"] = "Ваша рыбалка",
	["Tu pesca está al máximo"] = "Ваша рыбная ловля на максимуме",
	["Tu piedra de hogar te regresa a tu posada. Úsala para ahorrar caminata."] = "Камень возвращения переносит тебя в твою таверну. Пользуйся им, чтобы меньше ходить пешком.",
	["Tu piedra de hogar y el descanso"] = "Камень возвращения и отдых",
	["Tu pieza más gastada: %s al %d %%."] = "Самая изношенная вещь: %s, %d %%.",
	["Tu plan"] = "Ваш план",
	["Tu plan de juego"] = "Твой план игры",
	["Tu plan está en Talentos."] = "Ваш план — в «Талантах».",
	["Tu plan no pudo agregarlo."] = "Не удалось добавить в план.",
	["Tu plan no tiene metas"] = "В вашем плане нет целей",
	["Tu plan no tiene metas todavía"] = "В вашем плане пока нет целей",
	["Tu plan para %s, con tus minutos de verdad."] = "Твой план на %s, с твоими реальными минутами.",
	["Tu plan para %s: unos %d min por misión, %s."] = "Твой план на %s: около %d мин на задание, %s.",
	["Tu plan se quedó sin paso"] = "В вашем плане не осталось шагов",
	["Tu plan se quedó sin paso. Seguir lo vuelve a armar con las misiones que tienes ahora."] = "В вашем плане не осталось шагов. «Следовать» соберёт его заново с текущими заданиями.",
	["Tu plano nuevo"] = "Твой новый слой",
	["Tu posición en la parte de abajo del minimapa."] = "Ваше положение внизу мини-карты.",
	["Tu posición y la del cursor bajo el mapa."] = "Ваше положение и положение курсора под картой.",
	["Tu primer demonio: el diablillo lanza fuego desde lejos."] = "Твой первый демон: бес мечет огонь издалека.",
	["Tu primer día en Azeroth"] = "Твой первый день в Азероте",
	["Tu primer punto, en el nivel 10."] = "Первое очко — на 10-м уровне.",
	["Tu primer raro"] = "Твой первый редкий",
	["Tu primer raro: %s"] = "Твой первый редкий: %s",
	["Tu primer talento"] = "Ваш первый талант",
	["Tu primera curación. Úsala entre peleas para no gastar comida."] = "Твое первое лечение. Применяй между боями, чтобы экономить еду.",
	["Tu primera guía"] = "Ваш первый гайд",
	["Tu primera mazmorra"] = "Твое первое подземелье",
	["Tu primera mazmorra: %s"] = "Твое первое подземелье: %s",
	["Tu primera montura"] = "Твое первое ездовое животное",
	["Tu primera montura (nivel 40)"] = "Ваш первый транспорт (40-й уровень)",
	["Tu primera sesión entra al diario cuando salgas del juego. La manada te espera: ¡a cazar!"] = "Ваш первый сеанс попадет в дневник, когда вы выйдете из игры. Стая ждет: на охоту!",
	["Tu prioridad"] = "Ваш приоритет",
	["Tu prioridad: %s"] = "Ваш приоритет: %s",
	["Tu progreso"] = "Ваш прогресс",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "Ваш собственный список целей в любом порядке: предмет, золото, профессия, место, задание, уровень или заметка. Alfa сам отслеживает их и ведет вас к каждой.",
	["Tu propio marco aparece aunque no estés en grupo, para curarte con un clic."] = "Ваша собственная рамка видна, даже если вы не в группе, чтобы лечить себя одним щелчком.",
	["Tu prueba"] = "Ваша проверка",
	["Tu rama: %s"] = "Ваша ветка: %s",
	["Tu rastro"] = "Ваш след",
	["Tu ratón"] = "Ваша мышь",
	["Tu registro está lleno: cierra algunas misiones primero."] = "Журнал заданий заполнен: сначала закройте некоторые задания.",
	["Tu registro está vacío"] = "Журнал заданий пуст",
	["Tu reporte, listo para pegar"] = "Ваш отчет готов к вставке",
	["Tu retrato y el de tu objetivo"] = "Твой портрет и портрет цели",
	["Tu ritmo de los últimos 15 minutos"] = "Ваш темп за последние 15 минут",
	["Tu ritmo de los últimos 15 minutos, con el contador de XP de Alfa."] = "Ваш темп за последние 15 минут, по счетчику опыта Alfa.",
	["Tu ruta de %d tramos."] = "Ваш маршрут: этапов — %d.",
	["Tu ruta de %s en %s está lista"] = "Маршрут «%s» в %s готов",
	["Tu ruta dibujada en el mapa de Alfa hasta tu destino, que late para que lo encuentres; arriba ves a qué distancia está y cuánto falta, y un clic te muestra todo el camino."] = "Твой маршрут на карте Alfa до цели, которая пульсирует, чтобы ты её заметил; вверху видно, как далеко она и сколько осталось, а один щелчок покажет весь путь.",
	["Tu ruta está vacía"] = "Ваш маршрут пуст",
	["Tu ruta no pudo agregarlo."] = "Маршрут не смог это добавить.",
	["Tu ruta no tiene tramos todavía"] = "В вашем маршруте пока нет этапов",
	["Tu ruta pasa por ahí."] = "Ваш маршрут проходит там.",
	["Tu ruta personalizada, armada por Alfa con tus tramos."] = "Ваш собственный маршрут, составленный Alfa из ваших этапов.",
	["Tu ruta se actualizó"] = "Маршрут обновлен",
	["Tu ruta, guía por guía"] = "Твой маршрут, гид за гидом",
	["Tu ruta, paso a paso"] = "Ваш маршрут шаг за шагом",
	["Tu ruta, tus misiones y tus guías (/alfa rutas ayuda)."] = "Ваш маршрут, задания и гайды (/alfa rutas ayuda).",
	["Tu semana de caza"] = "Твоя охотничья неделя",
	["Tu semana se comparte con tu hermandad. Cada lobo suma; aquí nadie compite."] = "Твоя неделя видна гильдии. Каждый волк добавляет свое; здесь никто не соревнуется.",
	["Tu semana solo la ves tú. Compártela en los ajustes de abajo para sumar con la manada."] = "Твою неделю видишь только ты. Поделись ею в настройках ниже, чтобы она вошла в общий счет стаи.",
	["Tu semana: %s"] = "Твоя неделя: %s",
	["Tu sesión anterior (%s): %s"] = "Ваш прошлый сеанс (%s): %s",
	["Tu sesión anterior, %s"] = "Ваш прошлый сеанс, %s",
	["Tu sesión de ahora"] = "Текущий сеанс",
	["Tu sesión de pesca ya estaba vacía: la nueva empieza con tu primer lanzamiento."] = "Ваша рыболовная сессия уже была пустой: новая начнётся с первого заброса.",
	["Tu sesión, tu diario, recordatorios y tu siguiente paso, con el color de tu clase."] = "Ваш сеанс, дневник, напоминания и следующий шаг — в цвете вашего класса.",
	["Tu siguiente mazmorra"] = "Ваше следующее подземелье",
	["Tu siguiente paso"] = "Ваш следующий шаг",
	["Tu siguiente paso, lo urgente y lo de tu clase, de un vistazo."] = "Ваш следующий шаг, срочное и все для вашего класса — с одного взгляда.",
	["Tu siguiente talento"] = "Ваш следующий талант",
	["Tu spot de farmeo"] = "Твое место фарма",
	["Tu súcubo: mucho daño y puede seducir a un enemigo para controlarlo."] = "Твоя суккуба: много урона, и она может соблазнить врага, чтобы его контролировать.",
	["Tu tecla de pantalla limpia"] = "Твоя клавиша чистого экрана",
	["Tu tecla del mapa (%s) lo abre."] = "Ваша клавиша карты (%s) открывает ее.",
	["Tu tecla primero te pone la mejor caña y lo que tengas con bonificación de pesca (sombrero, guantes, botas, abalorios)."] = "Сначала клавиша надевает лучшую удочку и все с бонусом к рыбной ловле (шляпу, перчатки, сапоги, аксессуары).",
	["Tu tecla y tus ajustes del juego quedan como siempre. Enciéndela para pescar con una sola tecla."] = "Ваша клавиша и игровые настройки остаются как всегда. Включите, чтобы рыбачить одной клавишей.",
	["Tu tiempo de juego"] = "Твое время игры",
	["Tu tiempo y tu camino al 60"] = "Твое время и путь к 60",
	["Tu ventana de Alfa"] = "Ваше окно Alfa",
	["Tu vida baja: Rejuvenecimiento te cura poco a poco."] = "Здоровье падает: Омоложение лечит вас постепенно.",
	["Tu vida baja: Renovar te cura poco a poco."] = "Здоровье падает: Обновление лечит вас постепенно.",
	["Tu vida baja: el escudo absorbe el daño."] = "Здоровье падает: щит поглощает урон.",
	["Tu vida está a punto de acabarse: Imposición de manos te cura entero."] = "Здоровье на исходе: Возложение рук полностью исцелит вас.",
	["Tu vida está baja: cúrate rápido."] = "Мало здоровья: быстро вылечитесь.",
	["Tu vida está baja: cúrate."] = "Мало здоровья: вылечитесь.",
	["Tu vida está baja: róbasela al enemigo."] = "Мало здоровья: отнимите его у противника.",
	["Tu vida está muy baja: cúrate rápido."] = "Очень мало здоровья: быстро вылечитесь.",
	["Tu vuelo en el mapa"] = "Твой полёт на карте",
	["Tu zona"] = "Твоя зона",
	["Tu árbol"] = "Ваше дерево",
	["Tu última pelea"] = "Твой последний бой",
	["Tu última sesión: %s · %s"] = "Прошлый сеанс: %s · %s",
	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Последнее сканирование: %s. Просканируйте аукцион снова, чтобы цены были актуальны.",
	["Turalyon y Alleria Brisaveloz cruzaron el Portal Oscuro tras la guerra para cerrarles el paso a los orcos, y no regresaron."] = "Туралион и Аллерия Ветрокрылая ушли после войны за Темный портал, чтобы отрезать путь оркам, и не вернулись.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "Все очки (%d) там, где их требует билд. Дальше — снаряжение: вещи с характеристиками, полезными вашему билду.",
	["Tus actitudes son de batalla, defensiva y rabiosa; elige la que pida el momento."] = "Твои стойки — боевая, оборонительная и берсерка; выбирай ту, что нужна в этот момент.",
	["Tus ajustes de Alfa llegaron vacíos"] = "Настройки Alfa оказались пустыми",
	["Tus ajustes pasan una prueba de guardar y recargar en cada versión, para que nunca se pierdan."] = "Ваши настройки проходят проверку сохранения и перезагрузки в каждой версии, чтобы никогда не потеряться.",
	["Tus ajustes quedaron guardados: %s."] = "Настройки сохранены: %s.",
	["Tus ajustes volvieron a como estaban: %s. Algunas cosas se ven completas al recargar."] = "Настройки вернулись к состоянию: %s. Кое-что покажется полностью после перезагрузки.",
	["Tus ajustes vuelven a como estaban: %s. Lo de ahora queda guardado como el perfil «%s»."] = "Настройки вернутся к состоянию: %s. Текущие сохранятся как профиль «%s».",
	["Tus atajos"] = "Твои горячие клавиши",
	["Tus atajos de Alfa"] = "Твои горячие клавиши Alfa",
	["Tus atajos se abren al terminar el combate."] = "Твои горячие клавиши откроются после боя.",
	["Tus avisos"] = "Ваши оповещения",
	["Tus beneficios y perjuicios"] = "Твои положительные и отрицательные эффекты",
	["Tus bolsas"] = "Ваши сумки",
	["Tus bolsas están casi llenas"] = "Ваши сумки почти полны",
	["Tus bolsas están llenas"] = "Ваши сумки полны",
	["Tus bolsas están vacías"] = "Ваши сумки пусты",
	["Tus bolsas piden auxilio (%d libres). Vende o tira lo que ya no uses."] = "Сумки просят о помощи (свободно: %d). Продай или выброси то, чем больше не пользуешься.",
	["Tus bolsas se están llenando"] = "Сумки заполняются",
	["Tus bolsas se están llenando: queda 1 casilla."] = "Сумки заполняются: осталась 1 ячейка.",
	["Tus bolsas se están llenando: quedan %d casillas."] = "Сумки заполняются: осталось ячеек: %d.",
	["Tus bolsas se llenaron: lo demás sigue en el buzón."] = "Сумки заполнились: остальное лежит в почтовом ящике.",
	["Tus bolsas y tu banco en una sola ventana, y lo que lleva cada uno de tus personajes."] = "Ваши сумки и банк в одном окне, а также то, что носит каждый ваш персонаж.",
	["Tus builds importados"] = "Ваши импортированные билды",
	["Tus clics"] = "Ваши щелчки",
	["Tus clics de Curación se aplican al salir de combate."] = "Ваши щелчки «Исцеления» применятся после выхода из боя.",
	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Ваши щелчки вернутся к набору. Ручные изменения будут потеряны.",
	["Tus clics:"] = "Ваши щелчки:",
	["Tus comodidades están listas"] = "Ваши удобства готовы",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Участники вашей группы и рейда на карте Alfa.",
	["Tus conjuntos de equipo"] = "Твои комплекты экипировки",
	["Tus conjuntos:"] = "Твои комплекты:",
	["Tus críticos de habilidades pegan todavía más."] = "Критические удары ваших способностей бьют еще сильнее.",
	["Tus críticos hacen muchísimo daño."] = "Ваши критические удары наносят огромный урон.",
	["Tus críticos hacen sangrar: matas más rápido y sufres menos."] = "Ваши критические удары вызывают кровотечение: вы убиваете быстрее и меньше страдаете.",
	["Tus críticos sangran."] = "Ваши критические удары вызывают кровотечение.",
	["Tus críticos sangran: más daño y amenaza."] = "Ваши критические удары вызывают кровотечение: больше урона и угрозы.",
	["Tus curas curan más."] = "Ваше исцеление лечит сильнее.",
	["Tus datos"] = "Ваши данные",
	["Tus datos guardados"] = "Твои сохраненные данные",
	["Tus demonios llegan con misiones: diablillo, abisario, súcubo y manáfago; y más adelante, el infernal y el guardia apocalíptico."] = "Твои демоны приходят через задания: бес, демон Бездны, суккуб и охотник Скверны; а позже инфернал и страж ужаса.",
	["Tus días de caza"] = "Твои дни охоты",
	["Tus estadísticas"] = "Ваши характеристики",
	["Tus extras"] = "Твои дополнения",
	["Tus flechas de mejora no usan tu build"] = "Стрелки улучшения не учитывают ваш билд",
	["Tus flechas de mejora usan tu build"] = "Стрелки улучшения учитывают ваш билд",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Ваши удары достают второго противника: идеально, когда на вас двое.",
	["Tus golpes hacen daño sagrado extra. Tu sello de siempre para pelear solo."] = "Твои удары наносят дополнительный урон от светлой магии. Повседневная печать для одиночной игры.",
	["Tus golpes sagrados generan más amenaza. Préndela si vas a tanquear."] = "Твой урон от светлой магии создает больше угрозы. Включай, если танкуешь.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Ваши крики действуют дальше и дольше: вы помогаете всей группе.",
	["Tus habilidades cuestan menos ira."] = "Ваши способности стоят меньше ярости.",
	["Tus habilidades de ira te curan: menos descanso."] = "Ваши способности ярости лечат вас: меньше отдыха.",
	["Tus habilidades nuevas"] = "Ваши новые способности",
	["Tus habilidades que tardan en volver, en una barra discreta con lo que les falta."] = "Твои способности с долгим восстановлением — на неприметной полосе с оставшимся временем.",
	["Tus hechizos de daño pegan más."] = "Ваши атакующие заклинания бьют сильнее.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Ваши ледяные заклинания замедляют: монстр почти никогда не успевает вас ударить.",
	["Tus hechizos fallan menos."] = "Ваши заклинания реже промахиваются.",
	["Tus hechizos hacen crítico más seguido."] = "Ваши заклинания чаще наносят критический эффект.",
	["Tus herramientas de combate"] = "Ваши боевые инструменты",
	["Tus historias"] = "Ваши истории",
	["Tus llaves junto a tus bolsas."] = "Ваши ключи рядом с сумками.",
	["Tus marcadores"] = "Ваши маркеры",
	["Tus marcadores en el mapa de Alfa y en el del juego."] = "Ваши маркеры на карте Alfa и на карте игры.",
	["Tus marcadores también en el minimapa, cuando estás cerca."] = "Ваши маркеры и на мини-карте, когда вы рядом.",
	["Tus marcos aparecen al entrar a un grupo"] = "Ваши рамки появятся, когда вы вступите в группу",
	["Tus marcos de combate volvieron a su lugar de siempre."] = "Ваши боевые окна вернулись на привычное место.",
	["Tus marcos de combate vuelven a su lugar de siempre."] = "Боевые рамки возвращаются на обычное место.",
	["Tus marcos de curación están apagados"] = "Рамки исцеления выключены",
	["Tus marcos están listos"] = "Ваши рамки готовы",
	["Tus metas de pesca"] = "Твои рыболовные цели",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "Ваши цели в вашем порядке: предмет, золото, профессия, место...",
	["Tus misiones"] = "Ваши задания",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "Ваши открытые задания — чтобы выполнить и сдать их по самому короткому пути.",
	["Tus misiones aquí"] = "Твои задания здесь",
	["Tus misiones en su voz"] = "Твои задания ее голосом",
	["Tus misiones grises valen la pena o no tienes ninguna."] = "Твои серые задания стоят того, или их у тебя нет.",
	["Tus misiones y tus viajes"] = "Твои задания и путешествия",
	["Tus misiones, raros, mazmorras y niveles de la semana suman en «La semana de la manada» de tu hermandad."] = "Твои задания, редкие, подземелья и уровни за неделю добавляются в «Неделю стаи» твоей гильдии.",
	["Tus notas en el mapa"] = "Твои заметки на карте",
	["Tus notas en el mapa, donde las dejas. Un clic en la marca y la flecha te lleva."] = "Твои заметки на карте, там, где ты их оставил. Щелчок по метке — и стрелка поведет тебя.",
	["Tus notas nuevas también salen en el mapa de los lobos de tu hermandad, y ves las suyas."] = "Твои новые заметки видны и на карте волков твоей гильдии, а ты видишь их заметки.",
	["Tus números"] = "Ваши цифры",
	["Tus oficios"] = "Твои профессии",
	["Tus oficios con su paso de ahora y la guía de cada uno. La guía también se abre con /alfa comercio oficios."] = "Твои профессии с текущим шагом и гидом для каждой. Гид также открывается через /alfa comercio oficios.",
	["Tus perfiles"] = "Твои профили",
	["Tus personajes"] = "Ваши персонажи",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "Ваши аукционные цены устарели: просканируйте аукцион снова.",
	["Tus profesiones"] = "Ваши профессии",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "Следующие удары задевают еще одного противника.",
	["Tus puntos"] = "Ваши очки",
	["Tus puntos van por otro camino"] = "Ваши очки вложены иначе",
	["Tus recargas largas"] = "Твои долгие восстановления",
	["Tus recetas de pescado, la cola de cocina y la fogata."] = "Ваши рыбные рецепты, очередь готовки и костер.",
	["Tus recetas que dejan ganancia"] = "Ваши прибыльные рецепты",
	["Tus spots de farmeo en el mapa, dorados y en su propia capa."] = "Твои места фарма на карте, золотом и на своем слое.",
	["Tus spots nuevos también salen en el mapa de los lobos de tu hermandad, y ves los suyos."] = "Твои новые места видны и на картах волков твоей гильдии, а ты видишь их места.",
	["Tus talentos"] = "Ваши таланты",
	["Tus tótems de tierra, fuego, agua y aire se ganan con misiones a lo largo de tu camino."] = "Тотемы земли, огня, воды и воздуха ты получаешь за задания по ходу пути.",
	["Tuya"] = "Твоя",
	["Tyrande liberó a Illidan para pelear contra la Plaga, y Maiev, su carcelera, nunca se lo perdonó."] = "Тиранда освободила Иллидана, чтобы сражаться с Плетью, и Майев, его тюремщица, так ей этого и не простила.",
	["Tótem"] = "Тотем",
	["Tótems"] = "Тотемы",
	["Tótems enemigos"] = "Вражеские тотемы",
	["Tú"] = "Вы",
	["Tú no contestas: actívalo en los ajustes de abajo si quieres ayudar a la manada."] = "Ты не отвечаешь: включи в настройках ниже, если хочешь помогать стае.",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Вы принимаете удары и защищаете группу. Нужен щит.",
	["Tú también contestas: si alguien busca algo que llevas, Alfa le dice cuántos tienes (solo eso)."] = "Ты тоже отвечаешь: если кто-то ищет то, что есть у тебя, Alfa скажет ему, сколько у тебя (только это).",
	["Ubicación de %s"] = "Местоположение: %s",
	["Ultra"] = "Ультра",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "По оружию в каждой руке и много ярости: больше всех урона в группе.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Большое двуручное оружие и удары с кровотечением. Самый простой способ прокачки.",
	["Un aturdimiento cuando lo necesites."] = "Оглушение, когда оно нужно.",
	["Un aullido corto cada vez que entregas una misión. Viene apagado."] = "Короткий вой при каждой сдаче задания. По умолчанию выключено.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Волчий вой из самой игры при первом открытии Alfa в каждом сеансе.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Оповещение с боссами и тем, сколько вы победили, — в одном щелчке от советов.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Короткое оповещение с местом, его зоной и временем пути.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Короткое оповещение, когда срабатывает способность, зависящая от происходящего, например Превосходство после уклонения противника.",
	["Un aviso cuando juntas todo lo de un material o la lista entera."] = "Сообщение, когда собран весь материал или весь список.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Оповещение, когда вы побеждаете нового босса, — в одном щелчке от его добычи.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Оповещение и полоса в сумках: что продать, что оставить и к какому торговцу идти, плюс один щелчок, чтобы отметить хлам.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Мягкое темное затемнение на значках, пока идет восстановление.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Рамка цвета качества: зеленая, синяя, фиолетовая...",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Пульсирующая зеленая рамка на кнопке панели с предложенной способностью, чтобы быстро ее найти.",
	["Un botón «Alfa» en el menú Esc, como el ícono del minimapa: clic, abre la ventana de Alfa; clic derecho, el menú de Alfa."] = "Кнопка «Alfa» в меню Esc, как значок у миникарты: щелчок открывает окно Alfa, правый щелчок — меню Alfa.",
	["Un brujo con dos compañeros puede invocar al resto del grupo a la entrada de una mazmorra."] = "Чернокнижник с двумя помощниками может призвать остальную группу ко входу в подземелье.",
	["Un buzón"] = "Почтовый ящик",
	["Un clic bajito cuando Lya te dice algo."] = "Тихий щелчок, когда Lya что-то говорит.",
	["Un clic te pone el conjunto (fuera de combate; en combate, al terminar). Lo que esté en el banco no se puede poner."] = "Один щелчок надевает комплект (вне боя; в бою — после него). То, что лежит в банке, надеть нельзя.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Один щелчок — и остается только главное: вы, ваша группа, ваши маркеры и следующий шаг гайда.",
	["Un compañero tiene %s y tú lo puedes quitar, pero ningún clic lo hace. Elige «%s» en Tus clics, en la página Curación."] = "У союзника %s, и ты можешь это снять, но ни один щелчок этого не делает. Выбери «%s» в «Ваши щелчки» на странице «Исцеление».",
	["Un consejo"] = "Совет",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Небольшое подвижное окошко со здоровьем и самыми важными для вашего класса характеристиками. В бою игра скрывает некоторые числа: остается последнее прочитанное значение.",
	["Un disparo instantáneo extra. Úsalo mientras corres o para rematar."] = "Дополнительный мгновенный выстрел. Применяй на ходу или для добивания.",
	["Un enemigo"] = "Один противник",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Ошибка, идея или комментарий — прямо разработчику",
	["Un escudo que absorbe daño. Ponlo antes de que te peguen o en quien tanquea."] = "Щит, поглощающий урон. Наложи до того, как тебя ударят, или на своего танка.",
	["Un fondo del color de tu clase bajo tu nombre."] = "Фон цвета вашего класса под вашим именем.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Огромный удар щитом и очень много угрозы.",
	["Un golpe más para gastar ira."] = "Еще один удар, чтобы тратить ярость.",
	["Un golpe nuevo y fuerte para tu barra."] = "Новый сильный удар для вашей панели.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Большой прирост урона против сложных монстров; к тому же освобождает от страха.",
	["Un grano fino de cine sobre el mundo."] = "Тонкое киношное зерно поверх мира.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Тонкое зерно, как в кино. Почти не нагружает: меняется около 14 раз в секунду и только когда видно.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Заклинание старого ранга на панели",
	["Un lobo de La Jauría anda cerca"] = "Рядом волк из La Jauría",
	["Un lobo de nivel %d te quiere echar la mano: ve tu nivel, tu zona y tu misión, solo él. Acepta aquí o en La Jauría."] = "Волк %d-го уровня хочет тебе помочь: только он увидит твой уровень, зону и задание. Прими здесь или в La Jauría.",
	["Un mapa de una pieza: al acercar ya no se ven pedazos pegados, y el terreno se une sin rayas ni cuadros."] = "Карта единым целым: при приближении больше не видно склеенных кусков, а местность соединяется без полос и квадратов.",
	["Un mapa impecable"] = "Безупречная карта",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Золотая рамка на предметах для заданий (с «!», если предмет начинает задание).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Нужный вам предмет: Alfa строит путь к нему со всем, что нужно сначала.",
	["Un paisaje más bonito"] = "Пейзаж покрасивее",
	["Un paseíto y unas palabras. Así también se hace manada."] = "Небольшая прогулка и пара слов. Так тоже становятся стаей.",
	["Un pescadito asado no me caería nada mal."] = "Жареная рыбка мне бы сейчас не помешала.",
	["Un pescadito asado para la loba que te acompaña no estaría nada mal, ¿eh?"] = "Жареная рыбка для волчицы, которая тебя сопровождает, была бы совсем не лишней, а?",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Маленькая метка с номером там, куда ведут следующие шаги.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Немного шанса критического удара, уклонения и брони.",
	["Un poco de vida de vuelta después de críticos."] = "Немного здоровья обратно после критических ударов.",
	["Un poco más de defensa."] = "Чуть больше защиты.",
	["Un poco más de ira al cargar."] = "Чуть больше ярости от Рывка.",
	["Un punto azul abajo a la derecha si a ese compañero le falta el buff de tu clase. Se revisa fuera de combate."] = "Синяя точка справа внизу, если у союзника нет положительного эффекта твоего класса. Проверяется вне боя.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Одно очко, чтобы открыть следующий ряд и чуть реже промахиваться.",
	["Un raro vuelve más o menos entre media hora y una hora después de caer. Aquí ves hace cuánto lo cazaron tú o la manada."] = "Редкий возвращается примерно через полчаса–час после смерти. Здесь видно, как давно его убил ты или стая.",
	["Un raro: %s"] = "Редкий: %s",
	["Un rayo que salta entre varios enemigos."] = "Молния, которая перескакивает между несколькими врагами.",
	["Un reto de Lya para esta semana."] = "Испытание от Лии на эту неделю.",
	["Un rincón de %s que todavía no pisas."] = "Уголок зоны %s, где ты еще не бывал.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Ближайшая услуга, маркер на вашей карте, место, где вы сейчас, или вход в подземелье.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Восклицательный знак над теми, кто дает задания вашего уровня.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Вопросительный знак над теми, кому можно сдать выполненное задание.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Один аддон со всем, что нужно в игре: пошаговые гайды со стрелкой и маршрутом, карта, сумки, билды, исцеление по щелчку, сбор, подземелья, рыбная ловля и торговля. Все в едином стиле.",
	["Un solo día de precios: el historial crece con cada escaneo o búsqueda."] = "Цены только за один день: история растет с каждым сканированием или поиском.",
	["Un solo menú de Alfa: el ícono del minimapa, la lista de addons y el botón Alfa del menú Esc abren lo mismo."] = "Одно меню Alfa: значок у миникарты, список аддонов и кнопка Alfa в меню Esc открывают одно и то же.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Танк, который сильно бьет: много угрозы для групп с большим уроном ценой меньшей дополнительной защиты. Для танков с некоторым опытом.",
	["Un tramo más en la ruta que armas en la página Ruta: Alfa elige el camino para conseguirlo."] = "Еще один этап маршрута, который вы составляете на странице «Маршрут»: Alfa сам выберет путь, чтобы это получить.",
	["Un tótem que atrae los golpes de los enemigos. Te da un respiro."] = "Тотем, который притягивает атаки врагов. Дает передышку.",
	["Un tótem que cura poco a poco a tu grupo."] = "Тотем, который понемногу лечит твою группу.",
	["Un tótem que hace lentos a los enemigos cercanos. Para escapar o pelear con ventaja."] = "Тотем, замедляющий врагов рядом. Чтобы уйти или драться с преимуществом.",
	["Un tótem que le dispara fuego al enemigo. Ponlo al empezar."] = "Тотем, который стреляет во врага огнем. Ставь в начале.",
	["Un tótem que quita el miedo, el sueño y el encanto a tu grupo."] = "Тотем, который снимает страх, сон и очарование с твоей группы.",
	["Un tótem que reduce el daño que recibes cuerpo a cuerpo."] = "Тотем, снижающий урон в ближнем бою по тебе.",
	["Un zarpazo fuerte en forma de oso. Genera mucha amenaza."] = "Сильный удар в облике медведя. Создает много угрозы.",
	["Un «?» en cada página de Alfa para que Lya te la explique, y su propia tecla."] = "«?» на каждой странице Alfa, чтобы Лия её объяснила, и своя клавиша.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Значок со способностью, которую лучше применить сейчас. Только показывает: никогда ничего не нажимает за вас.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Значок задания на индикаторе здоровья противников и персонажей, которые еще нужны для задания из журнала. В подземельях игра скрывает эти данные, и они не отмечаются.",
	["Un'Goro de día: dinosaurios por todas partes. Yo me quedo atrás de ti, ¿va?"] = "Ун'Горо днем: динозавры повсюду. Я буду за твоей спиной, ладно?",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Одно крупное рекомендуемое действие и ваш путь в пару щелчков.",
	["Una barra bajo el buzón para tomar el dinero y los objetos de tus cartas con un clic, y lo que recibiste al final."] = "Полоска под почтовым ящиком, чтобы одним щелчком забрать деньги и предметы из писем, а в конце — что ты получил.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Полоса с атаками, которые собирается применить босс, и временем до каждой. Так вы знаете, когда отойти или защищаться.",
	["Una bienvenida nueva en 9 pasos con la intro del lobo: eliges el idioma de Alfa (hay 10) y cada cosa que hace sola por ti."] = "Новое приветствие из 9 шагов со вступлением с волком: вы выбираете язык Alfa (их 10) и все, что он делает за вас сам.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Одна строка текста содержит весь билд: вы ее копируете, передаете, а ее вставляют.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Сумма золота; цель выполнена, когда она у вас при себе.",
	["Una carta con objetos vence pronto"] = "Письмо с предметами скоро истечет",
	["Una categoría…"] = "Категория…",
	["Una cuenta de prueba no puede compartir"] = "Пробная учетная запись не может делиться",
	["Una curación muy rápida pero cara. Para emergencias."] = "Очень быстрое, но дорогое лечение. На крайний случай.",
	["Una curación más fuerte. Para cuando la vida baja mucho."] = "Более сильное лечение. Когда здоровье сильно падает.",
	["Una curación que salta entre tus compañeros heridos."] = "Лечение, которое перескакивает между ранеными друзьями.",
	["Una curación rápida y barata. Perfecta para mantener a todos de pie."] = "Быстрое и дешевое лечение. Идеально, чтобы держать всех на ногах.",
	["Una curación rápida. Para cuando no hay tiempo."] = "Быстрое лечение. Когда нет времени.",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Ряд с полетом, таверной, ремонтом, банком, почтой и вашим учителем — в один щелчок.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Стрелка на экране, указывающая на следующую цель, с расстоянием. Выключено: путь выбираете вы.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Зеленая стрелка на каждом предмете в сумках, который станет улучшением для вашей специализации.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Зеленая стрелка на экипировке, которая лучше надетой, с учетом вашего класса и уровня.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Светло-зеленая полоска показывает уже летящее исцеление.",
	["Una gran curación para todo el grupo mientras canalizas."] = "Большое лечение всей группы, пока ты поддерживаешь заклинание.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Гайд для вашего уровня и зоны или собственный маршрут заданий.",
	["Una hora de caza"] = "Час охоты",
	["Una hora de caza, aviso de cadena, «Deshacer» al omitir y cuánto te falta de tu guía."] = "Час охоты, предупреждение о цепочке, «Отменить» после пропуска и сколько осталось по гайду.",
	["Una huella sobre la mejor para tu clase (o la que más vale al venderla) y «Alfa te recomienda». Nunca elige por ti."] = "Отпечаток лапы на лучшей для твоего класса (или самой дорогой при продаже) и «Alfa советует». Выбор всегда за тобой.",
	["Una lista de las grises que ya no valen la pena, con «Abandonar» en cada una (tú lo confirmas)."] = "Список серых заданий, которые уже не стоят того, с кнопкой «Отказаться» у каждого (подтверждаешь ты).",
	["Una loba gordita como yo necesita sus tres comidas... y sus botanas."] = "Пухленькой волчице вроде меня нужны три приема пищи... и перекусы.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Черная волчица, которая дает советы и подбадривает в пути, не мешая. В память об одной замечательной собачке.",
	["Una loba que cuida tan bien a su lobo merece una salchicha, ¿no crees?"] = "Волчица, которая так хорошо заботится о своем волке, заслуживает сосиску, правда?",
	["Una línea con el enlace de la misión cuando completas sus objetivos, otra cuando está lista para entregar y otra al entregarla. En grupo la ve todo el grupo, con o sin Alfa; solo, sale en tu chat. Nunca en banda."] = "Строка со ссылкой на задание, когда выполнены его цели, ещё одна, когда его можно сдать, и ещё одна при сдаче. В группе её видят все, с Alfa или без; в одиночку она появляется в твоём чате. Никогда в рейде.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Короткая строка под значком, например «Смертельный удар: восстановлено». Каждая показывается до 4 раз, затем умолкает; кнопка × заглушает ее раньше.",
	["Una línea debajo del aviso con lo que pasó."] = "Строка под оповещением о том, что произошло.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Красная линия сверху предупреждает, когда противник нацелился на этого союзника.",
	["Una mano"] = "Одноручное",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Цель, которую отмечаете вы (кнопкой выполнения в трекере или в этом списке).",
	["Una misión"] = "Задание",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Монетка на серых предметах и отмеченном вами хламе.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Заметка с ближайшим учителем, когда у вас есть новые способности.",
	["Una piedra de salud para emergencias. Haz una antes de cada mazmorra."] = "Камень здоровья на крайний случай. Делай перед каждым подземельем.",
	["Una piedra que deja revivir al morir. Pónsela a quien cura."] = "Камень, который позволяет вернуться после смерти. Наложи на своего лекаря.",
	["Una revisión completa de todos los módulos: más de 60 arreglos."] = "Полная проверка всех модулей: более 60 исправлений.",
	["Una revisión completa para la versión estable: más de 20 arreglos en mazmorras con grupo, combate, el mapa, Pesca, Talentos y más."] = "Полная проверка для стабильной версии: более 20 исправлений в групповых подземельях, бою, на карте, в рыбалке, талантах и не только.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Elige una de estas para empezar:"] = "Маршрут — это ваше дерево этапов: задания на опыт, золото или классовые, материалы или предметы. Выберите один из них, чтобы начать:",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Маршруту нужно хотя бы 3 места, доступных вашему навыку. Выберите ниже другой тип или ресурс либо собирайте здесь: Alfa записывает каждый найденный узел.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Маршрут по лучшим местам для вашего навыка, с несколькими заданиями на опыт по пути.",
	["Una salchicha al día mantiene a la loba feliz. Es ciencia."] = "Одна сосиска в день — и волчица счастлива. Это наука.",
	["Una semana de caza juntos"] = "Неделя охоты вместе",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Сеанс заканчивается после 20 минут без забросов или когда вы начинаете новый; тогда он появляется здесь с уловом и местом.",
	["Una sesión tranquila: nada nuevo que contar."] = "Спокойный сеанс: ничего нового.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Одна клавиша для всего: снаряжение, приманка, заброс и подсечка. С журналом, гайдом, кулинарией, целями и статистикой.",
	["Una tormenta de hielo en un área. Ideal contra grupos."] = "Ледяная буря по области. Отлично против групп.",
	["Una vuelta de recolección en tu zona"] = "Круг сбора в твоей зоне",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Соединяет %d мест, доступных вашему навыку, в короткий круг, рисует его на карте, и стрелка ведет вас от остановки к остановке.",
	["Unir las capas de sombra"] = "Сглаживать стыки слоев теней",
	["Unirte al grupo de tus amigos"] = "Вступать в группы друзей",
	["Uno de los dragones verdes de la pesadilla aparece en el Bosque del Ocaso, junto a un gran árbol."] = "Один из зеленых драконов кошмара появляется в Сумеречном лесу, рядом с великим деревом.",
	["Uno menos"] = "На один меньше",
	["Uno más"] = "На один больше",
	["Unos %d pasos a tu ritmo"] = "Около %d шагов в твоем темпе",
	["Unos %s de juego a tu ritmo (%s XP por hora)."] = "Около %s игры в твоем темпе (%s опыта в час).",
	["Unos materiales: %s."] = "Об этих материалах: %s.",
	["Unos pocos altos elfos siguen con la Alianza; viven en Quel'Danil, en las Tierras del Interior."] = "Немногие высшие эльфы остаются с Альянсом; они живут в Кель'Даниле во Внутренних землях.",
	["Unos prefieren que yo haga lo aburrido y otros quieren hacerlo todo. Tú dime, y si cambias de idea, lo cambias cuando quieras."] = "Одни хотят, чтобы скучное делала я, другие всё сами. Скажи мне, а передумаешь — поменяешь когда захочешь.",
	["Usa %s"] = "Используйте %s",
	["Usa %s: tu tecla lo pone."] = "Используйте %s: клавиша его наложит.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "Используйте Блок щитом, когда босс бьет сильно.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "Используйте Жажду смерти в начале боя с боссом.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "Используйте Жажду смерти против сложных монстров, а не против легких.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "Используйте Смертельный удар прежде всего против лекарей.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "Используйте Размашистые удары, когда рядом два противника или больше.",
	["Usa Ira rabiosa para romper miedos."] = "Используйте Ярость берсерка, чтобы снимать страх.",
	["Usa Revancha cada vez que se ilumine y Hender armadura para sumar amenaza."] = "Используйте Реванш каждый раз, когда он подсвечивается, и Раскол брони, чтобы набирать угрозу.",
	["Usa Transfusión de vida para recuperar maná a cambio de vida."] = "Используйте Жизнеотвод, чтобы получить ману в обмен на здоровье.",
	["Usa a tu demonio para frenar al monstruo mientras lanzas."] = "Используйте демона, чтобы задержать монстра, пока вы произносите заклинания.",
	["Usa el juicio y vuelve a poner tu sello enseguida."] = "Используйте Правосудие и сразу накладывайте печать снова.",
	["Usa el número de abajo en lugar del que detecta el juego."] = "Использует число ниже вместо определенного игрой.",
	["Usa el número de abajo para el blanco normal."] = "Использует число ниже для обычного белого.",
	["Usa el resaltado del propio juego sobre el botón de la habilidad sugerida."] = "Использует подсветку самой игры на кнопке предложенной способности.",
	["Usa la forma felina con un monstruo y la de oso si vienen varios."] = "Используйте облик кошки против одного монстра и облик медведя, если их несколько.",
	["Usa tu golpe principal para juntar puntos de combo y gástalos en tu remate."] = "Используйте основной удар, чтобы набирать приемы в серии, и тратьте их на завершающий прием.",
	["Usa tu varita cuando quieras ahorrar maná."] = "Используйте жезл, когда хотите сэкономить ману.",
	["Usa tus hechizos de control si se te juntan dos monstruos."] = "Используйте заклинания контроля, если на вас напали два монстра.",
	["Usa un arma lenta y fuerte: tus mejoras de arma pegan con cada golpe."] = "Используйте медленное и сильное оружие: усиления оружия срабатывают с каждым ударом.",
	["Usa una varita para rematar enemigos sin gastar maná."] = "Добивай противников жезлом, не тратя ману.",
	["Usar"] = "Использовать",
	["Usar el banco de Alfa"] = "Использовать банк Alfa",
	["Usar esta"] = "Использовать",
	["Usar esta guía"] = "Использовать этот гайд",
	["Usar la base de datos incluida"] = "Использовать встроенную базу данных",
	["Usar la pesca de Alfa"] = "Рыбалка Alfa",
	["Usar la piedra"] = "Использовать камень",
	["Usar las bolsas de Alfa"] = "Использовать сумки Alfa",
	["Usar los marcos de Alfa"] = "Использовать рамки Alfa",
	["Usar los pesos de mi build"] = "Использовать веса моего билда",
	["Usar mis talentos de ahora"] = "Использовать мои текущие таланты",
	["Usar siempre el mejor"] = "Всегда использовать лучшее",
	["Usar siempre la prioridad de Alfa"] = "Всегда использовать приоритет Alfa",
	["Usar solo una flecha"] = "Одна стрелка",
	["Usar también en los marcos de Blizzard"] = "Использовать и на рамках Blizzard",
	["Usar un perfil"] = "Использовать профиль",
	["Usar una venda"] = "Использовать бинт",
	["Usarlo"] = "Использовать",
	["Usas el perfil «%s»"] = "Используется профиль «%s»",
	["Usas las bolsas del juego"] = "Вы используете сумки игры",
	["Uso: /alfa comercio precio <enlace del objeto>"] = "Использование: /alfa comercio precio <ссылка на предмет>",
	["Uso: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]"] = "Использование: /alfa recoleccion [ruta [mineria|hierbas|pesca|tesoros] | guiar | parar | mapa | minimapa]",
	["Uso: /alfa silenciar <número>, /alfa silenciar quitar <número>, /alfa silenciar borrar."] = "Использование: /alfa silenciar <номер>, /alfa silenciar quitar <номер>, /alfa silenciar borrar.",
	["Va a %s"] = "Идет в %s",
	["Vaciar"] = "Очистить",
	["Vaciar la lista"] = "Очистить список",
	["Vacía"] = "Пусто",
	["Vaelastrasz, un dragón rojo, está preso de Nefarian en la Guarida Alanegra. Antes de pelear contra ti, te presta su fuerza."] = "Вейластраз, красный дракон, — пленник Нефариана в Логове Крыла Тьмы. Перед боем с тобой он одалживает тебе свою силу.",
	["Vale la pena: abre “%s”"] = "Стоит того: открывает «%s»",
	["Vale la pena: da %s"] = "Стоит того: дает %s",
	["Vallefresno es un bosque precioso. Pero cuida de no enojar a sus espíritus antiguos."] = "Ясеневый лес прекрасен. Но старайся не гневить его древних духов.",
	["Valor de %s: llevas %s"] = "Стоимость %s: уже %s",
	["Valor de bloqueo"] = "Показатель блока",
	["Valor de lo pescado"] = "Стоимость улова",
	["Valor de venta"] = "Цена у торговца",
	["Valor en la subasta"] = "Цена на аукционе",
	["Valor exacto"] = "Точное значение",
	["Vamos a %s: sigue la flecha."] = "Идем в %s: следуй за стрелкой.",
	["Van: %s"] = "Идут: %s",
	["Van: %s."] = "Идут: %s.",
	["Variable del juego: %s"] = "Переменная игры: %s",
	["Varimathras sirve a Sylvanas en Entrañas. Es un señor del terror, así que nadie sabe cuánto le va a durar la lealtad."] = "Вариматрас служит Сильване в Подгороде. Он повелитель ужаса, так что никто не знает, надолго ли хватит его верности.",
	["Varios"] = "Разное",
	["Varios enemigos cerca: Nova sagrada los golpea a todos."] = "Рядом несколько противников: Кольцо света бьет их всех.",
	["Varios enemigos cerca: el cono los golpea y los frena."] = "Рядом несколько противников: конус бьет и замедляет их.",
	["Varios enemigos cerca: el tótem de magma los quema a todos."] = "Рядом несколько противников: Тотем магмы сжигает их всех.",
	["Varios enemigos cerca: golpéalos a todos a la vez."] = "Рядом несколько противников: бейте всех сразу.",
	["Varios enemigos cerca: la ola los golpea y los frena."] = "Рядом несколько противников: волна бьет и замедляет их.",
	["Varios enemigos juntos: el huracán los golpea a todos."] = "Несколько противников вместе: Гроза бьет их всех.",
	["Varios enemigos juntos: la ventisca los golpea a todos."] = "Несколько противников вместе: Снежная буря бьет их всех.",
	["Varios enemigos juntos: lluvia de fuego sobre ellos."] = "Несколько противников вместе: обрушьте на них Огненный ливень.",
	["Varios enemigos juntos: quémalos a todos a la vez."] = "Несколько противников вместе: сожгите их всех разом.",
	["Varios enemigos: consagra el suelo bajo ti."] = "Несколько противников: освятите землю под собой.",
	["Varios enemigos: el disparo alcanza a varios."] = "Несколько противников: выстрел задевает нескольких.",
	["Varios enemigos: el rayo salta entre ellos."] = "Несколько противников: молния перескакивает между ними.",
	["Varios enemigos: golpéalos a todos."] = "Несколько противников: бейте всех.",
	["Varios enemigos: tus golpes alcanzan a otro más."] = "Несколько противников: ваши удары задевают еще одного.",
	["Varios misiles que no fallan. Bueno cuando el enemigo no se mueve."] = "Несколько снарядов, которые никогда не промахиваются. Хорошо, когда враг стоит на месте.",
	["Varios puntos juntos: acércate en el mapa para verlos."] = "Несколько точек рядом: приблизьте карту, чтобы их увидеть.",
	["Varita"] = "Жезл",
	["Vas en %d de %d"] = "Пройдено: %d из %d",
	["Vas muy bien. Cada paso cuenta, aunque no lo parezca."] = "У тебя отлично получается. Каждый шаг важен, даже если так не кажется.",
	["Vas tras %s"] = "Вы идете за: %s",
	["Ve con cuidado: la presa también muerde."] = "Осторожнее: добыча тоже кусается.",
	["Ve quién de tu hermandad busca grupo y pon tu anuncio. Se quita solo en una hora."] = "Смотри, кто из гильдии ищет группу, и размещай свое объявление. Само исчезнет через час.",
	["Veces completada"] = "Сколько раз пройдено",
	["Veces completadas"] = "Число прохождений",
	["Vegetación"] = "Растительность",
	["Veinte. Ya te respetan en los caminos."] = "Двадцать. На дорогах тебя уже уважают.",
	["Vela sagrada"] = "Святая свеча",
	["Velen, Kil'jaeden y Archimonde guiaban a los eredar. Los dos últimos aceptaron el poder de Sargeras; Velen huyó."] = "Велен, Кил'джеден и Архимонд вели эредаров. Двое последних приняли силу Саргераса; Велен бежал.",
	["Velocidad"] = "Скорость",
	["Velocidad del zoom"] = "Скорость приближения",
	["Ven a jugar con la manada, pregunta lo que quieras o cuéntanos si algo falla. Haz clic en el cuadro y cópialo con Ctrl+C (Cmd+C en Mac)."] = "Приходи играть со стаей, спрашивай что угодно или расскажи, если что-то сломалось. Щелкни по полю и скопируй через Ctrl+C (Cmd+C на Mac).",
	["Vence a este jefe para descubrir su nombre y su botín."] = "Победите этого босса, чтобы узнать его имя и добычу.",
	["Vence a sus jefes para ver lo que sueltan, o apaga el modo historia en Ajustes."] = "Победите боссов, чтобы увидеть, что с них падает, или выключите режим истории в «Настройках».",
	["Vencido"] = "Побежден",
	["Vendas para curarte sin gastar maná ni esperar: imprescindible para todos."] = "Бинты, чтобы лечиться без маны и ожидания: обязательно для всех.",
	["Vende"] = "Продает",
	["Vende cañas y cebos"] = "Продает удочки и приманки",
	["Vende lo gris cada vez que pases por un pueblo: es oro fácil y libera espacio."] = "Продавай серое в каждом городке по пути: это легкое золото и свободное место.",
	["Vende lo gris con cualquier vendedor o tira algo que ya no uses."] = "Продайте серые предметы любому торговцу или выбросьте то, чем больше не пользуетесь.",
	["Vende lo que no usas y junta lo que cuesta aprender a montar."] = "Продайте ненужное и накопите на обучение верховой езде.",
	["Vende los materiales en montones de 20 o de 10: así es como la gente los compra."] = "Продавай материалы стопками по 20 или по 10: так их и покупают.",
	["Vende los objetos grises y lo que marcaste como basura. Nunca lo que marcaste para guardar."] = "Продает серые предметы и то, что вы отметили как хлам. Никогда то, что вы отметили для хранения.",
	["Vende tu chatarra en este comerciante (%d)."] = "Продает хлам этому торговцу (%d).",
