	["Ventura y Cía."] = "Торговая компания",
	["Ventura y Cía. abrió minas en Mulgore sin pedir permiso, y a los tauren eso no les hace ninguna gracia."] = "Торговая компания открыла шахты в Мулгоре без спроса, и тауренам это совсем не нравится.",
	["Ventura y Cía. tala y mina la Sierra Espolón sin piedad, y los druidas hacen lo que pueden por detenerla."] = "Торговая компания беспощадно рубит лес и роет шахты в Когтистых горах, а друиды делают все, чтобы ее остановить.",
