	["Viernes"] = "Пятница",
	["Villa del Lago tiene un puente roto que la gente quiere reconstruir, si alguien le echa la mano."] = "В Приозерье разрушен мост, и жители хотят его отстроить, если кто-нибудь поможет.",
	["Villa del Lago vive con miedo de los orcos Roca Negra que bajan de las montañas, y también de los gnolls."] = "Приозерье живет в страхе перед орками Черной горы, спускающимися с гор, и перед гноллами тоже.",
	["Vincular"] = "Ссылка",
	["Violeta"] = "Фиолетовый",
	["Visita a un banquero con ese personaje y Alfa la guardará."] = "Посетите банкира этим персонажем, и Alfa сохранит снимок.",
	["Visita a un banquero una vez y Alfa guardará una foto para verlo desde cualquier lugar."] = "Посетите банкира один раз, и Alfa сохранит снимок, чтобы банк было видно откуда угодно.",
	["Visita a un banquero y Alfa te dirá cuánto cuesta la siguiente casilla de bolsa del banco."] = "Посетите банкира, и Alfa скажет, сколько стоит следующая ячейка для сумки в банке.",
	["Vista"] = "Вид",
	["Vista Eterna es un pueblo goblin en medio de la nieve: aunque haga frío, el negocio no para."] = "Круговзор — гоблинский городок посреди снегов: холодно или нет, торговля не останавливается.",
	["Vista Eterna tiene casa de subastas neutral, ideal para comerciar con el otro bando."] = "В Круговзоре есть нейтральный аукцион — идеально для торговли с другой фракцией.",
	["Vista mínima al lanzar"] = "Минимальный вид при забросе",
