	["Vol'jin guía a los Lanza Negra y es uno de los amigos más leales de Thrall."] = "Вол'джин ведет племя Черного Копья и он один из самых верных друзей Тралла.",
	["Volumen de los efectos"] = "Громкость эффектов",
	["Volvemos a tu guía: la misión que esperabas ya está lista para ti."] = "Возвращаемся к гайду: задание, которого ты ждал, уже доступно.",
