	["Vuelos y rutas por aprender"] = "Полеты и маршруты, которые нужно открыть",
	["Vuelos, barcos y posadas también en el minimapa."] = "Полеты, корабли и таверны и на мини-карте.",
	["Vuelta a entregar"] = "Обход сдачи",
	["Vuelta a entregar por el camino más corto, la piedra de hogar a tiempo y la mejor recompensa marcada."] = "Сдача заданий кратчайшим путем, камень возвращения вовремя и отмеченная лучшая награда.",
	["Vuelta a entregar · Entrega %d de %d"] = "Обход сдачи · Сдача %d из %d",
	["Vuelve a %s"] = "Вернитесь: %s",
	["Vuelve al valor de fábrica del juego: %s."] = "Возвращает заводское значение игры: %s.",
	["Vuelve con /alfa guia o desde Aventura > Tu guía."] = "Верните его командой /alfa guia или через «Приключения» > «Ваш гайд».",
	["Vuelve en %s"] = "Через %s",
	["Vuelven a como venían el estilo Alfa con su color, %s. «%s» y tus perfiles no cambian."] = "Стиль Alfa с его цветом, %s вернутся к исходным. «%s» и твои профили не изменятся.",
	["World of Warcraft, Warcraft y Blizzard Entertainment son marcas de Blizzard Entertainment, Inc. El arte del juego y del mapa es de Blizzard. Alfa no está afiliado a Blizzard. Discord es marca de Discord Inc."] = "World of Warcraft, Warcraft и Blizzard Entertainment — товарные знаки Blizzard Entertainment, Inc. Графика игры и карты принадлежит Blizzard. Alfa не связан с Blizzard. Discord — товарный знак Discord Inc.",
	["XP"] = "Опыт",
	["XP descansada: %d %% de un nivel."] = "Опыт за отдых: %d %% уровня.",
	["XP descansada: %d%% de un nivel"] = "Опыт за отдых: %d%% уровня",
	["XP ganada"] = "Получено опыта",
	["XP ganada en la sesión: %s"] = "Опыта за сеанс: %s",
	["XP por hora"] = "Опыт в час",
	["XP por hora en cada sesión"] = "Опыт в час за каждый сеанс",
	["XP por sesión"] = "Опыт за сеанс",
	["XP/h"] = "Опыт/ч",
	["Y %d piezas más necesitan reparación."] = "И еще вещей требуют починки: %d.",
	["Y 1 pieza más necesita reparación."] = "И еще 1 вещь требует починки.",
	["Y aquí estoy yo"] = "А вот и я",
	["Y la tuya tampoco se queda atrás, ¿eh?"] = "И твоя тоже не отстает, а?",
	["Y sin caer ni una vez. ¡Qué manada!"] = "И ни одного падения. Вот это стая!",
	["Y una prueba nueva que juega Alfa de punta a punta antes de cada versión, para que estos errores no regresen."] = "А еще новый тест, который проходит весь Alfa от начала до конца перед каждой версией, чтобы эти ошибки не вернулись.",
	["Ya casi no cabe nada: %d libres. Lo gris es oro fácil con cualquier vendedor."] = "Места почти не осталось: свободно %d. Серое — легкое золото у любого торговца.",
	["Ya cuidas a 3 aprendices: termina con alguno para adoptar otro."] = "Ты уже опекаешь 3 учеников: закончи с одним, чтобы взять другого.",
	["Ya es de madrugada, lobo. Una misión más y a dormir, ¿sí? Azeroth sigue aquí mañana."] = "Глубокая ночь, волк. Еще одно задание и спать, ладно? Азерот никуда не денется.",
	["Ya es de noche. Una buena cacería antes de dormir y luego a descansar."] = "Уже ночь. Одна хорошая охота перед сном, а потом отдых.",
	["Ya es tu aprendiz."] = "Он уже твой ученик.",
	["Ya está en tu registro"] = "Уже в журнале заданий",
