	["Ya no eres aprendiz"] = "Уже не ученик",
	["Ya no está en esa guarida."] = "Он больше не в этом логове.",
	["Ya no está en tu registro"] = "Уже нет в журнале заданий",
	["Ya no está sobre un cuadro negro: la acompañan una sombra suave y una elipse del color de tu estilo."] = "Больше никакого черного квадрата: ее сопровождают мягкая тень и эллипс цвета вашего стиля.",
	["Ya no hay nada más que aprender. ¡Qué orgullo!"] = "Больше нечему учиться. Горжусь тобой!",
	["Ya no queda nada por hacer aquí. Elige qué sigue y la manada va contigo."] = "Здесь больше нечего делать. Выбери, что дальше, и стая пойдёт с тобой.",
	["Ya no se consigue"] = "Больше недоступно",
	["Ya no se consiguen"] = "Больше не получить",
	["Ya no se puede deshacer"] = "Это уже нельзя отменить",
	["Ya no te dan casi experiencia y no abren nada que valga la pena. Abandónalas para tener espacio en tu registro."] = "Они почти не дают опыта и не открывают ничего стоящего. Откажись от них, чтобы освободить место в журнале.",
	["Ya no te queda ninguna casilla libre."] = "Свободных ячеек больше нет.",
	["Ya puedes aprender el rango %s"] = "Можно изучить ступень «%s»",
	["Ya puedes entregarla."] = "Его уже можно сдать.",
	["Ya puedes hacer venenos. Ponlos en tus armas: suman mucho daño."] = "Теперь ты умеешь делать яды. Наноси их на оружие: они добавляют много урона.",
	["Ya puedes salir del grupo: la guarida se queda contigo."] = "Можно выйти из группы: логово остаётся за тобой.",
	["Ya salió Alfa %s"] = "Вышел Alfa %s",
	["Ya salió una versión nueva de Alfa"] = "Вышла новая версия Alfa",
	["Ya se está buscando, espera un momento."] = "Поиск уже идет, подождите немного.",
	["Ya se usa: clic otra vez"] = "Уже используется: щелкните еще раз",
	["Ya te conté todo lo que sé por ahora. Con clic derecho puedo empezar de nuevo."] = "Я рассказала все, что пока знаю. Правый щелчок — и я начну сначала.",
	["Ya te dejé prendido lo que le va a tu clase. Agrega o quita lo que quieras: nada de esto juega por ti."] = "Я уже включила то, что подходит твоему классу. Добавь или убери что хочешь: ничего из этого не играет за тебя.",
	["Ya terminaste Armas: estos puntos van a Furia por más golpe crítico."] = "Оружие уже завершено: эти очки идут в Неистовство ради шанса критического удара.",
	["Ya tienes %d conjuntos: olvida uno primero."] = "У тебя уже %d комплектов: сначала забудь один.",
	["Ya tienes %d de %s. Te faltan %d de %d materiales."] = "Сейчас у тебя %d %s. Не хватает материалов: %d из %d.",
	["Ya tienes %d talentos de este plan."] = "Талантов из этого плана у вас уже: %d.",
	["Ya tienes 1 talento de este plan."] = "У вас уже есть 1 талант из этого плана.",
	["Ya tienes 3 citas propuestas. Quita una para proponer otra."] = "Уже предложено 3 сбора. Убери один, чтобы предложить другой.",
	["Ya tienes 60 notas. Borra alguna en La Jauría para dejar otra."] = "У тебя уже 60 заметок. Удали одну в La Jauría, чтобы оставить новую.",
	["Ya tienes algo mejor"] = "У вас уже есть что-то лучше",
	["Ya tienes demasiados builds importados. Borra alguno primero."] = "У вас слишком много импортированных билдов. Сначала удалите какой-нибудь.",
	["Ya tienes el rango más alto"] = "У тебя высшая ступень",
	["Ya tienes la equitación"] = "Верховая езда уже изучена",
	["Ya tienes las %d casillas de bolsa del banco. Para más espacio, pon bolsas más grandes en ellas."] = "У вас уже все ячейки для сумок в банке (%d). Чтобы было больше места, положите в них сумки побольше.",
	["Ya tienes seis guías abiertas: cierra una y vuelve a intentar."] = "У вас уже открыто шесть гайдов: закройте один и попробуйте снова.",
	["Ya tienes todos los materiales. ¡A trabajar!"] = "Все материалы есть. За работу!",
	["Ya tienes todos los talentos de este build. ¡Bien hecho!"] = "У вас уже есть все таланты этого билда. Отличная работа!",
	["Ya tienes tu montura"] = "Транспорт уже есть",
	["Ya van %d veces. La manada aúlla contigo."] = "Уже раз: %d. Стая воет вместе с вами.",
	["Ya van %s de cacería. Un descanso corto también es de lobos sabios."] = "Охотимся уже %s. Короткий отдых — тоже мудрость волка.",
	["Ya vencieron a todos sus jefes. Si tienes misiones listas, entrégalas al salir."] = "Все боссы уже побеждены. Если есть готовые задания, сдайте их на выходе.",
	["Ya vienen elegidas según tu clase y tu rol. Cámbialas si prefieres otra cosa."] = "Уже выбраны по вашему классу и роли. Измените, если хотите другое.",
	["Yendo solo, peleas de al menos"] = "В одиночку: бои не короче",
	["Yo correría por tu cuerpo."] = "Я бы побежала к телу.",
	["Yo decido"] = "Я решаю",
	["Yo huelo el rastro; tú pones los colmillos."] = "Я беру след, а ты пускаешь в ход клыки.",
