	["{dia}/{mes}"] = "{dia}.{mes}",
	["¡%d misiones entregadas hoy! Así se caza en manada."] = "Сегодня сдано заданий: %d! Вот так охотится стая.",
	["¡%d misiones hoy! A este paso me debes una salchicha."] = "Заданий сегодня: %d! Так ты мне скоро сосиску будешь должен.",
	["¡%d misiones hoy! Estás que no te para nadie."] = "Сегодня заданий: %d! Тебя не остановить.",
	["¡%s al máximo: %d/%d! Ya no hay nada que te enseñen. Qué orgullo, de verdad."] = "%s на максимуме: %d/%d! Учить тебя больше нечему. Как же я горжусь, правда.",
	["¡%s cazó a %s!"] = "%s добыл: %s!",
	["¡%s es tu aprendiz!"] = "%s — твой ученик!",
	["¡%s llegó al nivel %d!"] = "%s достиг %d-го уровня!",
	["¡%s subió a nivel %d! Auuuu, felicidades."] = "%s получил уровень %d! Ауууу, поздравляю.",
	["¡%s tiene su primera montura!"] = "%s получил первого скакуна!",
	["¡%s ya está feliz! Así sí da gusto cazar juntos."] = "%s уже доволен! Вот так охотиться вместе — одно удовольствие.",
	["¡%s!"] = "%s!",
	["¡%s! Hace días que no te veía. En Hoy te digo dónde íbamos."] = "%s! Давно тебя не видела. На странице «Сегодня» я покажу, где мы остановились.",
	["¡%s! Si algo te pega, corre hacia el tanque, no lejos de él."] = "%s! Если тебя бьют, беги к танку, а не от него.",
	["¡%s! Te extrañé mucho. Vine corriendo en cuanto te vi llegar."] = "%s! Я так по тебе скучала. Прибежала, как только тебя увидела.",
	["¡%s, listo! La manada aúlla por ti. Auuuu. ¿Y mi salchicha?"] = "%s, готово! Стая воет в твою честь. Ау-у-у. А моя сосиска?",
	["¡%s, volviste! Te extrañé tanto que no paraba de mover la cola."] = "%s, ты снова здесь! Я так скучала, что всё время виляла хвостом.",
	["¡Abrumar!"] = "Превосходство!",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "Теперь я бегу за тобой, высунув язык!",
	["¡Ahí estás, %s! Si quieres un consejo, dame clic."] = "Вот ты где, %s! Если нужен совет, щелкни по мне.",
	["¡Ahí estás, %s! Te estaba esperando… te extrañé."] = "Вот и ты, %s! Я тебя ждала… я скучала.",
	["¡Al máximo!"] = "Максимум!",
	["¡Arriba, lobo! Antes de volver a pelear, recupera vida y maná."] = "Подъем, волк! Перед новым боем восстанови здоровье и ману.",
	["¡Arriba, lobo! Caer es parte de la cacería. Al revivir, repara tu equipo."] = "Подъем, волк! Падать — часть охоты. Когда воскреснешь, почини экипировку.",
	["¡Arriba, lobo! Libera tu espíritu: la flecha te dice si conviene tu cuerpo o el sanador."] = "Подъем, волк! Освободи дух: стрелка подскажет, что лучше — тело или целитель душ.",
	["¡Arriba, lobo! Si eran muchos, la próxima jálalos de uno en uno."] = "Подъем, волк! Если их было много, в следующий раз выманивай по одному.",
	["¡Arriba, nivel %d! Si tienes un punto de talento libre, no lo olvides."] = "Выше, уровень %d! Если есть свободное очко талантов, не забудь о нем.",
	["¡Así se ve un aviso!"] = "Так выглядит оповещение!",
	["¡Ataque de la victoria!"] = "Победный раж!",
	["¡Auuu! Juntas cazamos mejor."] = "Ау-у! Вместе мы охотимся лучше.",
	["¡Auuu! Toda la manada está de fiesta."] = "Ауууу! Вся стая празднует.",
	["¡Auuuu! La manada unida no se rinde."] = "Ау-у-у! Сплоченная стая не сдается.",
	["¡Auuuu! ¡Nivel %d y dos niveles en menos de media hora! Vas como lobo en luna llena."] = "Ауууу! Уровень %d, и два уровня меньше чем за полчаса! Ты как волк в полнолуние.",
	["¡Bien hecho! %s"] = "Отлично! %s",
	["¡Buen día, %s! El sol ya salió en Azeroth. ¿Vamos?"] = "Доброе утро, %s! Солнце уже встало над Азеротом. Идём?",
	["¡Buenas noches, %s! Las lobas cazamos mejor de noche."] = "Добрый вечер, %s! Мы, волчицы, лучше всего охотимся ночью.",
	["¡Buenas tardes, %s! Buena hora para unas misiones."] = "Добрый день, %s! Отличное время для заданий.",
	["¡Buenas, %s! Paso a paso se llega lejos."] = "Привет, %s! Шаг за шагом можно уйти далеко.",
	["¡Buenos días! Un buen desayuno y a cazar, que la mañana rinde."] = "Доброе утро! Хороший завтрак — и на охоту: утром успеваешь многое.",
	["¡Buenos días, %s! Me estiro, bostezo y estoy lista."] = "Доброе утро, %s! Потянусь, зевну — и я готова.",
	["¡Bájale, casi se lo quitas al tanque!"] = "Сбавь, ты вот-вот сорвешь его с танка!",
	["¡Claro! Saludo a tu mascota cuando la llamas y, si eres cazador, te aviso cuando tiene hambre o está triste para que le des de comer."] = "Конечно! Я здороваюсь с твоим питомцем, когда ты его зовешь, и, если ты охотник, говорю, когда он голоден или несчастен, чтобы ты его покормил.",
	["¡Completaste %s!"] = "Пройдено: %s!",
	["¡Contraataque!"] = "Контратака!",
	["¡Cumplido! Salchicha ganada."] = "Выполнено! Сосиска заработана.",
	["¡Córtale a tu foco!"] = "Прерви фокус!",
	["¡Córtalo!"] = "Прерви!",
	["¡De vuelta con la manada!"] = "Снова со стаей!",
	["¡De vuelta en la manada, %s!"] = "Снова в стае, %s!",
	["¡Ejecutar!"] = "Казнь!",
	["¡En Thelsamar venden morcilla! La morcilla de Thelsamar es casi una salchicha... ¿me compras una?"] = "В Телсамаре продают кровяную колбасу! Телсамарская кровяная колбаса — почти сосиска... купишь мне одну?",
	["¡Es Halloween de Azeroth! Pide dulces a los posaderos: a veces te disfrazan de algo chistoso."] = "Тыквовин! Попроси у трактирщиков угощение: иногда они наряжают тебя во что-нибудь смешное.",
	["¡Es ahora! Hasta las %s"] = "Уже идет! До %s",
	["¡Es el Festival del Fuego del Solsticio! Visita las hogueras de las ciudades y honra su llama."] = "Огненный солнцеворот! Посети костры городов и почти их пламя.",
	["¡Espera! Dejas %d misiones listas sin entregar. Si no, mañana empezamos por ahí."] = "Подожди! Готовых заданий без сдачи: %d. Если не сейчас, в следующий раз начнем с них.",
	["¡Esto le sirve a %s!"] = "Это пригодится: %s!",
	["¡Está lanzando!"] = "Он произносит заклинание!",
	["¡Explorada completa!"] = "Исследовано полностью!",
	["¡Felicidades por el nivel %d, %s! Auuuu."] = "Поздравляю с уровнем %d, %s! Ауууу.",
	["¡Feliz cumpleaños!"] = "С днем рождения!",
	["¡Feliz cumpleaños, Alfa!"] = "С днем рождения, Alfa!",
	["¡Gracias! Ya van %d salchichas que me das. Las llevo contadas, eh."] = "Спасибо! Сосисок от тебя уже: %d. Я их считаю, между прочим.",
	["¡Hasta pronto! Aquí te espero, cuidando tu lugar."] = "До скорого! Я жду тебя здесь и стерегу твое место.",
	["¡Hasta pronto! Hoy cazamos %s Aquí te espero."] = "До скорого! Сегодня мы добыли: %s Я жду тебя здесь.",
	["¡Hay algo nuevo en Alfa: %s! ¿Te lo enseño?"] = "В Alfa есть новое: %s! Показать?",
	["¡Hola!"] = "Привет!",
	["¡Hola! Pregúntame lo que quieras de Alfa: te lo explico corto y te llevo."] = "Привет! Спрашивай что угодно об Alfa: объясню коротко и отведу.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Cuido a la manada y voy contigo en el camino."] = "Привет! Я Lya, верная волчица Альфы. Я берегу стаю и иду с тобой в пути.",
	["¡Hola! Soy Lya, la loba de confianza del Alfa. Voy a acompañarte en esta configuración y después en tu camino."] = "Привет! Я Лия, верная волчица Альфы. Я проведу тебя через настройку, а потом буду рядом в пути.",
	["¡Hola, %s!"] = "Привет, %s!",
	["¡Hola, %s! Familia %s y de buena casta. Tú y yo vamos a cuidar a nuestro alfa."] = "Привет, %s! Семейство %s, и хорошей породы. Мы с тобой будем беречь нашего альфу.",
	["¡Hola, %s! Hoy huele a buena cacería."] = "Привет, %s! Сегодня пахнет хорошей охотой.",
	["¡Hola, %s! La tarde pinta tranquila. ¿Qué cazamos hoy?"] = "Привет, %s! День обещает быть спокойным. На кого охотимся сегодня?",
	["¡Hola, %s! Noche de luna: perfecta para la manada."] = "Привет, %s! Лунная ночь — то, что нужно стае.",
	["¡Hola, %s! Tú y yo vamos a cuidar a nuestro alfa."] = "Привет, %s! Мы с тобой будем беречь нашего альфу.",
	["¡Hoy Alfa cumple %d años! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Сегодня у Alfa день рождения, лет: %d! La Jauría сделала его с любовью для тебя. Отпразднуем сосиской?",
	["¡Hoy Alfa cumple 1 año! La Jauría lo hizo con cariño para ti. ¿Lo festejamos con una salchicha?"] = "Сегодня Alfa исполняется 1 год! La Jauría сделала его с любовью для тебя. Отпразднуем сосиской?",
	["¡Hoy cumplimos %d años cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Сегодня %d г. с тех пор, как мы охотимся вместе, %s! Спасибо, что позволил мне быть твоей волчицей. Ау-у-у.",
	["¡Hoy cumplimos 1 año cazando juntos, %s! Gracias por dejarme ser tu loba. Auuuu."] = "Сегодня ровно год, как мы охотимся вместе, %s! Спасибо, что позволил мне быть твоей волчицей. Ау-у-у.",
	["¡La Lya de %s me contestó el saludo! Ya somos manada."] = "Лия игрока %s ответила на приветствие! Теперь мы стая.",
	["¡La Lya de %s me saludó! Entre lobas nos entendemos."] = "Лия игрока %s поздоровалась со мной! Мы, волчицы, друг друга понимаем.",
	["¡Le encantan! Pero las mías son más ricas."] = "Обожает их! Но мои вкуснее.",
	["¡Listo! %s precios guardados."] = "Готово! Сохранено цен: %s.",
	["¡Listo! Alfa ya es tuyo"] = "Готово! Alfa теперь ваш",
	["¡Llegó el Festival de Invierno! En Forjaz y Orgrimmar el árbol se llena de luces y regalos."] = "Пришел Зимний Покров! В Стальгорне и Оргриммаре елка полна огней и подарков.",
	["¡Lo lograste: %s! Esa salchicha de premio me la voy a comer despacito."] = "Ты справился: %s! Эту сосиску-награду я съем не спеша.",
	["¡Lo tienes! %s ×%d"] = "Есть! %s ×%d",
	["¡Martillo de cólera!"] = "Молот гнева!",
	["¡Mi primera salchicha contigo! Esta no la voy a olvidar nunca."] = "Моя первая сосиска с тобой! Эту я никогда не забуду.",
	["¡Misión completada: %s!"] = "Задание выполнено: %s!",
	["¡Mmm, qué rica! Gracias, eres el mejor lobo de la manada."] = "Ммм, вкуснятина! Спасибо, ты лучший волк в стае.",
	["¡Mordedura de mangosta!"] = "Укус мангуста!",
	["¡Nivel %d! Date un momento para presumirlo, te lo ganaste."] = "Уровень %d! Найди минутку похвастаться — есть чем!",
	["¡Nivel %d! Paso firme y colmillo afilado."] = "Уровень %d! Твердый шаг и острые клыки.",
	["¡Nivel %d! Tu esfuerzo se nota. Sigue así."] = "Уровень %d! Твои старания видны. Так держать.",
	["¡Nivel %d! ¡Auuu! Así se sube en manada."] = "Уровень %d! Ауууу! Вот так растет стая.",
	["¡Nivel %d, bien hecho! Revisa si tu entrenador tiene algo nuevo."] = "Уровень %d, отлично! Загляни, нет ли у учителя чего-то нового.",
	["¡Nivel %d, y el anterior hace nada! Aúllo dos veces, una por cada uno. ¡Auuuu, auuuu!"] = "Уровень %d, а предыдущий был только что! Повою дважды, по разу за каждый. Ауууу, ауууу!",
	["¡Nivel 10! Ya tienes talentos: elígelos con calma, Talentos te ayuda."] = "Уровень 10! Теперь у тебя есть таланты: выбирай спокойно, «Таланты» помогут.",
	["¡Nivel 20! Ya puedes con mazmorras de verdad. ¿Armamos grupo?"] = "Уровень 20! Теперь тебе по силам настоящие подземелья. Соберем группу?",
	["¡Nivel 30! Ya vas a la mitad del camino. ¡Qué orgullo de manada!"] = "Уровень 30! Полпути позади. Стая гордится тобой!",
	["¡Nivel 40! Ya puedes aprender a montar. ¡Tu primera montura te espera!"] = "Уровень 40! Теперь можно научиться верховой езде. Твой первый транспорт ждет!",
	["¡Nivel 50! Ya se huele la cima. Junta oro para lo que viene."] = "Уровень 50! Вершина уже чувствуется. Копи золото на то, что впереди.",
	["¡Nivel 60! ¡Lo lograste, alfa! Ahora toca cazar en grande."] = "Уровень 60! У тебя получилось, альфа! Теперь время большой охоты.",
	["¡Nueva página en tu historia: %s! %s"] = "Новая страница в твоей истории: %s! %s",
	["¡Nuevo récord: %d misiones en un día! Ni la manada te alcanza."] = "Новый рекорд: %d заданий за день! Даже стая не поспевает.",
	["¡Ojo! Tu precio está %d %% por debajo de lo que vale."] = "Осторожно! Твоя цена на %d %% ниже стоимости.",
	["¡Otro nivel tan pronto! Nivel %d. ¡Auuuu, esta racha no la para nadie!"] = "Еще один уровень так скоро! Уровень %d. Ауууу, эту серию никому не остановить!",
	["¡Perdiste su atención!"] = "Ты потерял его внимание!",
	["¡Plan cumplido!"] = "План выполнен!",
	["¡Plan terminado!"] = "План выполнен!",
	["¡Primera vez! Nuevo en tu diario"] = "Впервые! Новая запись в журнале",
	["¡Qué buena racha traes! Sigue así."] = "Какая удачная серия! Так держать.",
	["¡Qué bueno tenerte de vuelta, %s! Aquí sigo, cuidándote la espalda."] = "Как хорошо, что ты снова здесь, %s! Я все еще рядом и прикрываю тебе спину.",
	["¡Qué gusto verte de vuelta! Esto es lo que trae esta versión para ti y tu manada."] = "Рады снова вас видеть! Вот что эта версия принесла вам и вашей стае.",
	["¡Qué gusto verte, %s! La manada ya te esperaba."] = "Рада тебя видеть, %s! Стая уже ждала тебя.",
	["¡Repara tu equipo!"] = "Почините экипировку!",
	["¡Reto cumplido: %s! Me gané una salchicha... digo, te la ganaste tú. Bueno, nos la ganamos."] = "Испытание выполнено: %s! Я заработала сосиску... то есть ты ее заработал. Ладно, мы заработали.",
	["¡Revancha!"] = "Реванш!",
	["¡Salchicha! *mueve la cola a toda velocidad* Gracias, gracias."] = "Сосиска! *виляет хвостом изо всех сил* Спасибо, спасибо.",
	["¡Salimos de %s! %s adentro."] = "Мы вышли из %s! %s внутри.",
	["¡Salimos de la mazmorra! %s adentro."] = "Мы вышли из подземелья! %s внутри.",
	["¡Sesenta! Lo lograste. Me debes una salchicha gigante."] = "Шестьдесят! Получилось. С тебя гигантская сосиска.",
	["¡Subiste a nivel %d! Cada nivel te hace más fuerte."] = "Новый уровень — %d! Каждый уровень делает тебя сильнее.",
	["¡Sí, acompáñame!"] = "Да, будь рядом!",
	["¡Te está atacando a ti!"] = "Он атакует тебя!",
	["¡Te extrañé, %s! Corrí hasta aquí para verte."] = "Я скучала по тебе, %s! Бежала со всех лап, чтобы тебя увидеть.",
	["¡Te extrañé, %s! Tu ruta sigue donde la dejaste."] = "Я скучала, %s! Твой маршрут там же, где и был.",
	["¡Terminaste %s!"] = "Готово: %s!",
	["¡Terminaste esta guía!"] = "Ты прошёл этот гайд!",
	["¡Terminaste esta guía! Elige la siguiente y sigue subiendo con la manada."] = "Вы прошли этот гайд! Выберите следующий и продолжайте расти вместе со стаей.",
	["¡Terminaste tu guía!"] = "Вы прошли гайд!",
	["¡Tienes todo!"] = "У тебя все есть!",
	["¡Tierra a la vista! La manada desembarca en %s"] = "Земля на горизонте! Стая высаживается: %s",
	["¡Tierra a la vista: %s!"] = "Земля на горизонте: %s!",
	["¡Todo listo para la mazmorra!"] = "Все готово к подземелью!",
	["¡Tu %s llegó a %d/%d! Ya puedes aprender el rango %s."] = "%s: %d/%d! Теперь можно выучить уровень «%s».",
	["¡Tu lista de compras está completa!"] = "Список покупок собран!",
	["¡Tú!"] = "Вы!",
	["¡Va! Te lo sigo diciendo, con gusto."] = "Хорошо! Продолжу говорить, с радостью.",
	["¡Van %d misiones hoy! La manada está orgullosa."] = "Заданий сегодня: %d! Стая гордится.",
	["¡Volviste, %s! Estira las patas y vámonos."] = "С возвращением, %s! Разомни лапы — и в путь.",
	["¡Voy!"] = "Иду!",
	["¡Vuelta completa!"] = "Обход завершен!",
	["¡Ya eres nivel %d! La manada aúlla por ti."] = "Уже уровень %d! Стая воет в твою честь.",
	["¡Ya estamos en %s! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Мы в %s! Пусть танк пуллит первым, а ты держись рядом с лекарем.",
	["¡Ya estamos en la mazmorra! Deja que el tanque jale primero y quédate cerca de quien cura."] = "Мы в подземелье! Пусть танк пуллит первым, а ты держись рядом с лекарем.",
	["¡Ya estás en la %s!"] = "Ты в: %s!",
	["¡Ya estás en otro plano!"] = "Ты уже в другом слое!",
	["¡Ya la desbloqueaste!"] = "Ты её разблокировал!",
	["¡Ya llegaste al 60!"] = "Ты достиг 60-го!",
	["¡Ya llegaste, %s! Te extrañé. ¿A dónde vamos hoy?"] = "Наконец-то ты здесь, %s! Я скучала. Куда отправимся сегодня?",
	["¡Ya llegó! Vamos, manada"] = "Прибыли! Вперёд, стая",
	["¡Ya terminaste %d misiones! Vamos a cobrar la recompensa."] = "Выполнено заданий: %d! Пойдем за наградой.",
	["¡Ya!"] = "Пора!",
	["¡Yo te la guardé! En Historias está todo lo que cuentan tus misiones, para leerlo cuando quieras."] = "А я её сохранила! В «Историях» всё, что рассказывают твои задания, читай когда хочешь.",
	["¡Ñam! Con esta van %d. Eres mi persona favorita de todo Azeroth."] = "Ням! С этой уже %d. Ты мой самый любимый человек во всем Азероте.",
	["«%s» tiene su historia. ¿Te la cuento?"] = "У «%s» есть своя история. Рассказать?",
	["«%s» ya quedó. Su final vale la pena, ¿te lo cuento?"] = "«%s» позади. Ее концовка того стоит — рассказать?",
	["«%s»: hay que llevar el recado y hablar con quien te espera."] = "«%s»: нужно отнести весточку и поговорить с тем, кто ждет.",
	["«%s»: toca %s."] = "«%s»: пора %s.",
	["«Alejar más la cámara» de Comodidades está encendido y manda sobre este valor al entrar."] = "Включено «Отдалять камеру сильнее» из «Удобств», и при входе оно перекрывает это значение.",
	["«Buscar cerca» en la página Hoy"] = "«Найти рядом» на странице «Сегодня»",
	["«Buscar cerca» te lleva con flecha a lo que necesitas, y «Mis planes» arma tus propias metas, que se marcan solas."] = "«Найти рядом» ведет вас стрелкой к нужному, а «Мои планы» составляют ваши собственные цели, которые отмечаются сами.",
	["«Camino al 60» en Hoy"] = "«Путь к 60» в «Сегодня»",
	["«Cerrar mis misiones» está al día"] = "«Закрыть мои задания»: все актуально",
	["«Igual que Alfa» sigue el estilo de Ajustes > Apariencia y cambia con él."] = "«Как в Alfa» следует стилю из Настройки > Внешний вид и меняется вместе с ним.",
	["«Invitar al clan» en el clic derecho"] = "«Пригласить в гильдию или сообщество» по правому клику",
	["«Llévame a…» (página Ruta, tu tecla o /alfa llevame): eliges el lugar y te llevo con vuelos, barcos, zepelines y portales, tramo por tramo."] = "«Отведи меня в…» (страница «Маршрут», твоя клавиша или /alfa llevame): выбери место, и я поведу с полетами, кораблями, дирижаблями и порталами, отрезок за отрезком.",
	["«Llévame» pone la flecha en este paso; «Siguiente» lo da por hecho y te lleva al que sigue."] = "«Отведи меня» направит стрелку на этот шаг; «Дальше» отметит его и перейдет к следующему.",
	["«Ponte esto» con el equipo mejor"] = "«Надень это» для лучшего снаряжения",
	["«Ponte esto», lista de compras, oficios del 1 al 300 y subastar fácil."] = "«Надень это», список покупок, профессии с 1 до 300 и простой аукцион.",
	["«Prepárame» recoge solo las que ya puedes tomar y te lleva a la entrada."] = "«Подготовь меня» берет только те, что уже можно взять, и ведет ко входу.",
	["«Reportar» ya los lleva."] = "«Отчет» их уже включает.",
	["«Seguir» en La Jauría ya no se suelta cuando tu guía cambia de paso ni cuando vas por tu cuerpo: al terminar, la flecha vuelve con quien sigues."] = "«Следовать» в La Jauría больше не сбрасывается, когда гид переходит к другому шагу или вы бежите к своему телу: потом стрелка снова указывает на того, за кем вы следуете.",
	["«Siempre» sirve si un amigo encantador te ayuda. Las tablas de desencantar son estimadas."] = "«Всегда» подходит, если вам помогает друг-чародей. Таблицы распыления примерные.",
	["«Tomar todo» en el buzón"] = "«Забрать все» у почтового ящика",
	["«Tomar todo» en el buzón, tu oro por hora y aviso de bolsas casi llenas."] = "«Забрать все» у почтового ящика, твое золото в час и предупреждение о почти полных сумках.",
	["«Ver el siguiente» te deja mirar el paso que viene y lo dice claro; y un solo contador de pasos hechos."] = "«Показать следующий» позволяет посмотреть следующий шаг и ясно об этом говорит; а счетчик выполненных шагов теперь один.",
	["«[Misión] está lista para entregar» y «¡Misión completada!» en el chat del grupo, para todos. Apagado, solo te salen a ti."] = "«[Задание] можно сдать» и «Задание выполнено!» в чате группы, для всех. Выключено — видишь только ты.",
	["«[Misión] está lista para entregar» y «¡Misión completada!». En grupo lo ve todo el grupo; solo, sale en tu chat."] = "«[Задание] можно сдать» и «Задание выполнено!». В группе это видят все; в одиночку — в твоём чате.",
	["«¿Cuánto tiempo tienes?» en Hoy"] = "«Сколько у тебя времени?» в «Сегодня»",
	["«¿Qué es esto?»"] = "«Что это?»",
	["«¿Qué es esto?»: la ayuda de Alfa"] = "«Что это?»: подсказки Alfa",
	["¿A cuánto vendo en la subasta?"] = "За сколько продавать на аукционе?",
	["¿A dónde vuelo?"] = "Куда лететь?",
	["¿Abandonar %d misiones?"] = "Отказаться от заданий: %d?",
	["¿Abandonar %d misión?"] = "Отказаться от %d задания?",
	["¿Abandonar esta misión?"] = "Отказаться от этого задания?",
	["¿Algo raro?"] = "Что-то не так?",
	["¿Alguien de la manada tiene lo que busco?"] = "Есть у кого-нибудь в стае то, что мне нужно?",
	["¿Aplicar estos talentos?"] = "Применить эти таланты?",
	["¿Borrar el diario?"] = "Очистить дневник?",
	["¿Borrar el historial?"] = "Удалить историю?",
	["¿Borrar esta ruta?"] = "Удалить этот маршрут?",
	["¿Borrar este build?"] = "Удалить этот билд?",
	["¿Borrar este plan?"] = "Удалить этот план?",
	["¿Borrar lo que descubriste?"] = "Удалить ваши находки?",
	["¿Borrar los precios?"] = "Удалить цены?",
	["¿Borrar todo tu progreso?"] = "Удалить весь ваш прогресс?",
	["¿Borrar todo tu registro de pesca?"] = "Удалить весь журнал рыбалки?",
	["¿Borrar todos tus marcadores?"] = "Удалить все ваши маркеры?",
	["¿Cuándo es nuestro cumpleaños?"] = "Когда наш день рождения?",
	["¿Cuándo sale el barco?"] = "Когда отходит корабль?",
	["¿Cuándo vuelve un raro?"] = "Когда редкий возвращается?",
	["¿Cuánto daño hago?"] = "Сколько урона я наношу?",
	["¿Cuánto de Alfa quieres ver?"] = "Сколько Alfa ты хочешь видеть?",
	["¿Cuánto decide Alfa por ti en el camino?"] = "Сколько Alfa решает за вас в пути?",
	["¿Cuánto me falta para el 60?"] = "Сколько мне до 60?",
	["¿Cuánto me falta para el nivel de mi guía?"] = "Сколько нужно до уровня в моем гиде?",
	["¿Cuánto quieres que Alfa haga por ti?"] = "Сколько Alfa делать за тебя?",
	["¿Cuánto tiempo tienes?"] = "Сколько у тебя времени?",
	["¿Cuánto vale lo que tengo?"] = "Сколько стоит моё добро?",
	["¿Cómo abro Alfa?"] = "Как открыть Alfa?",
	["¿Cómo cambio de equipo rápido?"] = "Как быстро сменить экипировку?",
	["¿Cómo cambio las teclas de Alfa?"] = "Как изменить клавиши Alfa?",
	["¿Cómo comparto una misión con mi grupo?"] = "Как поделиться заданием с группой?",
	["¿Cómo curo a mi grupo más fácil?"] = "Как проще лечить группу?",
	["¿Cómo curo y selecciono a la vez?"] = "Как лечить и брать в цель одновременно?",
	["¿Cómo encuentro a la manada?"] = "Как найти стаю?",
	["¿Cómo encuentro grupo en la manada?"] = "Как найти группу в стае?",
	["¿Cómo hago que el juego se vea mejor?"] = "Как сделать игру красивее?",
	["¿Cómo invito a alguien al clan?"] = "Как пригласить кого-то в клан?",
	["¿Cómo junto a la manada para una mazmorra?"] = "Как собрать стаю в подземелье?",
	["¿Cómo junto minerales o hierbas más rápido?"] = "Как быстрее собирать руду или травы?",
	["¿Cómo le mando un error a toxic3000?"] = "Как отправить ошибку toxic3000?",
	["¿Cómo le quito un veneno o una maldición a alguien?"] = "Как снять с кого-то яд или проклятие?",
	["¿Cómo limpio mis bolsas rápido?"] = "Как быстро очистить сумки?",
	["¿Cómo llego a la entrada de una mazmorra?"] = "Как добраться до входа в подземелье?",
	["¿Cómo llego a otro lugar?"] = "Как добраться в другое место?",
	["¿Cómo marco un lugar en el mapa?"] = "Как отметить место на карте?",
	["¿Cómo me cambio de capa (guarida)?"] = "Как сменить слой (логово)?",
	["¿Cómo me cambio de plano si hay mucha gente?"] = "Как сменить слой, когда людно?",
	["¿Cómo me entero de raros de la manada?"] = "Как узнавать о редких стаи?",
	["¿Cómo me fue en la pelea?"] = "Как прошел бой?",
	["¿Cómo me fue esta semana?"] = "Как прошла моя неделя?",
	["¿Cómo me fue hoy?"] = "Как прошёл мой день?",
	["¿Cómo pesco más fácil?"] = "Как рыбачить проще?",
	["¿Cómo pido ayuda a la manada?"] = "Как попросить стаю о помощи?",
	["¿Cómo quieres hacerlo?"] = "Как вы хотите это сделать?",
	["¿Cómo quieres que se vea Alfa?"] = "Как должен выглядеть Alfa?",
	["¿Cómo sigo una guía para subir de nivel?"] = "Как идти по гайду для прокачки?",
	["¿Cómo subo mi oficio de 1 a 300?"] = "Как прокачать профессию с 1 до 300?",
	["¿Cómo sé cuándo cortar un hechizo?"] = "Как понять, когда прерывать заклинание?",
	["¿Cómo sé cuándo vuelven mis habilidades grandes?"] = "Как понять, когда восстановятся мои сильные способности?",
	["¿Cómo sé si le voy a quitar el enemigo al tanque?"] = "Как понять, что я вот-вот сорву врага с танка?",
	["¿Cómo sé si lo que me cayó es mejor?"] = "Как узнать, лучше ли моя добыча?",
	["¿Cómo veo toda la cadena de una misión?"] = "Как увидеть всю цепочку задания?",
	["¿Dónde consigo un objeto o encuentro a alguien?"] = "Где взять предмет или найти кого-то?",
	["¿Dónde farmea la manada?"] = "Где фармит стая?",
	["¿Dónde hay minas o hierbas?"] = "Где руда или травы?",
	["¿Dónde subo mi pesca?"] = "Где качать рыбалку?",
	["¿Empezar el medidor de cero?"] = "Обнулить измеритель?",
	["¿Empezar una sesión nueva?"] = "Начать новый сеанс?",
	["¿En qué guarida anda la manada?"] = "В каком логове стая?",
	["¿En qué idioma quieres Alfa?"] = "На каком языке вам нужен Alfa?",
	["¿En qué orden hago las misiones de mi zona?"] = "В каком порядке выполнять задания моей зоны?",
	["¿En qué te ayudo?"] = "Чем помочь?",
	["¿En qué te ayudo? Toca una pregunta o una página y te cuento."] = "Чем помочь? Нажми на вопрос или страницу, и я расскажу.",
	["¿Eso que huele es pan de la posada? Mi nariz nunca se equivoca."] = "Это пахнет хлебом из таверны? Мой нос никогда не ошибается.",
	["¿Estoy listo para la mazmorra?"] = "Я готов к подземелью?",
	["¿Hay alguna fiesta hoy en Azeroth?"] = "Сегодня в Азероте праздник?",
	["¿La haces con tu manada o la saltas?"] = "Выполните его со стаей или пропустите?",
	["¿La vuelves a tomar o la sacas de la ruta?"] = "Взять его снова или убрать из маршрута?",
	["¿Me cuentas de qué va una misión?"] = "Расскажешь, о чем задание?",
	["¿Mi Lya conoce a las de mi grupo?"] = "Моя Лия знакома с Лиями моей группы?",
	["¿Mi grupo ve cuando completo una misión?"] = "Видит ли группа, когда я выполняю задание?",
	["¿Mucha gente? Te paso al plano de un lobo de la manada con su guarida abierta."] = "Слишком людно? Перенесу тебя в слой волка из стаи с открытым логовом.",
	["¿Nos cambiamos de plano?"] = "Сменим слой?",
	["¿Olvidar a este personaje?"] = "Забыть этого персонажа?",
	["¿Olvidar tu progreso?"] = "Забыть ваш прогресс?",
	["¿Otra cosa hoy?"] = "Что-то другое сегодня?",
	["¿Otra vez?"] = "Еще раз?",
	["¿Oíste eso? Nada… solo el viento. Sigamos."] = "Слышал? Ничего… просто ветер. Идём дальше.",
	["¿Para qué sirve cada botón?"] = "Для чего каждая кнопка?",
	["¿Paramos a comer? Mi panza ya está aullando."] = "Может, остановимся поесть? Мой живот уже воет.",
	["¿Por dónde empiezo?"] = "С чего начать?",
	["¿Por dónde sigues?"] = "Куда дальше?",
	["¿Puedo cambiar cómo se ve Alfa?"] = "Можно поменять вид Alfa?",
	["¿Puedo cuidar a un lobo nuevo?"] = "Можно опекать нового волка?",
	["¿Puedo dejar notas en el mapa?"] = "Можно оставлять заметки на карте?",
	["¿Puedo llamarte con una tecla?"] = "Можно позвать тебя клавишей?",
	["¿Puedo ver el mundo sin tanta cosa en pantalla?"] = "Можно смотреть на мир без лишнего на экране?",
	["¿Quieres cazar con nosotros? Pulsa el botón: Alfa busca a un oficial conectado y te abre un susurro con tu mensaje listo para que lo envíes con Intro."] = "Хотите охотиться с нами? Нажмите кнопку: Alfa найдет офицера в сети и откроет шепот с готовым сообщением — останется нажать Enter.",
	["¿Quieres que la manada te vea en el mapa del juego?"] = "Хотите, чтобы стая видела вас на карте игры?",
	["¿Quitar de tu lista?"] = "Убрать из списка?",
	["¿Quién busca grupo?"] = "Кто ищет группу?",
	["¿Quién de la manada puede ir a una mazmorra conmigo?"] = "Кто из стаи может пойти со мной в подземелье?",
	["¿Quién de mis personajes tiene esto?"] = "У кого из моих персонажей это есть?",
	["¿Quién eres, Lya?"] = "Кто ты, Лия?",
	["¿Quién tiene...?"] = "У кого есть...?",
	["¿Quién va a %s?"] = "Кто идет: %s?",
	["¿Quién va?"] = "Кто идет?",
	["¿Qué buscas?"] = "Что вы ищете?",
	["¿Qué buscas? Escribe una palabra"] = "Что ищешь? Введи слово",
	["¿Qué buscas? Un objeto, un material..."] = "Что ищешь? Предмет, материал...",
	["¿Qué buscas? «Minas, falta sanador»"] = "Что ищешь? «Копи, нужен лекарь»",
	["¿Qué citas tiene la manada esta semana?"] = "Какие сборы у стаи на этой неделе?",
	["¿Qué comida y agua compro?"] = "Какую еду и воду купить?",
	["¿Qué dice la nota?"] = "Что написать в заметке?",
	["¿Qué es Alfa?"] = "Что такое Alfa?",
	["¿Qué es el punto azul en mis marcos?"] = "Что за синяя точка на моих рамках?",
	["¿Qué es esto?"] = "Что это?",
	["¿Qué es peligroso en esta zona?"] = "Что опасно в этой зоне?",
	["¿Qué fabrico para ganar oro?"] = "Что создавать, чтобы заработать золото?",
	["¿Qué gano con esta pieza?"] = "Что мне даст этот предмет?",
	["¿Qué guardo en el banco?"] = "Что хранить в банке?",
	["¿Qué habilidad uso en combate?"] = "Какую способность жать в бою?",
	["¿Qué hace Alfa con comerciantes y viajes?"] = "Что Alfa делает с торговцами и путешествиями?",
	["¿Qué hace Alfa con tus misiones?"] = "Что Alfa делает с вашими заданиями?",
	["¿Qué hace Alfa sola por mí?"] = "Что Alfa делает за меня сама?",
	["¿Qué hacemos hoy?"] = "Чем займемся сегодня?",
	["¿Qué hacemos? Una mazmorra, una misión..."] = "Что делаем? Подземелье, задание...",
	["¿Qué hago al terminar una guía?"] = "Что делать, когда закончу гид?",
	["¿Qué hago con mis objetos?"] = "Что делать с моими предметами?",
	["¿Qué hago contra este jefe?"] = "Что делать против этого босса?",
	["¿Qué hizo la manada esta semana?"] = "Что сделала стая на этой неделе?",
	["¿Qué mazmorra me toca?"] = "Какое подземелье мне подходит?",
	["¿Qué me conviene vender en la subasta?"] = "Что выгодно продать на аукционе?",
	["¿Qué me dijiste hace rato?"] = "Что ты мне недавно говорила?",
	["¿Qué me falta para una receta?"] = "Чего мне не хватает для рецепта?",
	["¿Qué me falta por explorar en esta zona?"] = "Что осталось исследовать в этой зоне?",
	["¿Qué me puede caer en una mazmorra?"] = "Что может выпасть в подземелье?",
	["¿Qué misiones grises puedo abandonar?"] = "От каких серых заданий можно отказаться?",
	["¿Qué nos quieres contar?"] = "Что вы хотите нам рассказать?",
	["¿Qué quieres hacer hoy?"] = "Чем хотите заняться сегодня?",
	["¿Qué quieres hacer?"] = "Чем хотите заняться?",
	["¿Qué responde Alfa por ti a otros jugadores?"] = "Что Alfa отвечает за вас другим игрокам?",
	["¿Qué retos tengo esta semana?"] = "Какие у меня испытания на этой неделе?",
	["¿Qué sigue?"] = "Что дальше?",
	["¿Qué talentos pongo?"] = "Какие таланты брать?",
	["¿Reiniciar los gráficos?"] = "Перезапустить графику?",
	["¿Restaurar este respaldo?"] = "Восстановить эту копию?",
	["¿Sabías que las lobas tenemos el mejor oído de la manada? Bueno, eso digo yo."] = "А ты знаешь, что у волчиц лучший слух в стае? Ну, это я так говорю.",
	["¿Sabías que…? Alfa junta tus misiones listas en una sola ruta corta."] = "Знаешь ли ты? Alfa собирает твои готовые задания в один короткий маршрут.",
	["¿Sabías que…? Alfa tiene tres estilos: Alfa, Clásico WoW y Cristal. Y yo me pongo el que elijas."] = "Знаешь ли ты? У Alfa три стиля: Alfa, Классический WoW и Стекло. И я надеваю тот, что выберешь ты.",
	["¿Sabías que…? Alt+clic en un objeto lo abre en la Enciclopedia."] = "Знаешь ли ты? Alt+щелчок по предмету открывает его в «Энциклопедии».",
	["¿Sabías que…? Buscar cerca te lleva al herrero, al banco o al vuelo más cercano."] = "Знаешь ли ты? «Найти рядом» ведет к ближайшему кузнецу, банку или распорядителю полетов.",
	["¿Sabías que…? Comercio te dice si algo conviene venderlo, subastarlo o convertirlo."] = "Знаешь ли ты? «Торговля» подскажет, что выгоднее: продать торговцу, выставить на аукцион или переработать.",
	["¿Sabías que…? Con /alfa reportar le cuentas a toxic3000 de un error o una idea."] = "Знаешь ли ты? Командой /alfa reportar можно рассказать toxic3000 об ошибке или идее.",
	["¿Sabías que…? Con Pesca lanzas y recoges con una sola tecla."] = "Знаешь ли ты? С «Рыбной ловлей» ты забрасываешь и вытаскиваешь одной клавишей.",
	["¿Sabías que…? Con clic derecho sobre mí puedes silenciarme una hora o pedirme menos consejos."] = "Знаешь ли ты? Правым щелчком по мне можно заставить меня помолчать час или попросить меньше советов.",
	["¿Sabías que…? Con el botón del minimapa ocultas todo Alfa y lo vuelves a traer."] = "Знаешь ли ты? Кнопка у мини-карты скрывает весь Alfa и возвращает его.",
	["¿Sabías que…? El mapa de Alfa muestra el terreno, tus marcadores y lo que hay cerca."] = "Знаешь ли ты? Карта Alfa показывает рельеф, твои маркеры и то, что рядом.",
	["¿Sabías que…? En Bolsas ves tus bolsas, tu banco y lo de todos tus personajes."] = "Знаешь ли ты? В «Сумках» видны твои сумки, банк и вещи всех твоих персонажей.",
	["¿Sabías que…? En La Jauría ves a tu grupo y a la manada que usa Alfa."] = "Знаешь ли ты? В La Jauría видна твоя группа и стая, которая пользуется Alfa.",
	["¿Sabías que…? En Mis planes armas tu propia lista de metas y la flecha te guía."] = "Знаешь ли ты? В «Моих планах» ты составляешь свой список целей, и стрелка ведет тебя.",
	["¿Sabías que…? En Talentos ves qué talento poner ahora y por qué."] = "Знаешь ли ты? В «Талантах» видно, какой талант взять сейчас и почему.",
	["¿Sabías que…? La Enciclopedia te dice dónde sale cada objeto, PNJ o misión."] = "Знаешь ли ты? «Энциклопедия» подскажет, где найти любой предмет, NPC или задание.",
	["¿Sabías que…? La página Hoy te dice qué hacer ahora y lo urgente de tu personaje."] = "Знаешь ли ты? Страница «Сегодня» подскажет, что делать сейчас и что срочно для твоего персонажа.",
	["¿Sabías que…? Mazmorras te dice cuál te toca y cómo prepararte."] = "Знаешь ли ты? «Подземелья» подскажут, какое подземелье твое и как подготовиться.",
	["¿Sabías que…? Recolección te marca en el mapa minerales, hierbas y bancos de peces."] = "Знаешь ли ты? «Сбор» отмечает на карте руду, травы и косяки рыбы.",
	["¿Te conté que mi comida favorita son las salchichas? Ninguna otra cosa se le acerca."] = "Я говорила, что моя любимая еда — сосиски? Ничто с ними не сравнится.",
	["¿Te llevas bien con mi mascota?"] = "Ты ладишь с моим питомцем?",
	["¿Te puedes hacer a un lado en las peleas?"] = "Можешь отойти в сторону во время боя?",
	["¿Una carrerita hasta allá? Yo gano."] = "Наперегонки вон до туда? Я выиграю.",
	["¿Usar tu hechizo nuevo?"] = "Использовать новое заклинание?",
	["¿Usar «%s»?"] = "Использовать «%s»?",
	["¿Vaciar tu lista de compras?"] = "Очистить список покупок?",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>)"] = "Продать, на аукцион или переработать? (escanear — сканировать, precio <предмет> — цена)",
	["¿Vender, subastar o transformar? (escanear, precio <objeto>, oficios)"] = "Торговцу, на аукцион или в дело? (escanear = сканировать, precio <предмет> = цена, oficios = профессии)",
	["¿Vender, subastar o transformar? Lo que más oro te deja con cada objeto."] = "Продать, на аукцион или переработать? Что принесет больше всего золота с каждого предмета.",
	["¿Volver a lo de antes?"] = "Вернуть как было?",
	["¿Y el siguiente?"] = "А следующее?",
	["¿Y si me sale algo que le sirve a otro lobo?"] = "А если мне выпадет то, что пригодится другому волку?",
	["¿Y si pierdo mis ajustes?"] = "А если я потеряю настройки?",
	["¿Ya exploraste todo %s? Siempre queda un rincón por ver."] = "Ты уже весь %s исследовал? Всегда остаётся уголок, который стоит увидеть.",
	["¿Ya hiciste esta mazmorra?"] = "Вы уже проходили это подземелье?",
	["¿Ya te vas? Descansa bien. Yo me quedo vigilando hasta que vuelvas."] = "Уже уходишь? Отдыхай хорошо. Я посторожу, пока ты не вернешься.",
	["¿Ya viste cómo caza %s? Me cae bien."] = "Видел, как охотится %s? Мне нравится.",
	["¿qué quieres hacer?"] = "чем хотите заняться?",
	["Ábrela con su botón en la barra de menú del juego: la fila de botones pequeños de abajo a la derecha."] = "Откройте его кнопкой на панели меню игры — это ряд маленьких кнопок справа внизу.",
	["Ábrela con tu tecla de talentos (%s) o desde el menú del juego."] = "Откройте его клавишей талантов (%s) или через меню игры.",
	["Ábrela con tu tecla de talentos o desde el menú del juego."] = "Откройте его клавишей талантов или через меню игры.",
	["Ábrela con tu tecla del Legado (%s) o con su botón en la barra de menú del juego."] = "Откройте его клавишей «Наследия» (%s) или кнопкой на панели меню игры.",
	["Ábrelo con /alfa o con el lobo del minimapa. Para cambiar algo de esto: /alfa bienvenida."] = "Откройте его командой /alfa или волком на мини-карте. Чтобы что-то изменить: /alfa bienvenida.",
	["Ámbar"] = "Янтарный",
	["Ángel de la resurrección"] = "Целитель душ",
	["Ángeles de la resurrección"] = "Целители душ",
	["Árboles, rocas, cercas y adornos: más alto, se ven completos desde más lejos."] = "Деревья, камни, заборы и декор: чем выше, тем издалека они видны целиком.",
	["Área"] = "По области",
	["Échale la mano a un lobo nuevo"] = "Помоги новому волку",
	["Élite"] = "Элитный",
	["Épico"] = "Эпический",
	["Éxito"] = "Успех",
	["Ícono"] = "Значок",
	["Ícono de rotación"] = "Значок ротации",
	["Ícono del tipo de perjuicio"] = "Значок типа эффекта",
	["Ícono sobre el corcho"] = "Значок над поплавком",
	["Íconos de ayuda"] = "Значки-подсказки",
	["Íconos limpios y tus recursos en el mapa"] = "Чистые значки и ваши ресурсы на карте",
	["Íconos sin bordes negros: el mapa y las ventanas de Alfa se ven limpios al hacer zoom o al teñirse de color."] = "Значки без чёрных краёв: карта и окна Alfa выглядят чисто при масштабировании и окрашивании.",
	["Ídolo"] = "Идол",
	["Ñam. Esto me da energía para cuidarte otras tres horas."] = "Ням. Теперь у меня есть силы беречь тебя еще три часа.",
	["×%d"] = "×%d",
	["Última posición enviada %s."] = "Последнее положение отправлено %s.",
	["Última: %s ×%d · %d en la sesión"] = "Последняя: %s ×%d · за сеанс: %d",
	["Último envío: %s por %s, respuesta %s"] = "Последняя отправка: %s через %s, ответ %s",
	["Último escaneo %s · %s objetos con precio."] = "Последнее сканирование %s · предметов с ценой: %s.",
	["Únete a un grupo o banda para anunciar el top."] = "Вступите в группу или рейд, чтобы объявить топ.",
	["Únete a un grupo para compartir tus marcadores."] = "Вступите в группу, чтобы делиться маркерами.",
	["Único"] = "Уникальный",
	["élite"] = "элитный",
	["épico"] = "эпический",
	["última: %s"] = "последний раз: %s",
	["• El logo, el lobo, Lya y los módulos propios de Alfa son de toxic3000 / La Jauría (GPL-3.0)."] = "• Логотип, волк, Лия и собственные модули Alfa принадлежат toxic3000 / La Jauría (GPL-3.0).",
	["• GatherLite, de Wuild (MIT): la base de nodos de recolección."] = "• GatherLite от Wuild (MIT): база точек сбора.",
	["• Letras Inter, Fira Sans y Open Sans (SIL Open Font License 1.1)."] = "• Шрифты Inter, Fira Sans и Open Sans (SIL Open Font License 1.1).",
	["• Los datos que trae Polestar también vienen de QuestieDB, Efficient Games (CC BY 4.0), VMaNGOS, CMaNGOS y Factoruide (GPL) y de ForeverLevelingBiS de Thunder (MIT); sus avisos están en cada LICENSE-DATA.txt."] = "• Данные Polestar также взяты из QuestieDB, Efficient Games (CC BY 4.0), VMaNGOS, CMaNGOS и Factoruide (GPL) и из ForeverLevelingBiS от Thunder (MIT); их уведомления — в каждом LICENSE-DATA.txt.",
	["• OpenMap, de OpenMap contributors (MIT): la lógica del mapa continuo y las máscaras de territorio."] = "• OpenMap от OpenMap contributors (MIT): логика сплошной карты и маски территорий.",
	["• Polestar, de The Polestar authors (GPL-3.0): el motor de guías, navegación y datos (github.com/fitzforge/polestar)."] = "• Polestar от The Polestar authors (GPL-3.0): движок гайдов, навигации и данных (github.com/fitzforge/polestar).",
	["• Shortest Path Forever, de Cillian Berragan (GPL-3.0-or-later): la navegación y los servicios cercanos."] = "• Shortest Path Forever от Cillian Berragan (GPL-3.0-or-later): навигация и ближайшие услуги.",
	["• TerrainWorldMap, de Dramacydal (MIT): la tabla de mosaicos del terreno del mapa."] = "• TerrainWorldMap от Dramacydal (MIT): таблица фрагментов рельефа карты.",
	["• pfQuest, de shagu (MIT): datos de misiones, PNJ y objetos."] = "• pfQuest от shagu (MIT): данные о заданиях, NPC и объектах.",
	["≈ %s"] = "≈ %s",
}
